<?php
/*
 * 微思文件管理器 0.0.1 - 免费，易用的单文件在线文件管理器
 * Margin.top https://margin.top
 * 最后更新时间 2026/8/17 02:15:53
 */

// 独立配置文件路径，留空则使用内置配置文件模式
define('CUSTOM_CONFIG_FILE', '');

// #region 初始化
error_reporting(0);
version_compare(PHP_VERSION, '5.2.1', '>=') or exit('Need PHP 5.2.1+ to run this program.');
define('IS_WINDOWS', strtoupper(substr(PHP_OS, 0, 3)) === 'WIN');
// #endregion

// #region 独立配置文件模式下初始化配置文件/读取配置信息
define('CONFIG_FILE', CUSTOM_CONFIG_FILE ? CUSTOM_CONFIG_FILE . '.config.php' : __FILE__);

if (CUSTOM_CONFIG_FILE && !is_file(CONFIG_FILE)) {
    $self = file_get_contents(__FILE__);
    $pos  = strrpos($self, '<!----- CONFIG START -----><script>');
    file_put_contents(CONFIG_FILE, "<?php\nheader('HTTP/1.1 404 Not Found');\nexit();\n?>\n" . substr($self, $pos));
}

$config        = GetConfig();
$configChanges = 0;
// #endregion

// #region 初始化随机 Session Name
if (!$config['session_name']) {
    $config['session_name'] = RandStr(32);
    ++$configChanges;
}
// #endregion

// #region 初始化临时配置
$tmpcfg        = GetTmpcfg();
$tmpcfgChanges = 0;
// #endregion

// #region 初始化单次上传限制
$phpWriteSizeLimit    = GetPHPWriteSizeLimit();
$configWriteSizeLimit = ParseWriteSizeLimit(isset($config['write_size_limit']) ? $config['write_size_limit'] : null);

if ($configWriteSizeLimit === false) {
    if ($phpWriteSizeLimit !== false) {
        $configWriteSizeLimit       = $phpWriteSizeLimit;
        $config['write_size_limit'] = $configWriteSizeLimit;
        ++$configChanges;
    }
} else if ($phpWriteSizeLimit !== false && $configWriteSizeLimit > $phpWriteSizeLimit) {
    $configWriteSizeLimit       = $phpWriteSizeLimit;
    $config['write_size_limit'] = $configWriteSizeLimit;
    ++$configChanges;
}
// #endregion

// #region 初始化随机主密码
if (!$config['main_password']) {
    $config['main_password'] = RandStr(32);
    ++$configChanges;
}
// #endregion

// #region 初始化账号
foreach ($config['users'] as &$eachUser) {
    if (!$eachUser['salt']) {
        $password             = $eachUser['password'] ? $eachUser['password'] : $eachUser['username'] . '@123456';
        $eachUser['salt']     = RandStr(32);
        $eachUser['password'] = HashUserPassword($password, $eachUser['salt']);
        ++$configChanges;
    } else if (!IsBcryptHash($eachUser['password']) || BcryptNeedsRehash($eachUser['password'], 12)) {
        $eachUser['password'] = BcryptHash($eachUser['password'], 12);
        ++$configChanges;
    }

    if (!isset($eachUser['totp'])) {
        $eachUser['totp'] = '';
        ++$configChanges;
    }

    $eachUserAdmin = !!$eachUser['admin'];

    if ($eachUser['admin'] !== $eachUserAdmin) {
        $eachUser['admin'] = $eachUserAdmin;
        ++$configChanges;
    }

    $eachUserReadonly = !!$eachUser['readonly'];

    if ($eachUser['readonly'] !== $eachUserReadonly) {
        $eachUser['readonly'] = $eachUserReadonly;
        ++$configChanges;
    }

    if (!isset($eachUser['base_path'])) {
        $eachUser['base_path'] = './';
        ++$configChanges;
    }

    if (substr($eachUser['base_path'], -1) !== '/') {
        $eachUser['base_path'] .= '/';
        ++$configChanges;
    }

    if (isset($eachUser['write_size_limit']) && $eachUser['write_size_limit'] !== '' && $configWriteSizeLimit !== false) {
        $eachUserWriteSizeLimit = ParseWriteSizeLimit($eachUser['write_size_limit']);

        if ($eachUserWriteSizeLimit !== false && $eachUserWriteSizeLimit > $configWriteSizeLimit) {
            $eachUser['write_size_limit'] = $configWriteSizeLimit;
            ++$configChanges;
        }
    }
}

unset($eachUser);
// #endregion

// #region 初始化 TOTP 时间修正参数
$totp_time_fix = max(intval($config['totp_time_fix']), 0);

if ($config['totp_time_fix'] !== $totp_time_fix) {
    $config['totp_time_fix'] = $totp_time_fix;
    ++$configChanges;
}
// #endregion

// #region 初始化缓存时间
$cache_time = max(intval($config['cache_time']), 0);

if ($config['cache_time'] !== $cache_time) {
    $config['cache_time'] = $cache_time;
    ++$configChanges;
}
// #endregion

// #region 清理过期的 TOTP 验证码
if (!isset($tmpcfg['used_totp_codes'])) {
    $tmpcfg['used_totp_codes'] = array();
    ++$tmpcfgChanges;
}

foreach ($tmpcfg['used_totp_codes'] as $index => $item) {
    if (time() - $item[2] > ($tmpcfg['totp_time_fix'] + 2) * 30) {
        array_splice($tmpcfg['used_totp_codes'], $index, 1);
        ++$tmpcfgChanges;
    }
}
// #endregion

// #region 清理过期的登录失败锁定
if (!isset($tmpcfg['login_failures']) || !is_array($tmpcfg['login_failures'])) {
    $tmpcfg['login_failures'] = array();
    ++$tmpcfgChanges;
}

foreach ($tmpcfg['login_failures'] as $username => $failInfo) {
    if (!is_array($failInfo)) {
        unset($tmpcfg['login_failures'][$username]);
        ++$tmpcfgChanges;
        continue;
    }

    $lockUntil = intval($failInfo['lock_until']);

    if ($lockUntil > 0 && $lockUntil <= time()) {
        unset($tmpcfg['login_failures'][$username]);
        ++$tmpcfgChanges;
    }
}
// #endregion

// #region 初始化 Session
$configChanges && SetConfig($config);
$tmpcfgChanges && SetTmpcfg($tmpcfg);
$sessionSecure = (!empty($_SERVER['HTTPS']) && strtolower($_SERVER['HTTPS']) !== 'off')
    || (isset($_SERVER['SERVER_PORT']) && intval($_SERVER['SERVER_PORT']) === 443)
    || (isset($_SERVER['HTTP_X_FORWARDED_PROTO']) && strtolower($_SERVER['HTTP_X_FORWARDED_PROTO']) === 'https')
    || (isset($_SERVER['HTTP_X_FORWARDED_SSL']) && strtolower($_SERVER['HTTP_X_FORWARDED_SSL']) === 'on');

if (version_compare(PHP_VERSION, '7.3.0', '>=')) {
    session_set_cookie_params(array(
        'lifetime' => 0,
        'path'     => '/',
        'domain'   => '',
        'secure'   => $sessionSecure,
        'httponly' => true,
        'samesite' => 'Strict',
    ));
} else {
    session_set_cookie_params(0, '/; samesite=Strict', '', $sessionSecure, true);
}

session_name($config['session_name']);
session_start();
// #endregion

// #region 下载文件 [d:download]
if (isset($_GET['d'])) {
	$download = DecryptDownloadToken($_GET['d']);
	is_array($download) && isset($download['f'], $download['t']) or Error('invalid_download_token');
	is_string($download['f']) && intval($download['t']) > time() or Error('invalid_download_token');
	is_file($download['f']) or Error('file_not_found');
	
	session_write_close();
	ignore_user_abort(true);
	set_time_limit(0);
	
	if (!isset($_GET['inline'])) {
	    header('Content-Description: File Transfer');
	    header('Content-Type: application/octet-stream');
	    header('Content-Disposition: attachment; filename="' . basename($download['f']) . '"');
	    header('Content-Transfer-Encoding: binary');
	    header('Expires: 0');
	    header('Cache-Control: must-revalidate');
	    header('Pragma: public');
	    header('Content-Length: ' . filesize($download['f']));
	    $result = readfile($download['f']);
	    $result === false && Error('read_file_failed');
	    exit();
	}
	
	$fileSize = filesize($download['f']);
	$start    = 0;
	$end      = $fileSize - 1;
	
	if (isset($_SERVER['HTTP_RANGE'])) {
	    preg_match('/^bytes=(\d*)-(\d*)$/', trim($_SERVER['HTTP_RANGE']), $range) or $range = false;
	
	    if ($range === false || ($range[1] === '' && $range[2] === '')) {
	        header('Content-Range: bytes */' . $fileSize);
	        HttpResponseCode(416);
	        exit();
	    }
	
	    if ($range[1] === '') {
	        $length                = intval($range[2]);
	        $length > 0 or $length = $fileSize;
	        $start                 = max(0, $fileSize - $length);
	    } else {
	        $start = intval($range[1]);
	        $range[2] !== '' && ($end = min(intval($range[2]), $end));
	    }
	
	    if ($start > $end || $start >= $fileSize) {
	        header('Content-Range: bytes */' . $fileSize);
	        HttpResponseCode(416);
	        exit();
	    }
	
	    HttpResponseCode(206);
	    header('Content-Range: bytes ' . $start . '-' . $end . '/' . $fileSize);
	}
	
	$handle = fopen($download['f'], 'rb');
	$handle !== false or Error('read_file_failed');
	$start === 0 || fseek($handle, $start) === 0 or Error('read_file_failed');
	
	$ext = strtolower(pathinfo($download['f'], PATHINFO_EXTENSION));
	header('Content-Type: ' . Mime($ext));
	header('Content-Disposition: inline');
	header('Accept-Ranges: bytes');
	header('Content-Length: ' . ($end - $start + 1));
	header('Cache-Control: private, no-cache');
	
	$remaining = $end - $start + 1;
	
	while ($remaining > 0 && !feof($handle)) {
	    $buffer = fread($handle, min(8192, $remaining));
	    $buffer !== false or Error('read_file_failed');
	    echo $buffer;
	    $remaining -= strlen($buffer);
	    flush();
	}
	
	fclose($handle);
	exit();
}
// #endregion

// #region 加载程序自身相关文件 [f:file]
if (isset($_GET['f'])) {
	$user = GetCurrentUser();
	ModuleNeedLogin($_GET['f']) && !$user && HttpError(404);
	ModuleNeedAdmin($_GET['f']) && (!$user || !$user['admin']) && HttpError(404);
	$file = GetModule($_GET['f']);
	$file === false && HttpError(404);
	
	if (strpos($_GET['f'], 'lang/') === 0) {
	    $lang = json_decode($file, true);
	    GetCurrentUser() && JSONReturn($lang);
	
	    JSONReturn(array(
	        'id'       => $lang['id'],
	        'language' => $lang['language'],
	        'title'    => $lang['title'],
	        'login'    => $lang['login'],
	        'common'   => $lang['common'],
	    ));
	}
	
	$fileinfo = pathinfo($_GET['f']);
	$ext      = strtolower($fileinfo['extension']);
	
	$mime = array(
	    'html'  => 'text/html; charset=utf-8',
	    'css'   => 'text/css; charset=utf-8',
	    'js'    => 'application/javascript; charset=utf-8',
	    'json'  => 'application/json; charset=utf-8',
	    'md'    => 'text/markdown; charset=utf-8',
	    'svg'   => 'image/svg+xml',
	    'ico'   => 'image/x-icon',
	    'woff2' => 'font/woff2',
	);
	
	if ($config['cache_time']) {
	    header("Cache-Control: public, max-age=" . $config['cache_time']);
	    header("Expires: " . gmdate('D, d M Y H:i:s', time() + $config['cache_time']) . ' GMT');
	    header("Pragma: cache");
	}
	
	header('Content-Type: ' . ($mime[$ext] ? $mime[$ext] : 'application/octet-stream'));
	$_GET['f'] === 'js/global.js' && exit(str_replace('vsfile-SessionName', 'vsfile-' . $config['session_name'], $file));
	in_array($ext, array('svg')) && print('<?xml version="1.0" encoding="utf-8"?>');
	exit(in_array($ext, array('woff2')) ? base64_decode($file) : $file);
}
// #endregion

// #region 修改权限 [chmod]
if ($_GET['a'] === 'chmod') {
	CheckInvalidReferer() or Error('invalid_request');
	$user = GetCurrentUser() or Error('not_logged');
	$user['readonly'] && Error('read_only');
	
	$post = GetPost();
	is_array($post) or Error('invalid_request');
	
	$paths = isset($post['paths']) ? $post['paths'] : (isset($post['path']) ? $post['path'] : '');
	$mode  = isset($post['mode']) ? strval($post['mode']) : '';
	
	preg_match('/^[0-7]{3}$/', $mode) or Error('invalid_request');
	
	if (is_array($paths)) {
	    $pathList = array();
	    foreach ($paths as $path) {
	        $path = strval($path);
	        if ($path !== '') {
	            $pathList[] = $path;
	        }
	    }
	} else {
	    $pathList = array(strval($paths));
	}
	
	count($pathList) > 0 or Error('invalid_request');
	
	foreach ($pathList as $path) {
	    $filePath = UserPath($user['base_path'], $path) or Error('directory_not_found');
	    chmod($filePath, octdec($mode)) or Error('chmod_failed');
	}
	
	Success();
}
// #endregion

// #region 读写配置信息 [config]
if ($_GET['a'] === 'config') {
	CheckInvalidReferer() or Error('invalid_request');
	
	$user = GetCurrentUser() or Success(array(
	    'lang'     => $config['lang'] ? $config['lang'] : 'chs',
	    'timezone' => $config['timezone'] ? $config['timezone'] : 'Asia/Shanghai',
	    'zip'      => extension_loaded('zip'),
	));
	
	if (strtoupper($_SERVER['REQUEST_METHOD']) === 'GET') {
	    $cfgClone = json_decode(json_encode($config), true);
	
	    if ($user['admin']) {
	        foreach ($cfgClone['users'] as &$eachUser) {
	            foreach (array('password', 'salt') as $key) {
	                unset($eachUser[$key]);
	            }
	        }
	
	        unset($eachUser);
	    } else {
	        $white = array('cache_time', 'lang', 'session_name', 'timezone', 'write_size_limit');
	
	        foreach ($cfgClone as $key => $value) {
	            if (!in_array($key, $white, true)) {
	                unset($cfgClone[$key]);
	            }
	        }
	    }
	
	    $cfgClone['platform']      = IS_WINDOWS ? 'windows' : 'linux';
	    $cfgClone['timezone_list'] = timezone_identifiers_list();
	
	    $userAllow = isset($user['write_exts_allow']) ? $user['write_exts_allow'] : '';
	    $userDeny  = isset($user['write_exts_deny']) ? $user['write_exts_deny'] : '';
	
	    $cfgClone['extension'] = array(
	        'iconv' => function_exists('iconv'),
	        'tgz'   => class_exists('PharData') && function_exists('gzopen') && ArchiveTypeAllowed('gz', $userAllow, $userDeny),
	        'zip'   => class_exists('ZipArchive') && ArchiveTypeAllowed('zip', $userAllow, $userDeny),
	    );
	
	    Success($cfgClone);
	}
	
	$user['admin'] or Error('invalid_request');
	$post = GetPost();
	is_array($post) or Error('invalid_request');
	
	$cfgClone = json_decode(json_encode($config), true);
	is_array($cfgClone) or Error('internal_server_error');
	
	$hasConfigChanges = false;
	
	if (array_key_exists('lang', $post)) {
	    $validLangs = array('chs', 'cht', 'eng', 'ara', 'deu', 'fra', 'hin', 'ita', 'jpn', 'kor', 'por', 'rus', 'spa', 'tur');
	    $newLang    = strtolower(trim(strval($post['lang'])));
	    in_array($newLang, $validLangs, true) or Error('invalid_request');
	    $cfgClone['lang'] = $newLang;
	    $hasConfigChanges = true;
	}
	
	if (array_key_exists('timezone', $post)) {
	    $newTimezone = trim(strval($post['timezone']));
	    $newTimezone = $newTimezone !== '' ? $newTimezone : 'Asia/Shanghai';
	    in_array($newTimezone, timezone_identifiers_list(), true) or Error('invalid_request');
	    $cfgClone['timezone'] = $newTimezone;
	    $hasConfigChanges     = true;
	}
	
	if (array_key_exists('write_size_limit', $post)) {
	    $newWriteSizeLimit = trim(strval($post['write_size_limit']));
	    ParseWriteSizeLimit($newWriteSizeLimit) !== false || $newWriteSizeLimit === '' or Error('invalid_request');
	    $cfgClone['write_size_limit'] = $newWriteSizeLimit;
	    $hasConfigChanges             = true;
	}
	
	if (array_key_exists('totp_time_fix', $post)) {
	    $newTotpTimeFix = intval($post['totp_time_fix']);
	    $newTotpTimeFix >= 0 or Error('invalid_request');
	    $cfgClone['totp_time_fix'] = $newTotpTimeFix;
	    $hasConfigChanges          = true;
	}
	
	if (array_key_exists('session_name', $post)) {
	    $newSessionName = trim(strval($post['session_name']));
	    preg_match('/^[0-9A-Za-z_-]*$/', $newSessionName) or Error('invalid_request');
	    $cfgClone['session_name'] = $newSessionName;
	    $hasConfigChanges         = true;
	}
	
	if (array_key_exists('cache_time', $post)) {
	    $newCacheTime = intval($post['cache_time']);
	    $newCacheTime >= 0 or Error('invalid_request');
	    $cfgClone['cache_time'] = $newCacheTime;
	    $hasConfigChanges       = true;
	}
	
	if (array_key_exists('main_password', $post)) {
	    $cfgClone['main_password'] = strval($post['main_password']);
	    $hasConfigChanges          = true;
	}
	
	if (array_key_exists('comment', $post)) {
	    $cfgClone['comment'] = strval($post['comment']);
	    $hasConfigChanges    = true;
	}
	
	if (array_key_exists('users', $post)) {
	    is_array($post['users']) or Error('invalid_request');
	    count($post['users']) > 0 or Error('invalid_request');
	
	    $oldUsersByName = array();
	
	    foreach ($cfgClone['users'] as $oldUser) {
	        $oldUsersByName[$oldUser['username']] = $oldUser;
	    }
	
	    $newUsers    = array();
	    $usernameMap = array();
	    $adminCount  = 0;
	    $selfName    = $user['username'];
	
	    foreach ($post['users'] as $postUser) {
	        is_array($postUser) or Error('invalid_request');
	        $deleteUser     = isset($postUser['delete']) ? !!$postUser['delete'] : false;
	        $originUsername = trim(isset($postUser['origin_username']) ? strval($postUser['origin_username']) : '');
	
	        if ($originUsername === $selfName && $deleteUser) {
	            Error('invalid_request');
	        }
	
	        if ($deleteUser) {
	            continue;
	        }
	
	        $username = trim(isset($postUser['username']) ? strval($postUser['username']) : '');
	        preg_match('/^[0-9A-Za-z_-]+$/', $username) or Error('invalid_request');
	        !isset($usernameMap[strtolower($username)]) or Error('invalid_request');
	        $usernameMap[strtolower($username)] = true;
	
	        $password = isset($postUser['password']) ? strval($postUser['password']) : '';
	        $originUsername !== '' || $password !== '' or Error('invalid_request');
	        $totp = strtoupper(trim(isset($postUser['totp']) ? strval($postUser['totp']) : ''));
	        $totp !== '' && preg_match('/^[A-Z2-7=]+$/', $totp) !== 1 && Error('invalid_request');
	
	        $readonly = isset($postUser['readonly']) ? !!$postUser['readonly'] : false;
	        $admin    = isset($postUser['admin']) ? !!$postUser['admin'] : false;
	        $basePath = trim(isset($postUser['base_path']) ? strval($postUser['base_path']) : '');
	        $basePath !== '' or Error('invalid_request');
	
	        if (file_exists($basePath)) {
	            is_dir($basePath) or Error('create_directory_failed', 'User base path is not a directory: ' . $basePath);
	        } else if (!MkDirs($basePath)) {
	            Error('create_directory_failed', 'Failed to create user base directory: ' . $basePath);
	        }
	
	        $userWriteSizeLimit = trim(isset($postUser['write_size_limit']) ? strval($postUser['write_size_limit']) : '');
	        ParseWriteSizeLimit($userWriteSizeLimit) !== false || $userWriteSizeLimit === '' or Error('invalid_request');
	
	        $writeExtsAllow = strtolower(trim(isset($postUser['write_exts_allow']) ? strval($postUser['write_exts_allow']) : ''));
	        $writeExtsDeny  = strtolower(trim(isset($postUser['write_exts_deny']) ? strval($postUser['write_exts_deny']) : ''));
	
	        if ($writeExtsAllow !== '') {
	            preg_match('/^[0-9a-z?]+(?:\s*,\s*[0-9a-z?]+)*$/i', $writeExtsAllow) or Error('invalid_request');
	            $writeExtsAllow = implode(',', array_filter(array_map('trim', explode(',', $writeExtsAllow)), 'strlen'));
	        }
	
	        if ($writeExtsDeny !== '') {
	            preg_match('/^[0-9a-z?]+(?:\s*,\s*[0-9a-z?]+)*$/i', $writeExtsDeny) or Error('invalid_request');
	            $writeExtsDeny = implode(',', array_filter(array_map('trim', explode(',', $writeExtsDeny)), 'strlen'));
	        }
	
	        $userItem = array(
	            'username'  => $username,
	            'readonly'  => $readonly,
	            'admin'     => $admin,
	            'base_path' => $basePath,
	        );
	
	        $writeExtsAllow !== '' && $userItem['write_exts_allow']     = $writeExtsAllow;
	        $writeExtsDeny !== '' && $userItem['write_exts_deny']       = $writeExtsDeny;
	        $userWriteSizeLimit !== '' && $userItem['write_size_limit'] = $userWriteSizeLimit;
	        $totp !== '' && $userItem['totp']                           = $totp;
	
	        $oldUser = isset($oldUsersByName[$originUsername]) ? $oldUsersByName[$originUsername] : null;
	
	        if ($originUsername === $selfName) {
	            $oldUser or Error('invalid_request');
	            $username === $oldUser['username'] or Error('invalid_request');
	            $password === '' or Error('invalid_request');
	            $readonly === !!$oldUser['readonly'] or Error('invalid_request');
	            $admin === !!$oldUser['admin'] or Error('invalid_request');
	            $basePath === strval($oldUser['base_path']) or Error('invalid_request');
	            $userWriteSizeLimit === strval(isset($oldUser['write_size_limit']) ? $oldUser['write_size_limit'] : '') or Error('invalid_request');
	            $writeExtsAllow === strval(isset($oldUser['write_exts_allow']) ? $oldUser['write_exts_allow'] : '') or Error('invalid_request');
	            $writeExtsDeny === strval(isset($oldUser['write_exts_deny']) ? $oldUser['write_exts_deny'] : '') or Error('invalid_request');
	            $totp === strval(isset($oldUser['totp']) ? strtoupper(trim($oldUser['totp'])) : '') or Error('invalid_request');
	        }
	
	        if ($password !== '') {
	            $userItem['salt']     = RandStr(32);
	            $userItem['password'] = HashUserPassword($password, $userItem['salt']);
	        } else if ($oldUser) {
	            $userItem['salt']     = $oldUser['salt'];
	            $userItem['password'] = $oldUser['password'];
	        } else {
	            $userItem['salt']     = RandStr(32);
	            $userItem['password'] = HashUserPassword($username . '@123456', $userItem['salt']);
	        }
	
	        $admin && ++$adminCount;
	        array_push($newUsers, $userItem);
	    }
	
	    count($newUsers) > 0 or Error('invalid_request');
	    $adminCount > 0 or Error('invalid_request');
	    $cfgClone['users'] = $newUsers;
	    $hasConfigChanges  = true;
	}
	
	$hasConfigChanges or Error('invalid_request');
	SetConfig($cfgClone) or Error('internal_server_error');
	Success();
}
// #endregion

// #region 检查粘贴冲突 [conflict]
if ($_GET['a'] === 'conflict') {
	CheckInvalidReferer() or Error('invalid_request');
	$user = GetCurrentUser() or Error('not_logged');
	$user['readonly'] && Error('read_only');
	
	$post = GetPost();
	is_array($post) && isset($post['files'], $post['target'], $post['action']) or Error('invalid_request');
	is_array($post['files']) && count($post['files']) > 0 && is_string($post['target']) or Error('invalid_request');
	in_array($post['action'], array('copy', 'cut', 'upload'), true) or Error('invalid_request');
	
	$targetPath = UserPath($user['base_path'], $post['target']) or Error('directory_not_found');
	is_dir($targetPath) or Error('path_not_directory');
	$conflicts = 0;
	
	if ($post['action'] === 'upload') {
	    foreach ($post['files'] as $source) {
	        is_string($source) && trim($source) !== '' or Error('invalid_request');
	        $destination = UserPath($user['base_path'], $source, false, false) or Error('invalid_request');
	        IsSamePath(dirname($destination), $targetPath) or Error('invalid_request');
	        ValidFileName(basename($destination)) or Error('invalid_filename');
	        $conflicts += file_exists($destination) ? 1 : 0;
	    }
	} else {
	    foreach ($post['files'] as $source) {
	        is_string($source) && trim($source) !== '' or Error('invalid_request');
	        $sourcePath = UserPath($user['base_path'], $source, false, false) or Error('file_not_found');
	        is_file($sourcePath) || is_dir($sourcePath) or Error('file_not_found');
	        $destination = JoinPath($targetPath, basename($sourcePath));
	        is_dir($sourcePath) && IsPathInside($destination, $sourcePath) && Error('path_inside_source');
	        $conflicts += CheckPasteConflicts($sourcePath, $destination);
	    }
	}
	
	Success(array('conflicts' => $conflicts));
}
