// #region 加载目录 [dir]
if ($_GET['a'] === 'dir') {
	CheckInvalidReferer() or Error('invalid_request');
	$user        = GetCurrentUser() or Error('not_logged');
	$post        = GetPost();
	$data        = array();
	$currentPath = UserPath($user['base_path'], $post['path']) or Error('directory_not_found');
	$currentMode = sprintf('%03o', @fileperms($currentPath) & 0777);
	
	if (IS_WINDOWS && $user['base_path'] === '/' && in_array($post['path'], array('', '/', '\\'))) {
	    foreach (range('A', 'Z') as $drive) {
	        $drivePath = $drive . ':\\';
	        is_dir($drivePath) && array_push($data, array(
	            'name'     => $drive . ':',
	            'type'     => 'folder',
	            'size'     => 0,
	            'created'  => 0,
	            'modified' => 0,
	            'mode'     => '000',
	            'property' => 3 | (!is_writable($drivePath) ? 8 : 0),
	            'path'     => RelativeUserPath(realpath($drivePath) !== false ? realpath($drivePath) : $drivePath, $user['base_path']),
	        ));
	    }
	
	    Success(array('mode' => $currentMode, 'items' => $data));
	}
	
	$userpath = $currentPath;
	is_dir($userpath) or Error('directory_not_found');
	$files    = @scandir($userpath) or Error('directory_not_found');
	$basePath = UserPath($user['base_path'], '', true);
	
	foreach ($files as $file) {
	    if ($file === '.' || $file === '..') {
	        continue;
	    }
	
	    $itemPath = $userpath . '/' . $file;
	    $fullPath = realpath($itemPath);
	
	    if ($fullPath === false) {
	        continue;
	    }
	
	    $isMine     = $user['base_path'] === '/' || ($basePath !== false && (IsSamePath($fullPath, $basePath) || IsPathInside($fullPath, $basePath)));
	    $isLink     = is_link($itemPath);
	    $isReadonly = !is_writable($fullPath);
	    $property   = ($isMine ? 2 : 0) | ($isLink ? 4 : 0) | ($isReadonly ? 8 : 0);
	
	    $item = array(
	        'name'     => $file,
	        'type'     => is_dir($fullPath) ? 'folder' : 'file',
	        'size'     => is_dir($fullPath) ? 0 : intval(@filesize($fullPath)),
	        'created'  => intval(@filectime($fullPath)),
	        'modified' => intval(@filemtime($fullPath)),
	        'mode'     => sprintf('%03o', @fileperms($fullPath) & 0777),
	        'property' => $property,
	        'path'     => RelativeUserPath($fullPath, $basePath),
	    );
	
	    array_push($data, $item);
	}
	
	usort($data, 'CompareItems');
	Success(array('mode' => $currentMode, 'items' => $data));
}
// #endregion

