// #region 登录 [login]
if ($_GET['a'] === 'login') {
	CheckInvalidReferer() or Error('invalid_request');
	GetCurrentUser() && Error('logged_in');
	
	$data     = GetPost();
	$username = isset($data['username']) ? trim($data['username']) : '';
	$password = isset($data['password']) ? trim($data['password']) : '';
	$username && $password or Error('login_failed');
	$user = GetUserByUsername($username) or Error('login_failed');
	
	if (!isset($tmpcfg['login_failures'][$user['username']]) || !is_array($tmpcfg['login_failures'][$user['username']])) {
	    $tmpcfg['login_failures'][$user['username']] = array('count' => 0, 'lock_until' => 0);
	}
	
	$failInfo  = $tmpcfg['login_failures'][$user['username']];
	$lockUntil = intval($failInfo['lock_until']);
	$lockUntil > time() && Error('login_failed');
	VerifyUserPassword($data['password'], $user['salt'], $user['password']) or LoginFailed();
	
	if ($user['totp']) {
	    $data['totp'] or LoginFailed();
	
	    foreach ($tmpcfg['used_totp_codes'] as $item) {
	        $item[0] === $user['username'] && $item[1] === $data['totp'] && LoginFailed();
	    }
	
	    array_push($tmpcfg['used_totp_codes'], array($user['username'], $data['totp'], time()));
	    SetTmpcfg($tmpcfg);
	    CheckTOTP($user['totp'], $data['totp']) or LoginFailed();
	}
	
	if (isset($tmpcfg['login_failures'][$user['username']])) {
	    unset($tmpcfg['login_failures'][$user['username']]);
	    SetTmpcfg($tmpcfg);
	}
	
	session_regenerate_id(true);
	$_SESSION['username'] = $user['username'];
	Success();
}
