// #region OTP操作 [otp]
if ($_GET['a'] === 'otp') {
	CheckInvalidReferer() or Error('invalid_request');
	$user = GetCurrentUser() or Error('not_logged');
	$post = GetPost();
	
	if ($post['action'] === 'generate') {
	    $user['totp'] && Error('invalid_request');
	    $secret                   = GenerateTOTPSecret(32);
	    $_SESSION['pending_totp'] = $secret;
	    JSONReturn(array('code' => 0, 'data' => array('secret' => $secret), 'message' => 'success'));
	} else if ($post['action'] === 'bind') {
	    $pendingTotp = $_SESSION['pending_totp'] or Error('invalid_request');
	    $code        = trim($post['code']);
	    CheckTOTP($pendingTotp, $code) or Error('totp_invalid');
	    $cfgClone = json_decode(json_encode($config), true);
	
	    foreach ($cfgClone['users'] as &$eachUser) {
	        if ($eachUser['username'] === $user['username']) {
	            $eachUser['totp'] = $pendingTotp;
	            break;
	        }
	    }
	
	    unset($eachUser);
	    SetConfig($cfgClone) or Error('internal_server_error');
	    unset($_SESSION['pending_totp']);
	    Success();
	} else if ($post['action'] === 'unbind') {
	    $user['totp'] or Error('invalid_request');
	    $code = trim($post['code']);
	    CheckTOTP($user['totp'], $code) or Error('totp_invalid');
	    $cfgClone = json_decode(json_encode($config), true);
	
	    foreach ($cfgClone['users'] as &$eachUser) {
	        if ($eachUser['username'] === $user['username']) {
	            unset($eachUser['totp']);
	            break;
	        }
	    }
	
	    unset($eachUser);
	    SetConfig($cfgClone) or Error('internal_server_error');
	    Success();
	}
	
	Success(array('totp' => $user['totp'] ? true : false));
}
