	in_array($post['action'], array('copy', 'cut'), true) && in_array($post['strategy'], array('overwrite', 'discard', 'rename'), true) or Error('invalid_request');
	
	$sourcePath = UserPath($user['base_path'], $post['src'], false, false) or Error('file_not_found');
