// #region 压缩/解压 TGZ / TAR.GZ 文件 [tgz]
if ($_GET['a'] === 'tgz') {
	CheckInvalidReferer() or Error('invalid_request');
	$user = GetCurrentUser() or Error('not_logged');
	$user['readonly'] && Error('read_only');
	strtoupper($_SERVER['REQUEST_METHOD']) === 'POST' or Error('invalid_request');
	class_exists('PharData') or Error('tar_not_support');
	function_exists('gzopen') or Error('gz_not_support');
	
	$post = GetPost();
	is_array($post) or Error('invalid_request');
	
	$requestAction = isset($post['action']) ? strtolower(strval($post['action'])) : 'zip';
	$requestAction = in_array($requestAction, array('zip', 'unzip'), true) ? $requestAction : 'zip';
	$write_exts_allow = isset($user['write_exts_allow']) ? $user['write_exts_allow'] : '';
	$write_exts_deny  = isset($user['write_exts_deny']) ? $user['write_exts_deny'] : '';
	
	if ($requestAction === 'zip' && !ArchiveTypeAllowed('gz', $write_exts_allow, $write_exts_deny)) {
	    Error('not_allowed_extension');
	}
	
	if ($requestAction === 'unzip') {
	    $srcInput = isset($post['src']) ? trim(strval($post['src'])) : '';
	    $srcInput !== '' or Error('invalid_request');
	
	    $srcPath = UserPath($user['base_path'], $srcInput, false, false) or Error('file_not_found');
	    is_file($srcPath) or Error('file_not_found');
	
	    $dstInput = isset($post['dst']) ? trim(strval($post['dst'])) : '';
	
	    if ($dstInput === '') {
	        $srcInputNorm = str_replace('\\', '/', $srcInput);
	        $srcDirInput  = dirname($srcInputNorm);
	        $srcDirInput  = $srcDirInput === '.' ? '' : $srcDirInput;
	        $srcBaseName  = pathinfo($srcPath, PATHINFO_FILENAME);
	        $srcBaseName  = preg_replace('/\.(tar\.gz|tgz)$/i', '', $srcBaseName);
	        $srcBaseName  = $srcBaseName !== '' ? $srcBaseName : 'unzipped';
	        $defaultDst   = $srcDirInput === '' ? $srcBaseName : (($srcDirInput === '/' ? '/' : rtrim($srcDirInput, '/') . '/') . $srcBaseName);
	        $dstPath      = UserPath($user['base_path'], $defaultDst, false, false) or Error('invalid_request');
	        $dstPath      = GetUniqueDirectoryPath($dstPath);
	    } else {
	        $dstPath = UserPath($user['base_path'], $dstInput, false, false) or Error('invalid_request');
	    }
	
	    if (file_exists($dstPath)) {
	        is_dir($dstPath) or Error('ungz_failed');
	    } else {
	        MkDirs($dstPath) or Error('ungz_failed');
	    }
	
	    try {
	        $archive = new PharData($srcPath);
	    } catch (Exception $e) {
	        Error('ungz_failed');
	    }
	
	    try {
	        $entries = GetSafeTgzEntries($srcPath, $write_exts_allow, $write_exts_deny);
	    } catch (Exception $e) {
	        Error('ungz_failed');
	    }
	
	    $entries !== false or Error('ungz_failed');
	
	    try {
	        $extractOk = count($entries) ? $archive->extractTo($dstPath, $entries, true) : true;
	    } catch (Exception $e) {
	        Error('ungz_failed');
	    }
	
	    $extractOk or Error('ungz_failed');
	
	    Success();
	}
	
	isset($post['src']) or Error('invalid_request');
	
	$srcInputList = array();
	
	if (is_string($post['src'])) {
	    $srcInput = trim(strval($post['src']));
	    $srcInput !== '' or Error('invalid_request');
	    array_push($srcInputList, $srcInput);
	} else if (is_array($post['src'])) {
	    count($post['src']) > 0 or Error('invalid_request');
	
	    foreach ($post['src'] as $srcItem) {
	        is_string($srcItem) or Error('invalid_request');
	        $srcInput = trim(strval($srcItem));
	        $srcInput !== '' or Error('invalid_request');
	        array_push($srcInputList, $srcInput);
	    }
	} else {
	    Error('invalid_request');
	}
	
	$sourcePaths = array();
	
	foreach ($srcInputList as $srcInput) {
	    $sourcePath = UserPath($user['base_path'], $srcInput, false, false) or Error('file_not_found');
	    is_file($sourcePath) || is_dir($sourcePath) || is_link($sourcePath) or Error('file_not_found');
	    array_push($sourcePaths, $sourcePath);
	}
	
	$dstInputRaw  = isset($post['dst']) ? strval($post['dst']) : '';
	$dstInputTrim = trim($dstInputRaw);
	$archivePath  = '';
	$archiveRespPath = '';
	
	if ($dstInputTrim === '') {
	    $firstInput      = str_replace('\\', '/', $srcInputList[0]);
	    $firstDirInput   = dirname($firstInput);
	    $firstDirInput   = $firstDirInput === '.' ? '' : $firstDirInput;
	    $targetDirectory = dirname($sourcePaths[0]);
	
	    do {
	        $archiveName = strval(time()) . '-' . strtolower(RandStr(8)) . '.tar.gz';
	        $archivePath = JoinPath($targetDirectory, $archiveName);
	    } while (file_exists($archivePath));
	
	    if ($firstDirInput === '') {
	        $archiveRespPath = basename($archivePath);
	    } else {
	        $archiveRespPath = ($firstDirInput === '/' ? '/' : rtrim($firstDirInput, '/') . '/') . basename($archivePath);
	    }
	} else {
	    $dstInputNorm = str_replace('\\', '/', $dstInputTrim);
	
	    if (substr($dstInputNorm, -1) === '/') {
	        $targetDirectory = UserPath($user['base_path'], $dstInputNorm, false, false) or Error('invalid_request');
	        MkDirs($targetDirectory) or Error('gz_failed');
	
	        do {
	            $archiveName = strval(time()) . '-' . strtolower(RandStr(8)) . '.tar.gz';
	            $archivePath = JoinPath($targetDirectory, $archiveName);
	        } while (file_exists($archivePath));
	
	        $archiveRespPath = ($dstInputNorm === '/' ? '/' : rtrim($dstInputNorm, '/') . '/') . basename($archivePath);
	    } else {
	        $archivePath = UserPath($user['base_path'], $dstInputNorm, false, false) or Error('invalid_request');
	
	        if (preg_match('/\.tar\.gz$/i', $archivePath) || preg_match('/\.tgz$/i', $archivePath)) {
	            $archivePath = preg_replace('/\.tgz$/i', '.tar.gz', $archivePath);
	        } else {
	            $archivePath .= '.tar.gz';
	        }
	
	        MkDirs(dirname($archivePath)) or Error('gz_failed');
	
	        if (file_exists($archivePath)) {
	            $archivePath = GetUniqueCopyPath($archivePath, true);
	        }
	
	        $archiveDirInput = dirname(str_replace('\\', '/', $dstInputNorm));
	
	        if ($archiveDirInput === '.' || $archiveDirInput === '') {
	            $archiveRespPath = basename($archivePath);
	        } else {
	            $archiveRespPath = ($archiveDirInput === '/' ? '/' : rtrim($archiveDirInput, '/') . '/') . basename($archivePath);
	        }
	    }
	}
	
	$tempTarPath = preg_replace('/\.tar\.gz$/i', '.tar', $archivePath);
	if (preg_match('/\.tgz$/i', $archivePath)) {
	    $tempTarPath = preg_replace('/\.tgz$/i', '.tar', $archivePath);
	}
	
	if (file_exists($tempTarPath)) {
	    @unlink($tempTarPath);
	}
	
	try {
	    $archive = new PharData($tempTarPath);
	} catch (Exception $e) {
	    Error('gz_failed');
	}
	
	$archiveOk = true;
	
	foreach ($sourcePaths as $sourcePath) {
	    $entryName = basename($sourcePath);
	
	    if ($entryName === '' || $entryName === '.' || $entryName === '..') {
	        $archiveOk = false;
	        break;
	    }
	
	    if (!TGZAddPath($archive, $sourcePath, $entryName)) {
	        $archiveOk = false;
	        break;
	    }
	}
	
	if (!$archiveOk) {
	    is_file($tempTarPath) && @unlink($tempTarPath);
	    Error('gz_failed');
	}
	
	try {
	    $archive->compress(Phar::GZ);
	} catch (Exception $e) {
	    is_file($tempTarPath) && @unlink($tempTarPath);
	    Error('gz_failed');
	}
	
	if (file_exists($tempTarPath)) {
	    @unlink($tempTarPath);
	}
	
	$finalArchivePath = $tempTarPath . '.gz';
	
	if (!file_exists($finalArchivePath)) {
	    $finalArchivePath = $archivePath;
	}
	
	if (!file_exists($finalArchivePath)) {
	    Error('gz_failed');
	}
	
	Success(array('tgz' => IS_WINDOWS && preg_match('/^[A-Za-z]:/', $archiveRespPath) ? str_replace('/', '\\', $archiveRespPath) : $archiveRespPath));
}
// #endregion

// #region 创建文件 [upload]
if ($_GET['a'] === 'upload') {
	CheckInvalidReferer() or Error('invalid_request');
	$user = GetCurrentUser() or Error('not_logged');
	$user['readonly'] && Error('read_only');
	$writeSizeLimit = GetUserWriteSizeLimit($user);
	$strategy       = isset($_POST['strategy']) ? strtolower(trim($_POST['strategy'])) : 'overwrite';
	in_array($strategy, array('overwrite', 'discard', 'rename'), true) or Error('invalid_request');
	$checkOnly    = isset($_POST['check']) && in_array(strtolower(trim($_POST['check'])), array('1', 'true', 'yes'), true);
	$hasChunk     = isset($_POST['chunk_index']) || isset($_POST['chunk_total']);
	$chunkIndex   = $hasChunk ? intval($_POST['chunk_index']) : 0;
	$chunkTotal   = $hasChunk ? intval($_POST['chunk_total']) : 1;
	$responsePath = str_replace('\\', '/', trim(isset($_POST['path']) ? $_POST['path'] : ''));
	
	$path = UserPath($user['base_path'], $_POST['path']) or Error('directory_not_found');
	ValidFileExtension($path, $user['write_exts_allow'], $user['write_exts_deny']) or Error('not_allowed_extension');
	
	if ($hasChunk) {
	    $chunkTotal > 0 && $chunkIndex >= 0 && $chunkIndex < $chunkTotal or Error('invalid_request');
	}
	
	$exists = file_exists($path);
	
	if ($checkOnly) {
	    Success(array('conflict' => $exists));
	}
	
	if (!$hasChunk) {
	    $exists && $strategy === 'discard' && Success(array('skipped' => true, 'path' => (IS_WINDOWS && preg_match('/^[A-Za-z]:/', $responsePath) ? str_replace('/', '\\', $responsePath) : $responsePath)));
	
	    if ($exists && $strategy === 'rename') {
	        $path = GetUniqueCopyPath($path, true);
	
	        $responseDir = str_replace('\\', '/', dirname($responsePath));
	
	        if ($responseDir === '.' || $responseDir === '') {
	            $responsePath = basename($path);
	        } else {
	            $responsePath = ($responseDir === '/' ? '/' : rtrim($responseDir, '/') . '/') . basename($path);
	        }
	    }
	
	    is_uploaded_file($_FILES['content']['tmp_name']) or Error('write_file_failed');
	
	    if ($writeSizeLimit !== false && isset($_FILES['content']['size']) && intval($_FILES['content']['size']) > $writeSizeLimit) {
	        Error('write_size_exceeded');
	    }
	
	    (!$_POST['encoding'] || $_POST['encoding'] === 'utf-8') && JSONReturn(CopyFileChunked($_FILES['content']['tmp_name'], $path, 8192, $writeSizeLimit));
	    extension_loaded('iconv') or Error('iconv_not_enabled');
	    JSONReturn(IconvStream($_FILES['content']['tmp_name'], $path, 'UTF-8', $_POST['encoding'], 8192, $writeSizeLimit));
	}
	
	is_uploaded_file($_FILES['content']['tmp_name']) or Error('write_file_failed');
	$chunkSize   = isset($_FILES['content']['size']) ? intval($_FILES['content']['size']) : 0;
	$currentSize = is_file($path) ? @filesize($path) : 0;
	$currentSize = $currentSize === false ? 0 : intval($currentSize);
	
	if ($chunkIndex === 0) {
	    $exists && $strategy === 'discard' && Success(array('skipped' => true, 'path' => (IS_WINDOWS && preg_match('/^[A-Za-z]:/', $responsePath) ? str_replace('/', '\\', $responsePath) : $responsePath)));
	
	    if ($exists && $strategy === 'rename') {
	        $path = GetUniqueCopyPath($path, true);
	
	        $responseDir = str_replace('\\', '/', dirname($responsePath));
	
	        if ($responseDir === '.' || $responseDir === '') {
	            $responsePath = basename($path);
	        } else {
	            $responsePath = ($responseDir === '/' ? '/' : rtrim($responseDir, '/') . '/') . basename($path);
	        }
	    }
	
	    MkDirs(dirname($path)) or Error('create_directory_failed');
	
	    if ($writeSizeLimit !== false && ($chunkSize > $writeSizeLimit || $currentSize + $chunkSize > $writeSizeLimit)) {
	        Error('write_size_exceeded');
	    }
	
	    move_uploaded_file($_FILES['content']['tmp_name'], $path) or Error('write_file_failed');
	    Success(array(
	        'path' => IS_WINDOWS && preg_match('/^[A-Za-z]:/', $responsePath) ? str_replace('/', '\\', $responsePath) : $responsePath,
	        'done' => $chunkTotal === 1,
	    ));
	}
	
	is_file($path) or Error('file_not_found');
	
	if ($writeSizeLimit !== false && ($chunkSize > $writeSizeLimit || $currentSize + $chunkSize > $writeSizeLimit)) {
	    Error('write_size_exceeded');
	}
	
	$in = fopen($_FILES['content']['tmp_name'], 'rb');
	$in !== false or Error('write_file_failed');
	$out = fopen($path, 'ab');
	
	if ($out === false) {
	    fclose($in);
	    Error('write_file_failed');
	}
	
	while (!feof($in)) {
	    $buffer = fread($in, 8192);
	    $buffer !== false or Error('write_file_failed');
	
	    if ($buffer === '') {
	        continue;
	    }
	
	    fwrite($out, $buffer) !== false or Error('write_file_failed');
	}
	
	fclose($in);
	fclose($out);
	Success(array('path' => IS_WINDOWS && preg_match('/^[A-Za-z]:/', $responsePath) ? str_replace('/', '\\', $responsePath) : $responsePath, 'done' => $chunkIndex + 1 === $chunkTotal));
}
// #endregion

// #region 用户信息 [userinfo]
if ($_GET['a'] === 'userinfo') {
	CheckInvalidReferer() or Error('invalid_request');
	$user = GetCurrentUser() or Error('not_logged');
	
	if (strtoupper($_SERVER['REQUEST_METHOD']) === 'GET') {
	    Success(array(
	        'username'         => $user['username'],
	        'readonly'         => $user['readonly'],
	        'admin'            => $user['admin'],
	        'totp'             => $user['totp'] ? true : false,
	        'base_root'        => $user['base_path'] === '/' ? true : false,
	        'write_exts_allow' => $user['write_exts_allow'],
	        'write_exts_deny'  => $user['write_exts_deny'],
	        'write_size_limit' => GetUserWriteSizeLimit($user),
	    ));
	}
	
	$post            = GetPost();
	$currentPassword = trim($post['current_password']);
	$newPassword     = trim($post['new_password']);
	$confirmPassword = trim($post['confirm_password']);
	
	if ($currentPassword && $newPassword && $confirmPassword) {
	    $newPassword === $confirmPassword or Error('password_mismatch');
	    VerifyUserPassword($currentPassword, $user['salt'], $user['password']) or Error('password_error');
	    $cfgClone = json_decode(json_encode($config), true);
	
	    foreach ($cfgClone['users'] as &$eachUser) {
	        if ($eachUser['username'] === $user['username']) {
	            $eachUser['salt']     = RandStr(32);
	            $eachUser['password'] = HashUserPassword($newPassword, $eachUser['salt']);
	            break;
	        }
	    }
	
	    unset($eachUser);
	    LogoutCurrentSession();
	}
	
	SetConfig($cfgClone) or Error('internal_server_error');
	Success();
}
// #endregion

// #region 压缩/解压 ZIP 文件 [zip]
if ($_GET['a'] === 'zip') {
	CheckInvalidReferer() or Error('invalid_request');
	$user = GetCurrentUser() or Error('not_logged');
	$user['readonly'] && Error('read_only');
	strtoupper($_SERVER['REQUEST_METHOD']) === 'POST' or Error('invalid_request');
	class_exists('ZipArchive') or Error('zip_not_support');
	
	$post = GetPost();
	is_array($post) or Error('invalid_request');
	
	$requestAction = isset($post['action']) ? strtolower(strval($post['action'])) : 'zip';
	$requestAction = in_array($requestAction, array('zip', 'unzip'), true) ? $requestAction : 'zip';
	
	if ($requestAction === 'zip' && !ArchiveTypeAllowed('zip', isset($user['write_exts_allow']) ? $user['write_exts_allow'] : '', isset($user['write_exts_deny']) ? $user['write_exts_deny'] : '')) {
	    Error('not_allowed_extension');
	}
	
	if ($requestAction === 'unzip') {
	    $srcInput = isset($post['src']) ? trim(strval($post['src'])) : '';
	    $srcInput !== '' or Error('invalid_request');
	
	    $srcPath = UserPath($user['base_path'], $srcInput, false, false) or Error('file_not_found');
	    is_file($srcPath) or Error('file_not_found');
	
	    $dstInput = isset($post['dst']) ? trim(strval($post['dst'])) : '';
	    $dstPath  = '';
	
	    if ($dstInput === '') {
	        $srcInputNorm = str_replace('\\', '/', $srcInput);
	        $srcDirInput  = dirname($srcInputNorm);
	        $srcDirInput  = $srcDirInput === '.' ? '' : $srcDirInput;
	        $srcBaseName  = pathinfo($srcPath, PATHINFO_FILENAME);
	        $srcBaseName  = $srcBaseName !== '' ? $srcBaseName : 'unzipped';
	        $defaultDst   = $srcDirInput === '' ? $srcBaseName : (($srcDirInput === '/' ? '/' : rtrim($srcDirInput, '/') . '/') . $srcBaseName);
	        $dstPath      = UserPath($user['base_path'], $defaultDst, false, false) or Error('invalid_request');
	        $dstPath      = GetUniqueDirectoryPath($dstPath);
	    } else {
	        $dstPath = UserPath($user['base_path'], $dstInput, false, false) or Error('invalid_request');
	    }
	
	    if (file_exists($dstPath)) {
	        is_dir($dstPath) or Error('unzip_failed');
	    } else {
	        MkDirs($dstPath) or Error('unzip_failed');
	    }
	
	    $zip = new ZipArchive();
	    $zip->open($srcPath) === true or Error('unzip_failed');
	    $entries = GetSafeZipEntries($zip, $user['write_exts_allow'], $user['write_exts_deny']);
	
	    if ($entries === false) {
	        $zip->close();
	        Error('unzip_failed');
	    }
	
	    $extractOk = count($entries) ? $zip->extractTo($dstPath, $entries) : true;
	    $closeOk   = $zip->close() !== false;
	    $extractOk && $closeOk or Error('unzip_failed');
	    Success();
	}
	
	isset($post['src']) or Error('invalid_request');
	$srcInputList = array();
	
	if (is_string($post['src'])) {
	    $srcInput = trim(strval($post['src']));
	    $srcInput !== '' or Error('invalid_request');
	    array_push($srcInputList, $srcInput);
	} else if (is_array($post['src'])) {
	    count($post['src']) > 0 or Error('invalid_request');
	
	    foreach ($post['src'] as $srcItem) {
	        is_string($srcItem) or Error('invalid_request');
	        $srcInput = trim(strval($srcItem));
	        $srcInput !== '' or Error('invalid_request');
	        array_push($srcInputList, $srcInput);
	    }
	} else {
	    Error('invalid_request');
	}
	
	$sourcePaths = array();
	
	foreach ($srcInputList as $srcInput) {
	    $sourcePath = UserPath($user['base_path'], $srcInput, false, false) or Error('file_not_found');
	    is_file($sourcePath) || is_dir($sourcePath) || is_link($sourcePath) or Error('file_not_found');
	    array_push($sourcePaths, $sourcePath);
	}
	
	$dstInputRaw  = isset($post['dst']) ? strval($post['dst']) : '';
	$dstInputTrim = trim($dstInputRaw);
	$zipPath      = '';
	$zipRespPath  = '';
	
	if ($dstInputTrim === '') {
	    $firstInput      = str_replace('\\', '/', $srcInputList[0]);
	    $firstDirInput   = dirname($firstInput);
	    $firstDirInput   = $firstDirInput === '.' ? '' : $firstDirInput;
	    $targetDirectory = dirname($sourcePaths[0]);
	
	    do {
	        $zipName = strval(time()) . '-' . strtolower(RandStr(8)) . '.zip';
	        $zipPath = JoinPath($targetDirectory, $zipName);
	    } while (file_exists($zipPath));
	
	    if ($firstDirInput === '') {
	        $zipRespPath = basename($zipPath);
	    } else {
	        $zipRespPath = ($firstDirInput === '/' ? '/' : rtrim($firstDirInput, '/') . '/') . basename($zipPath);
	    }
	} else {
	    $dstInputNorm = str_replace('\\', '/', $dstInputTrim);
	
	    if (substr($dstInputNorm, -1) === '/') {
	        $targetDirectory = UserPath($user['base_path'], $dstInputNorm, false, false) or Error('invalid_request');
	        MkDirs($targetDirectory) or Error('zip_failed');
	
	        do {
	            $zipName = strval(time()) . '-' . strtolower(RandStr(8)) . '.zip';
	            $zipPath = JoinPath($targetDirectory, $zipName);
	        } while (file_exists($zipPath));
	
	        $zipRespPath = ($dstInputNorm === '/' ? '/' : rtrim($dstInputNorm, '/') . '/') . basename($zipPath);
	    } else {
	        $zipPath = UserPath($user['base_path'], $dstInputNorm, false, false) or Error('invalid_request');
	
	        if (strtolower(pathinfo($zipPath, PATHINFO_EXTENSION)) !== 'zip') {
	            $zipPath .= '.zip';
	            $dstInputNorm .= '.zip';
	        }
	
	        MkDirs(dirname($zipPath)) or Error('zip_failed');
	
	        if (file_exists($zipPath)) {
	            $zipPath = GetUniqueCopyPath($zipPath, true);
	        }
	
	        $zipDirInput = dirname($dstInputNorm);
	
	        if ($zipDirInput === '.' || $zipDirInput === '') {
	            $zipRespPath = basename($zipPath);
	        } else {
	            $zipRespPath = ($zipDirInput === '/' ? '/' : rtrim($zipDirInput, '/') . '/') . basename($zipPath);
	        }
	    }
	}
	
	$zip = new ZipArchive();
	$zip->open($zipPath, ZipArchive::CREATE) === true or Error('zip_failed');
	$zipOk = true;
	
	foreach ($sourcePaths as $sourcePath) {
	    $entryName = basename($sourcePath);
	
	    if ($entryName === '' || $entryName === '.' || $entryName === '..') {
	        $zipOk = false;
	        break;
	    }
	
	    if (!ZipAddPath($zip, $sourcePath, $entryName)) {
	        $zipOk = false;
	        break;
	    }
	}
	
	$closeOk = $zip->close() !== false;
	
	if (!$zipOk || !$closeOk) {
	    is_file($zipPath) && @unlink($zipPath);
	    Error('zip_failed');
	}
	
	Success(array('zip' => IS_WINDOWS && preg_match('/^[A-Za-z]:/', $zipRespPath) ? str_replace('/', '\\', $zipRespPath) : $zipRespPath));
}
// #endregion

// #region 主界面 [main]
header('Content-Type: text/html; charset=utf-8');

if (GetCurrentUser()) {
    list($referer)       = explode('?', $_SERVER['HTTP_REFERER']);
    $_SESSION['referer'] = $referer;
    exit(GetModule('html/frame.html'));
} else {
    list($referer)       = explode('?', GetCurrentUrl());
    $_SESSION['referer'] = $referer;
    exit(GetModule('html/login.html'));
}
