function JSONReturn($array)
{
    header('Content-Type: application/json; charset=utf-8');
    exit(json_encode($array));
}

function HttpError($code)
{
    switch ($code) {
        case 400:
            header('HTTP/1.1 400 Bad Request');
            exit('400 Bad Request');
        case 401:
            header('HTTP/1.1 401 Unauthorized');
            exit('401 Unauthorized');
        case 403:
            header('HTTP/1.1 403 Forbidden');
            exit('403 Forbidden');
        case 404:
            header('HTTP/1.1 404 Not Found');
            exit('404 Not Found');
        case 500:
            header('HTTP/1.1 500 Internal Server Error');
            exit('500 Internal Server Error');
        case 503:
            header('HTTP/1.1 503 Service Unavailable');
            exit('503 Service Unavailable');
        default:
            header('HTTP/1.1 500 Internal Server Error');
            exit('500 Internal Server Error');
    }
}

function Success()
{
    func_num_args() || JSONReturn(GetError('success'));
    JSONReturn(array('code' => 0, 'message' => 'Success.', 'data' => func_get_arg(0)));
}

function GetError($error, $msg = false)
{
    $errors = array(
        'success'                 => 0,
        'internal_server_error'   => 500,
        'invalid_request'         => 1000,
        'logged_in'               => 1001,
        'login_failed'            => 1002,
        'not_logged'              => 1003,
        'read_only'               => 1004,
        'parent_not_found'        => 1005,
        'directory_not_found'     => 1006,
        'file_not_found'          => 1007,
        'invalid_filename'        => 1008,
        'invalid_type'            => 1009,
        'file_exists'             => 1010,
        'remove_failed'           => 1011,
        'path_not_directory'      => 1012,
        'path_not_file'           => 1013,
        'read_file_failed'        => 1014,
        'write_file_failed'       => 1015,
        'not_allowed_extension'   => 1016,
        'create_directory_failed' => 1017,
        'create_file_failed'      => 1018,
        'rename_failed'           => 1019,
        'move_failed'             => 1020,
        'chmod_failed'            => 1021,
        'invalid_download_token'  => 1022,
        'iconv_not_enabled'       => 1023,
        'file_not_image'          => 1024,
        'write_size_exceeded'     => 1025,
        'path_inside_source'      => 1026,
        'no_current_password'     => 1027,
        'no_new_password'         => 1028,
        'no_confirm_password'     => 1029,
        'password_mismatch'       => 1030,
        'password_error'          => 1031,
        'totp_invalid'            => 1032,
        'zip_not_support'         => 1033,
        'zip_failed'              => 1034,
        'unzip_failed'            => 1035,
        'extract_ico_failed'      => 1036,
        'tar_not_support'         => 1037,
        'tar_failed'              => 1038,
        'untar_failed'            => 1039,
        'gz_not_support'          => 1040,
        'gz_failed'               => 1041,
        'ungz_failed'             => 1042,
        'gz_failed1'              => 1043,
        'gz_failed2'              => 1044,
        'gz_failed3'              => 1045,
        'gz_failed4'              => 1046,
        'gz_failed5'              => 1047,
        'gz_failed6'              => 1048,
    );

    $code    = isset($errors[$error]) ? $errors[$error] : 9999;
    $message = $code < 9999 ? $msg ? $msg : str_replace('_', ' ', ucwords($error)) . '.' : 'Unknown error.';
    return array('code' => $code, 'message' => $message);
}

function Error($error, $msg = false)
{
    JSONReturn(GetError($error, $msg));
}

function ParseWriteSizeLimit($limit)
{
    if ($limit === null || $limit === '') {
        return false;
    }

    if (is_int($limit)) {
        return $limit >= 0 ? $limit : false;
    }

    if (is_float($limit)) {
        return $limit >= 0 ? intval(floor($limit)) : false;
    }

    if (is_string($limit)) {
        $limit = trim($limit);

        if ($limit === '') {
            return false;
        }

        if (!preg_match('/^([0-9]+(?:\.[0-9]+)?)\s*([A-Za-z]*)$/', $limit, $matches)) {
            return false;
        }

        $value = floatval($matches[1]);

        if ($value < 0) {
            return false;
        }

        $unit   = strtoupper($matches[2]);
        $powMap = array(
            ''   => 0,
            'B'  => 0,
            'K'  => 1,
            'M'  => 2,
            'G'  => 3,
            'T'  => 4,
            'P'  => 5,
            'E'  => 6,
            'Z'  => 7,
            'Y'  => 8,
            'KB' => 1,
            'MB' => 2,
            'GB' => 3,
            'TB' => 4,
            'PB' => 5,
            'EB' => 6,
            'ZB' => 7,
            'YB' => 8,
        );

        $pow   = isset($powMap[$unit]) ? $powMap[$unit] : 0;
        $bytes = floor($value * pow(1024, $pow));
        return $bytes < 0  ?false : intval($bytes);
    }

    return false;
}

function ParseIniSizeLimit($limit)
{
    if ($limit === null || $limit === false) {
        return false;
    }

    $limit = trim(strval($limit));

    if ($limit === '' || $limit === '-1') {
        return false;
    }

    $bytes = ParseWriteSizeLimit($limit);

    // INI value 0 means no limit; treat as unlimited here.
    if ($bytes === false || $bytes <= 0) {
        return false;
    }

    return $bytes;
}

function GetPHPWriteSizeLimit()
{
    $limits = array(
        ParseIniSizeLimit(ini_get('upload_max_filesize')),
        ParseIniSizeLimit(ini_get('post_max_size')),
        ParseIniSizeLimit(ini_get('memory_limit')),
    );

    $validLimits = array();

    foreach ($limits as $limit) {
        $limit !== false && $validLimits[] = $limit;
    }

    if (!count($validLimits)) {
        return false;
    }

    return min($validLimits);
}

function GetEffectiveWriteSizeLimit($userLimit, $globalLimit)
{
    $globalBytes = ParseWriteSizeLimit($globalLimit);
    $userBytes   = ParseWriteSizeLimit($userLimit);

    if ($userBytes === false) {
        return $globalBytes;
    }

    if ($globalBytes === false) {
        return $userBytes;
    }

    return $userBytes > $globalBytes ? $globalBytes : $userBytes;
}

function GetUserWriteSizeLimit($user)
{
    global $config;

    return GetEffectiveWriteSizeLimit(
        isset($user['write_size_limit']) ? $user['write_size_limit'] : null,
        isset($config['write_size_limit']) ? $config['write_size_limit'] : null
    );
}

function GetConfig()
{
    $self      = file_get_contents(CONFIG_FILE);
    $startFlag = '<!----- CONFIG START -----><script>';
    $start     = strrpos($self, $startFlag) + strlen($startFlag);
    $end       = strpos($self, '</script><!----- CONFIG END ----->', $start);

    if ($start === false || $end === false) {
        return false;
    }

    $config = json_decode(trim(substr($self, $start, $end - $start)), true);
    $config === null && exit('Config syntax error!');
    return $config;
}

function SetConfig($config)
{
    $self      = file_get_contents(CONFIG_FILE);
    $startFlag = '<!----- CONFIG START -----><script>';
    $start     = strrpos($self, $startFlag) + strlen($startFlag);
    $end       = strpos($self, '</script><!----- CONFIG END ----->', $start);

    if ($start === false || $end === false) {
        return false;
    }

    $newConfig = JSONEncode($config);
    $newSelf   = substr($self, 0, $start) . "\n" . $newConfig . "\n" . substr($self, $end);
    SafeWrite(CONFIG_FILE, $newSelf);
    return true;
}

function GetTmpcfg()
{
    global $config;
    $filename = sys_get_temp_dir() . DIRECTORY_SEPARATOR . $config['session_name'] . '-tmpcfg.json';
    $content  = @file_get_contents($filename);

    if ($content === false) {
        return array();
    }

    $tmpcfg = json_decode($content, true);
    return is_array($tmpcfg) ? $tmpcfg : array();
}

function SetTmpcfg($tmpcfg)
{
    global $config;
    $filename = sys_get_temp_dir() . DIRECTORY_SEPARATOR . $config['session_name'] . '-tmpcfg.json';
    return SafeWrite($filename, JSONEncode($tmpcfg));
}

function Base64URLSafeEncode($data)
{
    return rtrim(strtr(base64_encode($data), '+/', '-_'), '=');
}

function Base64URLSafeDecode($data)
{
    if (!is_string($data) || $data === '' || preg_match('/[^A-Za-z0-9_-]/', $data)) {
        return false;
    }

    $padding = strlen($data) % 4;
    $padding && $data .= str_repeat('=', 4 - $padding);
    return base64_decode(strtr($data, '-_', '+/'), true);
}

function HttpResponseCode($newcode = null)
{
    if (function_exists('http_response_code')) {
        return http_response_code($newcode);
    }

    static $code = 200;

    if ($newcode !== null) {
        if (!headers_sent()) {
            header('X-PHP-Response-Code: ' . $newcode, true, (int) $newcode);
            $code = (int) $newcode;
        }
    }

    return $code;
}

function CryptoRandomBytes($length)
{
    if (function_exists('openssl_random_pseudo_bytes')) {
        $strong = false;
        $bytes  = openssl_random_pseudo_bytes($length, $strong);

        if ($bytes !== false && strlen($bytes) === $length && $strong) {
            return $bytes;
        }
    }

    if (function_exists('mcrypt_create_iv')) {
        $bytes = mcrypt_create_iv($length, MCRYPT_DEV_URANDOM);
        return strlen($bytes) === $length ? $bytes : false;
    }

    return false;
}

function EncryptDownloadToken($data)
{
    global $config;
    $json = json_encode($data);
    $iv   = CryptoRandomBytes(16);

    if ($json === false || $iv === false) {
        return false;
    }

    $key = hash('sha256', $config['main_password'], true);

    if (function_exists('openssl_encrypt')) {
        $options    = defined('OPENSSL_RAW_DATA')  ?OPENSSL_RAW_DATA : 1;
        $ciphertext = openssl_encrypt($json, 'AES-256-CBC', $key, $options, $iv);
    } else if (function_exists('mcrypt_encrypt')) {
        $padding    = 16 - strlen($json) % 16;
        $ciphertext = mcrypt_encrypt(MCRYPT_RIJNDAEL_128, $key, $json . str_repeat(chr($padding), $padding), MCRYPT_MODE_CBC, $iv);
    } else {
        return false;
    }

    if ($ciphertext === false) {
        return false;
    }

    $payload = $iv . $ciphertext;
    $mac     = pack('H*', hmac_sha256($payload, $key));
    return Base64URLSafeEncode($payload . $mac);
}

function DecryptDownloadToken($token)
{
    global $config;
    $decoded   = Base64URLSafeDecode($token);
    $macLength = function_exists('hash_hmac') ? 32 : 20;

    if ($decoded === false || strlen($decoded) < 32 + $macLength || (strlen($decoded) - 16 - $macLength) % 16 !== 0) {
        return false;
    }

    $payload  = substr($decoded, 0, -$macLength);
    $mac      = substr($decoded, -$macLength);
    $key      = hash('sha256', $config['main_password'], true);
    $expected = pack('H*', hmac_sha256($payload, $key));

    if (!CompareStringSafe($mac, $expected)) {
        return false;
    }

    $iv         = substr($payload, 0, 16);
    $ciphertext = substr($payload, 16);

    if (function_exists('openssl_decrypt')) {
        $options = defined('OPENSSL_RAW_DATA')  ?OPENSSL_RAW_DATA : 1;
        $json    = openssl_decrypt($ciphertext, 'AES-256-CBC', $key, $options, $iv);
    } else if (function_exists('mcrypt_decrypt')) {
        $json    = mcrypt_decrypt(MCRYPT_RIJNDAEL_128, $key, $ciphertext, MCRYPT_MODE_CBC, $iv);
        $padding = ord(substr($json, -1));

        if ($padding < 1 || $padding > 16 || substr($json, -$padding) !== str_repeat(chr($padding), $padding)) {
            return false;
        }

        $json = substr($json, 0, -$padding);
    } else {
        return false;
    }

    if ($json === false) {
        return false;
    }

    $data = json_decode($json, true);
    return is_array($data) ? $data : false;
}

function GetModule($path)
{
    $self     = file_get_contents(__FILE__);
    $pathinfo = pathinfo($path);

    switch ($pathinfo['extension']) {
        case 'css':
            $startFlag = "<!----- FILE {$path} START -----><style>";
            $endFlag   = "</style><!----- FILE {$path} END ----->";
            break;
        case 'js':
        case 'json':
            $startFlag = "<!----- FILE {$path} START -----><script>";
            $endFlag   = "</script><!----- FILE {$path} END ----->";
            break;
        default:
            $startFlag = "<!----- FILE {$path} START ----->";
            $endFlag   = "<!----- FILE {$path} END ----->";
            break;
    }

    $start = strrpos($self, $startFlag) + strlen($startFlag);
    $end   = strpos($self, $endFlag, $start);

    if ($start === false || $end === false) {
        return false;
    }

    return trim(substr($self, $start, $end - $start));
}

function GetPost()
{
    $data = file_get_contents('php://input');
    return json_decode($data, true);
}

function GetUserByUsername($username)
{
    global $config;

    foreach ($config['users'] as $user) {
        if ($user['username'] === $username) {
            return $user;
        }
    }

    return null;
}

function CheckInvalidReferer()
{
    list($referer) = explode('?', $_SERVER['HTTP_REFERER']);
    return $referer === $_SESSION['referer'];
}

function packJ($value)
{
    if (PHP_INT_SIZE === 8 && version_compare(PHP_VERSION, '5.6.3', '>=')) {
        return pack('J', $value);
    }

    $result = '';

    for ($i = 7; $i >= 0; $i--) {
        $result .= chr(($value >> ($i * 8)) & 0xFF);
    }

    return $result;
}

function hmac_sha256($data, $salt)
{
    return function_exists('hash_hmac') ? hash_hmac('sha256', $data, $salt) : hmac_sha1($data, $salt);
}

function HashUserPassword($password, $salt)
{
    return BcryptHash(hmac_sha256($password, $salt), 12);
}

function VerifyUserPassword($password, $salt, $hash)
{
    $digest = hmac_sha256($password, $salt);

    if (IsBcryptHash($hash)) {
        return BcryptVerify($digest, $hash);
    }

    return CompareStringSafe($digest, $hash);
}

function IsBcryptHash($hash)
{
    return is_string($hash) && preg_match('/^\$2[aby]\$\d\d\$[\.\/A-Za-z0-9]{53}$/', $hash) === 1;
}

function BcryptHash($value, $cost)
{
    $cost = max(intval($cost), 4);

    if (defined('PASSWORD_BCRYPT') && function_exists('password_hash')) {
        $hash = password_hash($value, PASSWORD_BCRYPT, array('cost' => $cost));

        if ($hash !== false) {
            return $hash;
        }
    }

    $salt = '$2y$' . str_pad($cost, 2, '0', STR_PAD_LEFT) . '$' . GenerateBcryptSalt();
    $hash = crypt($value, $salt);

    if (!is_string($hash) || strlen($hash) < 13 || strpos($hash, '*') === 0) {
        exit('Need Blowfish support to hash passwords.');
    }

    return $hash;
}

function BcryptVerify($value, $hash)
{
    if (function_exists('password_verify')) {
        return password_verify($value, $hash);
    }

    $verify = crypt($value, $hash);
    return is_string($verify) && CompareStringSafe($verify, $hash);
}

function BcryptNeedsRehash($hash, $cost)
{
    if (!IsBcryptHash($hash)) {
        return true;
    }

    $cost = str_pad(max(intval($cost), 4), 2, '0', STR_PAD_LEFT);

    if (function_exists('password_needs_rehash') && defined('PASSWORD_BCRYPT')) {
        return password_needs_rehash($hash, PASSWORD_BCRYPT, array('cost' => intval($cost)));
    }

    return substr($hash, 4, 2) !== $cost;
}

function GenerateBcryptSalt($length = 22)
{
    $chars = './ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    $salt  = '';

    for ($i = 0; $i < $length; ++$i) {
        $salt .= $chars[SafeRand(0, 63)];
    }

    return $salt;
}

function CompareStringSafe($left, $right)
{
    if (!is_string($left) || !is_string($right)) {
        return false;
    }

    if (function_exists('hash_equals')) {
        return hash_equals($left, $right);
    }

    $leftLength  = strlen($left);
    $rightLength = strlen($right);
    $diff        = $leftLength ^ $rightLength;
    $length      = max($leftLength, $rightLength);

    for ($i = 0; $i < $length; ++$i) {
        $leftChar  = $i < $leftLength ? ord($left[$i]) : 0;
        $rightChar = $i < $rightLength ? ord($right[$i]) : 0;
        $diff |= $leftChar ^ $rightChar;
    }

    return $diff === 0;
}

function hmac_sha1($data, $salt, $raw_output = false)
{
    if (function_exists('hash_hmac')) {
        return hash_hmac('sha1', $data, $salt, $raw_output);
    }

    strlen($salt) > 64 && $salt = sha1($salt, true);

    $salt   = str_pad($salt, 64, chr(0x00));
    $ipad   = str_repeat(chr(0x36), 64);
    $opad   = str_repeat(chr(0x5C), 64);
    $k_ipad = $salt ^ $ipad;
    $inner  = sha1($k_ipad . $data, true);
    $k_opad = $salt ^ $opad;
    $result = sha1($k_opad . $inner, true);

    return $raw_output ? $result : bin2hex($result);
}

function GenerateTOTP($secret, $timestamp)
{
    $secret           = Base32Decode($secret);
    $timeCounter      = floor($timestamp / 30);
    $timeCounterBytes = packJ($timeCounter);
    $hash             = hmac_sha1($timeCounterBytes, $secret, true);
    $offset           = ord($hash[19]) & 0xF;

    $A    = (ord($hash[$offset]) & 0x7F) << 24;
    $B    = (ord($hash[$offset + 1]) & 0xFF) << 16;
    $C    = (ord($hash[$offset + 2]) & 0xFF) << 8;
    $D    = (ord($hash[$offset + 3]) & 0xFF);
    $code = $A | $B | $C | $D;

    $otp = $code % pow(10, 6);
    return str_pad($otp, 6, '0', STR_PAD_LEFT);
}

function GenerateTOTPSecret($length)
{
    $chars  = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    $length = intval($length);

    if ($length < 16) {
        $length = 16;
    }

    $secret = '';

    for ($i = 0; $i < $length; ++$i) {
        $secret .= $chars[SafeRand(0, 31)];
    }

    return $secret;
}

function Base32Decode($secret)
{
    $chars      = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    $buffer     = 0;
    $bufferSize = 0;
    $result     = '';
    $charsArray = str_split(strtoupper($secret));

    foreach ($charsArray as $char) {
        $pos = strpos($chars, $char);

        if ($pos === false) {
            continue;
        }

        $buffer <<= 5;
        $buffer |= $pos;
        $bufferSize += 5;

        if ($bufferSize >= 8) {
            $bufferSize -= 8;
            $result .= chr(($buffer >> $bufferSize) & 0xFF);
        }
    }

    return $result;
}

