function MimeContentType($filename)
{
    if (IsWebP($filename)) {
        return 'image/webp';
    }

    if (version_compare(PHP_VERSION, '5.3.0', '<') && function_exists('mime_content_type')) {
        $mime = mime_content_type($filename);
    } else {
        $file = finfo_open(FILEINFO_MIME_TYPE);
        $mime = finfo_file($file, $filename);
        finfo_close($file);
    }

    $fix = array(
        'image/svg' => 'image/svg+xml',
    );

    return isset($fix[$mime]) ? $fix[$mime] : $mime;
}

function IsWebP($filename)
{
    $handle = @fopen($filename, 'rb');

    if (!$handle) {
        return false;
    }

    $bytes = fread($handle, 12);
    fclose($handle);

    if (strlen($bytes) >= 12) {
        $riff = substr($bytes, 0, 4);
        $webp = substr($bytes, 8, 4);
        return $riff === 'RIFF' && $webp === 'WEBP';
    }

    return false;
}

function UserPath($base, $path, $unsafe = false, $followLink = true)
{
    $path = str_replace("\0", '', $path);
    $path = preg_replace('/[\x00-\x1F\x7F]/', '', $path);
    $path = preg_replace('/[\*\?\\\'\"<>\|]/', '', $path);

    $matches = array();

    if (IS_WINDOWS && preg_match_all('/[A-Za-z]:/', $path, $matches, PREG_OFFSET_CAPTURE)) {
        $lastMatch = end($matches[0]);
        $path      = substr($path, $lastMatch[1]);
    }

    $unsafe   = $base === '/'  ?true : !!$unsafe;
    $base     = rtrim(realpath($base), '/\\');
    $userPath = $base . '/' . $path;

    if (IS_WINDOWS) {
        if (preg_match('/^[a-zA-Z]:/', $path)) {
            $userPath = $path;
        }
    } else {
        if (strpos($path, '/') === 0) {
            $userPath = $path;
        }
    }

    while (strpos($userPath, '\\') !== false) {
        $userPath = str_replace('\\', '/', $userPath);
    }

    while (strpos($userPath, '//') !== false) {
        $userPath = str_replace('//', '/', $userPath);
    }

    $userPath  = $userPath !== '/' ? rtrim($userPath, '/') : $userPath;
    $userSplit = explode('/', $userPath);
    $root      = array_shift($userSplit);
    $pathStack = array();

    foreach ($userSplit as $part) {
        if ($part === '.') {
            continue;
        } else if ($part === '..') {
            array_pop($pathStack);
        } else {
            array_push($pathStack, $part);
        }
    }

    foreach ($pathStack as $part) {
        if (!ValidFilename($part)) {
            return false;
        }
    }

    if (IS_WINDOWS) {
        $currentPath = $root;

        foreach ($pathStack as $part) {
            $nextPath = rtrim($currentPath, '/\\') . '\\' . $part;

            if ($followLink && is_link($nextPath)) {
                $realPath = realpath($nextPath);

                if ($realPath === false) {
                    return false;
                }

                $currentPath = $realPath;
            } else {
                $currentPath = $nextPath;
            }
        }

        $finalPath = $currentPath;
    } else {
        $currentPath = $root === '' ? '/' : $root;

        foreach ($pathStack as $part) {
            $nextPath = $currentPath === '/' ? '/' . $part : rtrim($currentPath, '/') . '/' . $part;

            if ($followLink && is_link($nextPath)) {
                $realPath = realpath($nextPath);

                if ($realPath === false) {
                    return false;
                }

                $currentPath = $realPath;
            } else {
                $currentPath = $nextPath;
            }
        }

        $finalPath = $currentPath;
    }

    $finalPath = $finalPath === '' ? '/' : $finalPath;

    if (IS_WINDOWS) {
        $finalPath       = str_replace('/', '\\', $finalPath);
        $baseNormalized  = rtrim(str_replace('/', '\\', $base), '\\');
        $finalNormalized = rtrim($finalPath, '\\');

        if ($baseNormalized === '') {
            $checkSafe = false;
        } else {
            $basePrefix = $baseNormalized . '\\';
            $checkSafe  = strcasecmp($finalNormalized, $baseNormalized) === 0 || strcasecmp(substr($finalNormalized, 0, strlen($basePrefix)), $basePrefix) === 0;
        }
    } else {
        $baseNormalized  = rtrim($base, '/');
        $baseNormalized  = $baseNormalized === '' ? '/' : $baseNormalized;
        $finalNormalized = $finalPath === '/' ? '/' : rtrim($finalPath, '/');
        $basePrefix      = $baseNormalized === '/' ? '/' : $baseNormalized . '/';
        $checkSafe       = $finalNormalized === $baseNormalized || strpos($finalNormalized, $basePrefix) === 0;
    }

    return $unsafe || $checkSafe ? $finalPath : false;
}

function IsSamePath($left, $right)
{
    if (!is_string($left) || !is_string($right) || $left === '' || $right === '') {
        return false;
    }

    if (IS_WINDOWS) {
        $left  = str_replace('/', '\\', $left);
        $right = str_replace('/', '\\', $right);

        $left  = rtrim($left, '\\');
        $right = rtrim($right, '\\');

        return strcasecmp($left, $right) === 0;
    }

    $left  = $left === '/' ? '/' : rtrim($left, '/');
    $right = $right === '/' ? '/' : rtrim($right, '/');
    return $left === $right;
}

function IsPathInside($path, $parent)
{
    if (!is_string($path) || !is_string($parent) || $path === '' || $parent === '') {
        return false;
    }

    if (IS_WINDOWS) {
        $path   = rtrim(str_replace('/', '\\', $path), '\\');
        $parent = rtrim(str_replace('/', '\\', $parent), '\\');
        return strncasecmp($path, $parent . '\\', strlen($parent) + 1) === 0;
    }

    $path   = $path === '/' ? '/' : rtrim($path, '/');
    $parent = $parent === '/' ? '/' : rtrim($parent, '/');
    $prefix = $parent === '/' ? '/' : $parent . '/';
    return strpos($path, $prefix) === 0 && $path !== $parent;
}

function RelativeUserPath($path, $base)
{
    $path = str_replace('\\', '/', $path);

    if (IS_WINDOWS && $base === '/') {
        return rtrim($path, '/');
    }

    $base = str_replace('\\', '/', $base);
    $path = $path === '/' ? '/' : rtrim($path, '/');
    $base = $base === '/' ? '/' : rtrim($base, '/');

    if (IsSamePath($path, $base)) {
        return '';
    }

    if (IsPathInside($path, $base)) {
        return substr($path, strlen($base === '/' ? '/' : $base . '/'));
    }

    $pathParts = explode('/', trim($path, '/'));
    $baseParts = explode('/', trim($base, '/'));

    while (count($pathParts) && count($baseParts) && (IS_WINDOWS ? strcasecmp($pathParts[0], $baseParts[0]) === 0 : $pathParts[0] === $baseParts[0])) {
        array_shift($pathParts);
        array_shift($baseParts);
    }

    return str_repeat('../', count($baseParts)) . implode('/', $pathParts);
}

function ModuleNeedLogin($module)
{
    $whiteList = array(
        'js/zepto.js',
        'js/global.js',
        'js/login.js',
        'css/global.css',
        'css/login.css',
        'img/login/language.svg',
    );

    $whitePrefix = array(
        'lang/',
        'img/common/',
    );

    if (in_array($module, $whiteList)) {
        return false;
    }

    foreach ($whitePrefix as $prefix) {
        if (strpos($module, $prefix) === 0) {
            return false;
        }
    }

    return true;
}

function ModuleNeedAdmin($module)
{
    $needAdminList = array('html/config.html', 'css/config.css', 'js/config.js');
    return in_array($module, $needAdminList);
}

function ValidFileName($filename)
{
    if (empty($filename)) {
        return false;
    }

    if (strlen($filename) > 255) {
        return false;
    }

    if (in_array($filename, array('.'))) {
        return false;
    }

    if (strpos($filename, '..') !== false) {
        return false;
    }

    $invalidChars = array('\\', '/', ':', '*', '?', '"', '<', '>', '|');

    foreach ($invalidChars as $char) {
        if (strpos($filename, $char) !== false) {
            return false;
        }
    }

    for ($i = 0; $i < strlen($filename); ++$i) {
        if (ord($filename[$i]) < 32) {
            return false;
        }
    }

    if (IS_WINDOWS) {
        if (preg_match('/^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\..*)?$/i', $filename)) {
            return false;
        }
    }

    return true;
}

function ValidFileExtension($filename, $allow = '', $deny = '')
{
    $allow = is_string($allow) ? $allow : '';
    $deny  = is_string($deny) ? $deny : '';

    $ext    = strtolower(pathinfo($filename, PATHINFO_EXTENSION));
    $noExt  = (strpos($filename, '.') === false || $ext === '');
    $extKey = $noExt ? '?' : $ext;

    if ($allow !== '') {
        $allowList = array_map('trim', explode(',', $allow));
        $allowList = array_map('strtolower', $allowList);
        $allowList = array_values(array_filter($allowList, 'strlen'));

        if (!in_array($extKey, $allowList, true)) {
            return false;
        }
    }

    if ($deny !== '') {
        $denyList = array_map('trim', explode(',', $deny));
        $denyList = array_map('strtolower', $denyList);
        $denyList = array_values(array_filter($denyList, 'strlen'));

        if (in_array($extKey, $denyList, true)) {
            return false;
        }
    }

    return true;
}

function ArchiveTypeAllowed($archiveType, $allow = '', $deny = '')
{
    $archiveType = strtolower(trim(strval($archiveType)));

    if ($archiveType === 'zip') {
        return ValidFileExtension('archive.zip', $allow, $deny);
    }

    if ($archiveType === 'gz') {
        return ValidFileExtension('archive.gz', $allow, $deny);
    }

    return true;
}

function CreatePath($path = '', $content = '', $cover = false, $maxBytes = false)
{
    if (gettype($content) !== 'string') {
        return GetError(MkDirs($path) ? 'success' : 'create_file_failed');
    }

    if ($maxBytes !== false && strlen($content) > $maxBytes) {
        return GetError('write_size_exceeded');
    }

    MkDirs(dirname($path));

    if (is_dir($path)) {
        return GetError('path_not_file');
    }

    if ($cover === false && file_exists($path)) {
        return GetError('file_exists');
    }

    if (file_put_contents($path, $content) === false) {
        return GetError('create_file_failed');
    }

    return GetError('success');
}

function RemovePath($path)
{
    if (!file_exists($path)) {
        return false;
    }

    if (is_link($path)) {
        if (@unlink($path)) {
            return true;
        }

        return @rmdir($path);
    }

    if (is_file($path)) {
        return unlink($path);
    }

    $items = scandir($path);

    foreach ($items as $item) {
        if ($item === '.' || $item === '..') {
            continue;
        }

        RemovePath($path . '/' . $item);
    }

    return rmdir($path);
}

function CompareItems($a, $b)
{
    if ($a['type'] === 'folder' && $b['type'] === 'file') {
        return -1;
    } else if ($a['type'] === 'file' && $b['type'] === 'folder') {
        return 1;
    } else {
        return strcasecmp($a['name'], $b['name']);
    }
}

function JSONEncode($data)
{
    if (version_compare(PHP_VERSION, '5.4.0', '>=')) {
        return json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES);
    }

    if (version_compare(PHP_VERSION, '5.3.0', '>=')) {
        return str_replace('\\/', '/', json_encode($data, JSON_PRETTY_PRINT));
    }

    $json     = json_encode($data);
    $result   = '';
    $indent   = '    ';
    $level    = 0;
    $inQuotes = false;
    $len      = strlen($json);

    for ($i = 0; $i < $len; ++$i) {
        $char = $json[$i];

        if ($char === '"' && $i > 0 && $json[$i - 1] !== '\\') {
            $inQuotes = !$inQuotes;
        }

        if ($inQuotes) {
            $result .= $char;
            continue;
        }

        switch ($char) {
            case '{':
            case '[':
                $result .= $char . "\n" . str_repeat($indent, ++$level);
                break;
            case '}':
            case ']':
                $result .= "\n" . str_repeat($indent, --$level) . $char;
                break;
            case ',':
                $result .= ",\n" . str_repeat($indent, $level);
                break;
            case ':':
                $result .= ': ';
                break;
            default:
                $result .= $char;
        }
    }

    return str_replace('\\/', '/', $result);
}

function MkDirs($path)
{
    $dirs        = explode('/', str_replace('\\', '/', rtrim($path, '/\\')));
    $currentPath = '';

    foreach ($dirs as $dir) {
        $currentPath .= $dir . '/';

        if (file_exists($currentPath)) {
            if (is_file($currentPath)) {
                return false;
            }
        } else {
            if (!mkdir($currentPath)) {
                return false;
            }
        }
    }

    return true;
}

function RandStr($len = 64)
{
    $word = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    $str  = '';

    for ($i = 0; $i < $len; ++$i) {
        $str .= $word[SafeRand(0, 61)];
    }

    return $str;
}

function SafeRand($min, $max)
{
    $range = $max - $min;

    if ($range < 1) {
        return $min;
    }

    if (function_exists('random_int')) {
        try {
            return @random_int($min, $max);
        } catch (Exception $e) {
        }
    }

    $o = function_exists('openssl_random_pseudo_bytes');
    $m = function_exists('mcrypt_create_iv');

    if ($o || $m) {
        $log    = ceil(log($range, 2));
        $bytes  = (int) ceil($log / 8);
        $filter = (int) (1 << $log) - 1;

        do {
            $bin  = $o ? openssl_random_pseudo_bytes($bytes) : mcrypt_create_iv($bytes, MCRYPT_DEV_URANDOM);
            $rand = hexdec(bin2hex($bin)) & $filter;
        } while ($rand > $range);

        return $min + $rand;
    }

    return mt_rand($min, $max);
}

function SafeWrite($filename, $data, $timeout = 10)
{
    $writeLock = sys_get_temp_dir() . DIRECTORY_SEPARATOR . 'vsfile_write_lock_' . md5($filename);
    file_exists($writeLock) && time() - filectime($writeLock) > 1 && @unlink($writeLock);
    clearstatcache(true, $writeLock);

    $startTime = time();
    $locked    = false;

    while (time() - $startTime < $timeout) {
        clearstatcache(true, $writeLock);

        if (file_exists($writeLock)) {
            $locked = true;
            usleep(100000);
            continue;
        } else {
            $locked = false;
            break;
        }
    }

    if ($locked) {
        return false;
    }

    file_put_contents($writeLock, 'lock');
    $handle = fopen($filename, 'w+');

    if (!$handle) {
        @unlink($writeLock);
        return false;
    }

    $startTime = time();
    $locked    = false;

    while (time() - $startTime < $timeout) {
        if (flock($handle, LOCK_EX | LOCK_NB)) {
            $locked = true;
            break;
        }

        usleep(100000);
    }

    if (!$locked) {
        fclose($handle);
        @unlink($writeLock);
        return false;
    }

    $result = fwrite($handle, $data . PHP_EOL);
    fflush($handle);
    flock($handle, LOCK_UN);
    fclose($handle);
    @unlink($writeLock);
    return $result !== false;
}

function CopyFileChunked($source, $destination, $chunkSize = 8192, $maxBytes = false)
{
    if (!file_exists($source)) {
        return GetError('file_not_found');
    }

    $sourceHandle = fopen($source, 'rb');

    if (!$sourceHandle) {
        return GetError('read_file_failed');
    }

    $mkdirs = MkDirs(dirname($destination));

    if (!$mkdirs) {
        return GetError('create_directory_failed');
    }

    $destHandle = fopen($destination, 'wb');

    if (!$destHandle) {
        fclose($sourceHandle);
        return GetError('create_file_failed');
    }

    $written = 0;

    try {
        while (!feof($sourceHandle)) {
            $chunk = fread($sourceHandle, $chunkSize);

            if ($chunk === false) {
                return GetError('read_file_failed');
            }

            if ($maxBytes !== false && $written + strlen($chunk) > $maxBytes) {
                fclose($sourceHandle);
                fclose($destHandle);
                file_exists($destination) && unlink($destination);
                return GetError('write_size_exceeded');
            }

            $bytesWritten = fwrite($destHandle, $chunk);

            if ($bytesWritten === false) {
                return GetError('write_file_failed');
            }

            $written += $bytesWritten;
        }

        fflush($destHandle);
    } catch (Exception $e) {
    }

    fclose($sourceHandle);
    fclose($destHandle);
    return GetError('success');
}

function CopyLinkPath($source, $destination)
{
    if (!function_exists('symlink')) {
        return GetError('invalid_type');
    }

    $linkTarget = readlink($source);

    if ($linkTarget === false) {
        return GetError('read_file_failed');
    }

    if (!MkDirs(dirname($destination))) {
        return GetError('create_directory_failed');
    }

    return GetError(symlink($linkTarget, $destination) ? 'success' : 'create_file_failed');
}

function ValidateCopyPath($source, $allow = '', $deny = '', $maxBytes = false)
{
    if (is_link($source)) {
        return GetError('success');
    }

    if (is_file($source)) {
        if (!ValidFileExtension(basename($source), $allow, $deny)) {
            return GetError('not_allowed_extension');
        }

        $size = filesize($source);

        if ($size === false) {
            return GetError('read_file_failed');
        }

        if ($maxBytes !== false && $size > $maxBytes) {
            return GetError('write_size_exceeded');
        }

        return GetError('success');
    }

    if (!is_dir($source)) {
        return GetError('file_not_found');
    }

    $items = scandir($source);

    if ($items === false) {
        return GetError('read_file_failed');
    }

    foreach ($items as $item) {
        if ($item === '.' || $item === '..') {
            continue;
        }

        $result = ValidateCopyPath($source . '/' . $item, $allow, $deny, $maxBytes);

        if ($result['code']) {
            return $result;
        }
    }

    return GetError('success');
}

function CopyPath($source, $destination, $allow = '', $deny = '', $maxBytes = false)
{
    if (!file_exists($source)) {
        return GetError('file_not_found');
    }

    if (file_exists($destination)) {
        return GetError('file_exists');
    }

    if (IsSamePath($source, $destination)) {
        return GetError('invalid_request');
    }

    if (is_link($source)) {
        if (file_exists($destination)) {
            return GetError('file_exists');
        }

        return CopyLinkPath($source, $destination);
    }

    if (is_dir($source) && IsPathInside($destination, $source)) {
        return GetError('path_inside_source');
    }

    $validation = ValidateCopyPath($source, $allow, $deny, $maxBytes);

    if ($validation['code']) {
        return $validation;
    }

    if (is_file($source)) {
        return CopyFileChunked($source, $destination, 8192, $maxBytes);
    }

    if (!MkDirs(dirname($destination)) || !mkdir($destination)) {
        return GetError('create_directory_failed');
    }

    $items = scandir($source);

    if ($items === false) {
        RemovePath($destination);
        return GetError('read_file_failed');
    }

    foreach ($items as $item) {
        if ($item === '.' || $item === '..') {
            continue;
        }

        $result = CopyPath($source . '/' . $item, $destination . '/' . $item, $allow, $deny, $maxBytes);

        if ($result['code']) {
            RemovePath($destination);
            return $result;
        }
    }

    return GetError('success');
}

function GetUniqueCopyPath($path, $isFile = false)
{
    $directory = dirname($path);
    $filename  = basename($path);
    $extension = '';

    if ($isFile) {
        $dotIndex = strrpos($filename, '.');

        if ($dotIndex > 0) {
            $extension = substr($filename, $dotIndex);
            $filename  = substr($filename, 0, $dotIndex);
        }
    }

    $baseName  = $filename;
    $nextIndex = 1;

    while (file_exists($path)) {
        $match = array();

        if (preg_match('/^(.*)\((\d+)\)$/', $filename, $match)) {
            $baseName  = $match[1];
            $nextIndex = intval($match[2]) + 1;
        } else {
            $baseName  = $filename;
            $nextIndex = 1;
        }

        $filename = $baseName . '(' . $nextIndex . ')';
        $path     = JoinPath($directory, $filename . $extension);
    }

    return $path;
}

function JoinPath($directory, $name)
{
    if ($directory === DIRECTORY_SEPARATOR) {
        return $directory . $name;
    }

    return rtrim($directory, '/\\') . DIRECTORY_SEPARATOR . $name;
}

function GetUniqueDirectoryPath($path)
{
    $directory = dirname($path);
    $filename  = basename($path);
    $baseName  = $filename;
    $nextIndex = 1;

    while (file_exists($path)) {
        $match = array();

        if (preg_match('/^(.*)\((\d+)\)$/', $filename, $match)) {
            $baseName  = $match[1];
            $nextIndex = intval($match[2]) + 1;
        } else {
            $baseName  = $filename;
            $nextIndex = 1;
        }

        $filename = $baseName . '(' . $nextIndex . ')';
        $path     = JoinPath($directory, $filename);
    }

    return $path;
}

function ZipAddPath($zip, $sourcePath, $entryPath)
{
    if (is_link($sourcePath)) {
        return true;
    }

    $entryPath = trim(str_replace('\\', '/', $entryPath), '/');

    if ($entryPath === '') {
        $entryPath = basename($sourcePath);
    }

    if ($entryPath === '') {
        return false;
    }

    if (is_file($sourcePath)) {
        return $zip->addFile($sourcePath, $entryPath);
    }

    if (!is_dir($sourcePath)) {
        return false;
    }

    if (!$zip->addEmptyDir($entryPath)) {
        return false;
    }

    $items = scandir($sourcePath);

    if ($items === false) {
        return false;
    }

    foreach ($items as $item) {
        if ($item === '.' || $item === '..') {
            continue;
        }

        $childSource = JoinPath($sourcePath, $item);
        $childEntry  = $entryPath . '/' . $item;

        if (!ZipAddPath($zip, $childSource, $childEntry)) {
            return false;
        }
    }

    return true;
}

function ZipEntryIsSafe($entry)
{
    if (!is_string($entry) || $entry === '' || strpos($entry, "\0") !== false) {
        return false;
    }

    $entry = str_replace('\\', '/', $entry);

    while (strpos($entry, '//') !== false) {
        $entry = str_replace('//', '/', $entry);
    }

    if (preg_match('/^[A-Za-z]:\//', $entry)) {
        return false;
    }

    if (strpos($entry, '/') === 0) {
        return false;
    }

    $trimmed = rtrim($entry, '/');

    if ($trimmed === '') {
        return false;
    }

    $parts = explode('/', $trimmed);

    foreach ($parts as $part) {
        if ($part === '' || $part === '.' || $part === '..') {
            return false;
        }

        if (!ValidFileName($part)) {
            return false;
        }
    }

    return true;
}

function GetSafeZipEntries($zip, $allow = '', $deny = '')
{
    $entries = array();
    $count   = intval($zip->numFiles);

    for ($i = 0; $i < $count; ++$i) {
        $entry = $zip->getNameIndex($i);

        if (!ZipEntryIsSafe($entry)) {
            return false;
        }

        $isSymlink = false;

        if (method_exists($zip, 'getExternalAttributesIndex')) {
            $opsys = 0;
            $attr  = 0;
            $flags = 0;
            $zip->getExternalAttributesIndex($i, $opsys, $attr, $flags);
            $mode      = (($attr >> 16) & 0xFFFF);
            $isSymlink = (($mode & 0xF000) === 0xA000);
        }

        if ($isSymlink) {
            continue;
        }

        if (substr($entry, -1) !== '/' && !ValidFileExtension(basename($entry), $allow, $deny)) {
            continue;
        }

        array_push($entries, $entry);
    }

    return $entries;
}

function GetSafeTgzEntries($archivePath, $allow = '', $deny = '')
{
    $archiveRoot   = 'phar://' . str_replace('\\', '/', $archivePath);
    $archivePrefix = rtrim($archiveRoot, '/') . '/';
    $entries       = array();
    $iterator      = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($archiveRoot), RecursiveIteratorIterator::SELF_FIRST);

    foreach ($iterator as $fileInfo) {
        $filename = $fileInfo->getFilename();

        if ($filename === '.' || $filename === '..') {
            continue;
        }

        if (method_exists($fileInfo, 'isLink') && $fileInfo->isLink()) {
            continue;
        }

        $entryPath = str_replace('\\', '/', $fileInfo->getPathname());

        if (strpos($entryPath, $archivePrefix) !== 0) {
            return false;
        }

        $entry = substr($entryPath, strlen($archivePrefix));
        $entry = trim($entry, '/');

        if ($entry === '') {
            continue;
        }

        if (!ZipEntryIsSafe($entry)) {
            return false;
        }

        if (!$fileInfo->isDir() && !ValidFileExtension(basename($entry), $allow, $deny)) {
            continue;
        }

        array_push($entries, $entry);
    }

    return $entries;
}

function ReadUInt16LE($data, $offset)
{
    $value = unpack('v', substr($data, $offset, 2));
    return isset($value[1]) ? $value[1] : 0;
}

function ReadUInt32LE($data, $offset)
{
    $value = unpack('V', substr($data, $offset, 4));
    return isset($value[1]) ? $value[1] : 0;
}

function PeRvaToOffset($rva, $sections)
{
    $count = count($sections);

    for ($i = 0; $i < $count; ++$i) {
        $section     = $sections[$i];
        $virtualSize = $section['virtual_size'];
        $rawSize     = $section['size_of_raw_data'];
        $size        = $virtualSize > 0 ? $virtualSize : $rawSize;

        if ($rva >= $section['virtual_address'] && $rva < $section['virtual_address'] + $size) {
            return $section['pointer_to_raw_data'] + ($rva - $section['virtual_address']);
        }
    }

    return false;
}

function PeReadResourceData($data, $baseOffset, $directoryOffset, $sections, $typeId, $nameId, $languageId)
{
    $root = $baseOffset + $directoryOffset;

    if ($root + 16 > strlen($data)) {
        return false;
    }

    $entryCount  = ReadUInt16LE($data, $root + 12) + ReadUInt16LE($data, $root + 14);
    $entryOffset = $root + 16;

    for ($i = 0; $i < $entryCount; ++$i) {
        $entry    = $entryOffset + $i * 8;
        $nameRaw  = ReadUInt32LE($data, $entry);
        $childRaw = ReadUInt32LE($data, $entry + 4);

        if ($nameRaw & 0x80000000) {
            continue;
        }

        if ($typeId !== null && ($nameRaw & 0xffff) !== $typeId) {
            continue;
        }

        if (!($childRaw & 0x80000000)) {
            continue;
        }

        $nameDirOffset = $baseOffset + ($childRaw & 0x7fffffff);
        if ($nameDirOffset + 16 > strlen($data)) {
            return false;
        }

        $entryCount2  = ReadUInt16LE($data, $nameDirOffset + 12) + ReadUInt16LE($data, $nameDirOffset + 14);
        $entryOffset2 = $nameDirOffset + 16;

        for ($j = 0; $j < $entryCount2; ++$j) {
            $entry2    = $entryOffset2 + $j * 8;
            $nameRaw2  = ReadUInt32LE($data, $entry2);
            $childRaw2 = ReadUInt32LE($data, $entry2 + 4);

            if ($nameId !== null && ($nameRaw2 & 0x80000000)) {
                continue;
            }

            if ($nameId !== null && ($nameRaw2 & 0xffff) !== $nameId) {
                continue;
            }

            if (!($childRaw2 & 0x80000000)) {
                continue;
            }

            $langDirOffset = $baseOffset + ($childRaw2 & 0x7fffffff);
            if ($langDirOffset + 16 > strlen($data)) {
                return false;
            }

            $entryCount3  = ReadUInt16LE($data, $langDirOffset + 12) + ReadUInt16LE($data, $langDirOffset + 14);
            $entryOffset3 = $langDirOffset + 16;

            for ($k = 0; $k < $entryCount3; ++$k) {
                $entry3   = $entryOffset3 + $k * 8;
                $nameRaw3 = ReadUInt32LE($data, $entry3);
                $dataRaw3 = ReadUInt32LE($data, $entry3 + 4);

                if ($nameRaw3 & 0x80000000) {
                    continue;
                }

                if ($languageId !== null && ($nameRaw3 & 0xffff) !== $languageId) {
                    continue;
                }

                if ($dataRaw3 & 0x80000000) {
                    continue;
                }

                $dataEntryOffset = $baseOffset + ($dataRaw3 & 0x7fffffff);
                if ($dataEntryOffset + 8 > strlen($data)) {
                    return false;
                }

                $rva    = ReadUInt32LE($data, $dataEntryOffset);
                $size   = ReadUInt32LE($data, $dataEntryOffset + 4);
                $offset = PeRvaToOffset($rva, $sections);

                if ($offset === false || $offset + $size > strlen($data)) {
                    return false;
                }

                return substr($data, $offset, $size);
            }
        }
    }

    return false;
}

function ExtractExeIco($exePath)
{
    $data = @file_get_contents($exePath);

    if ($data === false || strlen($data) < 0x100) {
        return false;
    }

    if (substr($data, 0, 2) !== 'MZ') {
        return false;
    }

    $peOffset = ReadUInt32LE($data, 0x3c);

    if ($peOffset <= 0 || $peOffset + 24 > strlen($data) || substr($data, $peOffset, 4) !== "PE\0\0") {
        return false;
    }

    $numberOfSections     = ReadUInt16LE($data, $peOffset + 6);
    $sizeOfOptionalHeader = ReadUInt16LE($data, $peOffset + 20);
    $optionalOffset       = $peOffset + 24;
    $optionalMagic        = ReadUInt16LE($data, $optionalOffset);

    if ($optionalMagic !== 0x10b && $optionalMagic !== 0x20b) {
        return false;
    }

    $dataDirectoryOffset = $optionalOffset + ($optionalMagic === 0x20b ? 112 : 96);
    $resourceRva         = ReadUInt32LE($data, $dataDirectoryOffset + 16);
    $resourceSize        = ReadUInt32LE($data, $dataDirectoryOffset + 20);

    if (!$resourceRva || !$resourceSize) {
        return false;
    }

    $sections      = array();
    $sectionOffset = $optionalOffset + $sizeOfOptionalHeader;

    for ($i = 0; $i < $numberOfSections; ++$i) {
        $offset = $sectionOffset + $i * 40;

        if ($offset + 40 > strlen($data)) {
            return false;
        }

        $sections[] = array(
            'virtual_size'        => ReadUInt32LE($data, $offset + 8),
            'virtual_address'     => ReadUInt32LE($data, $offset + 12),
            'size_of_raw_data'    => ReadUInt32LE($data, $offset + 16),
            'pointer_to_raw_data' => ReadUInt32LE($data, $offset + 20),
        );
    }

    $resourceOffset = PeRvaToOffset($resourceRva, $sections);

    if ($resourceOffset === false || $resourceOffset + $resourceSize > strlen($data)) {
        return false;
    }

    $groupData = PeReadResourceData($data, $resourceOffset, 0, $sections, 14, null, null);

    if ($groupData === false || strlen($groupData) < 6) {
        return false;
    }

    if (ReadUInt16LE($groupData, 0) !== 0 || ReadUInt16LE($groupData, 2) !== 1) {
        return false;
    }

    $count = ReadUInt16LE($groupData, 4);

    if ($count < 1 || strlen($groupData) < 6 + $count * 14) {
        return false;
    }

    $bestEntry = null;
    $bestImage = false;
    $bestArea  = -1;

    for ($i = 0; $i < $count; ++$i) {
        $entryOffset = 6 + $i * 14;
        $width       = ord($groupData[$entryOffset + 0]);
        $height      = ord($groupData[$entryOffset + 1]);
        $colorCount  = ord($groupData[$entryOffset + 2]);
        $planes      = ReadUInt16LE($groupData, $entryOffset + 4);
        $bitCount    = ReadUInt16LE($groupData, $entryOffset + 6);
        $iconId      = ReadUInt16LE($groupData, $entryOffset + 12);

        $iconData = PeReadResourceData($data, $resourceOffset, 0, $sections, 3, $iconId, null);

        if ($iconData === false) {
            continue;
        }

        // In an ICO directory, zero means 256 pixels.
        $actualWidth  = $width === 0 ? 256 : $width;
        $actualHeight = $height === 0 ? 256 : $height;
        $area         = $actualWidth * $actualHeight;
        $isBetter     = $bestEntry === null
        || $area > $bestArea
            || ($area === $bestArea && $bitCount > $bestEntry['bitCount'])
            || ($area === $bestArea && $bitCount === $bestEntry['bitCount'] && $colorCount > $bestEntry['colorCount'])
            || ($area === $bestArea && $bitCount === $bestEntry['bitCount'] && $colorCount === $bestEntry['colorCount'] && strlen($iconData) > strlen($bestImage));

        if ($isBetter) {
            $bestEntry = array(
                'width'      => $width,
                'height'     => $height,
                'colorCount' => $colorCount,
                'planes'     => $planes,
                'bitCount'   => $bitCount,
                'bytesInRes' => strlen($iconData),
            );
            $bestImage = $iconData;
            $bestArea  = $area;
        }
    }

    if ($bestEntry === null || $bestImage === false) {
        return false;
    }

    $ico = pack('vvv', 0, 1, 1);
    $ico .= pack(
        'CCCCvvVV',
        $bestEntry['width'],
        $bestEntry['height'],
        $bestEntry['colorCount'],
        0,
        $bestEntry['planes'],
        $bestEntry['bitCount'],
        $bestEntry['bytesInRes'],
        22
    );
    $ico .= $bestImage;

    return $ico;
}

function CheckPasteConflicts($source, $destination)
{
    if (!file_exists($source)) {
        return 0;
    }

    if (IsSamePath($source, $destination)) {
        return 0;
    }

    if (is_link($source)) {
        return file_exists($destination) ? 1 : 0;
    }

    if (is_file($source)) {
        return file_exists($destination) ? 1 : 0;
    }

    if (!is_dir($source) || !file_exists($destination)) {
        return 0;
    }

    if (!is_dir($destination)) {
        return 1;
    }

    $items = scandir($source);

    if ($items === false) {
        return 0;
    }

    $conflicts = 0;

    foreach ($items as $item) {
        if ($item === '.' || $item === '..') {
            continue;
        }

        $conflicts += CheckPasteConflicts($source . '/' . $item, $destination . '/' . $item);
    }

    return $conflicts;
}

function PastePath($source, $destination, $action, $strategy, $allow = '', $deny = '', $maxBytes = false)
{
    if (!file_exists($source)) {
        return GetError('file_not_found');
    }

    if (IsSamePath($source, $destination)) {
        if ($action === 'cut') {
            return GetError('success');
        }

        $destination = GetUniqueCopyPath($destination, is_file($source));
    }

    if (is_link($source)) {
        if (file_exists($destination)) {
            if ($strategy === 'discard') {
                return GetError('success');
            }

            if ($strategy === 'rename') {
                $destination = GetUniqueCopyPath($destination, is_file($source));
            } else {
                if (!RemovePath($destination)) {
                    return GetError('remove_failed');
                }
            }
        }

        if ($action === 'cut') {
            if (!MkDirs(dirname($destination))) {
                return GetError('create_directory_failed');
            }

            return GetError(rename($source, $destination) ? 'success' : 'move_failed');
        }

        return CopyLinkPath($source, $destination);
    }

    if (is_dir($source) && IsPathInside($destination, $source)) {
        return GetError('path_inside_source');
    }

    if (is_file($source)) {
        if (file_exists($destination)) {
            if ($strategy === 'discard') {
                return GetError('success');
            }

            if ($strategy === 'rename') {
                $destination = GetUniqueCopyPath($destination, true);
            } else {
                if (!RemovePath($destination)) {
                    return GetError('remove_failed');
                }
            }
        }

        if ($action === 'cut') {
            if (!MkDirs(dirname($destination))) {
                return GetError('create_directory_failed');
            }

            return GetError(rename($source, $destination) ? 'success' : 'move_failed');
        }

        return CopyFileChunked($source, $destination, 8192, $maxBytes);
    }

    if (!is_dir($source)) {
        return GetError('file_not_found');
    }

    if (file_exists($destination) && !is_dir($destination)) {
        if ($strategy === 'discard') {
            return GetError('success');
        }

        if ($strategy === 'rename') {
            $destination = GetUniqueCopyPath($destination, false);
        } else {
            if (!RemovePath($destination)) {
                return GetError('remove_failed');
            }
        }
    }

    if (!file_exists($destination)) {
        if ($action === 'cut') {
            if (!MkDirs(dirname($destination))) {
                return GetError('create_directory_failed');
            }

            return GetError(rename($source, $destination) ? 'success' : 'move_failed');
        }

        return CopyPath($source, $destination, $allow, $deny, $maxBytes);
    }

    $items = scandir($source);

    if ($items === false) {
        return GetError('read_file_failed');
    }

    foreach ($items as $item) {
        if ($item === '.' || $item === '..') {
            continue;
        }

        $result = PastePath($source . '/' . $item, $destination . '/' . $item, $action, $strategy, $allow, $deny, $maxBytes);

        if ($result['code']) {
            return $result;
        }
    }

    if ($action === 'cut') {
        $remaining = scandir($source);

        if ($remaining !== false && count($remaining) === 2) {
            rmdir($source);
        }
    }

    return GetError('success');
}

function IconvStream($src, $dst, $from, $to, $chunkSize = 8192, $maxBytes = false)
{
    if (!file_exists($src)) {
        return GetError('file_not_found');
    }

    if (!is_readable($src)) {
        return GetError('read_file_failed');
    }

    $srcHandle = @fopen($src, 'rb');

    if ($srcHandle === false) {
        return GetError('read_file_failed');
    }

    $dstHandle = @fopen($dst, 'wb');

    if ($dstHandle === false) {
        fclose($srcHandle);
        return GetError('create_file_failed');
    }

    if (!stream_filter_append($srcHandle, 'convert.iconv.' . $from . '.' . $to, STREAM_FILTER_READ)) {
        fclose($srcHandle);
        fclose($dstHandle);
        return GetError('read_file_failed');
    }

    $success       = true;
    $written       = 0;
    $limitExceeded = false;

    while (!feof($srcHandle)) {
        $data = fread($srcHandle, $chunkSize);

        if ($data === false) {
            $success = false;
            break;
        }

        if ($maxBytes !== false && $written + strlen($data) > $maxBytes) {
            $success       = false;
            $limitExceeded = true;
            break;
        }

        if (fwrite($dstHandle, $data) === false) {
            $success = false;
            break;
        }

        $written += strlen($data);
    }

    fclose($srcHandle);
    fclose($dstHandle);
    !$success && file_exists($dst) && unlink($dst);
    return $success ? GetError('success') : GetError($limitExceeded ? 'write_size_exceeded' : 'write_file_failed');
}

function CaculatePathSize($path)
{
    if (is_link($path)) {
        $stat = @lstat($path);

        if (is_array($stat) && isset($stat['size'])) {
            return intval($stat['size']);
        }

        $size = @filesize($path);
        return $size === false ? 0 : intval($size);
    }

    if (is_file($path)) {
        return filesize($path);
    }

    if (!is_dir($path)) {
        return 0;
    }

    $size  = 0;
    $items = scandir($path);

    foreach ($items as $item) {
        $item !== '.' && $item !== '..' && $size += CaculatePathSize($path . DIRECTORY_SEPARATOR . $item);
    }

    return $size;
}

function LogoutCurrentSession()
{
    $_SESSION = array();

    if (ini_get('session.use_cookies')) {
        $params = session_get_cookie_params();
        @setcookie(session_name(), '', time() - 3600, $params['path'], $params['domain'], $params['secure'], $params['httponly']);
    }

    session_destroy();
    return true;
}

function CheckTOTP($secret, $code, $timeFix = -1)
{
    global $config;
    $timeFix = max($timeFix >= 0 ? $timeFix : $config['totp_time_fix'], 0);
    $secret  = is_string($secret) ? trim($secret) : '';
    $code    = is_string($code) ? trim($code) : '';

    if ($secret === '' || !preg_match('/^\d{6}$/', $code)) {
        return false;
    }

    $now   = time();
    $totps = array(GenerateTOTP($secret, $now));

    for ($i = 1; $i <= $timeFix; ++$i) {
        array_push($totps, GenerateTOTP($secret, $now - $i * 30));
        array_push($totps, GenerateTOTP($secret, $now + $i * 30));
    }

    return in_array($code, $totps, true);
}

function LoginFailed()
{
    global $tmpcfg, $user;
    $now       = time();
    $failInfo  = $tmpcfg['login_failures'][$user['username']];
    $failCount = intval($failInfo['count']) + 1;
    $newLock   = $failCount >= 5 ? $now + 600 : 0;

    $tmpcfg['login_failures'][$user['username']] = array('count' => $failCount, 'lock_until' => $newLock);
    SetTmpcfg($tmpcfg);
    return Error('login_failed');
}

function TGZAddPath($archive, $sourcePath, $entryPath)
{
    if (is_link($sourcePath)) {
        return true;
    }

    $entryPath = trim(str_replace('\\', '/', $entryPath), '/');

    if ($entryPath === '') {
        $entryPath = basename($sourcePath);
    }

    if ($entryPath === '') {
        return false;
    }

    if (is_file($sourcePath)) {
        $result = $archive->addFile($sourcePath, $entryPath);
        return $result !== false;
    }

    if (!is_dir($sourcePath)) {
        return false;
    }

    if ($archive->addEmptyDir($entryPath) === false) {
        return false;
    }

    $items = scandir($sourcePath);

    if ($items === false) {
        return false;
    }

    foreach ($items as $item) {
        if ($item === '.' || $item === '..') {
            continue;
        }

        $childSource = JoinPath($sourcePath, $item);
        $childEntry  = $entryPath . '/' . $item;

        if (!TGZAddPath($archive, $childSource, $childEntry)) {
            return false;
        }
    }

    return true;
}

function GetCurrentUrl()
{
    $https = false;

    if (!empty($_SERVER['HTTPS']) && strtolower($_SERVER['HTTPS']) !== 'off') {
        $https = true;
    } elseif (!empty($_SERVER['HTTP_X_FORWARDED_PROTO']) &&
        $_SERVER['HTTP_X_FORWARDED_PROTO'] === 'https') {
        $https = true;
    } elseif (!empty($_SERVER['HTTP_X_FORWARDED_SSL']) &&
        strtolower($_SERVER['HTTP_X_FORWARDED_SSL']) === 'on') {
        $https = true;
    }

    $scheme = $https ? 'https' : 'http';
    $host   = '';

    if (!empty($_SERVER['HTTP_HOST'])) {
        $host = $_SERVER['HTTP_HOST'];
    } elseif (!empty($_SERVER['SERVER_NAME'])) {
        $host = $_SERVER['SERVER_NAME'];
    } else {
        $host = 'localhost';
    }

    $port         = '';
    $standardPort = $https ? '443' : '80';

    if (strpos($host, ':') === false) {
        $serverPort = (string) $_SERVER['SERVER_PORT'];
        if ($serverPort !== '' && $serverPort !== $standardPort) {
            $port = ':' . $serverPort;
        }
    }

    $requestUri = $_SERVER['REQUEST_URI'] ?? '';
    return $scheme . '://' . $host . $port . $requestUri;
}
