html,
body {
    width: 100%;
    height: 100%;
    margin: 0;
    overflow: hidden;
    background: #1f1f1f;
}

.audio-player {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 18px;
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    padding: 56px 24px 24px;
}

.audio-waveform {
    display: none;
    width: min(900px, 100%);
    aspect-ratio: 3 / 1;
    overflow: hidden;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 12px;
    background: #000;
}

.audio-player.visualizer-supported .audio-waveform {
    display: block;
}

.audio-waveform canvas {
    display: block;
    width: 100%;
    height: 100%;
}

.audio-player audio {
    display: block;
    width: min(640px, 100%);
}

.audio-status {
    max-width: calc(100% - 48px);
    color: #d8d8d8;
    font-size: 14px;
    line-height: 20px;
    text-align: center;
    pointer-events: none;
}

.audio-status:empty {
    display: none;
}

@media (max-width: 600px) {
    .audio-player {
        gap: 12px;
        padding: 48px 16px 16px;
    }
}
