<!----- FILE css/folder-detail.css START -----><style>
.folder-mode .folder-mode-item[data-mode="detail"]::before {
    background: url(?f=img/folder/detail.svg) no-repeat center center / 18px 18px;
}

.folder-mode .folder-mode-item-active[data-mode="detail"]::before,
.folder-mode .folder-mode-item[data-mode="detail"]:hover::before {
    background-image: url(?f=img/folder/detail-hover.svg);
}

.folder-detail-column-detail {
    position: absolute;
    display: block;
    top: 64px;
    left: 0;
    width: 100%;
    height: 32px;
    line-height: 34px;
    font-size: 14px;
    background-color: #2a2a2a;
    cursor: default;
}

.folder-detail-column-detail .folder-detail-column-item-icon {
    display: block;
    float: left;
    width: 16px;
    height: 16px;
    margin: 8px 0 0 10px;
    visibility: hidden;
}

.folder-detail-column-detail .folder-detail-column-item-name {
    float: left;
    margin-left: 4px;
}

.folder-detail-column-detail .folder-detail-column-item {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
}

.folder-detail-column-detail .folder-detail-column-label {
    display: inline-block;
    white-space: nowrap;
}

.folder-detail-column-detail .folder-detail-column-actions {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 2px;
    margin-left: 2px;
}

.folder-detail-column-detail .folder-detail-column-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 16px;
    height: 16px;
    padding: 0;
    border: 0;
    background: transparent;
    color: #9aa0a6;
    cursor: pointer;
    opacity: 0.8;
    background-repeat: no-repeat;
    background-position: center center;
    background-size: 16px 16px;
}

.folder-detail-column-detail .folder-detail-column-action:hover {
    color: #fff;
    opacity: 1;
}

.folder-detail-column-detail .folder-detail-column-sort {
    color: #9aa0a6;
    background-image: url(?f=img/folder/sort-arrow.svg);
    background-size: 16px 16px;
}

.folder-detail-column-detail .folder-detail-column-sort[data-sort-state="asc"] {
    color: #fff;
    background-image: url(?f=img/folder/sort-asc.svg);
}

.folder-detail-column-detail .folder-detail-column-sort[data-sort-state="desc"] {
    color: #fff;
    background-image: url(?f=img/folder/sort-desc.svg);
}

.folder-detail-column-detail .folder-detail-column-sort[data-sort-state="default"] {
    color: #9aa0a6;
    background-image: url(?f=img/folder/sort-arrow.svg);
}

.folder-detail-column-detail .folder-detail-column-filter {
    background-image: url(?f=img/folder/filter.svg);
}

.folder-detail-column-detail .folder-detail-column-filter[data-filter-active="true"] {
    background-image: url(?f=img/folder/filter-active.svg);
}

.folder-detail-column-detail .folder-detail-column-item-size {
    float: right;
    width: 120px;
    justify-content: flex-end;
    text-align: right;
    margin-right: 20px;
}

.folder-detail-column-detail .folder-detail-column-item-created {
    float: right;
    width: 180px;
    text-align: center;
    margin-right: 40px;
}

.folder-detail-column-detail .folder-detail-column-item-type {
    float: right;
    width: 90px;
    text-align: center;
    margin-right: 20px;
}

.folder-detail-column-detail .folder-detail-column-item-modified {
    float: right;
    width: 180px;
    text-align: center;
    margin-right: 40px;
}

.folder-detail-column-detail .folder-detail-column-item-operations {
    float: right;
    width: 140px;
    text-align: center;
    margin-right: 14px;
}

.folder-items-wrap-detail {
    top: 96px;
    height: calc(100% - 137px);
}

.folder-items-wrap-detail .folder-item {
    display: block;
    margin: 0 auto;
    width: 100%;
    height: 32px;
    line-height: 34px;
    font-size: 14px;
    overflow: hidden;
}

.folder-items-wrap-detail .folder-item:nth-child(even) {
    background-color: #2a2a2a;
}

.folder-items-wrap-detail .folder-item:hover {
    background-color: #373737;
}

.folder-items-wrap-detail .folder-item:hover .folder-item-name {
    color: #fff;
}

.folder-items-wrap-detail .folder-item-icon {
    display: block;
    float: left;
    width: 16px;
    height: 16px;
    margin: 8px 0 0 10px;
    background: url(?f=img/filetype/default.svg) no-repeat center center / 16px 16px;
    cursor: pointer;
}

.folder-items-wrap-detail .folder-item.folder-item-link .folder-item-icon::after,
.folder-items-wrap-detail .folder-item.folder-item-not-mine .folder-item-icon::after {
    left: -3px;
    bottom: -3px;
    width: 10px;
    height: 10px;
    background-size: 10px 10px;
}

.folder-items-wrap-detail .folder-item-name {
    float: left;
    width: calc(100% - 900px);
    margin-left: 4px;
    cursor: pointer;
}

.folder-filter-popup {
    position: fixed;
    z-index: 2000;
    display: none;
    width: 280px;
    max-width: calc(100vw - 24px);
    padding: 12px;
    border-radius: 6px;
    background-color: #2a2a2a;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
    box-sizing: border-box;
}

.folder-filter-popup[data-filter-column="name"] {
    width: 400px;
}

.folder-filter-popup[data-filter-column="size"] {
    width: 320px;
}

.folder-filter-popup[data-filter-column="type"] {
    width: 400px;
}

.folder-filter-popup[data-filter-column="created"],
.folder-filter-popup[data-filter-column="modified"] {
    width: 600px;
}

.folder-filter-popup-input {
    width: 100%;
    box-sizing: border-box;
    height: 30px;
    padding: 0 8px;
    border: 1px solid #4a4a4a;
    border-radius: 4px;
    background-color: #1f1f1f;
    color: #fff;
    outline: none;
    accent-color: #fff;
    color-scheme: dark;
}

.folder-filter-popup-panel-hidden {
    display: none !important;
}

.folder-filter-popup-size {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.folder-filter-popup-datetime {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.folder-filter-popup-actions-row {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 12px;
    margin-top: 10px;
    flex-wrap: wrap;
}

.folder-filter-popup-time-links {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 10px;
    margin: 0;
    flex: 1;
    min-width: 0;
}

.folder-filter-popup-time-link {
    display: inline-block;
    padding: 0;
    border: 0;
    background: transparent;
    color: #6bf;
    font-size: 14px;
    line-height: 1.4;
    cursor: pointer;
    text-decoration: none;
    user-select: none;
}

.folder-filter-popup-time-link:hover {
    color: #a8d5ff;
}

.folder-filter-popup-size-row {
    display: flex;
    align-items: center;
    gap: 8px;
}

.folder-filter-popup-label {
    color: #d0d0d0;
    font-size: 13px;
    white-space: nowrap;
}

.folder-filter-popup-size-title {
    min-width: 60px;
}

.folder-filter-popup-range-separator {
    color: #d0d0d0;
    font-size: 14px;
}

.folder-filter-popup-size-input {
    flex: 1;
    min-width: 0;
}

.folder-filter-popup-type {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.folder-filter-popup-type-title {
    color: #d0d0d0;
    font-size: 13px;
}

.folder-filter-popup-type-list {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    max-height: 320px;
    overflow-y: auto;
    scrollbar-width: auto;
    scrollbar-color: #4f4f4f #242424;
}

.folder-filter-popup-type-item {
    display: block;
    position: relative;
    width: calc(33% - 5px);
    min-width: 0;
    padding: 6px 8px;
    border: 1px solid #4a4a4a;
    border-radius: 4px;
    background-color: #242424;
    color: #f0f0f0;
    font-size: 12px;
    line-height: 16px;
    cursor: pointer;
    box-sizing: border-box;
    overflow: hidden;
}

.folder-filter-popup-type-item-directory {
    width: calc(100% - 2px);
}

.folder-filter-popup-type-item input {
    float: left;
    margin: 1px 6px 0 0;
}

.folder-filter-popup-type-item-icon {
    float: left;
    width: 16px;
    height: 16px;
    margin: 0 6px 0 0;
    background: url(?f=img/filetype/default.svg) no-repeat center center / 16px 16px;
}

.folder-filter-popup-type-item-text {
    display: block;
    margin-left: 28px;
    margin-right: 24px;
    overflow: hidden;
