.folder-thumb-thumb {
    display: block;
    position: absolute;
    top: 64px;
    left: 0px;
    width: calc(100% - 240px);
    height: calc(100% - 105px);
}

.folder-thumb-thumb .folder-thumb-image {
    display: block;
    width: 100%;
    height: 100%;
    background-color: #373737;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.folder-thumb-thumb .folder-thumb-image-img {
    display: block;
    object-fit: contain;
}

.folder-thumb-image {
    position: relative;
    z-index: 0;
}

.folder-thumb-prev {
    position: absolute;
    top: calc(50% - 82px);
    left: 20px;
    width: 64px;
    height: 64px;
    background-color: #3939397f;
    z-index: 1;
    display: none;
    cursor: pointer;
}

.folder-thumb:hover .folder-thumb-prev {
    display: block;
}

.folder-thumb-prev-arrow {
    position: absolute;
    top: 16px;
    left: 24px;
    width: 32px;
    height: 32px;
    transform: rotate(-45deg);
    border-radius: 3px;
    overflow: hidden;
}

.folder-thumb-prev-arrow::before {
    content: '';
    display: block;
    width: 32px;
    height: 5px;
    position: absolute;
    top: 0px;
    left: 0px;
    background-color: #c9c9c9;
    border-bottom-right-radius: 3px;
}

.folder-thumb-prev-arrow::after {
    content: '';
    display: block;
    width: 5px;
    height: 32px;
    position: absolute;
    top: 0px;
    left: 0px;
    background-color: #c9c9c9;
    border-bottom-right-radius: 3px;
}

