.folder-thumb-prev:hover .folder-thumb-prev-arrow::after {
    background-color: #fff;
}

.folder-thumb-next {
    position: absolute;
    top: calc(50% - 82px);
    right: 20px;
    width: 64px;
    height: 64px;
    background-color: #3939397f;
    z-index: 1;
    display: none;
    cursor: pointer;
}

.folder-thumb:hover .folder-thumb-next {
    display: block;
}

.folder-thumb-next-arrow {
    position: absolute;
    top: 16px;
    right: 24px;
    width: 32px;
    height: 32px;
    transform: rotate(135deg);
    border-radius: 3px;
    overflow: hidden;
}

.folder-thumb-next-arrow::before {
    content: '';
    display: block;
    width: 32px;
    height: 5px;
    position: absolute;
    top: 0px;
    left: 0px;
    background-color: #c9c9c9;
    border-bottom-right-radius: 3px;
}

.folder-thumb-next-arrow::after {
