    display: flex;
}

.folder-upload-drop-mask-text {
    padding: 22px 32px;
    border: 2px dashed #4aa3ff;
    color: #fff;
    background-color: rgba(31, 31, 31, 0.86);
    font-size: 20px;
}

.folder-path-input {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 32px;
    display: none;
    outline: none;
    border: none;
    color: #fff;
    text-indent: 10px;
    background-color: transparent;
    appearance: none;
    -webkit-appearance: none;
}

.global-path-search-icon {
    position: relative;
    width: 18px;
    height: 18px;
    float: left;
    margin: 7px 2px 0 10px;
    background: url(?f=img/common/search.svg) no-repeat center / 18px 18px;
}

.folder-item.folder-item-link .folder-item-icon,
.folder-item.folder-item-link .folder-item-image,
.folder-item.folder-item-not-mine .folder-item-icon,
.folder-item.folder-item-not-mine .folder-item-image {
    position: relative;
}

.folder-item.folder-item-link .folder-item-icon::after,
.folder-item.folder-item-link .folder-item-image::after,
.folder-item.folder-item-not-mine .folder-item-icon::after,
.folder-item.folder-item-not-mine .folder-item-image::after {
    content: '';
    position: absolute;
    background: url(?f=img/common/symlink-badge.svg) no-repeat center center;
    pointer-events: none;
}

.folder-item.folder-item-not-mine.folder-item-link .folder-item-icon::after,
.folder-item.folder-item-not-mine.folder-item-link .folder-item-image::after {
    background-image: url(?f=img/common/symlink-badge-red.svg);
}

.folder-item.folder-item-not-mine:not(.folder-item-link) .folder-item-icon::after,
.folder-item.folder-item-not-mine:not(.folder-item-link) .folder-item-image::after {
    background-image: url(?f=img/common/no-access-badge.svg);
}

.folder-action {
    position: absolute;
    top: 32px;
    left: 0px;
    height: 32px;
    z-index: 100;
    background-color: #1f1f1f;
    padding-right: 10px;
}

.folder-action:hover {
    z-index: 300;
}

.folder-action .folder-action-separator {
    width: 1px;
    height: 16px;
    float: left;
    margin: 8px 5px 0;
    background-color: #c9c9c9;
}

.folder-action .folder-action-item {
    padding: 0 10px;
    height: 32px;
    line-height: 34px;
    text-align: center;
    float: left;
    font-size: 14px;
    cursor: pointer;
}

.folder-action .folder-action-item:hover {
    background-color: #373737;
    color: #fff;
