<!----- FILE css/frame.css START -----><style>
.main {
    position: fixed;
    width: 100%;
    height: 100%;
    top: 0;
    left: 0;
    margin: 0;
    padding: 0;
    font-size: 0;
}

iframe {
    border: none;
    outline: none;
    resize: none;
}

.navi {
    width: 100%;
    height: 40px;
    border: none;
    border-bottom: 1px solid #2b2b2b;
}

.tree {
    width: 320px;
    height: calc(100% - 41px);
    float: left;
    position: relative;
    z-index: 10;
    overflow: hidden;
}

.resize {
    width: 4px;
    height: calc(100% - 41px);
    float: left;
    cursor: ew-resize;
    background-color: transparent;
    position: relative;
    z-index: 20;
    margin-left: -2px;
    transition: 0.3s ease;
}

.resize:hover {
    background-color: #0078d4;
}

.resize.moving {
    background-color: #0078d4;
    transition: none;
}

.resize .frame-resize-width-left {
    position: absolute;
    background-color: #0078d4;
    width: 60px;
    height: 24px;
    line-height: 24px;
    text-align: center;
    font-size: 14px;
    top: 50%;
    right: 10px;
    margin-top: -12px;
    white-space: nowrap;
    color: #fff;
    display: none;
    transition: 0.3s;
    opacity: 0;
}

.resize .frame-resize-width-left::before {
    content: "";
    display: block;
    position: absolute;
    top: 0px;
    left: -8px;
    width: 0;
    height: 0;
    border-top: 12px solid transparent;
    border-right: 8px solid #0078d4;
    border-bottom: 12px solid transparent;
    border-left: none;
}

.resize .frame-resize-width-right {
    position: absolute;
    background-color: #0078d4;
    width: 60px;
    height: 24px;
    line-height: 24px;
    text-align: center;
    font-size: 14px;
    top: 50%;
    left: 10px;
    margin-top: -12px;
    white-space: nowrap;
    color: #fff;
    display: none;
    transition: 0.3s;
    opacity: 0;
}

.resize .frame-resize-width-right::after {
    content: "";
    display: block;
    position: absolute;
    top: 0px;
    right: -8px;
    width: 0;
    height: 0;
    border-top: 12px solid transparent;
    border-right: none;
    border-bottom: 12px solid transparent;
    border-left: 8px solid #0078d4;
}

.right {
    width: calc(100% - 320px);
    height: calc(100% - 41px);
    float: right;
    background-color: #1f1f1f;
    box-sizing: border-box;
    border-left: 1px solid #2b2b2b;
    position: relative;
    z-index: 10;
    margin-left: -2px;
}

.tab {
    width: 100%;
    height: 35px;
    overflow: hidden;
}

.content {
    width: 100%;
    height: calc(100% - 35px);
    overflow: hidden;
    display: none;
    border: none;
}

.navi-language-list {
    position: absolute;
    opacity: 0;
    cursor: pointer;
    z-index: 100;
    text-align: center;
    font-size: 14px;
    background-color: #181818;
}

.navi-language-list option {
    color: #c9c9c9;
    cursor: pointer;
}

.tree-menu {
    position: absolute;
    background-color: #1f1f1f;
    border: 1px solid #454545;
    border-radius: 5px;
    z-index: 1000;
    display: none;
    font-size: 14px;
    padding: 4px;
    top: 0px;
    left: 0px;
}

.tree-menu .tree-menu-item {
    position: relative;
    min-width: 150px;
    font-size: 14px;
    border-radius: 3px;
    padding: 5px 25px;
    color: #c9c9c9;
    cursor: pointer;
}

.tree-menu .tree-menu-item:hover {
    background-color: #0078d4;
    color: #fff;
}

.tree-menu .tree-menu-item.tree-menu-item-disabled,
.tree-menu .tree-menu-item.tree-menu-item-disabled:hover {
    background-color: transparent;
    color: #666;
    cursor: not-allowed;
}

.tree-menu .tree-menu-item.tree-menu-item-disabled .tree-menu-hotkey,
.tree-menu .tree-menu-item.tree-menu-item-disabled:hover .tree-menu-hotkey {
    color: #555;
}

.tree-menu .tree-menu-separator {
    width: calc(100% + 10px);
    height: 1px;
    background-color: #454545;
    margin: 4px -5px;
}

.tree-menu .tree-menu-item .tree-menu-hotkey {
    margin: 4px 0 0 10px;
    float: right;
    color: #8e8e8e;
    font-size: 12px;
}

.tree-menu .tree-menu-item:hover .tree-menu-hotkey {
    color: #fff;
}

.tree-menu .tree-menu-item .tree-menu-submenu {
    position: absolute;
    top: 50%;
    right: -5px;
    margin-top: -8px;
    float: right;
    display: block;
    width: 28px;
    height: 16px;
    background: url(?f=img/tree/folder.svg) no-repeat 0px center / 16px 16px;
}

.tree-menu .tree-menu-item::before {
    content: "";
    display: block;
    position: absolute;
    top: 50%;
    left: -5px;
    margin-top: -8px;
    width: 28px;
    height: 16px;
    z-index: -9999;
}

.tree-menu .tree-menu-item:hover .tree-menu-submenu {
    background-image: url(?f=img/tree/folder-hover.svg);
}

.tree-menu .tree-menu-item .tree-menu {
    top: -5px;
    left: auto;
    right: -4px;
    transform: translate(100%, 0px);
}

.tree-menu .tree-menu-item:hover .tree-menu {
    display: block;
}

.tree-menu .tree-menu-item .tree-menu .tree-menu-item {
    width: auto;
    min-width: auto;
}

.frame-dialog {
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 10000;
    display: none;
    cursor: default;
}

.frame-dialog .frame-dialog-content {
    position: absolute;
    width: 400px;
    top: 50%;
    left: 50%;
