}

.frame-dialog .frame-dialog-text-1 {
    width: 350px;
    font-size: 18px;
    color: #003399;
    margin-top: 10px;
    float: right;
}

.frame-dialog .frame-dialog-text-2 {
    width: 350px;
    font-size: 14px;
    color: #000;
    margin-top: 10px;
    float: right;
}

.frame-dialog .frame-dialog-buttons {
    margin-top: 20px;
}

.frame-dialog .frame-dialog-buttons::after {
    content: "";
    display: block;
}

.frame-dialog .frame-dialog-button {
    float: right;
    font-size: 14px;
    padding: 4px 12px;
    margin-right: 10px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    border: 1px solid #181818;
    color: #000;
}

.frame-dialog .frame-dialog-button:hover {
    background-color: #0078d4;
    color: #fff;
    border-color: #0078d4;
}
