    -ms-user-select: none;
    user-select: none;
    -webkit-touch-callout: none;
}

body.tree-page input,
body.tree-page textarea,
body.tree-page [contenteditable="true"] {
    -webkit-user-select: text;
    -moz-user-select: text;
    -ms-user-select: text;
    user-select: text;
}

.tree-title {
    height: 40px;
    line-height: 40px;
    margin-left: 10px;
    text-indent: 15px;
    cursor: pointer;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    padding-right: 15px;
}

.tree-root {
    position: absolute;
    top: 40px;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 500;
    overflow: hidden;
}

.tree-list {
    border-left: 1px solid #5e5e5e;
    margin-left: 7px;
