}

.tree-item {
    position: relative;
    margin-left: 4px;
}

.tree-item-line {
    height: 24px;
    line-height: 24px;
    cursor: pointer;
    position: relative;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.tree-item .tree-item-switch {
    display: inline-block;
    position: relative;
    width: 16px;
    height: 16px;
    top: 4px;
    margin: 0 -4px 0 0;
    visibility: hidden;
}

.tree-item-folder .tree-item-switch {
    background: url(?f=img/tree/folder.svg) no-repeat center center / 16px 16px;
    transition: 0.2s ease;
    visibility: visible;
}

.tree-item-folder.tree-item-folder-open .tree-item-switch {
    transform: rotate(90deg);
}

.tree-item .tree-item-icon {
    display: inline-block;
    position: relative;
    width: 16px;
    height: 16px;
    top: 4px;
    margin: 0 6px;
    background: url(?f=img/filetype/default.svg) no-repeat center center / 16px 16px;
}

.tree-item .tree-item-folder-open .tree-item-icon {
    background-image: url(?f=img/filetype/folder-open.svg) !important;
}

.tree-item .tree-item-disk .tree-item-icon {
    background-image: url(?f=img/filetype/disk.svg) !important;
}

.tree-item .tree-item-link .tree-item-icon::after,
.tree-item .tree-item-not-mine .tree-item-icon::after {
    content: '';
    position: absolute;
    left: -3px;
    bottom: -3px;
    width: 10px;
    height: 10px;
    background: url(?f=img/common/symlink-badge.svg) no-repeat center center / 10px 10px;
    pointer-events: none;
}

.tree-item .tree-item-not-mine.tree-item-link .tree-item-icon::after {
    background-image: url(?f=img/common/symlink-badge-red.svg);
}

.tree-item .tree-item-not-mine:not(.tree-item-link) .tree-item-icon::after {
    background-image: url(?f=img/common/no-access-badge.svg);
}

.tree-item-line-active .tree-item-name {
    color: #fff;
}

.tree-item .tree-item-name-input {
    position: absolute;
    display: block;
    top: 0px;
    left: 39px;
    right: 0px;
    height: 24px;
    box-sizing: border-box;
    border: 1px solid #0078d4;
    background-color: transparent;
    outline: none;
    color: #c9c9c9;
    font-size: 14px;
    font-family: inherit;
}

.tree-item .tree-item-name-input.warning {
    border: 1px solid #815112;
}

.tree-item .tree-item-name-input.error {
    border: 1px solid #be1100;
}

.tree-item-name-input-error {
    position: absolute;
    top: 0px;
    left: 0px;
    font-size: 14px;
    line-height: 24px;
    padding: 5px;
    color: #c9c9c9;
    box-sizing: border-box;
    border: 1px solid #be1100;
    background-color: #5a1d1d;
    z-index: 2000;
}

.tree-item-name-input-error.warning {
    border: 1px solid #815112;
    background-color: #b8731a;
}

.tree-item-name-input-error .filename {
    font-weight: bold;
}

.file-bg {
    position: absolute;
    width: 100%;
    height: 24px;
    left: 0px;
}

.file-bg.file-bg-hover {
    background-color: #2a2d2e;
}

.file-bg.file-bg-current {
    background-color: #373737;
}

.file-bg.file-bg-selected {
    background-color: #04395e;
}

.file-bg.file-bg-active {
    box-sizing: border-box;
    border: 1px solid #0078d4;
}
</style><!----- FILE css/tree.css END ----->
<!----- FILE css/userinfo.css START -----><style>
body {
