</head>

<body>
    <div class="config-page">
        <div class="config-sidebar">
            <div class="config-nav-item active" data-group="basic" data-lang="config.group_basic"></div>
            <div class="config-nav-item" data-group="users" data-lang="config.group_users"></div>
        </div>
        <div class="config-content">
            <div class="config-group" data-group="basic">
                <div class="config-group-header">
                    <div class="config-group-title" data-lang="config.group_basic"></div>
                    <button class="config-help" type="button" data-help="module-config" aria-label="Help"></button>
                </div>
                <div class="config-group-body">
                    <div class="config-row">
                        <label class="config-label" for="config-lang" data-lang="config.default_lang"></label>
                        <select class="config-input config-select" id="config-lang"></select>
                        <button class="config-help" type="button" data-help="config-default-lang" aria-label="Help"></button>
                    </div>
                    <div class="config-row">
                        <label class="config-label" for="config-timezone-input" data-lang="config.timezone"></label>
                        <div class="config-timezone-picker" id="config-timezone-picker">
                            <input class="config-input" id="config-timezone-input" type="text" autocomplete="off" spellcheck="false" />
                            <input id="config-timezone" type="hidden" />
                            <div class="config-timezone-list" id="config-timezone-list"></div>
                        </div>
                        <button class="config-help" type="button" data-help="config-timezone" aria-label="Help"></button>
                    </div>
                    <div class="config-row">
                        <label class="config-label" for="config-write-size-limit" data-lang="config.write_size_limit"></label>
                        <input class="config-input" id="config-write-size-limit" type="text" spellcheck="false" />
                        <button class="config-help" type="button" data-help="config-upload-limit" aria-label="Help"></button>
                        <span class="config-input-tips" id="config-tip-write-size-limit" data-lang="config.tip_write_size_limit_invalid"></span>
                    </div>
                    <div class="config-row">
                        <label class="config-label" for="config-totp-time-fix" data-lang="config.totp_time_fix"></label>
                        <input class="config-input" id="config-totp-time-fix" type="text" inputmode="numeric" spellcheck="false" />
                        <button class="config-help" type="button" data-help="config-totp-fix" aria-label="Help"></button>
                        <span class="config-input-tips" id="config-tip-totp-time-fix" data-lang="config.tip_totp_time_fix_invalid"></span>
                    </div>
                    <div class="config-row">
                        <label class="config-label" for="config-session-name" data-lang="config.session_name"></label>
                        <input class="config-input" id="config-session-name" type="text" spellcheck="false" />
                        <button class="config-help" type="button" data-help="config-session-name" aria-label="Help"></button>
                        <span class="config-input-tips" id="config-tip-session-name" data-lang="config.tip_session_name_invalid"></span>
                    </div>
                    <div class="config-row">
                        <label class="config-label" for="config-cache-time" data-lang="config.cache_time"></label>
                        <input class="config-input" id="config-cache-time" type="text" inputmode="numeric" spellcheck="false" />
                        <button class="config-help" type="button" data-help="config-cache-time" aria-label="Help"></button>
                        <span class="config-input-tips" id="config-tip-cache-time" data-lang="config.tip_cache_time_invalid"></span>
                    </div>
                    <div class="config-row">
                        <label class="config-label" for="config-main-password" data-lang="config.main_password"></label>
                        <input class="config-input" id="config-main-password" type="text" spellcheck="false" />
                        <button class="config-help" type="button" data-help="config-main-password" aria-label="Help"></button>
                    </div>
                    <div class="config-row config-row-textarea">
                        <label class="config-label" for="config-comment" data-lang="config.comment"></label>
                        <textarea class="config-input config-textarea" id="config-comment" spellcheck="false"></textarea>
                        <button class="config-help" type="button" data-help="config-comment" aria-label="Help"></button>
                    </div>
                    <div class="config-row config-actions-row">
                        <label class="config-label"></label>
                        <div class="config-value">
                            <button class="config-submit" id="config-submit-basic" type="button" data-lang="config.confirm"></button>
                            <button class="config-reset" id="config-reset-basic" type="button" data-lang="config.reset"></button>
                        </div>
                    </div>
                </div>
            </div>
            <div class="config-group" data-group="users">
                <div class="config-group-header">
                    <div class="config-group-title" data-lang="config.group_users"></div>
                    <button class="config-help" type="button" data-help="module-users" aria-label="Help"></button>
                </div>
                <div class="config-group-body config-users-body">
                    <div class="config-users-table-wrap">
                        <table class="config-users-table">
                            <thead>
                                <tr>
                                    <th data-lang="config.user_username"></th>
                                    <th data-lang="config.user_password"></th>
                                    <th data-lang="config.user_totp"></th>
                                    <th data-lang="config.user_readonly"></th>
                                    <th data-lang="config.user_admin"></th>
                                    <th data-lang="config.user_base_path"></th>
                                    <th data-lang="config.user_write_size_limit"></th>
                                    <th data-lang="config.user_write_limit"></th>
                                    <th data-lang="config.user_action"></th>
                                </tr>
                            </thead>
                            <tbody id="config-users-tbody"></tbody>
                        </table>
                    </div>
                    <div class="config-users-actions">
                        <button class="config-submit" id="config-add-user" type="button" data-lang="config.add_user"></button>
                        <button class="config-submit" id="config-submit-users" type="button" data-lang="config.confirm"></button>
                        <button class="config-reset" id="config-reset-users" type="button" data-lang="config.reset"></button>
                    </div>
                </div>
            </div>
        </div>
    </div>
</body>
<script src="?f=js/zepto.js"></script>
<script src="?f=js/global.js"></script>
<script src="?f=js/scrollbar.js"></script>
<script src="?f=js/config.js"></script>

</html>
