</head>

<body class="folder-page">
    <div class="main">
        <ul class="global-path" id="global-path"></ul>
        <input type="text" class="folder-path-input" id="folder-path-input" />
        <div class="folder-action">
            <div class="folder-action-item" id="folder-mode-prev" data-action="prev" data-lang="folder.prev"></div>
            <div class="folder-action-item" id="folder-mode-next" data-action="next" data-lang="folder.next"></div>
            <div class="folder-action-item" id="folder-mode-parent" data-action="parent" data-lang="folder.parent"></div>
            <div class="folder-action-separator"></div>
            <div class="folder-action-item" id="folder-mode-refresh" data-action="refresh" data-lang="folder.refresh"></div>
            <div class="folder-action-item" id="folder-mode-select-all" data-action="select-all" data-lang="folder.select_all"></div>
            <div class="folder-action-item" id="folder-mode-invert-selection" data-action="invert-selection" data-lang="folder.invert_selection"></div>
            <div class="folder-action-separator"></div>
            <div class="folder-action-item" id="folder-mode-upload" data-action="upload" data-lang="folder.upload"></div>
            <div class="folder-action-item" id="folder-mode-uploading" data-action="uploading" data-lang="folder.uploading"></div>
            <div class="folder-action-item" id="folder-mode-upload-cancel" data-action="upload-cancel" data-lang="folder.upload_cancel"></div>
            <div class="folder-action-item" id="folder-mode-new-file" data-action="new-file" data-lang="folder.new_file"></div>
            <div class="folder-action-item" id="folder-mode-new-folder" data-action="new-folder" data-lang="folder.new_folder"></div>
            <div class="folder-action-separator"></div>
            <div class="folder-action-item" id="folder-mode-cut" data-action="cut" data-lang="folder.cut"></div>
            <div class="folder-action-item" id="folder-mode-copy" data-action="copy" data-lang="folder.copy"></div>
            <div class="folder-action-item" id="folder-mode-paste" data-action="paste" data-lang="folder.paste"></div>
            <div class="folder-action-item" id="folder-mode-remove" data-action="remove" data-lang="folder.remove"></div>
        </div>
        <div class="folder-mode">
            <div class="folder-mode-title" data-lang="folder.mode_title"></div>
            <div class="folder-mode-item" id="folder-mode-item-detail" data-mode="detail" data-lang="folder.mode_item.detail"></div>
            <div class="folder-mode-item" id="folder-mode-item-icon" data-mode="icon" data-lang="folder.mode_item.icon"></div>
            <div class="folder-mode-item" id="folder-mode-item-tile" data-mode="tile" data-lang="folder.mode_item.tile"></div>
            <div class="folder-mode-item" id="folder-mode-item-thumb" data-mode="thumb" data-lang="folder.mode_item.thumb"></div>
        </div>
        <ul class="folder-detail-column" id="folder-detail-column">
            <li class="folder-detail-column-item folder-detail-column-item-icon"></li>
            <li class="folder-detail-column-item folder-detail-column-item-name">
                <span class="folder-detail-column-label" data-lang="folder.detail.name"></span>
                <span class="folder-detail-column-actions">
                    <button class="folder-detail-column-action folder-detail-column-sort" type="button" aria-label="sort" data-sort-state="default" data-sort-column="name"></button>
                    <button class="folder-detail-column-action folder-detail-column-filter" type="button" aria-label="filter" data-filter-column="name"></button>
                </span>
            </li>
            <li class="folder-detail-column-item folder-detail-column-item-operations">
                <span class="folder-detail-column-label" data-lang="folder.detail.operations"></span>
            </li>
            <li class="folder-detail-column-item folder-detail-column-item-modified">
                <span class="folder-detail-column-label" data-lang="folder.detail.modified"></span>
                <span class="folder-detail-column-actions">
                    <button class="folder-detail-column-action folder-detail-column-sort" type="button" aria-label="sort" data-sort-state="default" data-sort-column="modified"></button>
                    <button class="folder-detail-column-action folder-detail-column-filter" type="button" aria-label="filter" data-filter-column="modified"></button>
                </span>
            </li>
            <li class="folder-detail-column-item folder-detail-column-item-created">
                <span class="folder-detail-column-label" data-lang="folder.detail.created"></span>
                <span class="folder-detail-column-actions">
                    <button class="folder-detail-column-action folder-detail-column-sort" type="button" aria-label="sort" data-sort-state="default" data-sort-column="created"></button>
                    <button class="folder-detail-column-action folder-detail-column-filter" type="button" aria-label="filter" data-filter-column="created"></button>
                </span>
            </li>
            <li class="folder-detail-column-item folder-detail-column-item-type">
                <span class="folder-detail-column-label" data-lang="folder.detail.type"></span>
                <span class="folder-detail-column-actions">
                    <button class="folder-detail-column-action folder-detail-column-sort" type="button" aria-label="sort" data-sort-state="default" data-sort-column="type"></button>
                    <button class="folder-detail-column-action folder-detail-column-filter" type="button" aria-label="filter" data-filter-column="type"></button>
                </span>
            </li>
            <li class="folder-detail-column-item folder-detail-column-item-size">
                <span class="folder-detail-column-label" data-lang="folder.detail.size"></span>
                <span class="folder-detail-column-actions">
                    <button class="folder-detail-column-action folder-detail-column-sort" type="button" aria-label="sort" data-sort-state="default" data-sort-column="size"></button>
                    <button class="folder-detail-column-action folder-detail-column-filter" type="button" aria-label="filter" data-filter-column="size"></button>
                </span>
            </li>
        </ul>
        <div class="folder-items-wrap" id="folder-items-wrap"><ul class="folder-items"></ul></div>
        <div class="folder-item-info">
            <div class="folder-item-info-icon" aria-hidden="true"></div>
            <div class="folder-item-info-name"></div>
            <div class="folder-item-info-size">
                <span class="folder-item-info-size-text" data-lang="folder.calc"></span>
            </div>
            <div class="folder-item-info-mode">
                <span class="folder-item-info-mode-label" data-lang="common.permission"></span>
                <input class="folder-item-info-mode-input" type="text" inputmode="numeric" maxlength="3" spellcheck="false" />
                <button class="folder-item-info-mode-set" type="button" data-lang="common.set"></button>
                <span class="folder-item-info-mode-success" aria-hidden="true"></span>
                <div class="folder-item-info-mode-popup folder-item-info-mode-popup-hidden">
                    <table class="folder-item-info-mode-popup-table">
                        <thead>
                            <tr>
                                <th class="folder-item-info-mode-popup-corner"></th>
                                <th data-lang="folder.permission.owner"></th>
                                <th data-lang="folder.permission.group"></th>
                                <th data-lang="folder.permission.other"></th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr>
                                <th data-lang="folder.permission.read"></th>
                                <td><input type="checkbox" data-mode-group="owner" data-mode-bit="4" /></td>
                                <td><input type="checkbox" data-mode-group="group" data-mode-bit="4" /></td>
                                <td><input type="checkbox" data-mode-group="other" data-mode-bit="4" /></td>
                            </tr>
                            <tr>
                                <th data-lang="folder.permission.write"></th>
                                <td><input type="checkbox" data-mode-group="owner" data-mode-bit="2" /></td>
                                <td><input type="checkbox" data-mode-group="group" data-mode-bit="2" /></td>
                                <td><input type="checkbox" data-mode-group="other" data-mode-bit="2" /></td>
                            </tr>
                            <tr>
                                <th data-lang="folder.permission.execute"></th>
                                <td><input type="checkbox" data-mode-group="owner" data-mode-bit="1" /></td>
                                <td><input type="checkbox" data-mode-group="group" data-mode-bit="1" /></td>
                                <td><input type="checkbox" data-mode-group="other" data-mode-bit="1" /></td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </div>
            <div class="folder-item-info-filter">
                <input class="folder-item-info-mode-filter-input" type="text" spellcheck="false" data-lang-title="folder.filter.placeholder" data-lang-placeholder="folder.filter.placeholder" />
                <button class="folder-item-info-mode-filter" type="button" data-lang="folder.filter.filter"></button>
            </div>
            <div class="folder-item-info-summary" id="folder-item-info-summary" data-lang="folder.summary" data-lang-args='[0,0]'></div>
        </div>
        <div class="folder-filter-popup" id="folder-filter-popup">
            <div class="folder-filter-popup-name folder-filter-popup-panel-hidden" id="folder-filter-popup-name">
                <input class="folder-filter-popup-input" id="folder-filter-popup-input" type="text" spellcheck="false" data-lang-title="folder.filter.placeholder" />
            </div>
            <div class="folder-filter-popup-size folder-filter-popup-panel-hidden" id="folder-filter-popup-size">
                <div class="folder-filter-popup-size-row">
                    <label class="folder-filter-popup-label folder-filter-popup-size-title" data-lang="folder.filter.size_range"></label>
                    <input class="folder-filter-popup-input folder-filter-popup-size-input" id="folder-filter-popup-size-min" type="text" spellcheck="false" data-lang-title="folder.filter.size_min" />
                    <span class="folder-filter-popup-range-separator">-</span>
                    <input class="folder-filter-popup-input folder-filter-popup-size-input" id="folder-filter-popup-size-max" type="text" spellcheck="false" data-lang-title="folder.filter.size_max" />
                </div>
            </div>
            <div class="folder-filter-popup-datetime folder-filter-popup-panel-hidden" id="folder-filter-popup-datetime">
                <div class="folder-filter-popup-size-row">
                    <label class="folder-filter-popup-label folder-filter-popup-size-title" id="folder-filter-popup-datetime-title" data-lang="folder.filter.time_range"></label>
                    <input class="folder-filter-popup-input folder-filter-popup-size-input" id="folder-filter-popup-datetime-min" type="datetime-local" step="1" spellcheck="false" data-lang-title="folder.filter.time_min" />
                    <span class="folder-filter-popup-range-separator">-</span>
                    <input class="folder-filter-popup-input folder-filter-popup-size-input" id="folder-filter-popup-datetime-max" type="datetime-local" step="1" spellcheck="false" data-lang-title="folder.filter.time_max" />
                </div>
            </div>
            <div class="folder-filter-popup-type folder-filter-popup-panel-hidden" id="folder-filter-popup-type">
                <div class="folder-filter-popup-type-title" data-lang="folder.detail.type"></div>
                <div class="folder-filter-popup-type-list" id="folder-filter-popup-type-list"></div>
            </div>
            <div class="folder-filter-popup-actions-row">
                <div class="folder-filter-popup-actions" id="folder-filter-popup-actions">
                    <button class="folder-filter-popup-button folder-filter-popup-button-clear" id="folder-filter-popup-button-clear" type="button" data-lang="folder.filter.clear"></button>
                    <button class="folder-filter-popup-button folder-filter-popup-button-select-all" id="folder-filter-popup-button-select-all" type="button" data-lang="folder.select_all"></button>
                    <button class="folder-filter-popup-button folder-filter-popup-button-invert" id="folder-filter-popup-button-invert" type="button" data-lang="folder.invert_selection"></button>
                    <button class="folder-filter-popup-button folder-filter-popup-button-confirm" id="folder-filter-popup-button-confirm" type="button" data-lang="common.ok"></button>
                </div>
            </div>
        </div>
        <div class="folder-thumb" id="folder-thumb">
            <div class="folder-thumb-prev" data-lang-title="folder.thumb.prev"><div class="folder-thumb-prev-arrow"></div></div>
            <div class="folder-thumb-next" data-lang-title="folder.thumb.next"><div class="folder-thumb-next-arrow"></div></div>
            <div class="folder-thumb-image" id="folder-thumb-image"></div>
        </div>
        <div class="folder-upload-drop-mask" id="folder-upload-drop-mask">
            <div class="folder-upload-drop-mask-text" data-lang="folder.drop_upload"></div>
        </div>
    </div>
</body>
<script src="?f=js/codemirror.js"></script>
<script src="?f=js/zepto.js"></script>
<script src="?f=js/global.js"></script>
<script src="?f=js/scrollbar.js"></script>
