<!DOCTYPE html>
<html lang="zh-CN">

<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <link rel="icon" href="?f=img/common/favicon.svg" type="image/svg+xml" />
    <link rel="stylesheet" href="?f=css/login.css" />
    <title></title>
</head>

<body>
    <div class="login-box">
        <div class="login-title" data-lang="login.title"></div>
        <div class="login-hr-1"></div>
        <div class="login-username-label" data-lang="login.username"></div>
        <input type="text" class="login-username-text" />
        <div class="login-password-label" data-lang="login.password"></div>
        <input type="password" class="login-password-text" />
        <div class="login-totp-label" data-lang="login.totp"></div>
        <input type="text" class="login-totp-text" />
        <div class="login-submit" data-lang="login.submit"></div>
        <div class="login-hr-2"></div>
        <div class="login-copyright" data-lang="login.copyright"></div>
    </div>
    <div class="login-toolbar">
        <div class="login-toolbar-language">
            <img class="login-toolbar-language-icon" src="?f=img/login/language.svg" alt="" />
            <div class="login-toolbar-language-name"></div>
            <select name="language" class="login-toolbar-language-list"></select>
        </div>
    </div>
    <div class="login-dialog">
        <div class="login-dialog-content">
            <div class="login-dialog-title" data-lang="login.title"></div>
            <div class="login-dialog-icon"></div>
            <div class="login-dialog-text-1"></div>
            <div class="login-dialog-text-2"></div>
            <div class="clear"></div>
            <div class="login-dialog-buttons"></div>
        </div>
    </div>
</body>
<script src="?f=js/zepto.js"></script>
<script src="?f=js/global.js"></script>
<script src="?f=js/login.js"></script>

</html>
