<!----- FILE js/audio.js START -----><script>
const id = $(frameElement).data('id');
const content = top.global.content['content-' + id];
const audio = document.getElementById('audio');
const status = document.getElementById('audio-status');
const player = document.querySelector('.audio-player');
const canvas = document.getElementById('audio-canvas');
const canvasContext = canvas && canvas.getContext ? canvas.getContext('2d') : null;
const AudioContext = window.AudioContext || window.webkitAudioContext;
const barColors = ['#00f5ff', '#0078ff', '#7b2ff7'];
let audioUrl = '';
let audioContext = null;
let analyser = null;
let audioData = null;
let animationFrame = null;
let statusLangPath = '';

document.title = content.path.split('/').pop();
renderPath(content.path);

audio.addEventListener('loadedmetadata', function () {
    statusLangPath = setStatusLangText(status);
});

audio.addEventListener('error', function () {
    statusLangPath = setStatusLangText(status, 'audio.play_failed');
});

audio.addEventListener('play', startWaveform);
audio.addEventListener('pause', stopWaveform);
audio.addEventListener('ended', stopWaveform);

content.hide = function () {
    audio.pause();
};

content.renderLang = async function () {
    await renderLang();
    renderPath(content.path);
    statusLangPath && (status.textContent = getLangTextByPath(statusLangPath));
};

if (AudioContext && canvasContext) {
    player.classList.add('visualizer-supported');
    clearCanvas();
}

loadAudio();
renderLang();

function initWaveform() {
    if (analyser || !AudioContext || !canvasContext) {
        return Boolean(analyser);
    }

    try {
        audioContext = new AudioContext();
        analyser = audioContext.createAnalyser();
        analyser.fftSize = 512;

        const source = audioContext.createMediaElementSource(audio);
        source.connect(analyser);
        analyser.connect(audioContext.destination);
        audioData = new Uint8Array(analyser.frequencyBinCount);
        player.classList.add('visualizer-supported');
        clearCanvas();
        return true;
    } catch (error) {
        disableWaveform();
        return false;
    }
}

function startWaveform() {
    if (!initWaveform()) {
        return;
    }

    if (audioContext.state === 'suspended') {
        audioContext.resume();
    }

    if (!animationFrame) {
        drawWaveform();
    }
}

function stopWaveform() {
    if (animationFrame) {
        cancelAnimationFrame(animationFrame);
        animationFrame = null;
    }
}

function disableWaveform() {
    stopWaveform();
    player.classList.remove('visualizer-supported');
    analyser = null;
    audioData = null;
}

function clearCanvas() {
    canvasContext.fillStyle = '#000';
    canvasContext.fillRect(0, 0, canvas.width, canvas.height);
}

function drawWaveform() {
    animationFrame = requestAnimationFrame(drawWaveform);
    drawBars();
}

function drawBars() {
    analyser.getByteFrequencyData(audioData);

    const width = canvas.width;
    const height = canvas.height;
    const barCount = 64;
    const step = Math.floor(audioData.length / barCount);
    const barWidth = width / barCount - 2;
    const gradient = canvasContext.createLinearGradient(0, height, 0, 0);
    gradient.addColorStop(0, barColors[0]);
    gradient.addColorStop(0.5, barColors[1]);
    gradient.addColorStop(1, barColors[2]);

    canvasContext.fillStyle = 'rgba(0, 0, 0, 0.3)';
    canvasContext.fillRect(0, 0, width, height);

    for (let index = 0; index < barCount; ++index) {
        let sum = 0;

        for (let offset = 0; offset < step; ++offset) {
            sum += audioData[index * step + offset];
        }

        const value = sum / step;
        const barHeight = value / 255 * height * 0.85;
        const x = index * (barWidth + 2);
        const y = height - barHeight;
        const radius = Math.min(4, barWidth / 2);

        canvasContext.fillStyle = gradient;
        canvasContext.beginPath();
        canvasContext.moveTo(x + radius, y);
        canvasContext.lineTo(x + barWidth - radius, y);
        canvasContext.quadraticCurveTo(x + barWidth, y, x + barWidth, y + radius);
        canvasContext.lineTo(x + barWidth, height - 2);
        canvasContext.lineTo(x, height - 2);
        canvasContext.lineTo(x, y + radius);
        canvasContext.quadraticCurveTo(x, y, x + radius, y);
        canvasContext.fill();

        canvasContext.fillStyle = 'rgba(255, 255, 255, 0.15)';
        canvasContext.fillRect(x, y, barWidth, 2);
    }
}

async function loadAudio(allowTokenRetry = true) {
    statusLangPath = setStatusLangText(status, 'audio.loading');

    const response = await ajax({
        url: '?a=download',
        data: JSON.stringify({ path: content.path, timeout: 3600 }),
    });

    if (response.code) {
        statusLangPath = response.message
            ? setStatusLangText(status, '', response.message)
            : setStatusLangText(status, 'audio.load_failed');
        return;
    }

    try {
        const download = await fetch('?d=' + encodeURIComponent(response.data.token));
        const contentType = download.headers.get('Content-Type') || '';

        if (contentType.includes('application/json')) {
            const result = await download.json();

            if (result.code === 1022 && allowTokenRetry) {
                return loadAudio(false);
            }

            if (result.code === 1022) {
                throw { langPath: 'common.error.invalid_download_token' };
            }

            throw new Error(result.message || getLangTextByPath('audio.load_failed'));
        }

        if (!download.ok) {
            throw { langPath: 'audio.load_failed' };
        }

        const source = await download.blob();
        const ext = content.path.split('.').pop().toLowerCase();
        const blob = new Blob([source], { type: mimeType(ext) });
        audioUrl = URL.createObjectURL(blob);
        audio.src = audioUrl;
    } catch (error) {
        statusLangPath = error.langPath
            ? setStatusLangText(status, error.langPath)
            : error.message
                ? setStatusLangText(status, '', error.message)
                : setStatusLangText(status, 'audio.load_failed');
    }
}

$(document).on('click contextmenu', function () {
    top.global.tree.blur();
});

$(window).on('unload', function () {
    stopWaveform();
    audioContext && audioContext.close();
    audioUrl && URL.revokeObjectURL(audioUrl);
});
</script><!----- FILE js/audio.js END ----->
