<!----- FILE js/config.js START -----><script>
ignoreAutoFillPassword();
const id = $(frameElement).data('id');
const tab = top.global.tab;
let cachedConfigData = null;
let changed = false;
let timezoneItems = [];

function getTimezoneOffsetMinutes(timezone) {
    try {
        const now = new Date();
        const utcDate = new Date(now.toLocaleString('en-US', { timeZone: 'UTC' }));
        const tzDate = new Date(now.toLocaleString('en-US', { timeZone: timezone }));
        return Math.round((tzDate.getTime() - utcDate.getTime()) / 60000);
    } catch (error) {
        return 0;
    }
}

function formatTimezoneOffsetLabel(offsetMinutes) {
    const sign = offsetMinutes >= 0 ? '+' : '-';
    const abs = Math.abs(offsetMinutes);
    const hours = String(Math.floor(abs / 60)).padStart(2, '0');
    const minutes = String(abs % 60).padStart(2, '0');
    return 'UTC' + sign + hours + ':' + minutes;
}

function getTimezoneDisplayLabel(timezone) {
    const offsetMinutes = getTimezoneOffsetMinutes(timezone);
    return '(' + formatTimezoneOffsetLabel(offsetMinutes) + ') ' + timezone;
}

function setChangedStatus(value) {
    changed = value === true;
    tab.changeTab(id, { unsave: changed, unlock: false });
    tab.renderTabs();
}

function registerContentHandlers() {
    const content = top.global.content['content-' + id];

    if (!content) {
        return;
    }

    content.renderLang = async function () {
        await renderLang();
        renderLanguageOptions();
    };

    content.saveContent = async function () {
        return await submitActiveConfig();
    };
}

function parseWriteSizeLimit(value) {
    if (value === false || value === '' || value === null || value === undefined) {
        return false;
    }

    if (typeof value === 'number' && isFinite(value)) {
        return Math.max(0, Math.floor(value));
    }

    if (typeof value !== 'string') {
        return false;
    }

    const trimmed = value.trim();

    if (!trimmed) {
        return false;
    }

    const match = trimmed.match(/^([0-9]+(?:\.[0-9]+)?)\s*([a-z]*)$/i);

    if (!match) {
        return false;
    }

    const number = parseFloat(match[1]);

    if (!isFinite(number) || number < 0) {
        return false;
    }

    const unit = (match[2] || '').toUpperCase();
    const unitMap = { '': 0, B: 0, K: 1, KB: 1, M: 2, MB: 2, G: 3, GB: 3, T: 4, TB: 4, P: 5, PB: 5, E: 6, EB: 6, Z: 7, ZB: 7, Y: 8, YB: 8 };

    if (!Object.prototype.hasOwnProperty.call(unitMap, unit)) {
        return false;
    }

    return Math.max(0, Math.floor(number * Math.pow(1024, unitMap[unit])));
}

function normalizeExtList(value) {
    const text = String(value || '').trim().toLowerCase();

    if (!text) {
        return '';
    }

    const items = text.split(',').map(item => item.trim()).filter(Boolean);

    for (let i = 0; i < items.length; ++i) {
        if (!/^[0-9a-z?]+$/.test(items[i])) {
            return null;
        }
    }

    return items.join(',');
}

function normalizeTotp(value) {
    const text = String(value || '').trim().toUpperCase().replace(/\s+/g, '');

    if (!text) {
        return '';
    }

    if (!/^[A-Z2-7=]+$/.test(text)) {
        return null;
    }

    return text;
}

function isIntegerText(value) {
    return /^\d+$/.test(String(value || '').trim());
}

function setFieldTipVisible(selector, visible) {
    const tip = $(selector);
    visible ? tip.css('display', 'inline-block') : tip.css('display', 'none');
}

function validateWriteSizeLimitField() {
    const value = String($('#config-write-size-limit').val() || '').trim();
    const valid = value === '' || parseWriteSizeLimit(value) !== false;
    setFieldTipVisible('#config-tip-write-size-limit', !valid);
    return valid;
}

function validateTotpTimeFixField() {
    const value = String($('#config-totp-time-fix').val() || '').trim();
    const valid = isIntegerText(value);
    setFieldTipVisible('#config-tip-totp-time-fix', !valid);
    return valid;
}

function validateSessionNameField() {
    const value = String($('#config-session-name').val() || '').trim();
    const valid = /^[0-9A-Za-z_-]*$/.test(value);
    setFieldTipVisible('#config-tip-session-name', !valid);
    return valid;
}

function validateCacheTimeField() {
    const value = String($('#config-cache-time').val() || '').trim();
    const valid = isIntegerText(value);
    setFieldTipVisible('#config-tip-cache-time', !valid);
    return valid;
}

function validateBasicFields() {
    const checks = [
        { ok: validateWriteSizeLimitField(), key: 'config.tip_write_size_limit_invalid' },
        { ok: validateTotpTimeFixField(), key: 'config.tip_totp_time_fix_invalid' },
        { ok: validateSessionNameField(), key: 'config.tip_session_name_invalid' },
        { ok: validateCacheTimeField(), key: 'config.tip_cache_time_invalid' },
    ];

    for (let i = 0; i < checks.length; ++i) {
        if (!checks[i].ok) {
            return checks[i].key;
        }
    }

    return '';
}

function renderLanguageOptions() {
    const select = $('#config-lang');
    const value = String(select.data('value') || getCurrentLanguage());
    fillLanguageOptions(select);
    select.val(value);
}

function renderTimezoneOptions() {
    const hidden = $('#config-timezone');
    const input = $('#config-timezone-input');
    const timezoneValue = String(hidden.data('value') || hidden.val() || 'Asia/Shanghai');
    const globalList = top.global.config.timezone_list;
    const map = {};

    for (let i = 0; i < globalList.length; ++i) {
        map[String(globalList[i])] = true;
    }

    map[timezoneValue] = true;
    timezoneItems = Object.keys(map).sort((a, b) => a.localeCompare(b));
    hidden.val(timezoneValue).data('value', timezoneValue);

    for (let i = 0; i < timezoneItems.length; ++i) {
        if (timezoneItems[i] === timezoneValue) {
            input.val(getTimezoneDisplayLabel(timezoneValue));
            break;
        }
    }

    if (!input.val()) {
        input.val(getTimezoneDisplayLabel(timezoneValue));
    }

    renderTimezoneDropdown('');
}

function renderTimezoneDropdown(keyword) {
    const list = $('#config-timezone-list').empty();
    const selectedValue = String($('#config-timezone').val() || 'UTC');
    const text = String(keyword || '').trim().toLowerCase();
    let matched = 0;

    for (let i = 0; i < timezoneItems.length; ++i) {
        const timezone = timezoneItems[i];
        const label = getTimezoneDisplayLabel(timezone);
        const normalized = (label + ' ' + timezone).toLowerCase();

        if (text && normalized.indexOf(text) === -1) {
            continue;
        }

        const activeClass = timezone === selectedValue ? ' active' : '';
        list.append('<div class="config-timezone-option' + activeClass + '" data-value="' + escapeHtml(timezone) + '">' + escapeHtml(label) + '</div>');
        matched += 1;
    }

    if (!matched) {
        list.append('<div class="config-timezone-empty"></div>');
    }
}

function getTimezoneOptionList() {
    return $('#config-timezone-list .config-timezone-option');
}

function setActiveTimezoneOption(index) {
    const options = getTimezoneOptionList();

    if (!options.length) {
        return;
    }

    const maxIndex = options.length - 1;
    const nextIndex = Math.max(0, Math.min(maxIndex, index));
    const list = $('#config-timezone-list');
    const option = options.eq(nextIndex);

    options.removeClass('active');
    option.addClass('active');

    const listEl = list.get(0);
    const optionEl = option.get(0);

    if (!listEl || !optionEl) {
        return;
    }

    const optionTop = optionEl.offsetTop;
    const optionBottom = optionTop + optionEl.offsetHeight;
    const viewTop = listEl.scrollTop;
    const viewBottom = viewTop + listEl.clientHeight;

    if (optionTop < viewTop) {
        listEl.scrollTop = optionTop;
    } else if (optionBottom > viewBottom) {
        listEl.scrollTop = optionBottom - listEl.clientHeight;
    }
}

function moveActiveTimezoneOption(step) {
    const options = getTimezoneOptionList();

    if (!options.length) {
        return;
    }

    let index = options.index(options.filter('.active').first());

    if (index < 0) {
        index = step > 0 ? 0 : options.length - 1;
    } else {
        index += step;
    }

    setActiveTimezoneOption(index);
}

function getActiveTimezoneValue() {
    const active = getTimezoneOptionList().filter('.active').first();
    return active.length ? String(active.attr('data-value') || '') : '';
}

function showTimezoneDropdown() {
    const input = $('#config-timezone-input');
    renderTimezoneDropdown(input.val());
    $('#config-timezone-list').show();
}

function hideTimezoneDropdown() {
    $('#config-timezone-list').hide();
}

function selectTimezone(value, shouldMarkChanged) {
    const timezone = String(value || 'UTC');
    const hidden = $('#config-timezone');
    const input = $('#config-timezone-input');

    hidden.val(timezone).data('value', timezone);
    input.val(getTimezoneDisplayLabel(timezone));
    renderTimezoneDropdown('');
    hideTimezoneDropdown();

    if (shouldMarkChanged === true) {
        setChangedStatus(true);
    }
}

function getWriteLimitModeByUser(user) {
    if (user && user.write_exts_allow) {
        return 'allow';
    }

    if (user && user.write_exts_deny) {
        return 'deny';
    }

    return 'none';
}

function getWriteLimitValueByUser(user) {
    if (user && user.write_exts_allow) {
        return String(user.write_exts_allow);
    }

    if (user && user.write_exts_deny) {
        return String(user.write_exts_deny);
    }

    return '';
}

function createUserRow(user) {
    const row = $('<tr class="config-user-row"></tr>');
    const originUsername = String(user.origin_username || user.username || '');
    const isSelf = user.self === true;
    const inputReadonlyAttr = isSelf ? ' readonly="readonly" disabled="disabled"' : '';
    const checkDisabledAttr = isSelf ? ' disabled="disabled"' : '';

    row.attr('data-origin-username', originUsername);
    isSelf && row.addClass('config-user-row-self');
    row.append('<td><input class="config-input config-user-username" type="text" spellcheck="false" value="' + escapeHtml(user.username || '') + '"' + inputReadonlyAttr + ' /></td>');

    if (isSelf) {
        row.append('<td><input class="config-input config-user-password" type="password" spellcheck="false" value="" autocomplete="new-password" data-lang-title="config.user_self_edit_forbidden" data-lang-placeholder="config.user_self_edit_forbidden" readonly="readonly" disabled="disabled" /></td>');
    } else {
        row.append('<td><input class="config-input config-user-password" type="password" spellcheck="false" value="" autocomplete="new-password" data-lang-title="config.password_placeholder" data-lang-placeholder="config.password_placeholder" /></td>');
    }

    row.append('<td><input class="config-input config-user-totp" type="text" spellcheck="false" value="' + escapeHtml(user.totp || '') + '"' + inputReadonlyAttr + ' /></td>');
    row.append('<td><input class="config-user-flag config-user-readonly" type="checkbox" spellcheck="false" ' + (user.readonly ? 'checked' : '') + checkDisabledAttr + ' /></td>');
    row.append('<td><input class="config-user-flag config-user-admin" type="checkbox" spellcheck="false" ' + (user.admin ? 'checked' : '') + checkDisabledAttr + ' /></td>');
    row.append('<td><input class="config-input config-user-base-path" type="text" spellcheck="false" value="' + escapeHtml(user.base_path || './') + '"' + inputReadonlyAttr + ' /></td>');
    row.append('<td><input class="config-input config-user-write-size" type="text" spellcheck="false" value="' + escapeHtml(user.write_size_limit || '') + '"' + inputReadonlyAttr + ' /></td>');
    row.append('<td><div class="config-user-write-limit-wrap"><select class="config-input config-select config-user-write-limit-mode"' + checkDisabledAttr + '><option value="none" data-lang="config.write_limit_none"></option><option value="allow" data-lang="config.write_limit_allow"></option><option value="deny" data-lang="config.write_limit_deny"></option></select><input class="config-input config-user-ext config-user-write-limit-value" type="text" spellcheck="false" value="' + escapeHtml(user.write_limit_value || '') + '"' + inputReadonlyAttr + ' /></div></td>');

    if (isSelf) {
        row.append('<td><span class="config-user-self-lock" data-help="user-admin-ban" data-lang-title="config.user_self_edit_forbidden" aria-hidden="true"></span></td>');
    } else {
        row.append('<td><button class="config-delete config-user-delete" type="button" data-lang="config.delete"></button></td>');
    }

    row.find('.config-user-write-limit-mode').val(user.write_limit_mode || 'none');
    return row;
}

function fillConfigData(config) {
    cachedConfigData = config || {};

    $('#config-lang').data('value', String(cachedConfigData.lang || 'chs'));
    renderLanguageOptions();

    const timezone = String(cachedConfigData.timezone || 'UTC');
    $('#config-timezone').data('value', timezone);
    renderTimezoneOptions();
    selectTimezone(timezone, false);

    $('#config-write-size-limit').val(cachedConfigData.write_size_limit !== undefined && cachedConfigData.write_size_limit !== null ? String(cachedConfigData.write_size_limit) : '');
    $('#config-totp-time-fix').val(String(cachedConfigData.totp_time_fix !== undefined ? cachedConfigData.totp_time_fix : 0));
    $('#config-session-name').val(cachedConfigData.session_name !== undefined && cachedConfigData.session_name !== null ? String(cachedConfigData.session_name) : '');
    $('#config-cache-time').val(String(cachedConfigData.cache_time !== undefined ? cachedConfigData.cache_time : 2592000));
    $('#config-main-password').val(cachedConfigData.main_password !== undefined && cachedConfigData.main_password !== null ? String(cachedConfigData.main_password) : '');
    $('#config-comment').val(cachedConfigData.comment !== undefined && cachedConfigData.comment !== null ? String(cachedConfigData.comment) : '');

    const tbody = $('#config-users-tbody').empty();
    const users = Array.isArray(cachedConfigData.users) ? cachedConfigData.users : [];
    const currentUsername = getCurrentUsername();

    for (let i = 0; i < users.length; ++i) {
        const user = users[i] || {};

        tbody.append(createUserRow({
            origin_username: user.username || '',
            username: user.username || '',
            totp: user.totp || '',
            readonly: user.readonly === true,
            admin: user.admin === true,
            base_path: user.base_path || './',
            write_size_limit: user.write_size_limit !== undefined && user.write_size_limit !== null ? String(user.write_size_limit) : '',
            write_limit_mode: getWriteLimitModeByUser(user),
            write_limit_value: getWriteLimitValueByUser(user),
            self: currentUsername !== '' && String(user.username || '') === currentUsername,
        }));
    }

    renderLang();
    setChangedStatus(false);
}

async function loadConfigData() {
    const response = await ajax({ url: '?a=config', type: 'GET' });

    if (response.code) {
        error(response.code);
        return false;
    }

    fillConfigData(response.data || {});
    return true;
}

function bindGroupSwitch() {
    $(document).on('click', '.config-nav-item', function () {
        const group = $(this).data('group');
        const target = $('.config-group[data-group="' + group + '"]');

        $('.config-nav-item').removeClass('active');
        $(this).addClass('active');

        if (target.length) {
            const content = $('.config-content');
            const offsetTop = target.offset().top - content.offset().top + content.scrollTop();
            content.scrollTop(offsetTop);
        }
    });
}

function bindChangeStatus() {
    $(document).on('input change', '.config-input, .config-user-flag, .config-select', function () {
        if (this.id === 'config-lang') {
            $(this).data('value', $(this).val());
        }

        if (this.id === 'config-timezone-input') {
            showTimezoneDropdown();
            return;
        }

        setChangedStatus(true);
    });
}

function bindTimezonePicker() {
    $(document).on('focus click', '#config-timezone-input', function () {
        showTimezoneDropdown();
    });

    $(document).on('input', '#config-timezone-input', function () {
        showTimezoneDropdown();
    });

    $(document).on('keydown', '#config-timezone-input', function (event) {
        const key = event.key;

        if (key !== 'ArrowDown' && key !== 'ArrowUp' && key !== 'Enter') {
            return;
        }

        const list = $('#config-timezone-list');

        if (list.css('display') === 'none') {
            showTimezoneDropdown();
        }

        if (key === 'ArrowDown') {
            event.preventDefault();
            moveActiveTimezoneOption(1);
            return;
        }

        if (key === 'ArrowUp') {
            event.preventDefault();
            moveActiveTimezoneOption(-1);
            return;
        }

        const value = getActiveTimezoneValue();

        if (value) {
            event.preventDefault();
            selectTimezone(value, true);
        }
    });

    $(document).on('click', '.config-timezone-option', function () {
        const value = String($(this).attr('data-value') || 'UTC');
        selectTimezone(value, true);
    });

    $(document).on('click', function (event) {
        const target = $(event.target);

        if (!target.closest('#config-timezone-picker').length) {
            hideTimezoneDropdown();
        }
    });
}

function bindButtons() {
    $(document).on('change', '.config-user-readonly, .config-user-admin', function () {
        const current = $(this);

        if (current.prop('checked') !== true) {
            return;
        }

        const row = current.closest('.config-user-row');

        if (current.hasClass('config-user-readonly')) {
            row.find('.config-user-admin').prop('checked', false);
        } else {
            row.find('.config-user-readonly').prop('checked', false);
        }
    });

    $(document).on('click', '#config-add-user', function () {
        $('#config-users-tbody').append(createUserRow({ base_path: './' }));
        renderLang();
        setChangedStatus(true);
    });

    $(document).on('click', '.config-user-delete', function () {
        const row = $(this).closest('.config-user-row');
        const deleted = row.hasClass('config-user-row-deleted');

        row.toggleClass('config-user-row-deleted');
        $(this).attr('data-lang', deleted ? 'config.delete' : 'config.undo_delete').text('');
        renderLang();
        setChangedStatus(true);
    });

    $(document).on('click', '#config-reset-basic, #config-reset-users', function () {
        fillConfigData(cachedConfigData || {});
    });

    $(document).on('click', '#config-submit-basic', async function () {
        await submitBasicConfig();
    });

    $(document).on('click', '#config-submit-users', async function () {
        await submitUsersConfig();
    });
}

function bindBasicFieldValidation() {
    $(document).on('blur', '#config-write-size-limit', function () {
        validateWriteSizeLimitField();
    });

    $(document).on('blur', '#config-totp-time-fix', function () {
        validateTotpTimeFixField();
    });

    $(document).on('blur', '#config-session-name', function () {
        validateSessionNameField();
    });

    $(document).on('blur', '#config-cache-time', function () {
        validateCacheTimeField();
    });
}

function collectBasicPayload() {
    const payload = {
        lang: String($('#config-lang').val() || 'chs').trim(),
        timezone: String($('#config-timezone').val() || '').trim(),
        write_size_limit: String($('#config-write-size-limit').val() || '').trim(),
        totp_time_fix: String($('#config-totp-time-fix').val() || '').trim(),
        session_name: String($('#config-session-name').val() || '').trim(),
        cache_time: String($('#config-cache-time').val() || '').trim(),
        main_password: String($('#config-main-password').val() || ''),
        comment: String($('#config-comment').val() || ''),
    };

    if (!payload.lang) {
        error('common.error.invalid_request');
        return null;
    }

    if (!payload.timezone) {
        const typedTimezone = String($('#config-timezone-input').val() || '').trim();
        payload.timezone = typedTimezone || 'UTC';
    }

    const basicErrorKey = validateBasicFields();

    if (basicErrorKey) {
        error(basicErrorKey);
        return null;
    }

    return payload;
}

function collectUsersPayload() {
    const payload = { users: [] };
    let userErrorKey = '';

    function invalidateUser(key) {
        userErrorKey = key;
        payload.users = null;
        return false;
    }

    const usernames = {};
    let activeUsers = 0;
    let activeAdmins = 0;

    $('#config-users-tbody .config-user-row').each(function () {
        const row = $(this);
        const deleted = row.hasClass('config-user-row-deleted');
        const username = String(row.find('.config-user-username').val() || '').trim();
        const password = String(row.find('.config-user-password').val() || '');
        const totp = normalizeTotp(row.find('.config-user-totp').val());
        const readonly = row.find('.config-user-readonly').prop('checked') === true;
        const admin = row.find('.config-user-admin').prop('checked') === true;
        const basePath = String(row.find('.config-user-base-path').val() || '').trim();
        const writeSizeLimit = String(row.find('.config-user-write-size').val() || '').trim();
        const writeLimitMode = String(row.find('.config-user-write-limit-mode').val() || 'none');
        const writeLimitValue = normalizeExtList(row.find('.config-user-write-limit-value').val());
        const originUsername = String(row.attr('data-origin-username') || '').trim();
        let writeExtAllow = '';
        let writeExtDeny = '';

        if (writeLimitMode !== 'none' && writeLimitMode !== 'allow' && writeLimitMode !== 'deny') {
            return invalidateUser('config.user_tip_write_limit_mode_invalid');
        }

        if (writeLimitMode === 'allow') {
            writeExtAllow = writeLimitValue;
        } else if (writeLimitMode === 'deny') {
            writeExtDeny = writeLimitValue;
        }

        if (totp === null || writeLimitValue === null) {
            return invalidateUser(totp === null ? 'config.user_tip_totp_invalid' : 'config.user_tip_write_limit_value_invalid');
        }

        if (writeLimitMode !== 'none' && !writeLimitValue) {
            return invalidateUser('config.user_tip_write_limit_value_required');
        }

        if (writeSizeLimit !== '' && parseWriteSizeLimit(writeSizeLimit) === false) {
            return invalidateUser('config.user_tip_write_size_invalid');
        }

        if (!deleted) {
            if (!/^[0-9A-Za-z_-]+$/.test(username)) {
                return invalidateUser('config.user_tip_username_invalid');
            }

            if (!originUsername && password === '') {
                return invalidateUser('config.user_tip_new_user_password_required');
            }

            const lower = username.toLowerCase();

            if (usernames[lower]) {
                return invalidateUser('config.user_tip_username_duplicate');
            }

            usernames[lower] = true;
            activeUsers += 1;
            admin && (activeAdmins += 1);

            if (!basePath) {
                return invalidateUser('config.user_tip_base_path_required');
            }
        }

        payload.users.push({
            origin_username: originUsername,
            username: username,
            password: password,
            totp: totp === null ? '' : totp,
            readonly: readonly,
            admin: admin,
            base_path: basePath,
            write_size_limit: writeSizeLimit,
            write_exts_allow: writeExtAllow,
            write_exts_deny: writeExtDeny,
            delete: deleted,
        });
    });

    if (payload.users === null || userErrorKey) {
        error(userErrorKey || 'common.error.invalid_request');
        return null;
    }

    if (activeUsers <= 0) {
        error('config.user_tip_at_least_one_user');
        return null;
    }

    if (activeAdmins <= 0) {
        error('config.user_tip_at_least_one_admin');
        return null;
    }

    return payload;
}

async function submitConfig(payload) {
    if (!payload) {
        return { code: 1000 };
    }

    const response = await ajax({
        url: '?a=config',
        data: JSON.stringify(payload),
    });

    if (response.code) {
        error(response.code);
        return response;
    }

    await loadConfig();
    await loadConfigData();
    top.global.frame.openDialog({
        type: 'success',
        text_1: 'common.error.success',
        buttons: [{
            label: 'common.ok',
            onClick: function () {
                top.global.frame.closeDialog();
            },
        }],
    });

    return response;
}

async function submitBasicConfig() {
    return await submitConfig(collectBasicPayload());
}

async function submitUsersConfig() {
    return await submitConfig(collectUsersPayload());
}

async function submitActiveConfig() {
    const activeGroup = String($('.config-nav-item.active').data('group') || 'basic');
    return await (activeGroup === 'users' ? submitUsersConfig() : submitBasicConfig());
}

async function init() {
    registerContentHandlers();
    new ScrollBar($('.config-content')[0], { barWidth: 8 });
    await renderLang();
    renderLanguageOptions();
    bindGroupSwitch();
    bindChangeStatus();
    bindTimezonePicker();
    bindButtons();
    bindBasicFieldValidation();
    await loadConfigData();
}

init();
</script><!----- FILE js/config.js END ----->
<!----- FILE js/editor.js START -----><script>
const id = $(frameElement).data('id');
const content = top.global.content['content-' + id];
content.renderLang = renderLang;

const contentInfo = {
    buffer: null,
    encoding: 'utf-8',
    bom: false,
};

renderPath(content.path);
loadFileContent(content.path);
renderLang();

let firstLoaded = false;
let changeEncoding = false;
let saving = false;
let needReSave = false;
const isSvgFile = /\.svg$/i.test(content.path || '');

const $editor = $('#editor-editor');
const $editorScroll = $('#editor-scroll');
const $highlightingSelect = $('#editor-info-highlighting-list');
const $saveAndViewButton = $('#editor-info-save-and-view');

for (let i = 0; i < CodeMirror.modeInfo.length; ++i) {
    $highlightingSelect.append(`<option value="${CodeMirror.modeInfo[i].name}">${CodeMirror.modeInfo[i].name}</option>`);
}

const editor = CodeMirror($editor[0], {
    theme: 'blackboard',
    lineNumbers: true,
    lineWrapping: true,
    styleActiveLine: true,
    matchBrackets: true,
    readOnly: isGlobalReadonly(),
    scrollbarStyle: 'null',
});

$(editor.getWrapperElement()).on('click contextmenu', function (e) {
    e.stopPropagation();
});

if (isGlobalReadonly()) {
    $('#editor-info-save').hide();
}

$saveAndViewButton.toggle(isSvgFile && !isGlobalReadonly());

const scrollBar = new ScrollBar($editorScroll[0], { barWidth: 14 });

function resetScrollBar() {
    const scrollInfo = editor.getScrollInfo();
    $editorScroll.find('.editor-scroll-in').css({ height: scrollInfo.height + 'px' });
    $editorScroll[0].scrollTop = scrollInfo.top;
    scrollBar.render();
}

new IntersectionObserver(resetScrollBar).observe($editorScroll[0]);
new ResizeObserver(resetScrollBar).observe($editorScroll[0]);

scrollBar.on('drag', function () {
    editor.scrollTo(0, this.outer.scrollTop);
});

scrollBar.on('bgclick', function () {
    editor.scrollTo(0, this.outer.scrollTop);
});

editor.on('scroll', function () {
    if (scrollBar.dragStartY >= 0) {
        return;
    }

    resetScrollBar();
});

editor.on('viewportChange', function () {
    if (scrollBar.dragStartY >= 0) {
        return;
    }

    resetScrollBar();
});

$editor.on('mouseover', function () {
    if (scrollBar.dragStartY >= 0) {
        return;
    }

    scrollBar.mouseOver = true;
    scrollBar.render();
});

$editor.on('mouseout', function () {
    if (scrollBar.dragStartY >= 0) {
        return;
    }

    scrollBar.mouseOver = false;
    scrollBar.render();
});

editor.on('change', function () {
    firstLoaded && !changeEncoding && setUnsavedChanges(true);
});

$(document).on('keydown', async function (e) {
    const key = e.key.toLowerCase();

    if (e.ctrlKey && key === 's') {
        e.preventDefault();
        if (isGlobalReadonly()) {
            return;
        }
        await saveContent();
    } else if (e.ctrlKey && key === 'r') {
        e.preventDefault();
        top.global.frame.resetTreeWidth();
    }
});

$(document).on('click', function () {
    top.global.tree.blur();
});

$(document).on('contextmenu', function () {
    top.global.tree.blur();
});

$highlightingSelect.on('change', function () {
    const mode = CodeMirror.findModeByName($(this).val());
    mode && editor.setOption('mode', mode.mode);
});

$('#editor-info-encoding-list').on('change', function () {
    const newEncoding = $(this).val();

    const changeEncodingFunc = () => {
        contentInfo.encoding = newEncoding;
        changeEncoding = true;
        fillFileContent();
        renderContentInfo();
        changeEncoding = false;
    };

    if (!content.unsave) {
        changeEncodingFunc();
        return;
    }

    top.global.frame.openDialog({
        type: 'warning',
        text_1: 'editor.dialog.change_encoding_unsaved_1',
        text_2: 'editor.dialog.change_encoding_unsaved_2',
        buttons: [{
            label: 'editor.dialog.ok',
            onClick: async function () {
                changeEncodingFunc();
                top.global.frame.closeDialog();
            },
        }, {
            label: 'editor.dialog.cancel',
            onClick: async function () {
                renderContentInfo();
                top.global.frame.closeDialog();
            },
        }],
    })
});

$('#editor-info-bom-checkbox').on('change', function () {
    if (isGlobalReadonly()) {
        $(this).prop('checked', contentInfo.bom);
        return;
    }

    contentInfo.bom = $(this).prop('checked');
    renderContentInfo();
});

$('#editor-info-save').on('click', function () {
    if (isGlobalReadonly()) {
        return;
    }

    saveContent();
});

$('#editor-info-save-and-view').on('click', async function () {
    if (isGlobalReadonly()) {
        return;
    }

    const response = await saveContent();

    if (response.code) {
        return;
    }

    openFileWithImageViewer();
});

function openFileWithImageViewer() {
    const tab = top.global.tab;
    const openTab = tab.findTab({ path: content.path, url: '?f=html/image.html' });

    if (openTab) {
        tab.showTab(openTab.id);
    } else {
        const newTab = tab.addTab({ type: 'file', path: content.path, url: '?f=html/image.html' }, 'after_current');
        tab.showTab(newTab.id);
    }

    tab.renderTabs();
}

function renderContentInfo() {
    $('#editor-info-encoding-list').val(contentInfo.encoding);
    const $bom = $('#editor-info-bom');
    const $bomCheckBox = $('#editor-info-bom-checkbox');
    const readonly = isGlobalReadonly();

    if (contentInfo.encoding === 'utf-8') {
        if (readonly) {
            $bom.addClass('disabled').removeAttr('data-lang-title');
            $bomCheckBox.prop('disabled', true);
        } else {
            $bom.removeClass('disabled').removeAttr('data-lang-title');
            $bomCheckBox.prop('disabled', false);
        }
    } else {
        contentInfo.bom = false;
        $bom.addClass('disabled').attr('data-lang-title', 'editor.info.bom_disabled');
        $bomCheckBox.prop('disabled', true);
    }

    $bomCheckBox.prop('checked', contentInfo.bom);
    renderLang();
}

function detectEncoding(buffer) {
    const encodings = ['utf-8', 'gbk', 'gb18030', 'gb2312', 'big5', 'euc-jp', 'shift_jis', 'euc-kr', 'iso-8859-1', 'windows-1252', 'windows-1251'];

    for (let i = 0; i < encodings.length; ++i) {
        try {
            new TextDecoder(encodings[i], { fatal: true }).decode(buffer);
            return encodings[i];
        } catch (e) {
        }
    }

    return 'utf-8';
}

function detectBOM(buffer) {
    return buffer.length >= 3 && buffer[0] === 0xEF && buffer[1] === 0xBB && buffer[2] === 0xBF;
}

function fillFileContent() {
    editor.setValue(new TextDecoder(contentInfo.encoding).decode(contentInfo.buffer));

    if (contentInfo.encoding === 'utf-8' || top.global.config.extension.iconv !== false) {
        return;
    }

    top.global.frame.openDialog({
        type: 'warning',
        text_1: 'common.error.iconv_not_enabled',
        buttons: [{
            label: 'editor.dialog.ok',
            onClick: async function () {
                top.global.frame.closeDialog();
            },
        }],
    });
}

async function loadFileContent(path) {
    const value = await getFileContent(path);

    if (value.code) {
        error(value.code);
        return;
    }

    const filename = path.split('/').pop();
    const mode = CodeMirror.findModeByFileName(filename);

    if (mode) {
        editor.setOption('mode', mode.mode);
        $highlightingSelect.val(mode.name);
    }

    contentInfo.buffer = value.data;
    contentInfo.encoding = detectEncoding(contentInfo.buffer);
    contentInfo.bom = detectBOM(contentInfo.buffer);

    fillFileContent();
    renderContentInfo();
    firstLoaded = true;
}

async function getFileContent(path) {
    const params = { path: path };

    return await new Promise(resolve => {
        const xhr = new XMLHttpRequest();
        xhr.responseType = 'arraybuffer';
        xhr.open('POST', '?a=read', true);

        xhr.onload = function () {
            if (xhr.status !== 200) {
                resolve({ code: 500, message: 'Internal server error.' });
                return;
            }

            const contentType = xhr.getResponseHeader('Content-Type');

            if (!contentType || !contentType.includes('application/json')) {
                resolve({ code: 0, message: 'Success', data: new Uint8Array(xhr.response) });
                return;
            }

            const decoder = new TextDecoder('utf-8');
            const str = decoder.decode(xhr.response);
            resolve(JSON.parse(str));
        };

        xhr.send(JSON.stringify(params));
    });
}

function setUnsavedChanges(unsave) {
    const tab = top.global.tab;
    tab.changeTab(id, { unsave: unsave, unlock: false });
    tab.renderTabs();
}

async function saveContent() {
    if (isGlobalReadonly()) {
        return { code: 0 };
    }

    if (saving) {
        needReSave = true;
        return { code: 0 };
    }

    saving = true;
    const response = await saveFile(content.path, editor.getValue(), contentInfo.encoding);
    response.code || setUnsavedChanges(false);
    saving = false;

    if (needReSave) {
        needReSave = false;
        return await saveContent();
    }

    return response;
}

async function saveFile(path, content, encoding) {
    let buffer = new Uint8Array(new TextEncoder().encode(content));

    if (encoding === 'utf-8') {
        if (contentInfo.bom) {
            detectBOM(buffer) || (buffer = new Uint8Array([0xEF, 0xBB, 0xBF, ...buffer]));
        } else {
            detectBOM(buffer) && (buffer = buffer.slice(3));
        }
    }

    const formData = new FormData();
    formData.append('content', new Blob([buffer]));
    formData.append('path', path);
    formData.append('encoding', encoding);

    const response = await ajax({
        url: '?a=upload',
        data: formData,
        processData: false,
        contentType: false,
        dataType: 'json',
    });

    response.code && error(response.code);
    return response;
}

function treeRename() {
    renderPath(content.path);
    renderLang();
}

content.document = document;
content.saveContent = saveContent;
content.treeRename = treeRename;
