<!----- FILE js/folder.js START -----><script>
class Node {
    constructor(params) {
        this.$ = null;
        this.change = [];

        const properties = {
            new: false,
            dir: '',
            name: '',
            type: 'folder',
            path: '',
            size: 0,
            open: false,
            disk: false,
            mine: true,
            link: false,
            readonly: false,
            mode: '',
            active: false,
            rename: false,
            blobUrl: null,
            created: 0,
            modified: 0,
            calcSize: 'no',
            selected: false,
            nameError: false,
            iconBlobUrl: null,
            clickTime: Date.now(),
        };

        const setMethods = {
            dir: value => {
                properties.path = value ? value + '/' + this.name : this.name;
            },
            name: value => {
                properties.path = this.dir ? this.dir + '/' + value : value;
            },
            active: value => {
                value && setNodeStatusAll({ active: false });
            },
        };

        let rendered = false;

        for (const k in properties) {
            Object.defineProperty(this, k, {
                get: () => properties[k],
                set: value => {
                    if (value === properties[k]) {
                        return;
                    }

                    setMethods[k] && setMethods[k](value);
                    properties[k] = value;
                    this.change.includes(k) || this.change.push(k);
                    rendered = false;

                    requestAnimationFrame(() => {
                        rendered || this.render();
                        rendered = true;
                    });
                }
            });
        }

        Object.assign(this, params);
        return this;
    }

    fileType() {
        return this.type === 'folder' ? 'folder' : fileType(this.name.split('.').pop().toLowerCase());
    }

    isImage() {
        return ['png', 'svg'].includes(this.fileType());
    }

    isVideo() {
        return ['mp4'].includes(this.fileType());
    }

    isAudio() {
        return ['mp3'].includes(this.fileType());
    }

    isChessText() {
        return ['pfc', 'pgn'].includes(this.fileType());
    }

    isExecutable() {
        return ['exe'].includes(this.fileType());
    }

    setCustomIcon($icon) {
        if (!$icon || !$icon.length) {
            return this;
        }

        const url = this.iconBlobUrl ? `url(${this.iconBlobUrl})` : '';
        $icon[0].style.setProperty('background-image', url, 'important');
        $icon[0].style.setProperty('background-size', 'contain', 'important');
        $icon[0].style.setProperty('background-repeat', 'no-repeat', 'important');
        $icon[0].style.setProperty('background-position', 'center center', 'important');
        return this;
    }

    clearCustomIcon($icon) {
        if (!$icon || !$icon.length) {
            return this;
        }

        $icon[0].style.removeProperty('background-image');
        $icon[0].style.removeProperty('background-size');
        $icon[0].style.removeProperty('background-repeat');
        $icon[0].style.removeProperty('background-position');
        return this;
    }

    async loadIcon() {
        if (!this.isExecutable()) {
            return this;
        }

        if (this.iconBlobUrl) {
            return this;
        }

        const xhr = new XMLHttpRequest();
        xhr.responseType = 'arraybuffer';
        xhr.open('POST', '?a=icon', true);

        xhr.onload = () => {
            if (xhr.status !== 200 || !xhr.response) {
                return;
            }

            const contentType = xhr.getResponseHeader('Content-Type') || 'image/vnd.microsoft.icon';

            if (!contentType.startsWith('image/')) {
                return;
            }

            if (this.iconBlobUrl) {
                URL.revokeObjectURL(this.iconBlobUrl);
            }

            this.iconBlobUrl = URL.createObjectURL(new Blob([xhr.response], { type: contentType }));

            if (this.$) {
                const $icon = this.$.find('.folder-item-icon').first();
                this.setCustomIcon($icon);
            }
        };

        xhr.onerror = () => { };
        xhr.send(JSON.stringify({ path: this.path }));
        return this;
    }

    renderSimple() {
        this.change.includes('active') && (this.active ? this.$.addClass('folder-item-active') : this.$.removeClass('folder-item-active'));
        this.change.includes('selected') && (this.selected ? this.$.addClass('folder-item-selected') : this.$.removeClass('folder-item-selected'));
        this.change.includes('created') && this.$.find('.folder-item-created').text(strTime(this.created));
        this.change.includes('modified') && this.$.find('.folder-item-modified').text(strTime(this.modified));
        this.change.length = 0;
        updateToolbarActionStatesNextFrame();
        renderLang();
        return this;
    }

    render(rebuild = false) {
        // #region 检查是否支持简单渲染
        rebuild && (this.$ = null);
        const simple = ['active', 'selected', 'created', 'modified'];
        const notSimple = this.change.find(c => !simple.includes(c))

        if (this.$ && !notSimple) {
            return this.renderSimple();
        }
        // #endregion

        // #region 创建节点
        const $new = $(`<li class="folder-item" title="${this.name}"></li>`);

        this.active && $new.addClass('folder-item-active');
        this.rename && $new.addClass('folder-item-rename');
        this.selected && $new.addClass('folder-item-selected');
        this.nameError && $new.addClass('folder-item-name-error');
        this.disk && $new.addClass('folder-item-disk');
        this.mine || $new.addClass('folder-item-not-mine');
        this.link && $new.addClass('folder-item-link');

        const isFolder = this.type === 'folder';
        const ext = isFolder ? 'folder' : this.name.includes('.') ? this.name.split('.').pop().toLowerCase() : 'null';
        const type = this.disk ? 'disk' : fileType(ext);
        const operations = $(`<div class="folder-item-operations"></div>`);
        const name = $('<div class="folder-item-name"></div>');

        if (this.rename) {
            const input = $('<input class="folder-item-name-input" type="text" spellcheck="false" />').val(this.name);
            input.on('click', e => e.stopPropagation());
            input.on('contextmenu', e => e.stopPropagation());
            input.on('keydown', e => this.keyDownNameInput(e));
            input.on('input', () => this.inputNameInput());
            input.on('blur', () => this.blurNameInput());
            name.append(input);
        } else {
            this.disk ? name.append(`<span data-lang="tree.local_disk"></span>(${this.name})`) : name.text(this.name);
        }
        // #endregion

        // #region 单击双击事件
        if (Folder.mode === 'detail') {
            name.on('dblclick', e => isFolder ? this.openFolder(e) : this.openFile(e));
        } else {
            $new.on('dblclick', e => isFolder ? this.openFolder(e) : this.openFile(e));
        }

        $new.on('click', e => {
            if ($(e.target).closest('input, textarea, select').length) {
                return true;
            }

            Folder.mode === 'thumb' && this.isImage() && loadItemThumb(this);
            const anchor = e.shiftKey && !e.ctrlKey ? getNodeByStatus({ active: true }) : null;
            this.active = true;

            if (e.shiftKey && !e.ctrlKey && anchor && anchor !== this) {
                selectRangeByAnchor(anchor, this);
            } else if (e.ctrlKey) {
                this.selected = !this.selected;
            } else {
                setNodeStatusAll({ selected: false });
                this.selected = true;
            }
        });

        $new.on('contextmenu', e => {
            if ($(e.target).closest('input, textarea, select').length) {
                return true;
            }

            return this.contextmenu(e);
        });
        // #endregion

        // #region 文件容器
        if (Folder.mode === 'detail' || !this.isImage()) {
            const $icon = $(`<div class="folder-item-icon filetype-${type}"></div>`);

            if (this.isExecutable()) {
                this.iconBlobUrl ? this.setCustomIcon($icon) : this.clearCustomIcon($icon);
                this.loadIcon();
            } else {
                this.clearCustomIcon($icon);
            }

            $new.append($icon);
        } else if (this.blobUrl) {
            $new.append(`<div class="folder-item-image"><img class="folder-item-image-img" src="${this.blobUrl}" /></div>`);
        } else {
            $new.append('<div class="folder-item-image"><img class="folder-item-image-img" src="?f=img/filetype/png.svg" /></div>');
            new IntersectionObserver(t => t[0] && t[0].isIntersecting && this.loadThumb()).observe($new[0]);
        }
        // #endregion

        // #region 文件详情
        $new.append(name);
        $new.append(operations);
        $new.append(`<div class="folder-item-modified">${strTime(this.modified)}</div>`);
        $new.append(`<div class="folder-item-created">${strTime(this.created)}</div>`);

        if (isFolder) {
            $new.append('<div class="folder-item-type folder-item-type-folder" data-lang="folder.detail.directory" data-lang-title="folder.detail.directory"></div>');
        } else {
            $new.append(`<div class="folder-item-type">${ext}</div>`);
        }

        if (isFolder) {
            if (this.calcSize === 'no') {
                const calc = $('<span class="folder-item-size-calc" data-lang="folder.calc"></span>');
                calc.on('click', e => this.calculateFolderSize(e));
                $new.append($('<div class="folder-item-size"></div>').append(calc));
            } else if (this.calcSize === 'calculating') {
                $new.append(`<div class="folder-item-size" data-lang="folder.calculating"></div>`);
            } else {
                $new.append(`<div class="folder-item-size">${fileSize(this.size)}</div>`);
            }
        } else {
            $new.append(`<div class="folder-item-size">${fileSize(this.size)}</div>`);
        }
        // #endregion

        // #region 操作栏
        if (isFolder) {
            const open = $('<span class="folder-item-operation folder-item-operation-open" data-lang-title="folder.open"></span>');
            open.on('click', e => this.openFolder(e));
            operations.append(open);
        } else if (this.isImage()) {
            const view = $('<span class="folder-item-operation folder-item-operation-view" data-lang-title="folder.view"></span>');
            view.on('click', e => this.openFileWith('image'));
            operations.append(view);
        } else if (this.isAudio()) {
            const view = $('<span class="folder-item-operation folder-item-operation-view" data-lang-title="folder.view"></span>');
            view.on('click', e => this.openFileWith('audio'));
            operations.append(view);
        } else if (this.isVideo()) {
            const view = $('<span class="folder-item-operation folder-item-operation-view" data-lang-title="folder.view"></span>');
            view.on('click', e => this.openFileWith('video'));
            operations.append(view);
        } else if (CodeMirror.findModeByFileName(this.name) || ['pfc', 'pgn'].includes(ext)) {
            const edit = $('<span class="folder-item-operation folder-item-operation-edit" data-lang-title="folder.edit"></span>');
            edit.on('click', e => this.openFileWith('editor'));
            operations.append(edit);
        } else {
            const download = $('<span class="folder-item-operation folder-item-operation-download" data-lang-title="folder.download"></span>');
            download.on('click', e => this.downloadFile(e));
            operations.append(download);
        }

        if (isSearchMode()) {
            const openContainingFolder = $('<span class="folder-item-operation folder-item-operation-open-containing-folder" data-lang-title="folder.open_containing_folder"></span>');
            openContainingFolder.on('click', e => {
                e.stopPropagation();
                const targetPath = getParentPath(this.path) || '';
                openFolderInNewTab({ path: targetPath });
            });
            operations.append(openContainingFolder);
        }

        if (!isGlobalReadonly() && !isSearchMode()) {
            const copy = $('<span class="folder-item-operation folder-item-operation-copy" data-lang-title="folder.copy"></span>');
            const cut = $('<span class="folder-item-operation folder-item-operation-cut" data-lang-title="folder.cut"></span>');
            const rename = $('<span class="folder-item-operation folder-item-operation-rename" data-lang-title="folder.rename"></span>');
            const remove = $('<span class="folder-item-operation folder-item-operation-remove" data-lang-title="folder.remove"></span>');

            copy.on('click', e => {
                e.stopPropagation();
                setClipboard('copy', this);
            });

            cut.on('click', e => {
                e.stopPropagation();
                setClipboard('cut', this);
            });

            rename.on('click', e => this.changeName(e));
            remove.on('click', e => this.remove(e));
            operations.append(copy).append(cut).append(rename).append(remove);
        }
        // #endregion

        // #region 渲染到页面
        if (this.$) {
            this.$.replaceWith($new);
        } else {
            const index = Folder.items.indexOf(this);
            const siblings = Folder.$.children();
            index >= siblings.length ? Folder.$.append($new) : siblings.eq(index).before($new);
        }

        this.$ = $new;
        this.change.length = 0;

        if (this.rename) {
            const input = $new.find('.folder-item-name-input').focus()[0];
            const dotIndex = this.name.lastIndexOf('.');
            input.setSelectionRange(0, dotIndex > 0 ? dotIndex : this.name.length);
        }

        updateToolbarActionStatesNextFrame();
        renderLang();
        // #endregion

        return this;
    }

    openFile() {
        if (this.isImage()) {
            this.openFileWith('image');
            return this;
        }

        if (this.isVideo()) {
            this.openFileWith('video');
            return this;
        }

        if (this.isAudio()) {
            this.openFileWith('audio');
            return this;
        }

        if (CodeMirror.findModeByFileName(this.name) || this.isChessText()) {
            this.openFileWith('editor');
            return this;
        }

        this.downloadFile();
        return this;
    }

    openFileWith(type) {
        if (!['editor', 'image', 'video', 'audio'].includes(type)) {
            return this;
        }

        const openTab = tab.findTab({ path: this.path, url: `?f=html/${type}.html` });

        if (openTab) {
            tab.showTab(openTab.id);
        } else {
            const newTab = tab.addTab({ type: 'file', path: this.path, url: `?f=html/${type}.html` }, 'after_current');
            tab.showTab(newTab.id);
        }

        tab.renderTabs();
        return this;
    }

    async downloadFile() {
        const { code, data } = await ajax({ url: '?a=download', data: JSON.stringify({ path: this.path, timeout: 60 }) });
        code ? error(code) : (window.location.href = `?d=${data.token}`);
    }

    async fetchDownloadUrl() {
        const { code, data } = await ajax({ url: '?a=download', data: JSON.stringify({ path: this.path, timeout: 300 }) });

        if (code) {
            error(code);
            return this;
        }

        const downloadUrl = `${window.location.origin}${window.location.pathname}?d=${data.token}`;

        top.global.frame.openDialog({
            type: 'success',
            text_1: 'tree.dialog.fetch_download_url_success',
            text_2: downloadUrl,
            buttons: [{
                label: 'tree.dialog.copy',
                onClick: function () {
                    top.global.frame.copy(downloadUrl);
                    top.global.frame.closeDialog();

                    top.global.frame.openDialog({
                        type: 'success',
                        text_1: 'tree.dialog.copy_success',
                        buttons: [{
                            label: 'common.ok',
                            onClick: function () {
                                top.global.frame.closeDialog();
                            },
                        }],
                    });
                },
            }, {
                label: 'common.ok',
                onClick: function () {
                    top.global.frame.closeDialog();
                },
            }],
        });
    }

    openFolder() {
        if (isSearchMode()) {
            const openTab = tab.findTab({ type: 'folder', path: this.path, url: '?f=html/folder.html' });

            if (openTab) {
                tab.showTab(openTab.id);
            } else {
                const newTab = tab.addTab({ type: 'folder', path: this.path, url: '?f=html/folder.html' }, 'after_current');
                tab.showTab(newTab.id);
            }

            tab.renderTabs();
            return this;
        }

        content.path = this.path;
        renderFolderPath(this.path);
        fetchFolder(this.path);
        return this;
    }

    async calculateFolderSize(e) {
        e && e.stopPropagation && e.stopPropagation();

        if (this.calcSize === 'calculating' || this.calcSize === 'finish') {
            return this;
        }

        this.calcSize = 'calculating';

        const { code, data } = await ajax({ url: '?a=size', data: JSON.stringify({ path: this.path }) });

        if (code) {
            this.calcSize = 'no';
            error(code);
        } else {
            this.size = data.size;
            this.calcSize = 'finish';
        }

        return this;
    }

    async loadThumb() {
        this.blobUrl = await getImageBlobUrl(this.path);
        return this;
    }

    contextmenu(e) {
        if ($(e.target).closest('input, textarea, select').length) {
            return true;
        }

        e.preventDefault();
        e.stopPropagation();

        const selected = getNodeByStatusAll({ selected: true });

        if (!this.selected || selected.length <= 1) {
            setNodeStatusAll({ selected: false });
            this.selected = true;
        }

        this.active = true;
        openContextMenu(e, this);
        return false;
    }

    changeName(e) {
        e && e.stopPropagation();
        this.rename = true;
        return this;
    }

    keyDownNameInput(e) {
        e.stopPropagation();

        if (e.key === 'Escape') {
            e.preventDefault();
            removeFolderNameInputErrorTips();
            this.$.find('.folder-item-name-input').removeClass('error warning');
            this.new ? this.cancelCreate() : (this.rename = false);
        } else if (e.key === 'Enter') {
            e.preventDefault();
            this.$.find('.folder-item-name-input').trigger('blur');
        }

        return true;
    }

    cancelCreate() {
        if (!this.new) {
            return this;
        }

        removeFolderNameInputErrorTips();
        this.createCancelled = true;
        this.$ && this.$.remove();
        Folder.items.remove(this);
        return this;
    }

    inputNameInput() {
        if (!this.rename) {
            return this;
        }

        const input = this.$.find('.folder-item-name-input');
        const newName = input.removeClass('error warning').val().trim();
        const siblingNames = Folder.items.filter(item => item !== this).map(item => item.name);
        const validation = checkValidFilename(newName, siblingNames);
        removeFolderNameInputErrorTips();

        if (validation.level !== 'success') {
            input.addClass(validation.level);
            showFolderNameInputErrorTip(input, newName, validation);
            renderLang();
        }

        return this;
    }

    async blurNameInput() {
        if (!this.rename || this.createCancelled) {
            return this;
        }

        removeFolderNameInputErrorTips();
        const input = this.$.find('.folder-item-name-input');
        const newName = input.val().trim();
        const siblingNames = Folder.items.filter(item => item !== this).map(item => item.name);
        const validation = checkValidFilename(newName, siblingNames);

        if (validation.level !== 'success' || newName === this.name) {
            if (this.new) {
                return this.cancelCreate();
            }

            this.nameError = false;
            this.rename = false;
            return this;
        }

        const oldPath = this.path;
        const newPath = this.dir ? this.dir + '/' + newName : newName;

        if (this.new) {
            let response;

            if (this.type === 'folder') {
                response = await ajax({ url: '?a=mkdir', data: JSON.stringify({ path: newPath }) });
            } else {
                const formData = new FormData();
                formData.append('content', new Blob(['']));
                formData.append('path', newPath);
                formData.append('encoding', 'utf-8');
                response = await ajax({ url: '?a=upload', data: formData, processData: false, contentType: false, dataType: 'json' });
            }

            response.code && error(response.code);
            await refreshFolder();
            await syncDirectory(content.path);
            return this;
        }

        const { code } = await ajax({ url: '?a=move', data: JSON.stringify({ src: oldPath, dst: newPath }) });

        if (code) {
            error(code);
            this.nameError = false;
            this.rename = false;
            return this;
        }

        this.blobUrl && URL.revokeObjectURL(this.blobUrl);
        this.blobUrl = null;
        this.iconBlobUrl && URL.revokeObjectURL(this.iconBlobUrl);
        this.iconBlobUrl = null;
        this.name = newName;
        this.nameError = false;
        this.rename = false;

        let openTab = tab.findTab({ path: oldPath });

        while (openTab) {
            tab.changeTab(openTab.id, { path: newPath });
            top.global.frame.trigger(openTab.id, 'treeRename');
            openTab = tab.findTab({ path: oldPath });
        }

        tab.renderTabs();
        await syncDirectory(content.path);
        return this;
    }

    remove(e) {
        if (isGlobalReadonly()) {
            return this;
        }

        e && e.stopPropagation();
        const removeList = this.selected ? getNodeByStatusAll({ selected: true }) : [this];
        const multi = removeList.length > 1;

        top.global.frame.openDialog({
            type: 'warning',
            text_1: 'tree.dialog.remove_confirm_title' + (multi ? '_multiple' : ''),
            text_1_args: [multi ? '' : this.name],
            text_2: 'tree.dialog.remove_confirm_text',
            buttons: [{
                label: 'common.ok',
                onClick: async function () {
                    top.global.frame.closeDialog();

                    await Promise.all(removeList.map(async node => {
                        const { code } = await ajax({ url: '?a=remove', data: JSON.stringify({ path: node.path }) });

                        if (code) {
                            error(code);
                            return;
                        }

                        node.blobUrl && URL.revokeObjectURL(node.blobUrl);
                        node.iconBlobUrl && URL.revokeObjectURL(node.iconBlobUrl);
                        node.$.remove();
                        Folder.items.remove(node);

                        let removeTab = tab.findTab({ path: node.path });

                        while (removeTab) {
                            tab.removeTab(removeTab.id);
                            removeTab = tab.findTab({ path: node.path });
                        }
                    }));

                    tab.renderTabs();
                    Folder.mode === 'thumb' && loadItemThumb();
                    updateToolbarActionStates();
                    await syncDirectory(content.path);
                },
            }, {
                label: 'common.cancel',
                onClick: function () {
                    top.global.frame.closeDialog();
                },
            }],
        });

        return this;
    }
}

const tab = top.global.tab;
const id = $(frameElement).data('id');
const content = top.global.content['content-' + id];

function isSearchMode() {
    return content.type === 'search';
}

content.renderLang = renderLang;

content.reloadPath = path => {
    if (typeof path !== 'string' || !isSamePath(content.path, path)) {
        return false;
    }

    return refreshFolder();
};

function isWindowsComputerRoot() {
    const config = top.global.config || {};
    const userinfo = top.global.data.userinfo || {};
    return config.platform === 'windows' && userinfo.base_root === true && normalizePath(content.path) === '';
}

function compactToolbarSeparators() {
    const children = $('.folder-action').children();
    let lastVisibleWasSeparator = true;

    for (let i = 0; i < children.length; ++i) {
        const child = $(children[i]);

        if (child.css('display') === 'none') {
            continue;
        }

        if (child.hasClass('folder-action-separator')) {
            if (lastVisibleWasSeparator) {
                child.hide();
                continue;
            }

            lastVisibleWasSeparator = true;
        } else {
            lastVisibleWasSeparator = false;
        }
    }

    for (let i = children.length - 1; i >= 0; --i) {
        const child = $(children[i]);

        if (child.css('display') === 'none') {
            continue;
        }

        if (child.hasClass('folder-action-separator')) {
            child.hide();
        }

        break;
    }
}

function applyToolbarReadonlyVisibility() {
    const writeActionSelectors = [
        '#folder-mode-upload',
        '#folder-mode-uploading',
        '#folder-mode-upload-cancel',
        '#folder-mode-new-file',
        '#folder-mode-new-folder',
        '#folder-mode-cut',
        '#folder-mode-copy',
        '#folder-mode-paste',
        '#folder-mode-remove',
    ];

    const readonly = isGlobalReadonly();

    for (let i = 0; i < writeActionSelectors.length; ++i) {
        $(writeActionSelectors[i]).css('display', readonly ? 'none' : '');
    }

    $('.folder-action-separator').css('display', '');
    compactToolbarSeparators();
}

let folderHistory = [];
let folderHistoryIndex = -1;

function updateFolderHistoryButtons() {
    toggleToolbarAction('#folder-mode-prev', folderHistoryIndex > 0);
    toggleToolbarAction('#folder-mode-next', folderHistoryIndex >= 0 && folderHistoryIndex < folderHistory.length - 1);
}

function pushFolderHistory(path) {
    const nextPath = normalizeFolderPath(path || '');

    if (folderHistoryIndex >= 0 && folderHistory[folderHistoryIndex] === nextPath) {
        return;
    }

    if (folderHistoryIndex >= 0) {
        folderHistory = folderHistory.slice(0, folderHistoryIndex + 1);
    }

    folderHistory.push(nextPath);
    folderHistoryIndex = folderHistory.length - 1;
    updateFolderHistoryButtons();
}

function goFolderHistory(offset) {
    const nextIndex = folderHistoryIndex + offset;

    if (nextIndex < 0 || nextIndex >= folderHistory.length) {
        return false;
    }

    folderHistoryIndex = nextIndex;
    const nextPath = folderHistory[nextIndex];
    content.path = nextPath;
    renderFolderPath(nextPath);
    fetchFolder(nextPath, true);
    updateFolderHistoryButtons();
    return true;
}

function isSamePath(a, b) {
    return normalizePath(a) === normalizePath(b);
}

const DIR_SHOW_MODE_KEY = 'dirShowMode';
const DIR_SHOW_MODE_DB_NAME = typeof getSessionStorageName === 'function' ? getSessionStorageName() : 'vsfile';
const DIR_SHOW_MODE_DB_VERSION = 2;
const DIR_SHOW_MODE_STORE = 'dirShowMode';
const DIR_MODE_TO_CODE = { detail: 1, icon: 2, tile: 3, thumb: 4 };
const DIR_CODE_TO_MODE = { 1: 'detail', 2: 'icon', 3: 'tile', 4: 'thumb' };
let dirShowModeDbPromise = null;

function normalizeDirShowModePath(path) {
    return normalizeFolderPath(path || '');
}

function normalizeDirShowModeCode(mode) {
    const modeCode = parseInt(mode, 10);
    return DIR_CODE_TO_MODE[modeCode] ? modeCode : 0;
}

function isIndexedDBSupported() {
    return typeof window !== 'undefined' && typeof window.indexedDB !== 'undefined';
}

function bootstrapDirShowModeDb() {
    if (!isIndexedDBSupported()) {
        return;
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            openDirShowModeDb();
        }, { once: true });
        return;
    }

    openDirShowModeDb();
}

function openDirShowModeDb() {
    if (!isIndexedDBSupported()) {
        return Promise.resolve(null);
    }

    if (dirShowModeDbPromise) {
        return dirShowModeDbPromise;
    }

    dirShowModeDbPromise = new Promise((resolve, reject) => {
        const request = window.indexedDB.open(DIR_SHOW_MODE_DB_NAME, DIR_SHOW_MODE_DB_VERSION);

        request.onupgradeneeded = event => {
            const db = event.target.result;

            if (db.objectStoreNames.contains(DIR_SHOW_MODE_STORE)) {
                const legacyStore = request.transaction.objectStore(DIR_SHOW_MODE_STORE);

                if (legacyStore.keyPath !== null) {
                    db.deleteObjectStore(DIR_SHOW_MODE_STORE);
                    db.createObjectStore(DIR_SHOW_MODE_STORE);
                }
            } else {
                db.createObjectStore(DIR_SHOW_MODE_STORE);
            }
        };

        request.onsuccess = event => resolve(event.target.result);
        request.onerror = () => reject(request.error || new Error('open indexeddb failed'));
    }).catch(error => {
        dirShowModeDbPromise = null;
        throw error;
    });

    return dirShowModeDbPromise;
}

bootstrapDirShowModeDb();

async function readDirShowModeFromIndexedDB(path) {
    const db = await openDirShowModeDb();

    if (!db) {
        return null;
    }

    return new Promise((resolve, reject) => {
        const transaction = db.transaction(DIR_SHOW_MODE_STORE, 'readonly');
        const store = transaction.objectStore(DIR_SHOW_MODE_STORE);
        const request = store.get(path);

        request.onsuccess = () => {
            const modeCode = normalizeDirShowModeCode(request.result);

            if (!modeCode) {
                resolve(null);
                return;
            }

            const mode = DIR_CODE_TO_MODE[modeCode];
            resolve(mode || null);
        };

        request.onerror = () => reject(request.error || new Error('read indexeddb failed'));
    }).finally(() => {
    });
}

async function saveDirShowModeToIndexedDB(path, modeCode) {
    const db = await openDirShowModeDb();

    if (!db) {
        return false;
    }

    return new Promise((resolve, reject) => {
        const transaction = db.transaction(DIR_SHOW_MODE_STORE, 'readwrite');
        const store = transaction.objectStore(DIR_SHOW_MODE_STORE);
        store.put(modeCode, path);

        transaction.oncomplete = () => resolve(true);
        transaction.onerror = () => reject(transaction.error || new Error('write indexeddb failed'));
    });
}

function getDirShowModeMapFromLocalStorage() {
    let config = {};

    try {
        config = getLocalConfig();
    } catch (error) {
        config = {};
    }

    const raw = config ? config[DIR_SHOW_MODE_KEY] : null;
    const modeMap = {};

    if (Array.isArray(raw)) {
        for (let i = 0; i < raw.length; ++i) {
            const item = raw[i] || {};
            const safePath = normalizeDirShowModePath(item.path);
            const modeCode = normalizeDirShowModeCode(item.mode);

            if (!modeCode) {
                continue;
            }

            modeMap[safePath] = modeCode;
        }

        return modeMap;
    }

    if (!raw || typeof raw !== 'object') {
        return modeMap;
    }

    for (const rawPath in raw) {
        const safePath = normalizeDirShowModePath(rawPath);
        const modeCode = normalizeDirShowModeCode(raw[rawPath]);

        if (!modeCode) {
            continue;
        }

        modeMap[safePath] = modeCode;
    }

    return modeMap;
}

function saveDirShowModeMapToLocalStorage(modeMap) {
    let config = {};

    try {
        config = getLocalConfig();
    } catch (error) {
        config = {};
    }

    if (!config || typeof config !== 'object' || Array.isArray(config)) {
        config = {};
    }

    const safeMap = {};
    modeMap = modeMap && typeof modeMap === 'object' ? modeMap : {};

    for (const rawPath in modeMap) {
        const safePath = normalizeDirShowModePath(rawPath);
        const modeCode = normalizeDirShowModeCode(modeMap[rawPath]);

        if (!modeCode) {
            continue;
        }

        safeMap[safePath] = modeCode;
    }

    config[DIR_SHOW_MODE_KEY] = safeMap;
    setLocalConfig(config);
    return true;
}

function readDirShowModeFromLocalStorage(path) {
    const modeMap = getDirShowModeMapFromLocalStorage();
    const modeCode = normalizeDirShowModeCode(modeMap[path]);
    return modeCode ? DIR_CODE_TO_MODE[modeCode] : null;
}

async function saveDirShowMode(path, mode) {
    const safePath = normalizeDirShowModePath(path);
    const modeCode = DIR_MODE_TO_CODE[mode];

    if (!modeCode) {
        return false;
    }

    if (isIndexedDBSupported()) {
        try {
            return await saveDirShowModeToIndexedDB(safePath, modeCode);
        } catch (error) {
            // 退化到 localStorage
        }
    }

    const modeMap = getDirShowModeMapFromLocalStorage();
    modeMap[safePath] = modeCode;
    saveDirShowModeMapToLocalStorage(modeMap);
    return true;
}

async function resolveDirShowMode(path, autoMode) {
    const safePath = normalizeDirShowModePath(path);
    let savedMode = null;

    if (isIndexedDBSupported()) {
        try {
            savedMode = await readDirShowModeFromIndexedDB(safePath);

            if (!savedMode) {
                const localMode = readDirShowModeFromLocalStorage(safePath);

                if (localMode) {
                    await saveDirShowModeToIndexedDB(safePath, DIR_MODE_TO_CODE[localMode]);
                    savedMode = localMode;
                }
            }
        } catch (error) {
            savedMode = readDirShowModeFromLocalStorage(safePath);
        }
    } else {
        savedMode = readDirShowModeFromLocalStorage(safePath);
    }

    if (savedMode) {
        return savedMode;
    }

    await saveDirShowMode(safePath, autoMode);
    return autoMode;
}

async function syncDirectory(path) {
    if (top.global.frame && typeof top.global.frame.syncDirectory === 'function') {
        await top.global.frame.syncDirectory(path, { excludeContentId: id });
        return true;
    }

    top.global.tree && typeof top.global.tree.reloadPath === 'function' && await top.global.tree.reloadPath(path);
    return true;
}

const Folder = {
    mode: 'detail',
    items: [],
    baseItems: [],
    currentDirMode: '000',
    currentDirSize: null,
    currentDirSizeLoading: false,
    sortColumn: null,
    sortState: 'default',
    nameFilter: '',
    sizeFilter: { min: null, max: null, minRaw: '', maxRaw: '' },
    createdFilter: { min: null, max: null, minRaw: '', maxRaw: '' },
    modifiedFilter: { min: null, max: null, minRaw: '', maxRaw: '' },
    typeFilter: [],
    $: $('.folder-items'),
};

function setDetailColumnSortState(button, state) {
    if (!button || !button.length) {
        return;
    }

    const states = ['default', 'asc', 'desc'];
    const nextState = state || 'default';
    const normalizedState = states.includes(nextState) ? nextState : 'default';
    button.attr('data-sort-state', normalizedState);

    if (normalizedState === 'asc') {
        button.css('background-image', 'url(?f=img/folder/sort-asc.svg)');
    } else if (normalizedState === 'desc') {
        button.css('background-image', 'url(?f=img/folder/sort-desc.svg)');
    } else {
        button.css('background-image', 'url(?f=img/folder/sort-arrow.svg)');
    }
}

function resetDetailColumnSortStates(exceptButton) {
    $('.folder-detail-column-sort').each(function () {
        if (exceptButton && this === exceptButton[0]) {
            return;
        }

        setDetailColumnSortState($(this), 'default');
    });
}

function getDetailSortValue(item, column) {
    if (!item || !column) {
        return '';
    }

    switch (column) {
        case 'name':
            return (item.name || '').toLowerCase();
        case 'modified':
            return Number(item.modified) || 0;
        case 'created':
            return Number(item.created) || 0;
        case 'type':
            if (item.type === 'folder') {
                return 'directory';
            }

            const ext = item.name && item.name.includes('.') ? item.name.split('.').pop().toLowerCase() : '';
            return ext || '';
        case 'size':
            return Number(item.size) || 0;
        default:
            return '';
    }
}

function isAsciiCharacter(value) {
    return /^[\x00-\x7F]$/.test(String(value || ''));
}

function compareDetailStringValues(aValue, bValue) {
    const left = String(aValue || '').toLowerCase();
    const right = String(bValue || '').toLowerCase();
    const leftChars = Array.from(left);
    const rightChars = Array.from(right);
    const length = Math.max(leftChars.length, rightChars.length);

    for (let index = 0; index < length; ++index) {
        const leftChar = leftChars[index];
        const rightChar = rightChars[index];

        if (leftChar === undefined) {
            return -1;
        }

        if (rightChar === undefined) {
            return 1;
        }

        const leftAscii = isAsciiCharacter(leftChar);
        const rightAscii = isAsciiCharacter(rightChar);

        if (leftAscii && rightAscii) {
            const charCodeDiff = leftChar.charCodeAt(0) - rightChar.charCodeAt(0);
            if (charCodeDiff !== 0) {
                return charCodeDiff;
            }
            continue;
        }

        if (!leftAscii && !rightAscii) {
            const localeDiff = leftChar.localeCompare(rightChar, undefined, { sensitivity: 'base' });
            if (localeDiff !== 0) {
                return localeDiff;
            }
            continue;
        }

        return leftAscii ? -1 : 1;
    }

    return 0;
}

function getDetailSortComparator(column, state) {
    const isAscending = state === 'asc';
    const baseIndexMap = new Map();

    (Folder.baseItems || []).forEach((item, index) => {
        baseIndexMap.set(item, index);
    });

    return function (a, b) {
        const aIsFolder = a && a.type === 'folder';
        const bIsFolder = b && b.type === 'folder';

        if (aIsFolder !== bIsFolder) {
            return aIsFolder ? -1 : 1;
        }

        if (!column || state === 'default') {
            const aIndex = nullish(baseIndexMap.get(a), 0);
            const bIndex = nullish(baseIndexMap.get(b), 0);
            return aIndex - bIndex;
        }

        const aValue = getDetailSortValue(a, column);
        const bValue = getDetailSortValue(b, column);

        if (typeof aValue === 'string' && typeof bValue === 'string') {
            const compareResult = compareDetailStringValues(aValue, bValue);
            if (compareResult !== 0) {
                return isAscending ? compareResult : -compareResult;
            }
        } else {
            const compareResult = aValue - bValue;
            if (compareResult !== 0) {
                return isAscending ? compareResult : -compareResult;
            }
        }

        const aIndex = nullish(baseIndexMap.get(a), 0);
        const bIndex = nullish(baseIndexMap.get(b), 0);
        return aIndex - bIndex;
    };
}

function matchesFolderNameFilter(item, filter) {
    const name = String(item && item.name ? item.name : '');
    const normalizedFilter = String(filter || '').trim();

    if (!normalizedFilter) {
        return true;
    }

    try {
        return new RegExp(normalizedFilter, 'i').test(name);
    } catch (error) {
        return name.toLowerCase().includes(normalizedFilter.toLowerCase());
    }
}

function parseFolderSizeFilterValue(value) {
    if (value === null || value === undefined || value === '' || value === false) {
        return null;
    }

    if (typeof value === 'number' && isFinite(value)) {
        return value > 0 ? Math.floor(value) : null;
    }

    const str = String(value).trim().toLowerCase();

    if (!str) {
        return null;
    }

    const match = str.match(/^([0-9]+(?:\.[0-9]+)?)\s*([a-z]*)$/i);

    if (!match) {
        return null;
    }

    const num = parseFloat(match[1]);

    if (!isFinite(num) || num < 0) {
        return null;
    }

    const unit = (match[2] || '').toUpperCase();
    const powMap = { '': 0, B: 0, K: 1, KB: 1, M: 2, MB: 2, G: 3, GB: 3, T: 4, TB: 4, P: 5, PB: 5, E: 6, EB: 6, Z: 7, ZB: 7, Y: 8, YB: 8 };

    if (!Object.prototype.hasOwnProperty.call(powMap, unit)) {
        return null;
    }

    return Math.floor(num * Math.pow(1024, powMap[unit]));
}

function matchesFolderSizeFilter(item, filter) {
    const size = Number(item && item.size != null ? item.size : 0) || 0;
    const min = filter && filter.min !== null && filter.min !== undefined && filter.min !== '' ? filter.min : null;
    const max = filter && filter.max !== null && filter.max !== undefined && filter.max !== '' ? filter.max : null;

    if (min !== null && size < min) {
        return false;
    }

    if (max !== null && size > max) {
        return false;
    }

    return true;
}

function getFolderTypeFilterValue(item) {
    if (!item) {
        return '';
    }

    if (item.type === 'folder') {
        return 'directory';
    }

    const name = String(item.name || '');

    if (!name.includes('.')) {
        return '';
    }

    return name.split('.').pop().toLowerCase();
}

function matchesFolderTypeFilter(item, filter) {
    if (!filter || !filter.length) {
        return true;
    }

    return filter.includes(getFolderTypeFilterValue(item));
}

function parseFolderDateTimeFilterValue(value) {
    if (value === null || value === undefined || value === '' || value === false) {
        return null;
    }

    if (typeof value === 'number' && isFinite(value)) {
        return Math.floor(value);
    }

    const str = String(value).trim();

    if (!str) {
        return null;
    }

    const numeric = Number(str);

    if (Number.isFinite(numeric)) {
        return Math.floor(numeric);
    }

    const match = str.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?:\s+|T)?(\d{1,2})?(?::(\d{1,2}))?(?::(\d{1,2}))?$/);
    if (!match) {
        return null;
    }

    const year = Number(match[1]);
    const month = Number(match[2]);
    const day = Number(match[3]);
    const hour = Number(match[4] || '0');
    const minute = Number(match[5] || '0');
    const second = Number(match[6] || '0');
    const date = new Date(year, month - 1, day, hour, minute, second);

    if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day || date.getHours() !== hour || date.getMinutes() !== minute || date.getSeconds() !== second) {
        return null;
    }

    return Math.floor(date.getTime() / 1000);
}

function formatFolderDateTimePickerValue(value) {
    const raw = value == null ? '' : String(value).trim();

    if (!raw) {
        return '';
    }

    const parsedValue = parseFolderDateTimeFilterValue(raw);

    if (parsedValue === null) {
        return raw.replace(/\s+/, 'T');
    }

    const date = new Date(parsedValue * 1000);
    const pad = number => String(number).padStart(2, '0');
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
}

function matchesFolderDateTimeFilter(item, column, filter) {
    const value = Number(item && item[column] != null ? item[column] : 0) || 0;
    const min = filter && filter.min !== null && filter.min !== undefined && filter.min !== '' ? filter.min : null;
    const max = filter && filter.max !== null && filter.max !== undefined && filter.max !== '' ? filter.max : null;

    if (min !== null && value < min) {
        return false;
    }

    if (max !== null && value > max) {
        return false;
    }

    return true;
}

function getFolderDisplayItems() {
    const sourceItems = Folder.baseItems.slice();

    const filteredItems = sourceItems.filter(item => {
        const matchesName = matchesFolderNameFilter(item, Folder.nameFilter);
        const matchesSize = matchesFolderSizeFilter(item, Folder.sizeFilter);
        const matchesCreated = matchesFolderDateTimeFilter(item, 'created', Folder.createdFilter);
        const matchesModified = matchesFolderDateTimeFilter(item, 'modified', Folder.modifiedFilter);
        const matchesType = matchesFolderTypeFilter(item, Folder.typeFilter);
        return matchesName && matchesSize && matchesCreated && matchesModified && matchesType;
    });

    if (Folder.sortColumn && Folder.sortState !== 'default') {
        const sortedItems = filteredItems.slice();
        sortedItems.sort(getDetailSortComparator(Folder.sortColumn, Folder.sortState));
        return sortedItems;
    }

    return filteredItems;
}

function applyFolderNameFilter(value, params = {}) {
    Folder.nameFilter = value == null ? '' : String(value).trim();
    Folder.items = getFolderDisplayItems();
    updateFolderFilterButtonState();
    params.render !== false && renderFolder();
    return Folder.items;
}

function applyFolderSizeFilter(minValue, maxValue, params = {}) {
    Folder.sizeFilter = {
        min: parseFolderSizeFilterValue(minValue),
        max: parseFolderSizeFilterValue(maxValue),
        minRaw: minValue == null ? '' : String(minValue).trim(),
        maxRaw: maxValue == null ? '' : String(maxValue).trim(),
    };

    Folder.items = getFolderDisplayItems();
    updateFolderFilterButtonState();
    params.render !== false && renderFolder();
    return Folder.items;
}

function applyFolderTypeFilter(values, params = {}) {
    const normalizedValues = Array.isArray(values) ? values.map(value => String(value || '').trim().toLowerCase()).filter(Boolean) : [];
    const availableValues = getFolderTypeFilterOptions();
    const allSelected = availableValues.length > 0 && normalizedValues.length === availableValues.length && availableValues.every(value => normalizedValues.includes(value));
    Folder.typeFilter = allSelected ? [] : normalizedValues;
    Folder.items = getFolderDisplayItems();
    updateFolderFilterButtonState();
    params.render !== false && renderFolder();
    return Folder.items;
}

function applyFolderDateTimeFilter(column, minValue, maxValue, params = {}) {
    const filterState = {
        min: parseFolderDateTimeFilterValue(minValue),
        max: parseFolderDateTimeFilterValue(maxValue),
        minRaw: minValue == null ? '' : String(minValue).trim(),
        maxRaw: maxValue == null ? '' : String(maxValue).trim(),
    };

    if (column === 'created') {
        Folder.createdFilter = filterState;
    } else if (column === 'modified') {
        Folder.modifiedFilter = filterState;
    }

    Folder.items = getFolderDisplayItems();
    updateFolderFilterButtonState();
    params.render !== false && renderFolder();
    return Folder.items;
}

function getFolderTypeFilterOptions() {
    const sourceItems = (Folder.baseItems && Folder.baseItems.length ? Folder.baseItems : Folder.items) || [];
    const directoryValues = [];
    const otherValues = [];
    const seen = new Set();

    sourceItems.forEach(item => {
        if (!item) {
            return;
        }

        const value = getFolderTypeFilterValue(item);
        if (!value || seen.has(value)) {
            return;
        }

        seen.add(value);

        if (value === 'directory') {
            directoryValues.push(value);
        } else {
            otherValues.push(value);
        }
    });

    return directoryValues.concat(otherValues.sort(compareDetailStringValues));
}

function getFolderTypeFilterIconClass(option) {
    if (!option || option === 'directory') {
        return 'filetype-folder';
    }

    const normalized = String(option).trim().toLowerCase();
    const ext = fileType(normalized.includes('.') ? normalized.split('.').pop() : normalized);
    return ext ? `filetype-${ext}` : 'filetype-default';
}

function renderFolderTypeFilterList() {
    const list = $('#folder-filter-popup-type-list');
    const options = getFolderTypeFilterOptions();
    const selectedValues = Folder.typeFilter && Folder.typeFilter.length ? Folder.typeFilter : options;

    list.empty();

    options.forEach(option => {
        const text = option === 'directory' ? getLangTextByPath('folder.detail.directory') : option;
        const label = $(`<label class="folder-filter-popup-type-item" title="${text}"></label>`);
        option === 'directory' && label.addClass('folder-filter-popup-type-item-directory');

        const input = $('<input type="checkbox" />');
        input.attr('value', option);
        input.prop('checked', selectedValues.includes(option));

        const icon = $('<span class="folder-filter-popup-type-item-icon"></span>');
        icon.addClass(getFolderTypeFilterIconClass(option));
        const action = $('<button class="folder-filter-popup-type-item-action" type="button" aria-label="filter"></button>');

        label.on('click', function (e) {
            if ($(e.target).closest('.folder-filter-popup-type-item-action').length) {
                return;
            }

            e.preventDefault();
            e.stopPropagation();
            input.prop('checked', !input.prop('checked'));
        });

        action.on('click', function (e) {
            e.preventDefault();
            e.stopPropagation();
            $('#folder-filter-popup-type-list input').prop('checked', false);
            input.prop('checked', true);
        });

        label.append(input).append(icon).append(`<span class="folder-filter-popup-type-item-text">${text}</span>`);
        label.prepend(action);
        list.append(label);
    });
}

function setFolderFilterPanelTexts() {
    const popup = $('#folder-filter-popup');
    popup.find('#folder-filter-popup-input').attr('placeholder', getLangTextByPath('folder.filter.placeholder'));
    popup.find('#folder-filter-popup-size-min').attr('placeholder', getLangTextByPath('folder.filter.size_min'));
    popup.find('#folder-filter-popup-size-max').attr('placeholder', getLangTextByPath('folder.filter.size_max'));
    popup.find('#folder-filter-popup-datetime-min').attr('placeholder', 'yyyy-mm-dd hh:mm:ss');
    popup.find('#folder-filter-popup-datetime-max').attr('placeholder', 'yyyy-mm-dd hh:mm:ss');
}

function renderFolderTimeQuickLinks() {
    const container = $('#folder-filter-popup-time-links');
    if (!container.length) {
        return;
    }

    container.find('.folder-filter-popup-time-link').each(function () {
        const link = $(this);
        const key = link.attr('data-quick-key');
        const secondsMap = {
            hour: 3600,
            day: 86400,
            week: 604800,
            month: 2592000,
            year: 31536000,
        };

        link.off('click.folderQuickLink').on('click.folderQuickLink', function (e) {
            e.preventDefault();
            e.stopPropagation();

            const now = Math.floor(Date.now() / 1000);
            const from = now - (secondsMap[key] || 0);
            const minValue = new Date(from * 1000).toISOString().slice(0, 19).replace('T', ' ');
            const maxValue = new Date(now * 1000).toISOString().slice(0, 19).replace('T', ' ');

            $('#folder-filter-popup-datetime-min').val(minValue);
            $('#folder-filter-popup-datetime-max').val(maxValue);
            applyFolderDateTimeFilter($('#folder-filter-popup').attr('data-filter-column') || 'created', minValue, maxValue, { render: true });
        });
    });
}

function refreshFolderFilterUi() {
    setFolderFilterPanelTexts();
    updateFolderFilterButtonState();

    if ($('#folder-filter-popup').attr('data-filter-column') === 'type') {
        renderFolderTypeFilterList();
    }

    if ($('#folder-filter-popup').attr('data-filter-column') === 'created' || $('#folder-filter-popup').attr('data-filter-column') === 'modified') {
        renderFolderTimeQuickLinks();
    }
}

function updateFolderFilterButtonState() {
    $('.folder-detail-column-filter').each(function () {
        const column = $(this).attr('data-filter-column') || 'name';
        let active = false;

        if (column === 'name') {
            active = !!Folder.nameFilter;
        } else if (column === 'size') {
            active = Folder.sizeFilter && (Folder.sizeFilter.min !== null || Folder.sizeFilter.max !== null);
        } else if (column === 'created') {
            active = Folder.createdFilter && (Folder.createdFilter.min !== null || Folder.createdFilter.max !== null);
        } else if (column === 'modified') {
            active = Folder.modifiedFilter && (Folder.modifiedFilter.min !== null || Folder.modifiedFilter.max !== null);
        } else if (column === 'type') {
            active = !!(Folder.typeFilter && Folder.typeFilter.length);
        }

        $(this).attr('data-filter-active', active ? 'true' : 'false');
    });
}

function updateFolderFilterPopupPosition(button, filterColumn) {
    if (!button || !button.length) {
        return;
    }

    const popup = $('#folder-filter-popup');
    if (!popup.length) {
        return;
    }

    const buttonElement = button[0] || button;
    const offset = button.offset ? button.offset() : { top: 0, left: 0 };
    const buttonHeight = buttonElement && typeof buttonElement.getBoundingClientRect === 'function'
        ? buttonElement.getBoundingClientRect().height
        : 0;
    const popupWidth = popup[0] && popup[0].offsetWidth ? popup[0].offsetWidth : (
        filterColumn === 'type' ? 360 :
            filterColumn === 'size' ? 320 :
                filterColumn === 'name' ? 400 :
                    280
    );
    const popupHeight = popup[0] && popup[0].offsetHeight ? popup[0].offsetHeight : (
        filterColumn === 'type' ? 260 :
            filterColumn === 'size' ? 200 :
                180
    );
    const viewportWidth = $(window).width();
    const viewportHeight = $(window).height();
    const top = Math.min(offset.top + buttonHeight + 8, viewportHeight - popupHeight - 16);
    const left = Math.min(offset.left, viewportWidth - popupWidth - 16);

    popup.css({
        top: Math.max(8, top),
        left: Math.max(8, left),
        right: 'auto',
    });

    if (left + popupWidth > viewportWidth - 16) {
        popup.css({ left: 'auto', right: 0 });
    }
}

function observeFolderFilterPopupResize(button, filterColumn) {
    const popup = $('#folder-filter-popup');

    if (!popup.length || typeof ResizeObserver === 'undefined') {
        return;
    }

    const currentObserver = popup[0].vsfileFilterPopupObserver;
    currentObserver && typeof currentObserver.disconnect === 'function' && currentObserver.disconnect();

    const observer = new ResizeObserver(() => {
        if (popup.css('display') === 'none') {
            return;
        }

        updateFolderFilterPopupPosition(button, filterColumn || popup.attr('data-filter-column') || 'name');
    });

    popup[0].vsfileFilterPopupObserver = observer;
    observer.observe(popup[0]);
}

function showFolderFilterPanel(button, column) {
    if (!button || !button.length) {
        return;
    }

    const popup = $('#folder-filter-popup');
    const input = $('#folder-filter-popup-input');
    const sizeMinInput = $('#folder-filter-popup-size-min');
    const sizeMaxInput = $('#folder-filter-popup-size-max');
    const datetimeMinInput = $('#folder-filter-popup-datetime-min');
    const datetimeMaxInput = $('#folder-filter-popup-datetime-max');
    const filterColumn = column || button.attr('data-filter-column') || 'name';

    const isSize = filterColumn === 'size';
    const isType = filterColumn === 'type';
    const isDateTime = filterColumn === 'created' || filterColumn === 'modified';

    $('#folder-filter-popup-name').toggleClass('folder-filter-popup-panel-hidden', isSize || isType || isDateTime);
    $('#folder-filter-popup-size').toggleClass('folder-filter-popup-panel-hidden', !isSize);
    $('#folder-filter-popup-datetime').toggleClass('folder-filter-popup-panel-hidden', !isDateTime);
    $('#folder-filter-popup-type').toggleClass('folder-filter-popup-panel-hidden', !isType);
    popup.attr('data-filter-column', filterColumn);

    $('#folder-filter-popup-button-clear').toggle(!isType);
    $('#folder-filter-popup-button-select-all').toggle(isType);
    $('#folder-filter-popup-button-invert').toggle(isType);

    if (isType) {
        renderFolderTypeFilterList();
        setFolderFilterPanelTexts();
        popup.show();
        requestAnimationFrame(() => {
            updateFolderFilterPopupPosition(button, filterColumn);
            observeFolderFilterPopupResize(button, filterColumn);
            $('#folder-filter-popup-type-list input').first().focus();
        });
        return;
    }

    if (isDateTime) {
        renderFolderTimeQuickLinks();
        const timeFilter = filterColumn === 'created' ? Folder.createdFilter : Folder.modifiedFilter;
        datetimeMinInput.val(formatFolderDateTimePickerValue(timeFilter.minRaw != null ? timeFilter.minRaw : timeFilter.min));
        datetimeMaxInput.val(formatFolderDateTimePickerValue(timeFilter.maxRaw != null ? timeFilter.maxRaw : timeFilter.max));
        setFolderFilterPanelTexts();
        popup.show();

        requestAnimationFrame(() => {
            updateFolderFilterPopupPosition(button, filterColumn);
            observeFolderFilterPopupResize(button, filterColumn);
            datetimeMinInput.focus();
        });

        return;
    }

    if (isSize) {
        sizeMinInput.val(Folder.sizeFilter.minRaw || '');
        sizeMaxInput.val(Folder.sizeFilter.maxRaw || '');
        setFolderFilterPanelTexts();
        popup.show();
        requestAnimationFrame(() => {
            updateFolderFilterPopupPosition(button, filterColumn);
            observeFolderFilterPopupResize(button, filterColumn);
            sizeMinInput.focus().select();
        });
        return;
    }

    input.val(Folder.nameFilter || '');
    setFolderFilterPanelTexts();
    popup.show();
    requestAnimationFrame(() => {
        updateFolderFilterPopupPosition(button, filterColumn);
        observeFolderFilterPopupResize(button, filterColumn);
        input.focus().select();
    });
}

function hideFolderFilterPanel() {
    $('#folder-filter-popup').hide();
}

function applyDetailSort(column, state) {
    const normalizedState = ['asc', 'desc'].includes(state) ? state : 'default';
    Folder.sortColumn = normalizedState === 'default' ? null : column;
    Folder.sortState = normalizedState;
    Folder.items = getFolderDisplayItems();
    return Folder.items;
}

function toggleDetailSortState(button) {
    if (!button || !button.length) {
        return;
    }

    const currentState = button.attr('data-sort-state') || 'default';
    const currentColumn = button.attr('data-sort-column') || '';
    const nextState = currentState === 'default' ? 'asc' : currentState === 'asc' ? 'desc' : 'default';
    resetDetailColumnSortStates(nextState === 'default' ? null : button);
    setDetailColumnSortState(button, nextState);

    if (nextState === 'default') {
        applyDetailSort(null, 'default');
    } else {
        applyDetailSort(currentColumn, nextState);
    }

    renderFolder();
}

let contextMenuVisible = false;

const Thumb = {
    dragging: false,
    dragStartX: 0,
    dragStartY: 0,
    lastX: 0,
    lastY: 0,
    scale: 1,
    deg: 0,
    $: $('#folder-thumb'),
    $wrap: $('#folder-thumb-image'),
    $img: null,
    init: function () {
        const properties = {
            url: '',
        };

        let rendered = false;

        for (const k in properties) {
            Object.defineProperty(this, k, {
                get: () => properties[k],
                set: value => {
                    if (value === properties[k]) {
                        return;
                    }

                    properties[k] = value;
                    rendered = false;

                    requestAnimationFrame(() => {
                        rendered || this.render();
                        rendered = true;
                    });
                }
            });
        }

        this.$wrap.on('mousedown', e => this.mouseDown(e));
        this.$wrap.on('mousemove', e => this.mouseMove(e));
        this.$wrap.on('mouseup', e => this.mouseUp(e));
        this.$wrap.on('wheel', e => this.mouseWheel(e));
        this.$.find('.folder-thumb-prev').on('click', e => this.prev(e));
        this.$.find('.folder-thumb-next').on('click', e => this.next(e));
        return this;
    },
    render: function () {
        if (Folder.mode !== 'thumb') {
            return this;
        }

        this.lastX = 0;
        this.lastY = 0;
        this.$wrap.empty();
        this.$img = $(`<img class="folder-thumb-image-img" src="${this.url ? this.url : '?f=img/filetype/png.svg'}" />`);

        this.$img.on('load', () => {
            const scaleX = this.$wrap.width() / this.$img[0].naturalWidth;
            const scaleY = this.$wrap.height() / this.$img[0].naturalHeight;
            this.scale = Math.min(scaleX, scaleY, 1);
            this.renderResize(0, 0);
        });

        this.$wrap.append(this.$img);
        renderLang();
        return this;
    },
    mouseDown: function (e) {
        if (Folder.mode !== 'thumb' || !this.url) {
            return this;
        }

        e.preventDefault();
        this.dragging = true;
        this.dragStartX = e.clientX;
        this.dragStartY = e.clientY;
        this.$wrap.css({ cursor: 'grabbing' });
        return this;
    },
    mouseMove: function (e) {
        if (Folder.mode !== 'thumb' || !this.url || !this.dragging) {
            return this;
        }

        e.preventDefault();
        const x = this.lastX + e.clientX - this.dragStartX;
        const y = this.lastY + e.clientY - this.dragStartY;
        this.renderResize(x, y);
        return this;
    },
    mouseUp: function (e) {
        if (Folder.mode !== 'thumb' || !this.url) {
            return this;
        }

        e.preventDefault();
        this.dragging = false;
        this.lastX += e.clientX - this.dragStartX;
        this.lastY += e.clientY - this.dragStartY;
        this.$wrap.css({ cursor: 'default' });
        return this;
    },
    mouseWheel: function (e) {
        if (Folder.mode !== 'thumb' || !this.url) {
            return this;
        }

        e.preventDefault();
        this.scale += e.deltaY > 0 ? -0.1 : 0.1;
        this.scale = Math.min(Math.max(this.scale, 0.1), 5);
        return this.renderResize(this.lastX, this.lastY);
    },
    renderResize: function (x, y) {
        if (Folder.mode !== 'thumb' || !this.url) {
            return this;
        }

        let transform = [
            `scale(${this.scale})`,
            `translate(${x / this.scale}px, ${y / this.scale}px)`,
            `rotate(${this.deg}deg)`
        ].join(' ');

        this.$img.css({ 'transform': transform });
        return this;
    },
    prev: async function () {
        if (Folder.mode !== 'thumb') {
            return this;
        }

        const currentIndex = Folder.items.findIndex(i => i.active);
        const L = findImageIndex(currentIndex - 1, 0);
        const R = findImageIndex(Folder.items.length - 1, currentIndex + 1);
        const prevImage = L >= 0 ? L : R;

        if (prevImage < 0) {
            return this;
        }

        const item = Folder.items[prevImage];
        await loadItemThumb(item);
        return this;
    },
    next: async function () {
        if (Folder.mode !== 'thumb') {
            return this;
        }

        const currentIndex = Folder.items.findIndex(i => i.active);
        const L = findImageIndex(0, currentIndex - 1);
        const R = findImageIndex(currentIndex + 1, Folder.items.length - 1);
        const nextImage = R >= 0 ? R : L;

        if (nextImage < 0) {
            return this;
        }

        const item = Folder.items[nextImage];
        await loadItemThumb(item);
        return this;
    },
};

const scrollBar = new ScrollBar($('.folder-items-wrap')[0], { barWidth: 14 });
const folderPathWrap = $('#global-path');
const folderPathInput = $('#folder-path-input');
let folderPathInputApplying = false;

folderPathInput.hide();
renderFolderPath(content.path);
isSearchMode() ? searchAllFolders() : fetchFolder(content.path);
Thumb.init();
renderLang();

function normalizeFolderPath(path) {
    const value = (path || '').trim().replace(/\\/g, '/');
    return value.replace(/^\/+|\/+$/g, '').replace(/\/+/g, '/');
}

function isWindowsDrivePath(path) {
    return /^[a-zA-Z]:/.test(path || '');
}

function parseFolderPathInputValue(value) {
    const inputValue = (value || '').trim();

    if (!inputValue || inputValue === '/') {
        return '';
    }

    if (isWindowsDrivePath(inputValue)) {
        const drive = inputValue.slice(0, 2);
        let rest = inputValue.slice(2).replace(/\//g, '\\').replace(/\\+/g, '\\');
        rest = rest.replace(/^\\+|\\+$/g, '');
        return rest ? `${drive}/${rest.replace(/\\/g, '/')}` : drive;
    }

    return normalizeFolderPath(inputValue);
}

function toFolderPathInputValue(path) {
    const safePath = normalizeFolderPath(path);

    if (!safePath) {
        return '/';
    }

    if (isWindowsDrivePath(safePath)) {
        const windowsPath = safePath.replace(/\//g, '\\');
        return /^[a-zA-Z]:$/.test(windowsPath) ? `${windowsPath}\\` : windowsPath;
    }

    return `/${safePath}`;
}

function showFolderPathInput() {
    if (isSearchMode()) {
        return;
    }

    folderPathInput.val(toFolderPathInputValue(content.path));
    folderPathWrap.hide();
    folderPathInput.show().focus().select();
}

function hideFolderPathInput() {
    folderPathInput.hide();
    folderPathWrap.show();
}

function isFolderPathInputVisible() {
    return folderPathInput.css('display') !== 'none';
}

async function applyFolderPathInput() {
    if (folderPathInputApplying) {
        return false;
    }

    const nextPath = parseFolderPathInputValue(folderPathInput.val());
    folderPathInput.val(toFolderPathInputValue(nextPath));

    if (nextPath === content.path) {
        return true;
    }

    folderPathInputApplying = true;
    const oldPath = content.path;
    content.path = nextPath;
    renderFolderPath(nextPath);

    const success = await fetchFolder(nextPath, true);

    if (!success) {
        content.path = oldPath;
        renderFolderPath(oldPath);
        folderPathInput.val(toFolderPathInputValue(oldPath));
    }

    folderPathInputApplying = false;
    return success;
}

function isFolderPathBlankClickTarget(target) {
    const safeTarget = target && target.nodeType === 3 ? target.parentNode : target;
    return !$(safeTarget).closest('.global-path-item, .global-path-separator, .global-path-filetype').length;
}

$('.folder-detail-column-sort').on('click', function (e) {
    e.stopPropagation();
    toggleDetailSortState($(this));
});

$('.folder-detail-column-filter').on('click', function (e) {
    e.stopPropagation();
    showFolderFilterPanel($(this), $(this).attr('data-filter-column') || 'name');
});

$('#folder-filter-popup').on('click', function (e) {
    e.stopPropagation();
});

$('#folder-filter-popup-input, #folder-filter-popup-size-min, #folder-filter-popup-size-max, #folder-filter-popup-datetime-min, #folder-filter-popup-datetime-max').on('keydown', function (e) {
    if (e.key === 'Enter') {
        e.preventDefault();
        $('#folder-filter-popup-button-confirm').trigger('click');
        return;
    }

    if (e.key === 'Escape') {
        e.preventDefault();
        hideFolderFilterPanel();
    }
});

$('#folder-filter-popup-button-clear').on('click', function (e) {
    e.stopPropagation();

    const filterColumn = $('#folder-filter-popup').attr('data-filter-column') || 'name';

    if (filterColumn === 'size') {
        $('#folder-filter-popup-size-min').val('');
        $('#folder-filter-popup-size-max').val('');
        applyFolderSizeFilter('', '', { render: true });
    } else if (filterColumn === 'type') {
        $('#folder-filter-popup-type-list input').prop('checked', false);
        applyFolderTypeFilter([], { render: true });
    } else if (filterColumn === 'created' || filterColumn === 'modified') {
        $('#folder-filter-popup-datetime-min').val('');
        $('#folder-filter-popup-datetime-max').val('');
        applyFolderDateTimeFilter(filterColumn, '', '', { render: true });
    } else {
        $('#folder-filter-popup-input').val('');
        applyFolderNameFilter('', { render: true });
    }

    hideFolderFilterPanel();
});

$('#folder-filter-popup-button-select-all').on('click', function (e) {
    e.stopPropagation();
    $('#folder-filter-popup-type-list input').prop('checked', true);
});

$('#folder-filter-popup-button-invert').on('click', function (e) {
    e.stopPropagation();
    $('#folder-filter-popup-type-list input').each(function () {
        $(this).prop('checked', !$(this).prop('checked'));
    });
});

$('#folder-filter-popup-button-confirm').on('click', function (e) {
    e.stopPropagation();

    const filterColumn = $('#folder-filter-popup').attr('data-filter-column') || 'name';

    if (filterColumn === 'size') {
        applyFolderSizeFilter($('#folder-filter-popup-size-min').val(), $('#folder-filter-popup-size-max').val(), { render: true });
    } else if (filterColumn === 'created') {
        applyFolderDateTimeFilter('created', $('#folder-filter-popup-datetime-min').val(), $('#folder-filter-popup-datetime-max').val(), { render: true });
    } else if (filterColumn === 'modified') {
        applyFolderDateTimeFilter('modified', $('#folder-filter-popup-datetime-min').val(), $('#folder-filter-popup-datetime-max').val(), { render: true });
    } else if (filterColumn === 'type') {
        const selectedValues = $('#folder-filter-popup-type-list input:checked').map(function () {
            return $(this).val();
        }).get();
        applyFolderTypeFilter(selectedValues, { render: true });
    } else {
        applyFolderNameFilter($('#folder-filter-popup-input').val(), { render: true });
    }

    hideFolderFilterPanel();
});

$(document).on('click', function (e) {
    if (!$(e.target).closest('#folder-filter-popup').length) {
        hideFolderFilterPanel();
    }
});

folderPathWrap.on('mousedown', function (e) {
    if (isSearchMode()) {
        return;
    }

    if (!isFolderPathBlankClickTarget(e.target)) {
        return;
    }

    if (isFolderPathInputVisible()) {
        return;
    }

    e.preventDefault();
    showFolderPathInput();
});

folderPathInput.on('keydown', function (e) {
    if (e.key === 'Enter') {
        e.preventDefault();
        this.blur();
        return;
    }

    if (e.key === 'Escape') {
        e.preventDefault();
        folderPathInput.val(toFolderPathInputValue(content.path));
        hideFolderPathInput();
    }
});

folderPathInput.on('blur', async function () {
    await applyFolderPathInput();
    hideFolderPathInput();
});

const folderPathInputEvents = ['mousedown', 'mouseup', 'mousemove', 'click', 'dblclick', 'keydown', 'keyup', 'keypress', 'input', 'focus', 'blur'];

folderPathInput.on(folderPathInputEvents.join(' '), function (e) {
    e.stopPropagation();
});

const dragSelect = {
    active: false,
    moved: false,
    suppressBlankClick: false,
    startX: 0,
    startY: 0,
    wrapRect: null,
    $box: null,
};

function ensureDragSelectBox() {
    if (dragSelect.$box && dragSelect.$box.length) {
        return dragSelect.$box;
    }

    dragSelect.$box = $('<div class="folder-selection-rect"></div>');
    $('#folder-items-wrap').append(dragSelect.$box);
    return dragSelect.$box;
}

function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
}

function setSelectionByRect(rect) {
    for (let i = 0; i < Folder.items.length; ++i) {
        const item = Folder.items[i];

        if (!item.$ || !item.$.length) {
            continue;
        }

        const itemRect = item.$[0].getBoundingClientRect();
        const intersect = !(
            itemRect.right < rect.left ||
            itemRect.left > rect.right ||
            itemRect.bottom < rect.top ||
            itemRect.top > rect.bottom
        );

        item.selected = intersect;
    }

    updateToolbarActionStates();
}

function removeFolderNameInputErrorTips() {
    $('.folder-item-name-input-error').each(function () {
        const observer = this.vsfileResizeObserver;
        observer && typeof observer.disconnect === 'function' && observer.disconnect();
        this.vsfileResizeObserver = null;
    }).remove();
}

function adjustFolderNameInputErrorTipLeft(tip, preferredLeft) {
    const minGap = 8;
    const scrollX = window.pageXOffset || document.documentElement.scrollLeft || document.body.scrollLeft || 0;
    const viewportWidth = Math.max(document.documentElement.clientWidth || 0, window.innerWidth || 0);
    const tipWidth = tip[0] && tip[0].offsetWidth ? tip[0].offsetWidth : 0;
    const minLeft = scrollX + minGap;
    const maxLeft = Math.max(minLeft, scrollX + viewportWidth - tipWidth - minGap);
    const safeLeft = Math.max(minLeft, Math.min(preferredLeft, maxLeft));
    tip.css({ left: `${safeLeft}px` });
    const rect = tip[0] && tip[0].getBoundingClientRect ? tip[0].getBoundingClientRect() : null;

    if (!rect) {
        return;
    }

    const rightLimit = viewportWidth - minGap;
    let correctedLeft = safeLeft;

    if (rect.right > rightLimit) {
        correctedLeft -= (rect.right - rightLimit);
    }

    if (rect.left < minGap) {
        correctedLeft += (minGap - rect.left);
    }

    if (correctedLeft !== safeLeft) {
        tip.css({ left: `${Math.max(minLeft, correctedLeft)}px` });
    }
}

function adjustFolderNameInputErrorTipTop(tip, preferredTop, fallbackTop) {
    const minGap = 8;
    const scrollY = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;
    const viewportHeight = Math.max(document.documentElement.clientHeight || 0, window.innerHeight || 0);
    const tipHeight = tip[0] && tip[0].offsetHeight ? tip[0].offsetHeight : 0;
    const minTop = scrollY + minGap;
    const maxTop = Math.max(minTop, scrollY + viewportHeight - tipHeight - minGap);
    let safeTop = preferredTop;

    if (preferredTop > maxTop) {
        safeTop = Math.max(minTop, Math.min(fallbackTop, maxTop));
    } else {
        safeTop = Math.max(minTop, Math.min(preferredTop, maxTop));
    }

    tip.css({ top: `${safeTop}px` });
    const rect = tip[0] && tip[0].getBoundingClientRect ? tip[0].getBoundingClientRect() : null;

    if (!rect) {
        return;
    }

    const bottomLimit = viewportHeight - minGap;
    let correctedTop = safeTop;

    if (rect.bottom > bottomLimit) {
        correctedTop -= (rect.bottom - bottomLimit);
    }

    if (rect.top < minGap) {
        correctedTop += (minGap - rect.top);
    }

    if (correctedTop !== safeTop) {
        tip.css({ top: `${Math.max(minTop, Math.min(correctedTop, maxTop))}px` });
    }
}

function adjustFolderNameInputErrorTipPosition(tip, preferredLeft, belowTop, aboveTop) {
    adjustFolderNameInputErrorTipLeft(tip, preferredLeft);
    adjustFolderNameInputErrorTipTop(tip, belowTop, aboveTop);
}

function observeFolderNameInputErrorTipSize(tip, preferredLeft, belowTop, aboveTop, topPlacementDownOffset) {
    const tipElement = tip[0];

    if (!tipElement || typeof ResizeObserver === 'undefined') {
        return;
    }

    tipElement.vsfileResizeObserver && tipElement.vsfileResizeObserver.disconnect();

    const observer = new ResizeObserver(() => {
        const nextTipHeight = tipElement && tipElement.offsetHeight ? tipElement.offsetHeight : 0;
        adjustFolderNameInputErrorTipPosition(tip, preferredLeft, belowTop, aboveTop - nextTipHeight + topPlacementDownOffset);
    });

    tipElement.vsfileResizeObserver = observer;
    observer.observe(tipElement);
}

function showFolderNameInputErrorTip(input, newName, validation) {
    const tip = $(`<div class="folder-item-name-input-error ${validation.level}" data-lang="tree.error.${validation.type}"></div>`);
    tip.data('lang-args', JSON.stringify([`<span class="filename">${newName}</span>`]));

    const offset = input.offset();
    const inputHeight = input[0] && input[0].offsetHeight ? input[0].offsetHeight : 24;
    const modeOffsetY = Folder.mode === 'detail' ? -2 : -3;
    const topPlacementDownOffset = Folder.mode === 'detail' ? 6 : 8;
    const belowTop = offset.top + inputHeight + 2 + modeOffsetY;
    const aboveTop = offset.top - 2 + modeOffsetY;
    tip.css({ top: `${belowTop}px`, left: `${offset.left}px` });

    $('body').append(tip);
    const tipHeight = tip[0] && tip[0].offsetHeight ? tip[0].offsetHeight : 0;
    adjustFolderNameInputErrorTipPosition(tip, offset.left, belowTop, aboveTop - tipHeight + topPlacementDownOffset);
    observeFolderNameInputErrorTipSize(tip, offset.left, belowTop, aboveTop, topPlacementDownOffset);
}

$('#folder-items-wrap').on('contextmenu', function (e) {
    e.preventDefault();
    setNodeStatusAll({ active: false, selected: false });
    openContextMenu(e);
    return false;
});

$('#folder-items-wrap').on('mousedown', function (e) {
    if (isFolderPathInputVisible() && !$(e.target).closest('#folder-path-input').length) {
        applyFolderPathInput();
        hideFolderPathInput();
        return;
    }

    if (e.button !== 0 || $(e.target).closest('.folder-item').length) {
        return;
    }

    closeContextMenu();
    dragSelect.active = true;
    dragSelect.moved = false;
    dragSelect.startX = e.clientX;
    dragSelect.startY = e.clientY;
    dragSelect.wrapRect = this.getBoundingClientRect();

    const left = clamp(e.clientX, dragSelect.wrapRect.left, dragSelect.wrapRect.right);
    const top = clamp(e.clientY, dragSelect.wrapRect.top, dragSelect.wrapRect.bottom);

    ensureDragSelectBox()
        .addClass('folder-selection-rect-visible')
        .css({
            left: `${left - dragSelect.wrapRect.left}px`,
            top: `${top - dragSelect.wrapRect.top}px`,
            width: '0px',
            height: '0px',
        });

    setNodeStatusAll({ selected: false });
    updateToolbarActionStates();
    e.preventDefault();
});

$('#folder-items-wrap').on('click', function (e) {
    if (dragSelect.suppressBlankClick) {
        dragSelect.suppressBlankClick = false;
        return;
    }

    if ($(e.target).closest('.folder-item').length) {
        return;
    }

    const renameInput = $('.folder-item-name-input:focus');

    if (renameInput.length) {
        renameInput.trigger('blur');
    }

    setNodeStatusAll({ selected: false });
    updateToolbarActionStates();
});

$(document).on('mousemove', function (e) {
    if (!dragSelect.active || !dragSelect.wrapRect) {
        return;
    }

    const startX = clamp(dragSelect.startX, dragSelect.wrapRect.left, dragSelect.wrapRect.right);
    const startY = clamp(dragSelect.startY, dragSelect.wrapRect.top, dragSelect.wrapRect.bottom);
    const currentX = clamp(e.clientX, dragSelect.wrapRect.left, dragSelect.wrapRect.right);
    const currentY = clamp(e.clientY, dragSelect.wrapRect.top, dragSelect.wrapRect.bottom);
    const left = Math.min(startX, currentX);
    const top = Math.min(startY, currentY);
    const width = Math.abs(currentX - startX);
    const height = Math.abs(currentY - startY);

    dragSelect.moved = dragSelect.moved || width > 2 || height > 2;

    ensureDragSelectBox().css({
        left: `${left - dragSelect.wrapRect.left}px`,
        top: `${top - dragSelect.wrapRect.top}px`,
        width: `${width}px`,
        height: `${height}px`,
    });

    setSelectionByRect({
        left: left,
        top: top,
        right: left + width,
        bottom: top + height,
    });

    e.preventDefault();
});

$(document).on('mouseup', function () {
    if (!dragSelect.active) {
        return;
    }

    dragSelect.active = false;
    dragSelect.wrapRect = null;
    dragSelect.$box && dragSelect.$box.removeClass('folder-selection-rect-visible');

    if (dragSelect.moved) {
        dragSelect.suppressBlankClick = true;
    }
});

$(document).on('mousedown', closeContextMenu);

const closeContextMenuFromTop = function (e) {
    $(e.target).closest('.tree-menu-main').length || closeContextMenu();
};

top.document.addEventListener('mousedown', closeContextMenuFromTop);
window.addEventListener('unload', function () {
    top.document.removeEventListener('mousedown', closeContextMenuFromTop);
});

$(document).on('keydown', async function (e) {
    const key = (e.key || '').toLowerCase();
    const node = getNodeByStatus({ active: true });
    const selected = getNodeByStatusAll({ selected: true });
    const readonly = isGlobalReadonly();
    const restricted = readonly || isSearchMode();
    const target = e.target;
    const tagName = target && target.tagName ? String(target.tagName).toLowerCase() : '';
    const isTextInputTarget = tagName === 'input' || tagName === 'textarea' || tagName === 'select' || (target && target.isContentEditable);
    const isDeleteKey = key === 'delete' || key === 'del' || e.code === 'Delete';

    if (Folder.mode === 'thumb' && !isTextInputTarget && !e.ctrlKey && !e.altKey && !e.shiftKey && !e.metaKey) {
        if (key === 'arrowleft' || key === 'arrowup') {
            e.preventDefault();
            await Thumb.prev();
            return;
        }

        if (key === 'arrowright' || key === 'arrowdown') {
            e.preventDefault();
            await Thumb.next();
            return;
        }
    }

    if (!restricted && e.ctrlKey && key === 'x' && node) {
        e.preventDefault();
        setClipboard('cut', node);
    } else if (!restricted && e.ctrlKey && key === 'c' && node) {
        e.preventDefault();
        setClipboard('copy', node);
    } else if (e.ctrlKey && key === 'a') {
        e.preventDefault();
        selectAllItems();
    } else if (!restricted && e.ctrlKey && key === 'v') {
        e.preventDefault();
        await pasteClipboard(content.path);
    } else if (!isSearchMode() && e.altKey && key === 'arrowup') {
        e.preventDefault();
        goParentFolder();
    } else if (e.ctrlKey && key === 'r') {
        e.preventDefault();
        top.global.frame.resetTreeWidth();
    } else if (e.shiftKey && e.altKey && key === 'c' && node) {
        e.preventDefault();
        copyNodePath(node);
    } else if (!restricted && key === 'f2') {
        e.preventDefault();
        renameSelected();
    } else if (!isSearchMode() && key === 'f5') {
        e.preventDefault();
        await refreshCurrentDirectory();
    } else if (!restricted && isDeleteKey) {
        const deleteTarget = selected.length ? selected[0] : node;

        if (!deleteTarget) {
            return;
        }

        e.preventDefault();
        deleteTarget.remove();
    }
});

