let uploadDragDepth = 0;

function isFileDrag(e) {
    const types = e.dataTransfer && e.dataTransfer.types;
    return types && Array.prototype.indexOf.call(types, 'Files') !== -1;
}

function setUploadDropMaskVisible(visible) {
    $('#folder-upload-drop-mask').toggleClass('folder-upload-drop-mask-visible', visible);
}

document.addEventListener('dragenter', function (e) {
    if (!isFileDrag(e) || !isToolbarActionEnabled('#folder-mode-upload')) {
        return;
    }

    e.preventDefault();
    ++uploadDragDepth;
    setUploadDropMaskVisible(true);
});

document.addEventListener('dragover', function (e) {
    if (!isFileDrag(e) || !isToolbarActionEnabled('#folder-mode-upload')) {
        return;
    }

    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
});

document.addEventListener('dragleave', function (e) {
    if (!isFileDrag(e)) {
        return;
    }

    uploadDragDepth = Math.max(0, uploadDragDepth - 1);
    uploadDragDepth || setUploadDropMaskVisible(false);
});

document.addEventListener('drop', async function (e) {
    if (!isFileDrag(e)) {
        return;
    }

    e.preventDefault();
    uploadDragDepth = 0;
    setUploadDropMaskVisible(false);

    if (!isToolbarActionEnabled('#folder-mode-upload')) {
        return;
    }

    await uploadFiles(e.dataTransfer.files);
});

$('#folder-mode-upload-cancel').on('click', function (e) {
    e.stopPropagation();
    if (!isToolbarActionEnabled('#folder-mode-upload-cancel')) {
        return false;
    }
    requestCancelUpload();
});

function getContextMenuTargetNodes(node) {
    const selected = node && node.selected ? getNodeByStatusAll({ selected: true }) : [];
    return (selected.length ? selected : node ? [node] : []).filter(Boolean);
}

function getZipMenuItem(node) {
    const supported = isZipMenuSupported();
    const zipNode = isZipFileNode(node);
    const zipName = getZipArchiveBaseName(node && (node.path || node.name) ? (node.path || node.name) : '');
    const readonly = isGlobalReadonly();

    return {
        name: 'zip_unzip',
        hidden: !supported || readonly,
        submenu: [
            { name: 'zip_archive', action: () => zipContextMenuNodes(node), hidden: !isZipSupported() || readonly },
            { name: 'tgz_archive', action: () => tgzContextMenuNodes(node), hidden: !isTgzSupported() || readonly },
            { name: 'unzip_current', action: () => unzipContextMenuNode(node, 'current'), hidden: !zipNode || readonly },
            { name: 'unzip_folder', action: () => unzipContextMenuNode(node, 'folder'), hidden: !zipNode || readonly, langArgs: [zipName] },
        ],
    };
}

async function zipContextMenuNodes(node) {
    if (!node || isGlobalReadonly()) {
        return false;
    }

    const nodes = getContextMenuTargetNodes(node);

    if (!nodes.length) {
        return false;
    }

    const src = nodes.map(item => item.path);
    const { code, data } = await requestZip(src.length === 1 ? src[0] : src);

    if (code) {
        error(code);
        return false;
    }

    const zipPath = data && data.zip ? String(data.zip).replace(/\\/g, '/') : '';
    const zipParentPath = getZipPathFromTarget({
        type: nodes[0] && nodes[0].type === 'folder' ? 'folder' : 'file',
        path: zipPath || nodes[0].path,
    });

    if (isSamePath(zipParentPath, content.path)) {
        await refreshFolder();

        if (zipPath) {
            const zipNode = Folder.items.find(item => isSamePath(item.path, zipPath));
            if (zipNode) {
                setNodeStatusAll({ active: false, selected: false });
                zipNode.active = true;
                zipNode.selected = true;
                updateToolbarActionStates();
            }
        }
    }

    await syncDirectory(zipParentPath);
    return true;
}

async function tgzContextMenuNodes(node) {
    if (!node || isGlobalReadonly()) {
        return false;
    }

    const nodes = getContextMenuTargetNodes(node);

    if (!nodes.length) {
        return false;
    }

    const src = nodes.map(item => item.path);
    const { code, data } = await requestTgz(src.length === 1 ? src[0] : src);

    if (code) {
        error(code);
        return false;
    }

    const tgzPath = data && data.tgz ? String(data.tgz).replace(/\\/g, '/') : '';
    const tgzParentPath = getZipPathFromTarget({
        type: nodes[0] && nodes[0].type === 'folder' ? 'folder' : 'file',
        path: tgzPath || nodes[0].path,
    });

    if (isSamePath(tgzParentPath, content.path)) {
        await refreshFolder();

        if (tgzPath) {
            const tgzNode = Folder.items.find(item => isSamePath(item.path, tgzPath));
            if (tgzNode) {
                setNodeStatusAll({ active: false, selected: false });
                tgzNode.active = true;
                tgzNode.selected = true;
                updateToolbarActionStates();
            }
        }
    }

    await syncDirectory(tgzParentPath);
    return true;
}

async function unzipContextMenuNode(node, mode) {
    if (!node || !isZipFileNode(node) || isGlobalReadonly()) {
        return false;
    }

    const dst = mode === 'folder' ? getZipUnzipTargetPath(node, 'folder') : (mode === 'current' ? getZipUnzipTargetPath(node, 'current') : undefined);
    const action = isZipFilePath(node.path) && /\.(tgz|tar\.gz)$/i.test(node.path) ? requestUntgz : requestUnzip;
    const { code } = await action(node.path, dst);

    if (code) {
        error(code);
        return false;
    }

    const targetPath = getParentPath(node.path);

    if (isSamePath(targetPath, content.path)) {
        await refreshFolder();
    }

    await syncDirectory(targetPath);
    return true;
}

async function openContextMenu(e, node) {
    const pasteDisabled = !getClipboard();
    let menuMap;

    if (isSearchMode()) {
        if (!node) {
            menuMap = [];
        } else if (node.type === 'folder') {
            menuMap = [
                { name: 'view-folder-new-tab', action: () => openFolderInNewTab(node) },
                { type: 'separator' },
                { name: 'copy-path', hotkey: 'Shift+Alt+C', action: () => copyNodePath(node) },
            ];
        } else {
            menuMap = [
                { name: 'open-file', action: () => node.openFile() },
                { name: 'open-containing-folder', action: () => openFolderInNewTab({ path: getParentPath(node.path) || '' }) },
                { name: 'download', action: () => node.downloadFile() },
                { type: 'separator' },
                { name: 'copy-path', hotkey: 'Shift+Alt+C', action: () => copyNodePath(node) },
            ];
        }
    } else if (!node) {
        menuMap = [
            { name: 'new-file', action: () => create('file') },
            { name: 'new-folder', action: () => create('folder') },
            { type: 'separator' },
            { name: 'refresh', hotkey: 'F5', action: refreshCurrentDirectory },
            { type: 'separator' },
            { name: 'copy-path', hotkey: 'Shift+Alt+C', action: () => copyNodePath({ path: content.path }) },
            { name: 'paste', hotkey: 'Ctrl+V', disabled: pasteDisabled, action: () => pasteClipboard(content.path) },
        ];
    } else if (node.type === 'folder') {
        menuMap = [
            { name: 'view-folder', action: () => node.openFolder() },
            { name: 'view-folder-new-tab', action: () => openFolderInNewTab(node) },
            { type: 'separator' },
            { name: 'cut', hotkey: 'Ctrl+X', action: () => setClipboard('cut', node) },
            { name: 'copy', hotkey: 'Ctrl+C', action: () => setClipboard('copy', node) },
            { name: 'paste', hotkey: 'Ctrl+V', disabled: pasteDisabled, action: () => pasteClipboard(node.path) },
            { type: 'separator' },
            getZipMenuItem(node),
            { type: 'separator' },
            { name: 'copy-path', hotkey: 'Shift+Alt+C', action: () => copyNodePath(node) },
            { type: 'separator' },
            { name: 'rename', hotkey: 'F2', action: () => node.changeName() },
            { name: 'remove', hotkey: 'Delete', action: () => node.remove() },
            { type: 'separator' },
            { name: 'refresh', hotkey: 'F5', action: refreshCurrentDirectory },
        ];
    } else {
        menuMap = [
            { name: 'open-file', action: () => node.openFile() },
            {
                name: 'open-with',
                submenu: [
                    { name: 'open-with-editor', action: () => node.openFileWith('editor') },
                    { name: 'open-with-image', action: () => node.openFileWith('image') },
                    { name: 'open-with-video', action: () => node.openFileWith('video') },
                    { name: 'open-with-audio', action: () => node.openFileWith('audio') },
                ],
            },
            { name: 'download', action: () => node.downloadFile() },
            { name: 'fetch-download-url', action: () => node.fetchDownloadUrl() },
            { type: 'separator' },
            getZipMenuItem(node),
            { type: 'separator' },
            { name: 'cut', hotkey: 'Ctrl+X', action: () => setClipboard('cut', node) },
            { name: 'copy', hotkey: 'Ctrl+C', action: () => setClipboard('copy', node) },
            { name: 'paste', hotkey: 'Ctrl+V', disabled: pasteDisabled, action: () => pasteClipboard(content.path) },
            { type: 'separator' },
            { name: 'copy-path', hotkey: 'Shift+Alt+C', action: () => copyNodePath(node) },
            { type: 'separator' },
            { name: 'rename', hotkey: 'F2', action: () => node.changeName() },
            { name: 'remove', hotkey: 'Delete', action: () => node.remove() },
            { type: 'separator' },
            { name: 'refresh', hotkey: 'F5', action: refreshCurrentDirectory },
        ];
    }

    if (isWindowsComputerRoot()) {
        menuMap = menuMap.filter(item => {
            if (item.hidden) {
                return false;
            }

            if (item.type === 'separator') {
                return true;
            }

            return !shouldHideContextActionOnWindowsComputerRoot(item.name);
        });
    }

    if (isGlobalReadonly()) {
        menuMap = menuMap.filter(item => {
            if (item.hidden) {
                return false;
            }

            if (item.type === 'separator') {
                return true;
            }

            return !shouldHideContextActionOnReadonly(item.name);
        });
    } else {
        menuMap = menuMap.filter(item => !item.hidden);
    }

    menuMap = compactContextMenuSeparators(menuMap);

    const menu = $(top.document).find('.tree-menu-main').empty();

    for (let i = 0; i < menuMap.length; ++i) {
        const params = menuMap[i];

        if (params.type === 'separator') {
            menu.append('<li class="tree-menu-separator"></li>');
            continue;
        }

        const item = createContextMenuItem(params);
        menu.append(item);
    }

    const frameRect = frameElement.getBoundingClientRect();
    const menuLeft = frameRect.left + e.clientX;
    const menuTop = frameRect.top + e.clientY;
    const menuElement = menu[0];
    const layoutToken = {};
    menuElement.vsfileLayoutToken = layoutToken;
    menu.css({ top: menuTop + 'px', left: menuLeft + 'px', opacity: 0 }).show();
    await top.global.frame.renderLang();
    await new Promise(resolve => top.requestAnimationFrame(resolve));

    if (menuElement.vsfileLayoutToken !== layoutToken) {
        return;
    }

    const rect = menuElement.getBoundingClientRect();
    const viewportWidth = top.window.innerWidth;
    const viewportHeight = top.window.innerHeight;
    const left = menuLeft + rect.width > viewportWidth ? Math.max(0, menuLeft - rect.width) : menuLeft;
    const topPosition = menuTop + rect.height > viewportHeight ? Math.max(0, menuTop - rect.height) : menuTop;

    menu.css({ left: left + 'px', top: topPosition + 'px', opacity: 1 });
    contextMenuVisible = true;
}

function createContextMenuItem(params) {
    if (params.hidden) {
        return null;
    }

    const langArgs = params.langArgs ? ` data-lang-args='${JSON.stringify(params.langArgs).replace(/'/g, '&apos;')}'` : '';
    const name = `<span data-lang="tree.menu.${params.name.replace(/-/g, '_')}"${langArgs}></span>`;
    const hotkey = params.hotkey ? `<span class="tree-menu-hotkey">${params.hotkey}</span>` : '';
    const item = $(`<li class="tree-menu-item folder-context-menu-${params.name}">${name}${hotkey}</li>`);

    if (params.disabled) {
        item.addClass('tree-menu-item-disabled');
        return item;
    }

    if (params.submenu && params.submenu.length) {
        item.append('<span class="tree-menu-submenu"></span>');
        const submenu = $('<div class="tree-menu"></div>');

        for (let i = 0; i < params.submenu.length; ++i) {
            const subItem = createContextMenuItem(params.submenu[i]);
            subItem && submenu.append(subItem);
        }

        item.append(submenu);
        syncContextMenuSubmenuPosition(item);
    } else {
        item.on('click', function (e) {
            e.stopPropagation();
            closeContextMenu();
            typeof params.action === 'function' && params.action();
        });
    }

    return item;
}

function closeContextMenu() {
    const menu = $(top.document).find('.tree-menu-main');

    if (!contextMenuVisible && menu.css('display') === 'none') {
        return;
    }

    contextMenuVisible = false;
    menu[0] && (menu[0].vsfileLayoutToken = null);
    $(top.document).find('.tree-menu').css({ opacity: 0 }).hide();
}

function openFolderInNewTab(node) {
    const openTab = tab.findTab({ type: 'home', path: node.path, url: '?f=html/folder.html' }) || tab.findTab({ type: 'folder', path: node.path, url: '?f=html/folder.html' });

    if (openTab) {
        tab.showTab(openTab.id);
    } else {
        const newTab = tab.addTab({ type: 'folder', path: node.path, url: '?f=html/folder.html' }, 'after_current');
        tab.showTab(newTab.id);
    }

    tab.renderTabs();
}

function create(type) {
    if (isGlobalReadonly()) {
        return null;
    }

    closeContextMenu();
    setNodeStatusAll({ active: false, selected: false });
    const now = Math.floor(Date.now() / 1000);

    const node = new Node({
        type: type,
        new: true,
        rename: true,
        dir: content.path,
        created: now,
        modified: now,
    });

    const firstFileIndex = Folder.items.findIndex(item => item.type === 'file');
    const insertIndex = type === 'folder' && firstFileIndex >= 0 ? firstFileIndex : Folder.items.length;
    Folder.items.splice(insertIndex, 0, node);
    return node;
}

function renameSelected() {
    if (isGlobalReadonly()) {
        return false;
    }

    const selected = getNodeByStatusAll({ selected: true });
    const node = selected[0] || getNodeByStatus({ active: true });
    node && !node.new && !node.rename && node.changeName();
    closeContextMenu();
}

function getClipboard() {
    try {
        const c = getLocalConfig().clipboard;
        const validAction = c && ['copy', 'cut'].includes(c.action);
        const validFiles = c && Array.isArray(c.files) && c.files.length > 0 && c.files.every(path => typeof path === 'string' && path !== '');
        return validAction && validFiles ? c : null;
    } catch (error) {
        return null;
    }
}

function setClipboard(action, node) {
    if (isGlobalReadonly()) {
        return null;
    }

    const selected = node.selected ? getNodeByStatusAll({ selected: true }) : [];
    const files = (selected.length ? selected : [node]).map(item => item.path);
    let config = {};

    try {
        config = getLocalConfig();
    } catch (error) {
        config = {};
    }

    if (!config || typeof config !== 'object' || Array.isArray(config)) {
        config = {};
    }

    config.clipboard = { action: action, files: files };
    setLocalConfig(config);
    updateToolbarActionStates();
    return config.clipboard;
}

function updateCutClipboard(files) {
    let config = {};

    try {
        config = getLocalConfig();
    } catch (error) {
        config = {};
    }

    if (!config || typeof config !== 'object' || Array.isArray(config)) {
        config = {};
    }

    if (files.length) {
        config.clipboard = { action: 'cut', files: files };
    } else {
        delete config.clipboard;
    }

    setLocalConfig(config);
    updateToolbarActionStates();
}

function clearClipboard() {
    let config = {};

    try {
        config = getLocalConfig();
    } catch (error) {
        config = {};
    }

    if (!config || typeof config !== 'object' || Array.isArray(config)) {
        config = {};
    }

    delete config.clipboard;
    setLocalConfig(config);
    updateToolbarActionStates();
}

let updateToolbarActionStatesRunning = null;

function updateToolbarActionStatesNextFrame() {
    if (updateToolbarActionStatesRunning) {
        return true;
    }

    updateToolbarActionStatesRunning = requestAnimationFrame(updateToolbarActionStates);
    return true;
}

function updateToolbarActionStates() {
    applyToolbarReadonlyVisibility();
    updateFolderItemInfo();
    updateFolderHistoryButtons();

    if (isSearchMode()) {
        toggleToolbarAction('#folder-mode-upload', false);
        toggleToolbarAction('#folder-mode-upload-cancel', false);
        toggleToolbarAction('#folder-mode-new-file', false);
        toggleToolbarAction('#folder-mode-new-folder', false);
        toggleToolbarAction('#folder-mode-prev', false);
        toggleToolbarAction('#folder-mode-next', false);
        toggleToolbarAction('#folder-mode-parent', false);
        toggleToolbarAction('#folder-mode-cut', false);
        toggleToolbarAction('#folder-mode-copy', false);
        toggleToolbarAction('#folder-mode-paste', false);
        toggleToolbarAction('#folder-mode-remove', false);
        toggleToolbarAction('#folder-mode-refresh', false);
        toggleToolbarAction('#folder-mode-select-all', true);
        toggleToolbarAction('#folder-mode-invert-selection', true);
        updateToolbarActionStatesRunning = null;
        return;
    }

    if (isGlobalReadonly()) {
        toggleToolbarAction('#folder-mode-parent', normalizePath(content.path) !== '');
        toggleToolbarAction('#folder-mode-refresh', true);
        toggleToolbarAction('#folder-mode-select-all', true);
        toggleToolbarAction('#folder-mode-invert-selection', true);
        return;
    }

    const inWindowsComputerRoot = isWindowsComputerRoot();
    const hasSelection = getNodeByStatusAll({ selected: true }).length > 0;
    const hasClipboard = !!getClipboard();

    if (inWindowsComputerRoot) {
        toggleToolbarAction('#folder-mode-upload', false);
        toggleToolbarAction('#folder-mode-upload-cancel', false);
        toggleToolbarAction('#folder-mode-new-file', false);
        toggleToolbarAction('#folder-mode-new-folder', false);
        toggleToolbarAction('#folder-mode-parent', false);
        toggleToolbarAction('#folder-mode-cut', false);
        toggleToolbarAction('#folder-mode-copy', false);
        toggleToolbarAction('#folder-mode-paste', false);
        toggleToolbarAction('#folder-mode-remove', false);
        toggleToolbarAction('#folder-mode-refresh', true);
        toggleToolbarAction('#folder-mode-select-all', true);
        toggleToolbarAction('#folder-mode-invert-selection', true);
        return;
    }

    toggleToolbarAction('#folder-mode-upload', true);
    toggleToolbarAction('#folder-mode-upload-cancel', true);
    toggleToolbarAction('#folder-mode-new-file', true);
    toggleToolbarAction('#folder-mode-new-folder', true);
    toggleToolbarAction('#folder-mode-parent', normalizePath(content.path) !== '');
    toggleToolbarAction('#folder-mode-cut', hasSelection);
    toggleToolbarAction('#folder-mode-copy', hasSelection);
    toggleToolbarAction('#folder-mode-remove', hasSelection);
    toggleToolbarAction('#folder-mode-paste', hasClipboard);
    updateToolbarActionStatesRunning = null;
}

function getFolderInfoTarget() {
    const selected = getNodeByStatusAll({ selected: true });

    if (selected.length > 1) {
        const folderNodes = selected.filter(item => item.type === 'folder');
        const hasFolder = folderNodes.length > 0;
        const totalSize = selected.reduce((sum, item) => sum + (Number(item.size) || 0), 0);
        const allFoldersFinished = folderNodes.length === 0 || folderNodes.every(item => item.calcSize === 'finish');
        const multiCalcSize = hasFolder ? (folderNodes.some(item => item.calcSize === 'calculating') ? 'calculating' : (allFoldersFinished ? 'finish' : 'no')) : 'finish';

        return {
            type: 'folder',
            name: '',
            path: '',
            size: totalSize,
            calcSize: multiCalcSize,
            mode: (selected[0] && selected[0].mode) || '000',
            isMultiSelect: true,
            calculateFolderSize: async function () {
                const selectedNodes = getNodeByStatusAll({ selected: true });
                const folderNodes = selectedNodes.filter(item => item.type === 'folder');

                if (!selectedNodes.length || !folderNodes.length) {
                    return this;
                }

                folderNodes.forEach(item => item.calcSize = 'calculating');
                this.calcSize = 'calculating';
                this.size = selectedNodes.reduce((sum, item) => sum + (Number(item.size) || 0), 0);
                updateFolderItemInfo();

                const refreshMultiTotal = () => {
                    const total = selectedNodes.reduce((sum, item) => {
                        if (item.type === 'folder') {
                            if (item.calcSize === 'finish') {
                                return sum + (Number(item.size) || 0);
                            }

                            return sum;
                        }

                        return sum + (Number(item.size) || 0);
                    }, 0);

                    this.size = total;
                    this.calcSize = folderNodes.some(item => item.calcSize === 'calculating') ? 'calculating' : 'finish';
                    updateFolderItemInfo();
                };

                await Promise.all(folderNodes.map(async item => {
                    const path = String(item.path || '');
                    const { code, data } = await ajax({ url: '?a=size', data: JSON.stringify({ path: path }) });

                    if (code) {
                        item.calcSize = 'finish';
                        refreshMultiTotal();
                        return;
                    }

                    item.size = Number(data && data.size) || 0;
                    item.calcSize = 'finish';
                    refreshMultiTotal();
                }));

                refreshMultiTotal();
                return this;
            },
        };
    }

    if (selected.length) {
        return selected[0];
    }

    return {
        type: 'folder',
        name: getFolderInfoName(content.path),
        path: content.path || '',
        size: Folder.currentDirSize === null ? 0 : Folder.currentDirSize,
        calcSize: Folder.currentDirSizeLoading ? 'calculating' : (Folder.currentDirSize === null ? 'no' : 'finish'),
        mode: Folder.currentDirMode || '000',
        calculateFolderSize: async function () {
            if (Folder.currentDirSizeLoading || Folder.currentDirSize !== null) {
                return this;
            }

            const path = content.path || '';
            Folder.currentDirSizeLoading = true;
            updateFolderItemInfo();

            const { code, data } = await ajax({ url: '?a=size', data: JSON.stringify({ path: path }) });

            if (path !== (content.path || '')) {
                Folder.currentDirSizeLoading = false;
                return this;
            }

            if (code) {
                Folder.currentDirSizeLoading = false;
                error(code);
                updateFolderItemInfo();
                return this;
            }

            Folder.currentDirSize = data.size;
            Folder.currentDirSizeLoading = false;
            updateFolderItemInfo();
            return this;
        },
    };
}

function getFolderInfoName(path) {
    const value = String(path || '').replace(/\\/g, '/').replace(/\/+$/g, '');

    if (!value || value === '/') {
        return getLangTextByPath('common.root');
    }

    const parts = value.split('/').filter(Boolean);
    return parts.length ? parts[parts.length - 1] : value;
}

function getFolderInfoIconClass(target) {
    if (!target) {
        return 'filetype-folder';
    }

    if (target.type === 'folder') {
        return 'filetype-folder';
    }

    const ext = target.name && target.name.includes('.') ? target.name.split('.').pop().toLowerCase() : '';
    const type = ext ? fileType(ext) : 'default';
    return `filetype-${type || 'default'}`;
}

function getFolderInfoSizeHtml(target) {
    if (!target || target.type !== 'folder') {
        return `<span class="folder-item-info-size-text">${fileSize(Number(target && target.size) || 0)}</span>`;
    }

    if (target.calcSize === 'calculating') {
        return '<span class="folder-item-info-size-calculating" data-lang="folder.calculating"></span>';
    }

    if (target.calcSize === 'no') {
        return '<span class="folder-item-info-size-calc" data-lang="folder.calc"></span>';
    }

    return `<span class="folder-item-info-size-text">${fileSize(Number(target.size) || 0)}</span>`;
}

function normalizeFolderInfoMode(mode) {
    const text = String(mode || '').trim();
    return /^[0-7]{3}$/.test(text) ? text : '000';
}

function normalizeFolderInfoModePreview(mode) {
    const text = String(mode || '').replace(/[^0-7]/g, '').slice(-3);
    return text.padStart(3, '0');
}

function getFolderInfoModePopup() {
    return $('.folder-item-info-mode-popup');
}

function getFolderInfoModeInput() {
    return $('.folder-item-info-mode-input');
}

function syncFolderInfoModePopupFromInput() {
    const popup = getFolderInfoModePopup();
    const modeInput = getFolderInfoModeInput();

    if (!popup.length || !modeInput.length) {
        return;
    }

    const digits = normalizeFolderInfoModePreview(modeInput.val()).split('');

    popup.find('input[type="checkbox"]').each(function () {
        const input = $(this);
        const bit = Number(input.attr('data-mode-bit') || '0');
        const group = input.attr('data-mode-group') || '';
        const modeDigitIndex = group === 'owner' ? 0 : group === 'group' ? 1 : 2;
        const modeDigit = Number(digits[modeDigitIndex] || '0');
        input.prop('checked', (modeDigit & bit) > 0);
    });
}

function syncFolderInfoModeInputFromPopup() {
    const popup = getFolderInfoModePopup();
    const modeInput = getFolderInfoModeInput();

    if (!popup.length || !modeInput.length) {
        return;
    }

    let owner = 0;
    let group = 0;
    let other = 0;

    popup.find('input[type="checkbox"]:checked').each(function () {
        const bit = Number($(this).attr('data-mode-bit') || '0');
        const groupName = $(this).attr('data-mode-group') || '';

        if (groupName === 'owner') {
            owner += bit;
        } else if (groupName === 'group') {
            group += bit;
        } else {
            other += bit;
        }
    });

    const mode = [owner, group, other].map((value) => value.toString(8)).join('');
    modeInput.val(mode.padStart(3, '0'));
}

function setFolderInfoModePopupVisible(visible) {
    const popup = getFolderInfoModePopup();
    const input = getFolderInfoModeInput();
    popup.toggleClass('folder-item-info-mode-popup-hidden', !visible);

    if (!visible && document.activeElement && input.length && input[0] === document.activeElement) {
        input[0].blur();
    }
}

let folderInfoModeSuccessTimer = null;

function setFolderInfoModeSuccessVisible(visible) {
    const successIcon = $('.folder-item-info-mode-success');

    if (!successIcon.length) {
        return;
    }

    successIcon.toggleClass('folder-item-info-mode-success-visible', !!visible);
}

function showFolderInfoModeSuccess() {
    if (folderInfoModeSuccessTimer !== null) {
        clearTimeout(folderInfoModeSuccessTimer);
        folderInfoModeSuccessTimer = null;
    }

    setFolderInfoModeSuccessVisible(true);

    folderInfoModeSuccessTimer = setTimeout(() => {
        setFolderInfoModeSuccessVisible(false);
        folderInfoModeSuccessTimer = null;
    }, 1000);
}

function syncFolderInfoNameFilterInput() {
    const info = $('.folder-item-info');
    if (!info.length) {
        return;
    }

    const input = info.find('.folder-item-info-mode-filter-input');
    if (!input.length) {
        return;
    }

    const value = Folder.nameFilter || '';
    if (input.val() !== value) {
        input.val(value);
    }
}

function updateFolderInfoModeReadonlyState() {
    const readonly = isGlobalReadonly();
    const info = $('.folder-item-info');
    const modeInput = info.find('.folder-item-info-mode-input');
    const modeSetButton = info.find('.folder-item-info-mode-set');
    const filterInput = info.find('.folder-item-info-mode-filter-input');
    const filterButton = info.find('.folder-item-info-mode-filter');

    modeInput.prop('disabled', readonly);
    modeSetButton.prop('disabled', readonly);
    filterInput.prop('disabled', readonly);
    filterButton.prop('disabled', readonly);

    if (readonly) {
        setFolderInfoModePopupVisible(false);
    }
}

function getCurrentFolderSummaryStats() {
    const items = Folder.baseItems || [];
    let folderCount = 0;
    let fileCount = 0;

    for (let i = 0; i < items.length; ++i) {
        const item = items[i];

        if (item.type === 'folder') {
            ++folderCount;
        } else if (item.type === 'file') {
            ++fileCount;
        }
    }

    return { folderCount, fileCount };
}

function updateFolderItemInfo() {
    const info = $('.folder-item-info');

    if (!info.length) {
        return;
    }

    const target = getFolderInfoTarget();
    const modeValue = normalizeFolderInfoMode(target.mode);
    const icon = info.find('.folder-item-info-icon');
    const name = info.find('.folder-item-info-name');
    const size = info.find('.folder-item-info-size-text');
    const modeInput = info.find('.folder-item-info-mode-input');

    if (isSearchMode()) {
        icon.attr('class', 'folder-item-info-icon folder-item-info-icon-search');
    } else if (isWindowsComputerRoot()) {
        icon.attr('class', 'folder-item-info-icon filetype-computer');
    } else {
        icon.attr('class', 'folder-item-info-icon ' + getFolderInfoIconClass(target));
    }

    icon[0].style.removeProperty('background-image');
    icon[0].style.removeProperty('background-size');
    icon[0].style.removeProperty('background-repeat');
    icon[0].style.removeProperty('background-position');

    if (target && target.type !== 'folder') {
        const ext = target.name && target.name.includes('.') ? target.name.split('.').pop().toLowerCase() : '';

        if (['exe', 'com'].includes(ext)) {
            const applyIcon = () => {
                if (!target.iconBlobUrl) {
                    return;
                }

                icon[0].style.setProperty('background-image', `url(${target.iconBlobUrl})`, 'important');
                icon[0].style.setProperty('background-size', 'contain', 'important');
                icon[0].style.setProperty('background-repeat', 'no-repeat', 'important');
                icon[0].style.setProperty('background-position', 'center center', 'important');
            };

            if (target.iconBlobUrl) {
                applyIcon();
            } else {
                const xhr = new XMLHttpRequest();
                xhr.responseType = 'arraybuffer';
                xhr.open('POST', '?a=icon', true);

                xhr.onload = () => {
                    if (xhr.status !== 200 || !xhr.response) {
                        return;
                    }

                    const contentType = xhr.getResponseHeader('Content-Type') || 'image/vnd.microsoft.icon';

                    if (!contentType.startsWith('image/')) {
                        return;
                    }

                    if (target.iconBlobUrl) {
                        URL.revokeObjectURL(target.iconBlobUrl);
                    }

                    target.iconBlobUrl = URL.createObjectURL(new Blob([xhr.response], { type: contentType }));
                    applyIcon();
                };

                xhr.onerror = () => { };
                xhr.send(JSON.stringify({ path: target.path }));
            }
        }
    }

    name.removeAttr('title').removeAttr('data-lang').removeAttr('data-lang-title').removeAttr('data-lang-args').text('');

    if (isSearchMode()) {
        name.attr('data-lang', 'navi.search_result').attr('data-lang-args', JSON.stringify([escapeHtml(content.query)]));
    } else if (isWindowsComputerRoot()) {
        name.attr('data-lang', 'common.my_computer').attr('data-lang-title', 'common.my_computer_title');
    } else if (target && target.isMultiSelect) {
        name.removeAttr('title').attr('data-lang', 'folder.multiple_files');
    } else if (target.path === '' || target.path === '/') {
        name.attr('data-lang', 'common.root').attr('data-lang-title', 'common.root_title');
    } else {
        name.text(getFolderInfoName(target.path || target.name || ''));
        name.attr('title', String(target.name || getFolderInfoName(target.path || '') || ''));
    }

    size.removeClass('folder-item-info-size-calc folder-item-info-size-calculating').removeAttr('data-lang');

    if (!target || target.type !== 'folder') {
        size.text(fileSize(Number(target && target.size) || 0));
    } else if (target.calcSize === 'calculating') {
        size.addClass('folder-item-info-size-calculating').attr('data-lang', 'folder.calculating').text('');
    } else if (target.calcSize === 'no') {
        size.addClass('folder-item-info-size-calc').attr('data-lang', 'folder.calc').text('');
    } else {
        size.text(fileSize(Number(target.size) || 0));
    }

    const stats = getCurrentFolderSummaryStats();
    info.find('.folder-item-info-summary').attr('data-lang-args', JSON.stringify([stats.folderCount || 0, stats.fileCount || 0]));
    modeInput.val(modeValue);
    syncFolderInfoModePopupFromInput();
    syncFolderInfoNameFilterInput();
    updateFolderInfoModeReadonlyState();
    renderLang();
}

async function applyFolderInfoMode(target) {
    if (!target) {
        return false;
    }

    if (isGlobalReadonly()) {
        error('common.error.read_only');
        return false;
    }

    const info = $('.folder-item-info');
    const modeInput = info.find('.folder-item-info-mode-input');
    const rawMode = String(modeInput.val() || '').trim();

    if (!/^[0-7]{3}$/.test(rawMode)) {
        error('common.error.invalid_request');
        modeInput.val(normalizeFolderInfoMode(target.mode));
        return false;
    }

    const mode = rawMode;
    const selected = getNodeByStatusAll({ selected: true });
    const targets = selected.length ? selected : [target];
    const paths = targets.map(item => String(item.path || '')).filter(Boolean);

    if (!paths.length) {
        return false;
    }

    modeInput.val(mode);

    const { code } = await ajax({
        url: '?a=chmod',
        data: JSON.stringify({
            paths: paths.length > 1 ? paths : paths[0],
            mode: mode,
        }),
    });

    if (code) {
        error(code);
        return false;
    }

    if (!selected.length) {
        Folder.currentDirMode = mode;
    } else {
        selected.forEach(item => {
            item.mode = mode;
        });
    }

    showFolderInfoModeSuccess();
    updateFolderItemInfo();
    return true;
}

$(document).on('click', '.folder-item-info-size-calc', async function (e) {
    e.stopPropagation();
    const target = getFolderInfoTarget();

    if (target && target.type === 'folder' && typeof target.calculateFolderSize === 'function') {
        await target.calculateFolderSize();
    }
});

$(document).on('click', '.folder-item-info-mode-set', async function (e) {
    e.stopPropagation();
    await applyFolderInfoMode(getFolderInfoTarget());
});

$(document).on('click', '.folder-item-info-mode-filter', function (e) {
    e.stopPropagation();
    const info = $(this).closest('.folder-item-info');
    const filterInput = info.find('.folder-item-info-mode-filter-input');
    const value = filterInput.length ? filterInput.val() : '';
    applyFolderNameFilter(value, { render: true });
    syncFolderInfoNameFilterInput();
});

$(document).on('keydown', '.folder-item-info-mode-filter-input', function (e) {
    if (e.key === 'Enter') {
        e.preventDefault();
        $(this).closest('.folder-item-info').find('.folder-item-info-mode-filter').trigger('click');
    }
});

$(document).on('focus', '.folder-item-info-mode-input', function () {
    if (isGlobalReadonly()) {
        setFolderInfoModePopupVisible(false);
        return;
    }

    syncFolderInfoModePopupFromInput();
    setFolderInfoModePopupVisible(true);
});

$(document).on('input', '.folder-item-info-mode-input', function () {
    if (isGlobalReadonly()) {
        return;
    }

    syncFolderInfoModePopupFromInput();
});

$(document).on('blur', '.folder-item-info-mode-input', function () {
    setTimeout(() => {
        if (!$('.folder-item-info-mode').find(':focus').length) {
            setFolderInfoModePopupVisible(false);
        }
    }, 0);
});

$(document).on('change', '.folder-item-info-mode-popup input[type="checkbox"]', function () {
    if (isGlobalReadonly()) {
        return;
    }

    syncFolderInfoModeInputFromPopup();
});

$(document).on('keydown', '.folder-item-info-mode-input', function (e) {
    if (isGlobalReadonly()) {
        return;
    }

    if (e.key !== 'Enter') {
        return;
    }

    e.preventDefault();
    $(this).closest('.folder-item-info').find('.folder-item-info-mode-set').trigger('click');
});

$(document).on('mousedown', function (e) {
    if (!$(e.target).closest('.folder-item-info-mode').length) {
        setFolderInfoModePopupVisible(false);
    }
});

function toggleToolbarAction(selector, enabled) {
    $(selector).toggleClass('folder-action-item-disabled', !enabled);
}

function isToolbarActionEnabled(selector) {
    return !$(selector).hasClass('folder-action-item-disabled');
}

function getToolbarSelectionNode() {
    const selected = getNodeByStatusAll({ selected: true });
    return selected[0] || getNodeByStatus({ active: true });
}

function toolbarSetClipboard(action) {
    const node = getToolbarSelectionNode();

    if (!node || !getNodeByStatusAll({ selected: true }).length) {
        return false;
    }

    setClipboard(action, node);
    return true;
}

async function toolbarPasteClipboard() {
    if (!getClipboard()) {
        return false;
    }

    return await pasteClipboard(content.path);
}

function toolbarRemoveSelection() {
    const node = getToolbarSelectionNode();

    if (!node || !getNodeByStatusAll({ selected: true }).length) {
        return false;
    }

    node.remove();
    return true;
}

function selectAllItems() {
    if (!Folder.items.length) {
        return false;
    }

    setNodeStatusAll({ selected: true });
    updateToolbarActionStates();
    return true;
}

function invertSelection() {
    if (!Folder.items.length) {
        return false;
    }

    for (let i = 0; i < Folder.items.length; ++i) {
        Folder.items[i].selected = !Folder.items[i].selected;
    }

    updateToolbarActionStates();
    return true;
}

async function pasteClipboard(targetPath) {
    if (isGlobalReadonly()) {
        return false;
    }

    const clipboard = getClipboard();

    if (!clipboard) {
        return false;
    }

    const files = clipboard.files.slice();
    const strategy = await resolvePasteStrategy(clipboard, targetPath);
    const changedDirsMap = {};
    const remaining = [];
    let completed = 0;

    changedDirsMap[targetPath] = true;

    if (!strategy) {
        return false;
    }

    for (; completed < files.length; ++completed) {
        const source = files[completed];
        const { code, data } = await ajax({
            url: '?a=paste',
            data: JSON.stringify({ src: source, target: targetPath, action: clipboard.action, strategy: strategy }),
        });

        if (code) {
            remaining.push(...files.slice(completed));
            error(code);
            break;
        }

        clipboard.action === 'cut' && data.source_exists && remaining.push(source);

        if (clipboard.action === 'cut' && !data.source_exists) {
            changedDirsMap[getParentPath(source)] = true;
        }
    }

    clearClipboard();
    const changedDirs = Object.keys(changedDirsMap);
    const shouldRefreshCurrent = changedDirs.some(path => isSamePath(path, content.path));
    shouldRefreshCurrent && await refreshFolder();

    for (let i = 0; i < changedDirs.length; ++i) {
        await syncDirectory(changedDirs[i]);
    }

    return completed === files.length && remaining.length === 0;
}

async function copyNodePath(node) {
    const isWindowsDrive = top.global.config.platform === 'windows' && /^([A-Z]):/i.test(node.path);
    const path = isWindowsDrive ? node.path.replace(/\//g, '\\') : '/' + node.path.replace(/^\/+/, '');

    try {
        await top.global.frame.copy(path);
        top.global.frame.openDialog({
            type: 'success',
            text_1: 'tree.dialog.copy_success',
            buttons: [{ label: 'common.ok', onClick: top.global.frame.closeDialog }],
        });
    } catch (error) {
        return false;
    }

    return true;
}

function refreshFolder() {
    return fetchFolder(content.path, true);
}

async function pickUploadFiles() {
    return await new Promise(resolve => {
        const input = document.createElement('input');
        input.type = 'file';
        input.multiple = true;
        input.style.display = 'none';
        document.body.appendChild(input);

        input.addEventListener('change', () => {
            const files = Array.from(input.files || []);
            input.remove();
            resolve(files);
        }, { once: true });

        input.addEventListener('cancel', () => {
            input.remove();
            resolve([]);
        }, { once: true });

        input.click();
    });
}

let uploadInProgress = false;
let uploadCancelRequested = false;

function parseWriteSizeLimit(value) {
    if (value === null || value === undefined || value === '' || value === false) {
        return false;
    }

    if (typeof value === 'number' && isFinite(value)) {
        return value > 0 ? Math.floor(value) : false;
    }

    const str = String(value).trim().toLowerCase();
    const match = str.match(/^([0-9]+(?:\.[0-9]+)?)\s*([a-z]*)$/i);

    if (!match) {
        return false;
    }

    const num = parseFloat(match[1]);

    if (!isFinite(num) || num < 0) {
        return false;
    }

    const unit = match[2].toUpperCase();
    const powMap = {
        '': 0,
        B: 0,
        K: 1,
        KB: 1,
        M: 2,
        MB: 2,
        G: 3,
        GB: 3,
        T: 4,
        TB: 4,
        P: 5,
        PB: 5,
        E: 6,
        EB: 6,
        Z: 7,
        ZB: 7,
        Y: 8,
        YB: 8,
    };

    if (!Object.prototype.hasOwnProperty.call(powMap, unit)) {
        return false;
    }

    return Math.floor(num * Math.pow(1024, powMap[unit]));
}

function getEffectiveUploadWriteSizeLimit() {
    const userinfo = top.global.data.userinfo || {};
    const userLimit = parseWriteSizeLimit(userinfo.write_size_limit);
    return userLimit !== false ? userLimit : false;
}

function calcUploadChunkSize() {
    const limit = getEffectiveUploadWriteSizeLimit();
    const fallback = 4 * 1024 * 1024;

    if (limit === false) {
        return fallback;
    }

    if (limit <= 128 * 1024) {
        return Math.max(1024, limit - 1024);
    }

    const reserved = Math.min(512 * 1024, Math.max(64 * 1024, Math.floor(limit * 0.1)));
    let chunkSize = limit - reserved;
    chunkSize = Math.min(chunkSize, 8 * 1024 * 1024);
    chunkSize = Math.max(chunkSize, 64 * 1024);
    return chunkSize;
}

function setUploadButtonProgress(percent) {
    const progress = Math.max(0, Math.min(100, percent));
    const progressText = progress.toFixed(2).padStart(6, '\u2002');

    $('#folder-mode-upload')
        .addClass('folder-action-item-upload-hidden');

    $('#folder-mode-uploading')
        .attr('aria-disabled', 'true')
        .addClass('folder-action-item-uploading-visible')
        .css({ '--upload-progress': `${progress}%` })
        .html(`<span class="folder-action-item-text">上传中 ${progressText}%</span>`);

    $('#folder-mode-upload-cancel').addClass('folder-action-item-upload-cancel-visible');
}

function resetUploadButton() {
    $('#folder-mode-upload')
        .removeClass('folder-action-item-upload-hidden')
        .attr('data-lang', 'folder.upload');

    $('#folder-mode-uploading')
        .removeAttr('aria-disabled')
        .removeClass('folder-action-item-uploading-visible')
        .css({ '--upload-progress': '0%' })
        .attr('data-lang', 'folder.uploading');

    $('#folder-mode-upload-cancel').removeClass('folder-action-item-upload-cancel-visible');
    uploadCancelRequested = false;
    renderLang();
}

function requestCancelUpload() {
    if (!uploadInProgress || uploadCancelRequested) {
        return false;
    }

    top.global.frame.openDialog({
        type: 'warning',
        text_1: 'tree.dialog.upload_cancel_confirm_title',
        text_2: 'tree.dialog.upload_cancel_confirm_text',
        buttons: [{
            label: 'common.ok',
            onClick: function () {
                uploadCancelRequested = true;
                top.global.frame.closeDialog();
            },
        }, {
            label: 'common.cancel',
            onClick: function () {
                top.global.frame.closeDialog();
            },
        }],
    });

    return true;
}

function uploadChunkWithProgress(formData, onProgress) {
    return new Promise(resolve => {
        const xhr = new XMLHttpRequest();
        xhr.open('POST', '?a=upload', true);

        xhr.upload.onprogress = function (event) {
            if (!event.lengthComputable) {
                return;
            }

            typeof onProgress === 'function' && onProgress(event.loaded, event.total);
        };

        xhr.onload = function () {
            if (xhr.status !== 200) {
                resolve({ code: 500, message: 'Internal server error.' });
                return;
            }

            try {
                const response = JSON.parse(xhr.responseText || '{}');
                resolve(response);
            } catch (e) {
                resolve({ code: 500, message: 'Internal server error.' });
            }
        };

        xhr.onerror = function () {
            resolve({ code: 500, message: 'Internal server error.' });
        };

        xhr.send(formData);
    });
}

async function uploadFileByChunks(file, rawPath, strategy, chunkSize, onChunkUploaded) {
    const totalChunks = Math.max(1, Math.ceil(file.size / chunkSize));
    let uploadPath = rawPath;
    let sentBytes = 0;

    for (let chunkIndex = 0; chunkIndex < totalChunks; ++chunkIndex) {
        if (uploadCancelRequested) {
            return { cancelled: true, sentBytes: sentBytes };
        }

        const start = chunkIndex * chunkSize;
        const end = Math.min(file.size, start + chunkSize);
        const chunk = file.slice(start, end);
        const formData = new FormData();
        formData.append('content', chunk, file.name);
        formData.append('path', uploadPath);
        formData.append('strategy', strategy);
        formData.append('chunk_index', String(chunkIndex));
        formData.append('chunk_total', String(totalChunks));

        let chunkProgressLoaded = 0;
        const { code, data } = await uploadChunkWithProgress(formData, (loaded, total) => {
            const safeLoaded = Math.min(Math.max(loaded, 0), total);
            const delta = safeLoaded - chunkProgressLoaded;

            if (delta > 0) {
                chunkProgressLoaded = safeLoaded;
                typeof onChunkUploaded === 'function' && onChunkUploaded(delta);
            }
        });

        if (code) {
            return { code: code };
        }

        if (chunkProgressLoaded < chunk.size) {
            const remain = chunk.size - chunkProgressLoaded;
            typeof onChunkUploaded === 'function' && onChunkUploaded(remain);
        }

        sentBytes += chunk.size;

        if (data && data.skipped) {
            return { skipped: true, sentBytes: sentBytes };
        }

        if (data && data.path) {
            uploadPath = data.path;
        }

    }

    return { skipped: false, sentBytes: sentBytes, path: uploadPath };
}

async function uploadFiles(selectedFiles) {
    if (uploadInProgress) {
        return false;
    }

    uploadInProgress = true;
    uploadCancelRequested = false;
    setUploadButtonProgress(0);

    try {
        const files = selectedFiles ? Array.from(selectedFiles) : await pickUploadFiles();

        if (!files.length) {
            return false;
        }

        let uploaded = 0;
        const paths = files.map(file => content.path ? content.path + '/' + file.name : file.name);
        const conflictResponse = await ajax({
            url: '?a=conflict',
            data: JSON.stringify({ files: paths, target: content.path || '', action: 'upload' }),
        });

        if (conflictResponse.code) {
            error(conflictResponse.code);
            return false;
        }

        let strategy = 'overwrite';

        if (conflictResponse.data && conflictResponse.data.conflicts) {
            strategy = await new Promise(resolve => {
                const choose = value => {
                    top.global.frame.closeDialog();
                    resolve(value);
                };

                top.global.frame.openDialog({
                    type: 'warning',
                    text_1: 'tree.dialog.paste_conflict_title',
                    text_1_args: [conflictResponse.data.conflicts],
                    text_2: 'tree.dialog.paste_conflict_text',
                    buttons: [{
                        label: 'tree.dialog.paste_overwrite',
                        onClick: () => choose('overwrite'),
                    }, {
                        label: 'tree.dialog.paste_discard',
                        onClick: () => choose('discard'),
                    }, {
                        label: 'tree.dialog.paste_rename',
                        onClick: () => choose('rename'),
                    }],
                });
            });
        }

        const chunkSize = calcUploadChunkSize();
        const uploadWriteSizeLimit = getEffectiveUploadWriteSizeLimit();
        const totalBytes = files.reduce((sum, item) => sum + item.size, 0);
        let uploadedBytes = 0;
        const setProgressByBytes = () => {
            const percent = totalBytes > 0 ? (uploadedBytes / totalBytes) * 100 : 100;
            setUploadButtonProgress(percent);
        };

        for (let i = 0; i < files.length; ++i) {
            if (uploadCancelRequested) {
                break;
            }

            const file = files[i];

            if (uploadWriteSizeLimit !== false && file.size > uploadWriteSizeLimit) {
                error('write_size_exceeded');
                continue;
            }

            const path = content.path ? content.path + '/' + file.name : file.name;
            const result = await uploadFileByChunks(file, path, strategy, chunkSize, chunkBytes => {
                uploadedBytes += chunkBytes;
                setProgressByBytes();
            });

            if (result.code) {
                error(result.code);
                continue;
            }

            if (result.cancelled) {
                break;
            }

            if (result.skipped) {
                uploadedBytes += Math.max(0, file.size - (result.sentBytes || 0));
                setProgressByBytes();
                continue;
            }

            ++uploaded;
        }

        !uploadCancelRequested && setUploadButtonProgress(100);

        if (!uploaded) {
            return false;
        }

        await refreshFolder();
        await syncDirectory(content.path);
        return true;
    } finally {
        uploadInProgress = false;
        resetUploadButton();
    }
}

async function refreshCurrentDirectory() {
    await refreshFolder();
    await syncDirectory(content.path);
    return true;
}

function goParentFolder() {
    if (!content.path) {
        return false;
    }

    const index = content.path.lastIndexOf('/');
    const parentPath = index >= 0 ? content.path.slice(0, index) : '';
    content.path = parentPath;
    renderFolderPath(parentPath);
    fetchFolder(parentPath, true);
    return true;
}

function renderFolderPath(path) {
    if (isSearchMode()) {
        const pathWrap = $('#global-path').empty();
        pathWrap.append('<li class="global-path-search-icon"></li>');
        pathWrap.append($('<li class="global-path-item"></li>')
            .attr('data-lang', 'navi.search_result')
            .attr('data-lang-args', JSON.stringify([escapeHtml(content.query)])));
        folderPathInput.hide();
        renderLang();
        return;
    }

    const safePath = normalizeFolderPath(path);
    folderPathInput.val(toFolderPathInputValue(safePath));

    renderPath(safePath, {
        mode: 'folder',
        onRootClick: function () {
            content.path = '';
            renderFolderPath('');
            fetchFolder('');
        },
        onSegmentClick: function (newPath) {
            content.path = newPath;
            renderFolderPath(newPath);
            fetchFolder(newPath);
        },
    });
}

async function fetchFolder(path, preserveMode = false) {
    const normalizedPath = normalizeFolderPath(path || '');
    const { code, data } = await ajax({ url: '?a=dir', data: JSON.stringify({ path: normalizedPath || '' }) });

    if (code) {
        error(code);
        return false;
    }

    tab.changeTab(id, { path: normalizedPath });
    tab.renderTabs();
    pushFolderHistory(normalizedPath);
    const payload = Array.isArray(data) ? { items: data, mode: '000' } : (data || {});
    const items = Array.isArray(payload.items) ? payload.items : [];
    const imageCount = items.reduce((count, item) => count + (isImage(item.name) ? 1 : 0), 0);
    const autoMode = items.length && imageCount / items.length >= 0.5 ? 'thumb' : 'detail';
    Folder.mode = await resolveDirShowMode(path, autoMode);
    Folder.baseItems = [];
    Folder.currentDirMode = String(payload.mode || '000');
    Folder.currentDirSize = null;
    Folder.currentDirSizeLoading = false;
    Folder.sortColumn = null;
    Folder.sortState = 'default';
    Folder.nameFilter = '';
    Folder.sizeFilter = { min: null, max: null, minRaw: '', maxRaw: '' };
    Folder.typeFilter = [];

    for (let i = 0; i < items.length; ++i) {
        const item = items[i];
        const props = parseProperty(item.property);
        const node = new Node(Object.assign({}, item, props));
        node.dir = path;
        Folder.baseItems.push(node);
    }

    resetDetailColumnSortStates();
    updateFolderFilterButtonState();
    Folder.items = getFolderDisplayItems();
    renderFolder();
    return true;
}

function resetFolderItems(items) {
    Folder.mode = 'detail';
    Folder.baseItems = [];
    Folder.currentDirMode = '000';
    Folder.currentDirSize = null;
    Folder.currentDirSizeLoading = false;
    Folder.sortColumn = null;
    Folder.sortState = 'default';
    Folder.nameFilter = '';
    Folder.sizeFilter = { min: null, max: null, minRaw: '', maxRaw: '' };
    Folder.typeFilter = [];

    for (let i = 0; i < items.length; ++i) {
        const item = items[i];
        const props = parseProperty(item.property);
        const node = new Node(Object.assign({}, item, props));
        node.dir = item.dir || '';
        Folder.baseItems.push(node);
    }

    resetDetailColumnSortStates();
    updateFolderFilterButtonState();
    Folder.items = getFolderDisplayItems();
    renderFolder();
}

function renderSearchResults() {
    renderFolderPath('');
    resetFolderItems(Array.isArray(content.searchResults) ? content.searchResults : []);
}

function appendSearchResults(items) {
    for (let i = 0; i < items.length; ++i) {
        const item = items[i];
        const props = parseProperty(item.property);
        const node = new Node(Object.assign({}, item, props));
        node.dir = item.dir || '';
        Folder.baseItems.push(node);
    }

    Folder.items = getFolderDisplayItems();
    renderFolder();
}

async function searchAllFolders() {
    await Promise.resolve();

    if (content.searchStarted) {
        renderSearchResults();
        return;
    }

    content.searchStarted = true;
    content.searchResults = [];
    content.searchComplete = false;
    renderSearchResults();
    const query = String(content.query || '').toLocaleLowerCase();
    const pending = [normalizeFolderPath(content.searchRoot || '')];
    const visitedPaths = new Set();
    const batchSize = 8;

    while (pending.length) {
        const batch = pending.splice(0, batchSize);
        const batchResults = await Promise.all(batch.map(async dir => {
            const response = await ajax({ url: '?a=dir', data: JSON.stringify({ path: dir }) });

            if (response.code) {
                error(response.code);
                return { dir, items: [] };
            }

            const payload = Array.isArray(response.data) ? { items: response.data } : (response.data || {});
            return { dir, items: Array.isArray(payload.items) ? payload.items : [] };
        }));

        const matchedItems = [];
        const nextPending = [];

        for (let i = 0; i < batchResults.length; ++i) {
            const { dir, items } = batchResults[i];

            for (let j = 0; j < items.length; ++j) {
                const item = items[j];
                const props = parseProperty(item.property);
                const itemPath = dir ? `${dir}/${item.name}` : item.name;
                const targetPath = String(item.path || '');

                if (targetPath && visitedPaths.has(targetPath)) {
                    continue;
                }

                if (targetPath) {
                    visitedPaths.add(targetPath);
                }

                if (String(item.name || '').toLocaleLowerCase().includes(query)) {
                    const matchedItem = Object.assign({}, item, { dir: dir });
                    content.searchResults.push(matchedItem);
                    matchedItems.push(matchedItem);
                }

                if (item.type === 'folder' && !props.link) {
                    nextPending.push(itemPath);
                }
            }
        }

        pending.push(...nextPending);
        appendSearchResults(matchedItems);
    }

    content.searchComplete = true;
}

function renderFolder(params = {}) {
    $('.folder-mode-item').removeClass('folder-mode-item-active');
    $(`#folder-mode-item-${Folder.mode}`).addClass('folder-mode-item-active');
    $('#folder-detail-column').removeClass().addClass(`folder-detail-column folder-detail-column-${Folder.mode}`);
    $('#folder-items-wrap').removeClass().addClass(`folder-items-wrap folder-items-wrap-${Folder.mode}`);
    $('#folder-thumb').removeClass().addClass(`folder-thumb folder-thumb-${Folder.mode}`);
    Folder.$.empty();
    refreshFolderFilterUi();
    updateToolbarActionStates();
    updateFolderItemInfo();

    if (Folder.mode === 'thumb') {
        params.thumbTarget ? loadItemThumb(params.thumbTarget) : loadItemThumb();
    }

    for (let i = 0; i < Folder.items.length; ++i) {
        Folder.items[i].render(true);
    }
}

async function loadItemThumb(item) {
    if (Folder.mode !== 'thumb') {
        return;
    }

    Thumb.url = '';
    item = item ? item : Folder.items.find(i => i.isImage());

    if (!item) {
        return;
    }

    setNodeStatusAll({ selected: false });
    item.selected = true;
    item.active = true;
    scrollBar.scrollToElement(item.$);
    Thumb.url = item.blobUrl ? item.blobUrl : await getImageBlobUrl(item.path);
}

content.show = () => {
    if (isSearchMode()) {
        renderFolderPath('');
        renderFolder();
        renderLang();
        return;
    }

    renderFolderPath(content.path);
    fetchFolder(content.path, true);
    renderLang();
};

function strTime(time) {
    const date = new Date(time * 1000);
    const year = date.getFullYear();
    const month = `0${date.getMonth() + 1}`.slice(-2);
    const day = `0${date.getDate()}`.slice(-2);
    const hours = `0${date.getHours()}`.slice(-2);
    const minutes = `0${date.getMinutes()}`.slice(-2);
    const seconds = `0${date.getSeconds()}`.slice(-2);
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

function fileSize(size) {
    const units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'];
    let index = 0;
    let newSize = size;

    while (newSize >= 1024 && index < units.length - 1) {
        newSize /= 1024;
        ++index;
    }

    if (typeof units[index] === 'undefined') {
        return '<span data-lang="folder.huge"></span>';
    }

    return index === 0 ? `${newSize} ${units[index]}` : `${newSize.toFixed(2)} ${units[index]}`;
}

async function getImageBlobUrl(path) {
    const params = { path: path };

    return await new Promise(resolve => {
        const xhr = new XMLHttpRequest();
        xhr.responseType = 'arraybuffer';
        xhr.open('POST', '?a=image', true);

        xhr.onload = function () {
            if (xhr.status !== 200) {
                resolve({ code: 500, message: 'Internal server error.' });
                return;
            }

            const contentType = xhr.getResponseHeader('Content-Type');

            if (contentType && contentType.startsWith('image/')) {
                resolve(URL.createObjectURL(new Blob([xhr.response], { type: contentType })));
                return;
            }

            if (!contentType || !contentType.includes('application/json')) {
                resolve({ code: 1023, message: 'File not image.' });
                return;
            }

            const decoder = new TextDecoder('utf-8');
            const str = decoder.decode(xhr.response);
            resolve(JSON.parse(str));
        };

        xhr.send(JSON.stringify(params));
    });
}

function selectRangeByAnchor(anchorNode, targetNode) {
    if (!anchorNode || !targetNode || anchorNode === targetNode) {
        return false;
    }

    const anchorIndex = Folder.items.indexOf(anchorNode);
    const targetIndex = Folder.items.indexOf(targetNode);

    if (anchorIndex < 0 || targetIndex < 0) {
        return false;
    }

    const start = Math.min(anchorIndex, targetIndex);
    const end = Math.max(anchorIndex, targetIndex);

    setNodeStatusAll({ selected: false });

    for (let i = start; i <= end; ++i) {
        Folder.items[i].selected = true;
    }

    targetNode.selected = true;
    targetNode.active = true;
    updateToolbarActionStates();
    return true;
}

function getNodeByStatus(status) {
    for (let i = 0; i < Folder.items.length; ++i) {
        const item = Folder.items[i];
        let match = true;

        for (const key in status) {
            if (item[key] !== status[key]) {
                match = false;
                break;
            }
        }

        if (match) {
            return item;
        }
    }

    return null;
}

function getNodeByStatusAll(status) {
    const results = [];

    for (let i = 0; i < Folder.items.length; ++i) {
        const item = Folder.items[i];
        let match = true;

        for (const key in status) {
            if (item[key] !== status[key]) {
                match = false;
                break;
            }
        }

        match && results.push(item);
    }

    return results;
}

function setNodeStatusAll(status) {
    for (let i = 0; i < Folder.items.length; ++i) {
        const item = Folder.items[i];

        for (const key in status) {
            item[key] = status[key];
        }
    }
}

function findImageIndex(start, end) {
    const step = start < end ? 1 : -1;

    for (let i = start; i >= 0 && i < Folder.items.length; i += step) {
        if (Folder.items[i].isImage()) {
            return i;
        }

        if (i === end) {
            break;
        }
    }

    return -1;
}
