<!----- FILE js/frame.js START -----><script>
top.global.frame = {};
top.global.navi = {};
top.global.tree = {};
top.global.tab = {};
top.global.content = {};

const $tree = $('.tree');
const $resize = $('.resize');
const $right = $('.right');
const $widthTipsL = $('.frame-resize-width-left');
const $widthTipsR = $('.frame-resize-width-right');
const defaultTreeWidth = 320;
let treeWidthBase = defaultTreeWidth;
let treeWidthLine = defaultTreeWidth;
let treeResizeStartX = -1;
let mouseDownFlag = false;

renderLang();
loadConfig();

const w = getLocalConfig().treeWidth;
setTreeWidth(typeof w === 'number' ? w : defaultTreeWidth);

function setTreeWidth(width) {
    if (width < 0) {
        return false;
    }

    treeWidthLine = width;
    $tree.width(width);
    $right.css('width', `calc(100% - ${width}px)`);
    const config = getLocalConfig();
    config.treeWidth = width;
    setLocalConfig(config);
    return true;
}

function resetTreeWidth() {
    setTreeWidth(defaultTreeWidth);
}

async function saveContent() {
    const currentTab = top.global.tab.findTab({ current: true });
    const content = top.global.content['content-' + currentTab.id];
    return await content.saveContent();
}

$(document).on('keydown', async function (e) {
    const key = e.key.toLowerCase();

    if (e.ctrlKey && key === 's') {
        e.preventDefault();
        const response = await saveContent();
        response.code && error(response.code);
    } else if (e.ctrlKey && key === 'r') {
        e.preventDefault();
        resetTreeWidth();
    }
});

$('.resize').on('mousedown', function (e) {
    e.preventDefault();
    mouseDownFlag = true;
    $('iframe').css('pointer-events', 'none');
    $resize.addClass('moving');
    treeResizeStartX = e.pageX;
    treeWidthBase = treeWidthLine;
    $widthTipsL.show();
    $widthTipsR.show();
});

$(document).on('mousemove', function (e) {
    e.preventDefault();

    if (mouseDownFlag) {
        mouseDownFlag = false;
        return;
    }

    if (treeResizeStartX <= 0) {
        return;
    }

    const mainWidth = $(window).width();
    const halfWidth = mainWidth / 2 | 0;
    const max = mainWidth - 200;
    $widthTipsL.css({ 'opacity': 1 });
    $widthTipsR.css({ 'opacity': 1 });

    const baseLine = treeWidthBase + e.pageX - treeResizeStartX;
    let width = baseLine;

    if (!e.altKey) {
        if (Math.abs(width - halfWidth) < 10) {
            width = halfWidth;
        } else if (Math.abs(width - defaultTreeWidth) < 10) {
            width = defaultTreeWidth;
        } else if (e.ctrlKey) {
            width = Math.round(width / 50) * 50;
            const isFlank = w => (width - w) * (baseLine - w) < 0;
            isFlank(halfWidth) && (width = halfWidth);
            isFlank(defaultTreeWidth) && (width = defaultTreeWidth);
        }
    }

    width < 200 && (width = 200);
    width > max && (width = max);
    $widthTipsL.html(width + 'px');
    $widthTipsR.html(mainWidth - width + 'px');
    setTreeWidth(width);
});

$(document).on('mouseup', function (e) {
    e.preventDefault();
    treeResizeStartX = -1;
    $('iframe').css('pointer-events', 'auto');
    $widthTipsL.css({ 'opacity': 0 });
    $widthTipsR.css({ 'opacity': 0 });
    $resize.removeClass('moving');

    setTimeout(() => {
        $widthTipsL.hide();
        $widthTipsR.hide();
    }, 500);
});

$(window).on('resize', function () {
    const max = $(window).width() - 200;
    treeWidthLine > max && setTreeWidth(max);
});

top.global.frame.addContent = function (params) {
    top.global.content['content-' + params.id] = params;
    $('.right').append(`<iframe src="${params.url}" class="content content-${params.id}" scrolling="no" data-id="${params.id}"></iframe>`);
};

top.global.frame.showContent = function (id) {
    $('.right .content').each(function () {
        const contentId = +$(this).data('id');

        if (contentId === +id) {
            return;
        }

        const contentHide = top.global.content['content-' + contentId].hide;
        typeof contentHide === 'function' && contentHide();
    });

    $('.right .content').hide();
    $('.right .content-' + id).show();
    const contentShow = top.global.content['content-' + id].show;
    typeof contentShow === 'function' && contentShow();
};

top.global.frame.removeContent = function (id) {
    delete top.global.content['content-' + id];
    $('.right .content-' + id).remove();
};

top.global.frame.trigger = function (id, name, params) {
    const content = top.global.content['content-' + id];
    const func = typeof content[name] === 'function' ? content[name] : function () { };
    return func(params);
};

top.global.frame.syncDirectory = async function (path, options) {
    if (typeof path !== 'string') {
        return false;
    }

    const opts = Object.assign({
        reloadTree: true,
        reloadFolders: true,
        excludeContentId: null,
    }, options || {});

    const tasks = [];

    if (opts.reloadTree && top.global.tree && typeof top.global.tree.reloadPath === 'function') {
        const treeTask = top.global.tree.reloadPath(path);
        treeTask && typeof treeTask.then === 'function' && tasks.push(treeTask);
    }

    if (opts.reloadFolders) {
        for (const key in top.global.content) {
            const content = top.global.content[key];

            if (!content || typeof content.reloadPath !== 'function') {
                continue;
            }

            if (opts.excludeContentId !== null && +content.id === +opts.excludeContentId) {
                continue;
            }

            const folderTask = content.reloadPath(path);
            folderTask && typeof folderTask.then === 'function' && tasks.push(folderTask);
        }
    }

    tasks.length && await Promise.all(tasks);
    return true;
};

top.global.frame.openDialog = function (params) {
    const dialog = $('.frame-dialog');
    dialog.find('.frame-dialog-text-1').data('lang', params.text_1 || '').data('lang-args', JSON.stringify(params.text_1_args || '[]'));
    dialog.find('.frame-dialog-text-2').data('lang', params.text_2 || '').data('lang-args', JSON.stringify(params.text_2_args || '[]'));
    dialog.find('.frame-dialog-icon').removeClass().addClass('frame-dialog-icon frame-dialog-icon-' + (params.type ? params.type : 'info'));
    const buttons = dialog.find('.frame-dialog-buttons').empty();

    if (params.width) {
        dialog.find('.frame-dialog-content').css('width', params.width + 'px');
        dialog.find('.frame-dialog-text-1, .frame-dialog-text-2').css('width', params.width - 50 + 'px');
    } else {
        dialog.find('.frame-dialog-content, .frame-dialog-text-1, .frame-dialog-text-2').removeAttr('style');
    }

    if (params.buttons) {
        for (let i = params.buttons.length - 1; i >= 0; --i) {
            const button = params.buttons[i];
            const btn = $(`<div class="frame-dialog-button frame-dialog-button-${i}"></div `);
            btn.data('lang', button.label || '').data('lang-args', JSON.stringify(button.labelArgs || '[]'));

            btn.on('click', function () {
                typeof button.onClick === 'function' && button.onClick();
            });

            buttons.append(btn);
        }
    }

    renderLang();
    dialog.show();
};

top.global.frame.closeDialog = function () {
    $('.frame-dialog').hide().find('.frame-dialog-content, .frame-dialog-text-1, .frame-dialog-text-2').removeAttr('style');
};

top.global.frame.copy = function (str) {
    if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
        return navigator.clipboard.writeText(str);
    }

    const textarea = $('<textarea></textarea>').val(str).css({
        position: 'fixed',
        top: '-1000px',
        left: '-1000px',
    }).appendTo(document.body);

    textarea[0].select();
    const copied = document.execCommand('copy');
    textarea.remove();
    return copied ? Promise.resolve() : Promise.reject(new Error('Copy failed.'));
};

top.global.frame.resetTreeWidth = resetTreeWidth;
top.global.frame.saveContent = saveContent;
top.global.frame.renderLang = renderLang;
</script><!----- FILE js/frame.js END ----->
