});

function openHelp(target) {
    const helpUrl = '?f=html/help.html';
    const helpTarget = String(target || '');
    const tab = top.global.tab;
    let helpTab = tab.findTab({ url: helpUrl });

    if (helpTab) {
        if (helpTarget) {
            tab.changeTab(helpTab.id, { target: helpTarget });
            top.global.frame.trigger(helpTab.id, 'showHelpTarget', helpTarget);
        }
    } else {
        const tabData = { type: 'help', url: helpUrl, unlock: false };

        if (helpTarget) {
            tabData.target = helpTarget;
        }

        helpTab = tab.addTab(tabData, 'after_current');
    }

    tab.showTab(helpTab.id);
    tab.renderTabs();
    return false;
}

$(document).on('click', '[data-help]', function (e) {
    e.preventDefault();
    e.stopPropagation();
    return openHelp($(this).attr('data-help'));
});

async function ajax(params) {
    const response = await new Promise(resolve => {
        $.ajax(Object.assign({
            url: '',
            type: 'POST',
            data: {},
            success: resolve,
            error: function () {
                resolve({ code: 500, message: 'Internal server error.' });
            },
        }, params));
    });

    if (response.code === 1003) {
        top.location.href = '?a=logout';
        return;
    }

    return response;
}

async function loadConfig() {
    const { data } = await ajax({ url: '?a=config', type: 'GET' });
    top.global.config = data || {};
    return true;
}

async function loadLang(lang) {
    const data = await ajax({ url: '?f=lang/' + lang + '.json', type: 'GET' });
    top.global.lang = data;
    return true;
}

function getLangTextByPath(path) {
    const keys = path.split('.');
    let text = top.global.lang;

    for (let i = 0; i < keys.length; ++i) {
        if (text[keys[i]] !== undefined) {
            text = text[keys[i]];
        } else {
            text = null;
            break;
        }
    }

    return text === null ? path : text;
}

async function renderLangRun(lang) {
    lang = lang || getCurrentLanguage();

    if (!top.global.lang || top.global.lang.id !== lang) {
        await loadLang(lang);
    }

    setDocumentTitle(top.global.lang.title);

    $('[data-lang]').each(function () {
        let text = getLangTextByPath($(this).data('lang'));
        let args = $(this).data('lang-args') || [];

        while (text.includes('%s')) {
            text = text.replace('%s', nullish(args.shift(), ''));
        }

        $(this).html(text);
    });

    $('[data-lang-title]').each(function () {
        $(this).attr('title', getLangTextByPath($(this).data('lang-title')));
    });

    $('[data-lang-placeholder]').each(function () {
        $(this).attr('placeholder', getLangTextByPath($(this).data('lang-placeholder')));
    });

    top.global.data.currentLanguage = getCurrentLanguage();
    return true;
}

async function renderLang(lang) {
    window.global.renderLang = true;

    return await new Promise(resolve => {
        requestAnimationFrame(async () => {
            if (!window.global.renderLang) {
                return resolve();
            }

            await renderLangRun(lang);
            window.global.renderLang = null;
            resolve();
        });
    });
}

function getLangById(id) {
    for (let i = 0; i < top.global.langs.length; ++i) {
        if (top.global.langs[i].id === id) {
            return top.global.langs[i];
        }
    }

    return null;
}

function getCurrentLanguage() {
    const localConfig = getLocalConfig();

    if (localConfig.lang) {
        return localConfig.lang;
    }

    return top.global.config.lang || 'chs';
}

function fileType(ext) {
    if (/^([0-9]{3})$/.test(ext)) {
        return 'zip';
    }

    const map = {
        iso: 'img ima bin cue nrg mdf mds ccd sub cdi dmg toast isz uif daa wim esd swm vhd vhdx vmdk vdi qcow qcow2',
        mp3: 'wav flac aac ogg wma mp2 m4a m4b m4p m4r ac3 tds flac ape alac oga',
        mp4: 'mkv mov mpg mpeg avi wmv flv webm 3gp rm rmvb m4v ogm ogv asf',
        png: 'jpg jpeg jpc jp2 jpx gif bmp ico tif tiff xbm wbmp webp avif',
        cfg: 'ini inf conf config env cfg toml gitignore htaccess htpasswd',
        zip: 'rar 7z tar gz bz2 cab bz tgz xz lzma arj z txz tzst',
        xml: 'html htm dtd xhtml shtml xsl xslt rss atom',
        pgn: 'cbl cbr xqf obk pfc enc che ccm',
        php: 'php3 php4 php5 phps phtml',
        cer: 'cert crt der pem cat pfx',
        ttf: 'fon otf ttc eot woff woff2',
        xls: 'xlsx csv ods',
        doc: 'docx wps odt',
        sql: 'sdb dbf',
        ppt: 'pptx',
        txt: 'text',
        yml: 'yaml',
        bat: 'cmd',
        exe: 'com',
        db: 'db3 sqlite sqlite3',
        js: 'jsx ts tsx',
        ma: 'mb mll iff',
        ps: 'ps1 psm1',
    }

    for (const key in map) {
        if (map[key].split(' ').includes(ext)) {
            return key;
        }
    }

    return ext;
}

function parseProperty(property) {
    property = parseInt(property, 10);
    isNaN(property) && (property = 0);

    return {
        disk: (property & 1) === 1,
        mine: (property & 2) === 2,
        link: (property & 4) === 4,
        readonly: (property & 8) === 8,
    };
}

