function setDocumentTitle(newTitle) {
    document.title = newTitle;

    if (!/iph|ipad|ipod/i.test(navigator.userAgent)) {
        return;
    }

    const iframe = document.createElement('iframe');
    iframe.style.cssText = 'display:none;width:0;height:0;visibility:hidden;';
    iframe.src = '?f=img/navi/logo.svg';

    const iframeLoadHandler = function () {
        requestAnimationFrame(function () {
            iframe.removeEventListener('load', iframeLoadHandler);
            document.body.removeChild(iframe);
        });
    };

    iframe.addEventListener('load', iframeLoadHandler);
    document.body.appendChild(iframe);
    return true;
}

function checkValidFilename(filename, existList) {
    if (top.global.config.platform === 'windows') {
        if (/^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\..*)?$/i.test(filename)) {
            return { level: 'error', type: 'invalid_name' };
        }

        if (existList.find(item => item.toLowerCase() === filename.toLowerCase())) {
            return { level: 'error', type: 'exist' };
        }
    } else {
        if (existList.includes(filename)) {
            return { level: 'error', type: 'exist' };
        }
    }

    if (filename === '') {
        return { level: 'error', type: 'blank' };
    }

    if (/([\.]+)$/.test(filename)) {
        return { level: 'error', type: 'invalid_name' };
    }

    const blockedKeywords = ['..'];

    for (const keyword of blockedKeywords) {
        if (filename.includes(keyword)) {
            return { level: 'error', type: 'invalid_name' };
        }
    }

    const invalidChars = ['\\', '/', ':', '*', '?', '"', '<', '>', '|'];

    for (const char of invalidChars) {
        if (filename.includes(char)) {
            return { level: 'error', type: 'invalid_name' };
        }
    }

    if (filename.length > 30) {
        return { level: 'warning', type: 'too_long' };
    }

    return { level: 'success' };
}

function error(err) {
    typeof err === 'number' && (err = 'common.error.' + errorCode(err));
    top.global.frame.openDialog({ type: 'error', text_1: err, buttons: [{ label: 'common.ok', onClick: top.global.frame.closeDialog }] });
    return false;
}

function errorCode(code) {
    const map = {
        0: 'success',
        500: 'internal_server_error',
        1000: 'invalid_request',
        1001: 'logged_in',
        1002: 'login_failed',
        1003: 'not_logged_in',
        1004: 'read_only',
        1005: 'parent_not_found',
        1006: 'directory_not_found',
        1007: 'file_not_found',
        1008: 'invalid_filename',
        1009: 'invalid_type',
        1010: 'file_exists',
        1011: 'remove_failed',
        1012: 'path_not_directory',
        1013: 'path_not_file',
        1014: 'read_file_failed',
        1015: 'write_file_failed',
        1016: 'not_allowed_extension',
        1017: 'create_directory_failed',
        1018: 'create_file_failed',
        1019: 'rename_failed',
        1020: 'move_failed',
        1021: 'chmod_failed',
        1022: 'invalid_download_token',
        1023: 'iconv_not_enabled',
        1024: 'file_not_image',
        1025: 'write_size_exceeded',
        1026: 'path_inside_source',
        1027: 'no_current_password',
        1028: 'no_new_password',
        1029: 'no_confirm_password',
        1030: 'password_mismatch',
        1031: 'password_error',
        1032: 'totp_invalid',
        1033: 'zip_not_support',
        1034: 'zip_failed',
        1035: 'unzip_failed',
        1036: 'extract_ico_failed',
        1037: 'tar_not_support',
        1038: 'tar_failed',
        1039: 'untar_failed',
        1040: 'gz_not_support',
        1041: 'gz_failed',
        1042: 'ungz_failed',
    };

    return map[code] || 'unknown_error';
}

async function resolvePasteStrategy(clipboard, targetPath) {
    const { code, data } = await ajax({
        url: '?a=conflict',
        data: JSON.stringify({ files: clipboard.files, target: targetPath, action: clipboard.action }),
    });

    if (code) {
        error(code);
        return null;
    }

    if (!data.conflicts) {
        return 'overwrite';
    }

    return await new Promise(resolve => {
        const choose = strategy => {
            top.global.frame.closeDialog();
            resolve(strategy);
        };

        top.global.frame.openDialog({
            type: 'warning',
            text_1: 'tree.dialog.paste_conflict_title',
            text_1_args: [data.conflicts],
            text_2: 'tree.dialog.paste_conflict_text',
            buttons: [{
                label: 'tree.dialog.paste_overwrite',
                onClick: () => choose('overwrite'),
            }, {
                label: 'tree.dialog.paste_discard',
                onClick: () => choose('discard'),
            }, {
                label: 'tree.dialog.paste_rename',
                onClick: () => choose('rename'),
            }],
        });
    });
}

function isRecursiveCall() {
    const lines = (new Error()).stack.split('\n');
    const names = [];

    for (let i = 1; i < lines.length; ++i) {
        let line = lines[i].trim();

        if (!line.startsWith('at ')) {
            continue;
        }

        line = line.replace(/^at /, '').replace(/^async /, '');
        names.push(line.split(' ')[0]);
    }

    return names.filter(n => n === names[1]).length > 1;
}

function getSessionStorageName() {
    return 'vsfile-SessionName';
}

function getLocalConfig() {
    return JSON.parse(localStorage.getItem(getSessionStorageName()) || '{}');
}

function setLocalConfig(config) {
    localStorage.setItem(getSessionStorageName(), JSON.stringify(config));
    return config;
}

function isGlobalReadonly() {
    return top.global.data.userinfo.readonly === true;
}

function normalizePath(path) {
    return (path || '').replace(/\\/g, '/').replace(/^\/+/, '').replace(/\/+$/, '');
}

function getParentPath(path) {
    const normalized = (path || '').replace(/\\/g, '/');
    const index = normalized.lastIndexOf('/');
    return index >= 0 ? normalized.slice(0, index) : '';
}

function isZipSupported() {
    const config = top.global.config || {};
    return !!(config.extension && config.extension.zip);
}

function isTgzSupported() {
    const config = top.global.config || {};
    return !!(config.extension && config.extension.tgz);
}

function isZipMenuSupported() {
    return isZipSupported() || isTgzSupported();
}

function isZipFilePath(path) {
    const value = String(path || '');
    const name = value.split('/').pop().split('\\').pop();
    const lower = name.toLowerCase();

    if (lower.endsWith('.tar.gz')) {
        return true;
    }

    if (lower.endsWith('.tgz')) {
        return true;
    }

    return lower.endsWith('.zip');
}

function isZipFileNode(node) {
    return !!node && node.type !== 'folder' && isZipFilePath(node.name || node.path || '');
}

async function requestZip(src, dst) {
    const payload = { src: src, action: 'zip' };

    if (dst !== undefined) {
        payload.dst = dst;
    }

    return await ajax({
        url: '?a=zip',
        data: JSON.stringify(payload),
    });
}

async function requestTgz(src, dst) {
    const payload = { src: src, action: 'zip' };

    if (dst !== undefined) {
        payload.dst = dst;
    }

    return await ajax({
        url: '?a=tgz',
        data: JSON.stringify(payload),
    });
}

async function requestUnzip(src, dst) {
    const payload = { src: src, action: 'unzip' };

    if (dst !== undefined) {
        payload.dst = dst;
    }

    return await ajax({
        url: '?a=zip',
        data: JSON.stringify(payload),
    });
}

async function requestUntgz(src, dst) {
    const payload = { src: src, action: 'unzip' };

    if (dst !== undefined) {
        payload.dst = dst;
    }

    return await ajax({
        url: '?a=tgz',
        data: JSON.stringify(payload),
    });
}

function getZipArchiveBaseName(path) {
    const value = String(path || '').replace(/\\/g, '/');
    const name = value.split('/').pop() || '';
    const lower = name.toLowerCase();

    if (lower.endsWith('.tar.gz')) {
        return name.slice(0, -7) || 'unzipped';
    }

    if (lower.endsWith('.tgz')) {
        return name.slice(0, -4) || 'unzipped';
    }

    const baseName = name.replace(/\.zip$/i, '');
    return baseName || 'unzipped';
}

function getZipPathFromTarget(node) {
    if (!node) {
        return '';
    }

    const path = String(node.path || '');
    return node.type === 'folder' ? path : getParentPath(path);
}

function getZipUnzipTargetPath(node, mode) {
    const parentPath = getZipPathFromTarget(node);

    if (mode === 'current') {
        return parentPath || '/';
    }

    const baseName = getZipArchiveBaseName(node && node.path ? node.path : node && node.name ? node.name : '');
    return parentPath ? parentPath + '/' + baseName : baseName;
}

function shouldHideContextActionOnWindowsComputerRoot(name) {
    return [
        'new-file',
        'new-folder',
        'cut',
        'copy',
        'paste',
        'rename',
        'remove',
    ].includes(name);
}

function shouldHideContextActionOnReadonly(name) {
    return [
        'new-file',
        'new-folder',
        'cut',
        'copy',
        'paste',
        'zip',
        'unzip',
        'rename',
        'remove',
    ].includes(name);
}

function compactContextMenuSeparators(menuItems) {
    const compacted = [];

    for (let i = 0; i < menuItems.length; ++i) {
        const item = menuItems[i];

        if (item.type === 'separator') {
            if (!compacted.length || compacted[compacted.length - 1].type === 'separator') {
                continue;
            }
        }

        compacted.push(item);
    }

    while (compacted.length && compacted[compacted.length - 1].type === 'separator') {
        compacted.pop();
    }

    return compacted;
}

function getFrameMenuPosition(e) {
    const frameRect = window.frameElement && window.frameElement.getBoundingClientRect ? window.frameElement.getBoundingClientRect() : { left: 0, top: 0 };
    return {
        left: typeof e.clientX === 'number' ? e.clientX + frameRect.left : 0,
        top: typeof e.clientY === 'number' ? e.clientY + frameRect.top : 0,
    };
}

function syncContextMenuSubmenuPosition($item) {
    if (!$item || !$item.length) {
        return;
    }

    const $subMenu = $item.children('.tree-menu').first();

    if (!$subMenu.length) {
        return;
    }

    const updatePlacement = () => {
        if (!$item[0] || !$subMenu[0]) {
            return;
        }

        const itemRect = $item[0].getBoundingClientRect();
        const subMenuRect = $subMenu[0].getBoundingClientRect();
        const viewportWidth = (top && top.window && top.window.innerWidth) || window.innerWidth || document.documentElement.clientWidth || 0;
        const shouldOpenLeft = itemRect.right + subMenuRect.width + 8 > viewportWidth;

        $subMenu.css({
            left: shouldOpenLeft ? '-4px' : 'auto',
            right: shouldOpenLeft ? 'auto' : '-4px',
            top: '-5px',
            transform: shouldOpenLeft ? 'translate(-100%, 0)' : 'translate(100%, 0)',
        });
    };

    if (typeof ResizeObserver !== 'undefined') {
        if ($subMenu[0].vsfileResizeObserver) {
            $subMenu[0].vsfileResizeObserver.disconnect();
        }

        const observer = new ResizeObserver(() => updatePlacement());
        observer.observe($subMenu[0]);
        $subMenu[0].vsfileResizeObserver = observer;
    }

    updatePlacement();
}

function setStatusLangText(statusElement, langPath, text) {
    const safeLangPath = langPath || '';
    statusElement.textContent = safeLangPath ? getLangTextByPath(safeLangPath) : text || '';
    return safeLangPath;
}

function fillLanguageOptions(select) {
    const $select = $(select).empty();

    for (let i = 0; i < top.global.langs.length; ++i) {
        const langItem = top.global.langs[i];
        $select.append(`<option value="${langItem.id}">${langItem.language}</option>`);
    }

    $select.val(getCurrentLanguage());
    return $select;
}

function renderPath(path, options) {
    const settings = Object.assign({
        selector: '#global-path',
        mode: 'file',
        onRootClick: null,
        onSegmentClick: null,
    }, options || {});

    const wrap = $(settings.selector).empty();

    if (!wrap.length) {
        return '';
    }

    const safePath = normalizePath(path);
    const config = top.global.config || {};
    const userinfo = top.global.data.userinfo || {};
    const windowsComputerRoot = config.platform === 'windows' && userinfo.base_root === true;
    const isDriveName = part => /^[a-zA-Z]:$/.test(part || '');
    const parts = safePath ? safePath.split('/') : [];
    const rootFiletype = $(`<li class="global-path-filetype ${windowsComputerRoot ? 'filetype-computer' : 'filetype-folder'}"></li>`);
    const rootName = $(`<li class="global-path-item global-path-item-root-path" data-lang="${windowsComputerRoot ? 'common.my_computer' : 'common.root'}" data-lang-title="${windowsComputerRoot ? 'common.my_computer_title' : 'common.root_title'}"></li>`);

    if (typeof settings.onRootClick === 'function') {
        rootName.on('click', function () {
            settings.onRootClick();
        });

        rootFiletype.on('click', function () {
            settings.onRootClick();
        });
    }

    wrap.append(rootFiletype);
    wrap.append(rootName);

    if (settings.mode === 'folder') {
        for (let i = 0; i < parts.length; ++i) {
            wrap.append('<li class="global-path-separator">&gt;</li>');
            const iconType = windowsComputerRoot && i === 0 && isDriveName(parts[i]) ? 'disk' : 'folder';
            const pathFiletype = $(`<li class="global-path-filetype filetype-${iconType}"></li>`);

            const pathName = $(`<li class="global-path-item">${parts[i]}</li>`);
            const isLast = i === parts.length - 1;

            if (!isLast && typeof settings.onSegmentClick === 'function') {
                pathName.on('click', function () {
                    settings.onSegmentClick(parts.slice(0, i + 1).join('/'), i, parts.slice());
                });

                pathFiletype.on('click', function () {
                    settings.onSegmentClick(parts.slice(0, i + 1).join('/'), i, parts.slice());
                });
            }

            wrap.append(pathFiletype);
            wrap.append(pathName);
        }

        return safePath;
    }

    for (let i = 0; i < parts.length - 1; ++i) {
        if (!parts[i]) {
            continue;
        }

        wrap.append('<li class="global-path-separator">&gt;</li>');
        const iconType = windowsComputerRoot && i === 0 && isDriveName(parts[i]) ? 'disk' : 'folder';
        wrap.append(`<li class="global-path-filetype filetype-${iconType}"></li>`);
        wrap.append(`<li class="global-path-item">${parts[i]}</li>`);
    }

    const file = parts.length ? parts[parts.length - 1] : '';

    if (file) {
        const ext = file.includes('.') ? file.split('.').pop().toLowerCase() : 'null';
        wrap.append('<li class="global-path-separator">&gt;</li>');
        wrap.append(`<li class="global-path-filetype filetype-${fileType(ext)}"></li>`);
        wrap.append(`<li class="global-path-item">${file}</li>`);
    }

    return safePath;
}

function escapeHtml(text) {
    return String(text || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function getCurrentUsername() {
    return String(top.global && top.global.data && top.global.data.userinfo ? top.global.data.userinfo.username || '' : '');
}

function ignoreAutoFillPassword() {
    $('body').prepend('<input class="ignore-autofill-password" type="password" tabindex="-1" aria-hidden="true" />');
}

function isImage(filename) {
    const ext = filename.split('.').pop().toLowerCase();
    const type = fileType(ext);
    return ['png'].includes(type) || ['svg'].includes(ext);
}

function nullish(value, defaultValue) {
    return value === null || value === undefined ? defaultValue : value;
}
</script><!----- FILE js/global.js END ----->
<!----- FILE js/help.js START -----><script>
const tab = top.global.tab;
const contentId = $(frameElement).data('id');
const content = top.global.content['content-' + contentId];
const helpContent = $('.help-content');
const helpSidebar = $('.help-sidebar');
const helpScrollBar = new ScrollBar(helpContent[0], { barWidth: 8 });
const helpSidebarScrollBar = new ScrollBar(helpSidebar[0], { barWidth: 8 });
let headingItems = [];
let activeTargetId = '';

tab.changeTab(contentId, { unlock: false });
tab.renderTabs();

function escapeHelpHtml(value) {
    return String(value || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function renderInlineMarkdown(value) {
    let text = escapeHelpHtml(value);
    text = text.replace(/`([^`]+)`/g, '<code>$1</code>');
    text = text.replace(/\[([^\]]+)\]\(((?:https?:\/\/|mailto:)[^\s)]+)\)/g, function (match, label, url) {
        const isExternal = /^https?:\/\//i.test(url);
        return '<a href="' + url + '"' + (isExternal ? ' target="_blank" rel="noopener noreferrer"' : '') + '>' + label + '</a>';
    });
    return text;
}

function parseHelpMarkdown(markdown) {
    const lines = String(markdown || '').replace(/\r\n?/g, '\n').split('\n');
    const html = [];
    let listType = '';

    function closeList() {
        if (listType) {
            html.push('</' + listType + '>');
            listType = '';
        }
    }

    for (let index = 0; index < lines.length; ++index) {
        const line = lines[index].trim();
        let match = null;

        if (!line) {
            closeList();
            continue;
        }

        match = line.match(/^<h([12])\b([^>]*)>(.*?)<\/h\1>$/i);
        if (match) {
            closeList();
            const tag = 'h' + match[1];
            const attrs = String(match[2] || '');
            const idMatch = attrs.match(/\bid=["']?([0-9a-z_-]+)["']?/i);
            const classMatch = attrs.match(/\bclass=["']([^"']+)["']/i);
            const id = idMatch ? idMatch[1] : '';
            const className = classMatch ? classMatch[1].trim() : '';
            const tagAttrs = id ? ' id="' + id + '"' : '';
            const classAttr = className ? ' class="' + className + '"' : '';
            const headingText = id === 'version' && !match[3].trim() ? getLangTextByPath('short_title') + ' V' + top.global.version : match[3];
            html.push('<' + tag + tagAttrs + classAttr + '>' + renderInlineMarkdown(headingText) + '</' + tag + '>');
            continue;
        }

        match = line.match(/^(#{1,2})\s+(.+)$/);
        if (match) {
            closeList();
            const level = match[1].length;
            const id = 'section-' + index;
            html.push('<h' + level + ' id="' + id + '">' + renderInlineMarkdown(match[2]) + '</h' + level + '>');
            continue;
        }

        match = line.match(/^[-*]\s+(.+)$/);
        if (match) {
            if (listType !== 'ul') {
                closeList();
                listType = 'ul';
                html.push('<ul>');
            }
            html.push('<li>' + renderInlineMarkdown(match[1]) + '</li>');
            continue;
        }

        match = line.match(/^\d+[.)]\s+(.+)$/);
        if (match) {
            if (listType !== 'ol') {
                closeList();
                listType = 'ol';
                html.push('<ol>');
            }
            html.push('<li>' + renderInlineMarkdown(match[1]) + '</li>');
            continue;
        }

        closeList();
        html.push('<p>' + renderInlineMarkdown(line) + '</p>');
    }

    closeList();
    return html.join('');
}

function filterAdminOnlyContent() {
    const root = $('.help-document')[0];
    const isAdmin = !!(top.global.data.userinfo && top.global.data.userinfo.admin === true);

    if (!root || isAdmin) {
        return;
    }

    const headings = Array.prototype.slice.call(root.querySelectorAll('h1, h2'));

    headings.forEach(function (heading) {
        if (!heading.classList || !heading.classList.contains('admin')) {
            return;
        }

        const level = parseInt(String(heading.tagName || '').replace(/^H/i, ''), 10) || 1;
        let current = heading.nextSibling;

        while (current) {
            if (current.nodeType === 1 && /^H[12]$/i.test(current.tagName)) {
                const nextLevel = parseInt(String(current.tagName || '').replace(/^H/i, ''), 10) || 1;
                if (nextLevel <= level) {
                    break;
                }
            }

            const next = current.nextSibling;
            current.parentNode.removeChild(current);
            current = next;
        }

        heading.parentNode.removeChild(heading);
    });
}

function renderHelpToc() {
    const toc = $('.help-toc').empty();
    headingItems = [];
    let currentGroup = null;

    $('.help-document').find('h1, h2').each(function () {
        const heading = $(this);
        const item = {
            id: String(heading.attr('id') || ''),
            level: this.tagName.toLowerCase() === 'h1' ? 1 : 2,
            text: heading.text(),
            element: this,
        };

        if (!item.id) {
            return;
        }

        headingItems.push(item);
        const escapedText = escapeHelpHtml(item.text);

        if (item.level === 1) {
            currentGroup = $('<div class="help-toc-group"></div>');
            currentGroup.append(`<a class="help-toc-item level-1" href="#${item.id}" data-target="${item.id}" aria-expanded="true" title="${escapedText}"><span class="help-toc-item-text">${escapedText}</span><span class="help-toc-arrow" aria-hidden="true">▼</span></a>`);
            currentGroup.append('<div class="help-toc-children"></div>');
            toc.append(currentGroup);
        } else if (currentGroup) {
            currentGroup.find('.help-toc-children').append(`<a class="help-toc-item level-2" href="#${item.id}" data-target="${item.id}" title="${escapedText}">${escapedText}</a>`);
        }
    });

    const title = headingItems.length ? headingItems[0].text : '';
    document.title = title;
    toc.find('.help-toc-item').first().addClass('active');
}

function scrollToHelpTarget(targetId) {
    const target = document.getElementById(String(targetId || '').replace(/^#/, ''));

    if (!target) {
        return false;
    }

    const tocItem = $(`.help-toc-item[data-target="${target.id}"]`);
    const group = tocItem.closest('.help-toc-group');
    activeTargetId = target.id;
    group.removeClass('collapsed');
    group.find('.help-toc-item.level-1').attr('aria-expanded', 'true');
    helpContent.scrollTop(target.offsetTop - 20);
    helpContent.trigger('scroll');
    $('.help-toc-item').removeClass('active');
    tocItem.addClass('active');
    return true;
}

async function loadHelpDocument() {
    const language = getCurrentLanguage();
    const markdown = await ajax({
        url: `?f=help/${language}.md`,
        type: 'GET',
        dataType: 'text',
        cache: false,
    });

    if (typeof markdown !== 'string') {
        throw new Error('Failed to load help document.');
    }

    $('.help-document').html(parseHelpMarkdown(markdown));
    filterAdminOnlyContent();
    renderHelpToc();
    $('.help-page').addClass('loaded');
    helpContent.scrollTop(0);
    helpScrollBar.render();
    helpSidebarScrollBar.render();
    content.target && scrollToHelpTarget(content.target);
}

function updateActiveHeading() {
    const scrollTop = helpContent.scrollTop();
    let activeId = activeTargetId || (headingItems.length ? headingItems[0].id : '');

    if (!activeTargetId) {
        for (let index = 0; index < headingItems.length; ++index) {
            if (headingItems[index].element.offsetTop <= scrollTop + 40) {
                activeId = headingItems[index].id;
            } else {
                break;
            }
        }
    }

    $('.help-toc-item').removeClass('active');
    $(`.help-toc-item[data-target="${activeId}"]`).addClass('active');
}

function toggleHelpTocGroup(item) {
    const group = item.closest('.help-toc-group');

    if (!group || !item.hasClass('level-1')) {
        return false;
    }

    const collapsed = group.hasClass('collapsed');
    group.toggleClass('collapsed', !collapsed);
    item.attr('aria-expanded', String(!collapsed));
    return true;
}

$(document).on('click', '.help-toc-item.level-1', function (event) {
    const item = $(this);
    const target = document.getElementById(String(item.data('target') || ''));
    const isArrowClick = $(event.target).closest('.help-toc-arrow').length > 0;

    if (isArrowClick) {
        event.preventDefault();
        toggleHelpTocGroup(item);
        return;
    }

    event.preventDefault();

    if (target) {
        scrollToHelpTarget(target.id);
    }
});

$(document).on('dblclick', '.help-toc-item.level-1', function (event) {
    event.preventDefault();
    toggleHelpTocGroup($(this));
});

$(document).on('click', '.help-toc-item.level-2', function (event) {
    event.preventDefault();
    const item = $(this);
    const target = document.getElementById(String(item.data('target') || ''));

    if (target) {
        scrollToHelpTarget(target.id);
    }
});

$('.help-content').on('scroll', updateActiveHeading);

$('.help-content').on('wheel touchstart pointerdown', function () {
    activeTargetId = '';
});

$(document).on('keydown', function (event) {
    if (['ArrowUp', 'ArrowDown', 'PageUp', 'PageDown', 'Home', 'End', ' '].indexOf(event.key) !== -1) {
        activeTargetId = '';
    }
});

content.renderLang = async function () {
    await loadHelpDocument();
};

content.showHelpTarget = function (target) {
    content.target = target;
    return scrollToHelpTarget(target);
};

content.show = function () {
    if (!content.target) {
        return;
    }

    requestAnimationFrame(function () {
        scrollToHelpTarget(content.target);
    });
};

loadHelpDocument().catch(function () {
    $('.help-loading').text('Failed to load help document.');
});
</script><!----- FILE js/help.js END ----->
<!----- FILE js/image.js START -----><script>
const id = $(frameElement).data('id');
const tab = top.global.tab;
const content = top.global.content['content-' + id];
const stage = document.getElementById('image-stage');
const image = document.getElementById('image');
const status = document.getElementById('image-status');
const scaleInput = document.getElementById('image-scale');
const toolbar = document.querySelector('.image-toolbar');
const openEditorButton = toolbar.querySelector('.image-toolbar-button-open-editor');
const isSvgImage = /\.svg$/i.test(content.path || '');

let imageUrl = '';
let scale = 1;
let rotation = 0;
let flipX = 1;
let flipY = 1;
let offsetX = 0;
let offsetY = 0;
let inverted = false;
let dragging = false;
let dragStartX = 0;
let dragStartY = 0;
let dragOffsetX = 0;
let dragOffsetY = 0;
let statusLangPath = '';

document.title = content.path.split('/').pop();
openEditorButton.hidden = !isSvgImage;
renderPath(content.path);

image.addEventListener('load', function () {
    stage.classList.add('loaded');
    statusLangPath = setStatusLangText(status);
    fitImage();
});

image.addEventListener('error', function () {
    stage.classList.remove('loaded');
    statusLangPath = setStatusLangText(status, 'image.load_failed');
});

stage.addEventListener('pointerdown', function (event) {
    if (!stage.classList.contains('loaded') || event.button > 0) {
        return;
    }

    event.preventDefault();
    dragging = true;
    dragStartX = event.clientX;
    dragStartY = event.clientY;
    dragOffsetX = offsetX;
    dragOffsetY = offsetY;
    stage.classList.add('dragging');
    stage.setPointerCapture(event.pointerId);
});

stage.addEventListener('pointermove', function (event) {
    if (!dragging) {
        return;
    }

    offsetX = dragOffsetX + event.clientX - dragStartX;
    offsetY = dragOffsetY + event.clientY - dragStartY;
    renderImage();
});

stage.addEventListener('pointerup', stopDragging);
stage.addEventListener('pointercancel', stopDragging);
stage.addEventListener('wheel', function (event) {
    if (!stage.classList.contains('loaded')) {
        return;
    }

    event.preventDefault();
    zoom(event.deltaY < 0 ? 1.1 : 1 / 1.1);
}, { passive: false });

scaleInput.addEventListener('input', function () {
    if (scaleInput.value === '') {
        return;
    }

    const percentage = Math.min(Math.max(Number(scaleInput.value), 5), 2000);

    if (!Number.isFinite(percentage)) {
        return;
    }

    scale = percentage / 100;
    scaleInput.value = Math.round(percentage);
    renderImage();
});

scaleInput.addEventListener('blur', renderScaleInput);
scaleInput.addEventListener('keydown', function (event) {
    if (event.key === 'Enter') {
        scaleInput.blur();
    }
});

toolbar.addEventListener('click', function (event) {
    const button = event.target.closest('button[data-action]');

    if (!button || !stage.classList.contains('loaded')) {
        return;
    }

    switch (button.dataset.action) {
        case 'zoom-in':
            zoom(1.2);
            break;
        case 'zoom-out':
            zoom(1 / 1.2);
            break;
        case 'rotate-left':
            rotation -= 90;
            renderImage();
            break;
        case 'rotate-right':
            rotation += 90;
            renderImage();
            break;
        case 'flip-horizontal':
            flipX *= -1;
            renderImage();
            break;
        case 'flip-vertical':
            flipY *= -1;
            renderImage();
            break;
        case 'invert':
            inverted = !inverted;
            button.classList.toggle('active', inverted);
            renderImage();
            break;
        case 'fit':
            fitImage();
            break;
        case 'open-editor':
            openImageWithEditor();
            break;
    }
});

content.renderLang = async function () {
    await renderLang();
    renderPath(content.path);
    statusLangPath && (status.textContent = getLangTextByPath(statusLangPath));
};

loadImage();
renderLang();

function stopDragging(event) {
    if (!dragging) {
        return;
    }

    dragging = false;
    stage.classList.remove('dragging');
    stage.hasPointerCapture(event.pointerId) && stage.releasePointerCapture(event.pointerId);
}

function zoom(multiplier) {
    scale = Math.min(Math.max(scale * multiplier, 0.05), 20);
    renderImage();
}

function fitImage() {
    const rotated = Math.abs(rotation % 180) === 90;
    const width = rotated ? image.naturalHeight : image.naturalWidth;
    const height = rotated ? image.naturalWidth : image.naturalHeight;
    scale = Math.min(stage.clientWidth / width, stage.clientHeight / height, 1);
    offsetX = 0;
    offsetY = 0;
    renderImage();
}

function renderImage() {
    image.style.transform = `translate(calc(-50% + ${offsetX}px), calc(-50% + ${offsetY}px)) rotate(${rotation}deg) scale(${scale * flipX}, ${scale * flipY})`;
    image.style.filter = inverted ? 'invert(1)' : 'none';
    renderScaleInput();
}

function renderScaleInput() {
    scaleInput.value = Math.round(scale * 100);
}

function openImageWithEditor() {
    tab.changeTab(id, { unlock: false });
    const openTab = tab.findTab({ path: content.path, url: '?f=html/editor.html' });

    if (openTab) {
        tab.showTab(openTab.id);
    } else {
        const newTab = tab.addTab({ type: 'file', path: content.path, url: '?f=html/editor.html' }, 'after_current');
        tab.showTab(newTab.id);
    }

    tab.renderTabs();
}

function show() {
    loadImage();
    renderLang();
}

async function loadImage() {
    statusLangPath = setStatusLangText(status, 'image.loading');

    try {
        const response = await fetch('?a=image', {
            method: 'POST',
            body: JSON.stringify({ path: content.path }),
        });
        const contentType = response.headers.get('Content-Type') || '';

        if (!response.ok || !contentType.startsWith('image/')) {
            const result = contentType.includes('application/json') ? await response.json() : null;

            if (result && result.code) {
                throw { langPath: 'common.error.' + errorCode(result.code) };
            }

            throw { langPath: 'image.load_failed' };
        }

        const blob = await response.blob();
        imageUrl = URL.createObjectURL(blob);
        image.src = imageUrl;
    } catch (error) {
        statusLangPath = setStatusLangText(status, error.langPath || 'image.load_failed');
    }
}

$(document).on('click contextmenu', function () {
    top.global.tree.blur();
});

$(window).on('unload', function () {
    imageUrl && URL.revokeObjectURL(imageUrl);
});

content.show = show;
</script><!----- FILE js/image.js END ----->
<!----- FILE js/login.js START -----><script>
async function init() {
    loadConfig();
    await renderLang();
    renderLangSelect();
}

init();

$(document).on('click', '.login-submit', function () {
    login();
});

$(window).on('keydown', function (e) {
    if (e.key === 'Enter') {
        login();
    }
});

$(document).on('change', '.login-toolbar-language-list', async function () {
    const lang = $(this).val();
    const localConfig = getLocalConfig();
    localConfig.lang = lang;
    setLocalConfig(localConfig);
    await renderLang();
    renderLangSelect();
});

async function login() {
    const username = $('.login-username-text').val();
    const password = $('.login-password-text').val();
    const totp = $('.login-totp-text').val();

    if (!username) {
        error('login.username_empty');
        return;
    }

    if (!password) {
        error('login.password_empty');
        return;
    }

    if (totp && /^([0-9]{6})$/.test(totp) === false) {
        error('login.totp_invalid');
        return;
    }

    const { code } = await ajax({
        url: '?a=login',
        data: JSON.stringify({
            username: username,
            password: password,
            totp: totp
        })
    });

    code ? error(code) : (window.location.href = window.location.pathname);
}

function renderLangSelect() {
    $('.login-toolbar-language-name').text(getLangById(getCurrentLanguage()).language);
    fillLanguageOptions($('.login-toolbar-language-list'));
}

function openDialog(params) {
    const dialog = $('.login-dialog');
    dialog.find('.login-dialog-text-1').data('lang', params.text_1 || '').data('lang-args', JSON.stringify(params.text_1_args || '[]'));
    dialog.find('.login-dialog-text-2').data('lang', params.text_2 || '').data('lang-args', JSON.stringify(params.text_2_args || '[]'));
    dialog.find('.login-dialog-icon').removeClass().addClass('login-dialog-icon login-dialog-icon-' + (params.type ? params.type : 'info'));
    const buttons = dialog.find('.login-dialog-buttons').empty();

    if (params.buttons) {
        for (let i = params.buttons.length - 1; i >= 0; --i) {
            const button = params.buttons[i];
            const btn = $(`<div class="login-dialog-button login-dialog-button-${i}"></div `);
            btn.data('lang', button.label || '').data('lang-args', JSON.stringify(button.labelArgs || '[]'));

            btn.on('click', function () {
                typeof button.onClick === 'function' && button.onClick();
            });

            buttons.append(btn);
        }
    }

    renderLang();
    dialog.show();
}

function closeDialog() {
    $('.login-dialog').hide();
}

function error(err) {
    typeof err === 'number' && (err = 'common.error.' + errorCode(err));
    openDialog({ type: 'error', text_1: err, buttons: [{ label: 'common.ok', onClick: closeDialog }] });
}
</script><!----- FILE js/login.js END ----->
<!----- FILE js/navi.js START -----><script>
const tab = top.global.tab;

async function init() {
    await renderLang();
    renderLangSelect();
}

init();

async function loadUserInfo() {
    const userinfo = await ajax({ url: '?a=userinfo', type: 'GET' });
    top.global.data.userinfo = userinfo.data;
    renderUserInfo();
}

loadUserInfo();

$(document).on('click', function (e) {
    const target = e.target || e.srcElement;
    const insideSearch = target && $(target).closest('.navi-search, .navi-search-input, .navi-search-button').length;

    typeof top.global.tree.blur === 'function' && top.global.tree.blur();

    if (!insideSearch && typeof top.global.navi.searchInputBlur === 'function') {
        top.global.navi.searchInputBlur();
    }
});

$(top.document).on('change', '.navi-language-list', async function () {
    const lang = $(this).val();
    const localConfig = getLocalConfig();
    localConfig.lang = lang;
    setLocalConfig(localConfig);
    await renderLang();
    renderLangSelect();

    top.global.frame.renderLang();
    top.global.tree.renderLang();
    top.global.tab.renderLang();

    for (const key in top.global.content) {
        if (typeof top.global.content[key].renderLang === 'function') {
            top.global.content[key].renderLang();
        }
    }
});

$(top.document).on('mouseover', '.navi-language-list', async function () {
    $('.navi-language').addClass('hover');
});

$(top.document).on('mouseout', '.navi-language-list', async function () {
    $('.navi-language').removeClass('hover');
});

$(document).on('click', '.navi-user, .navi-current-user-username', function (e) {
    e.stopPropagation();
    const openTab = tab.findTab({ url: '?f=html/userinfo.html' });

    if (openTab) {
        tab.showTab(openTab.id);
    } else {
        const newTab = tab.addTab({ type: 'userinfo', url: '?f=html/userinfo.html', unlock: false }, 'after_current');
        tab.showTab(newTab.id);
    }

    tab.renderTabs();
    return false;
});

$(document).on('click', '.navi-config', function (e) {
    e.stopPropagation();

    if (!top.global.data.userinfo || top.global.data.userinfo.admin !== true) {
        return false;
    }

    const openTab = tab.findTab({ url: '?f=html/config.html' });

    if (openTab) {
        tab.showTab(openTab.id);
    } else {
        const newTab = tab.addTab({ type: 'config', url: '?f=html/config.html', unlock: false }, 'after_current');
        tab.showTab(newTab.id);
    }

    tab.renderTabs();
    return false;
});

$(document).on('submit', '.navi-search', function (e) {
    e.preventDefault();
    const query = $('.navi-search-input').val().trim();

    if (!query) {
        $('.navi-search-input').focus();
        return false;
    }

    const currentTab = tab.findTab({ current: true });
    const searchRoot = currentTab && ['home', 'folder'].includes(currentTab.type) ? (currentTab.path || '') : '';
    const newTab = tab.addTab({
        type: 'search',
        name: 'navi.search_results',
        path: '',
        searchRoot: searchRoot,
        query: query,
        searchResults: [],
        searchComplete: false,
        url: '?f=html/folder.html',
        unlock: false,
    }, 'after_current');
    tab.showTab(newTab.id);
    tab.renderTabs();
    return false;
});

$(document).on('click', '.navi-logout', function () {
    top.global.frame.openDialog({
        type: 'warning',
        text_1: 'navi.dialog.logout_confirm_text_1',
        text_2: 'navi.dialog.logout_confirm_text_2',
        buttons: [{
            label: 'navi.dialog.ok',
            onClick: async function () {
                top.location.href = '?a=logout';
            },
        }, {
            label: 'navi.dialog.cancel',
            onClick: async function () {
                top.global.frame.closeDialog();
            },
        }],
    })
});

$(document).on('keydown', async function (e) {
    const key = e.key.toLowerCase();

    if (e.key === 'Escape') {
        const search = $('.navi-search-input')[0];
        
        if (search && document.activeElement === search) {
            e.preventDefault();
            searchInputBlur();
            return false;
        }
    }

    if (e.ctrlKey && key === 's') {
        e.preventDefault();
        const { code } = await top.global.frame.saveContent();
        code && error(code);
    } else if (e.ctrlKey && key === 'r') {
        e.preventDefault();
        top.global.frame.resetTreeWidth();
    }
});

function renderUserInfo() {
    $('.navi-current-user-username').text(top.global.data.userinfo.username);
    top.global.data.userinfo.admin && $('.navi-config').show();
}

function renderLangSelect() {
    $('.navi-language').text(getLangById(getCurrentLanguage()).language);
    const select = $(top.document).find('.navi-language-list');
    const lang = $('.navi-language');
    select.css({ width: lang.width(), height: lang.height(), top: lang.position().top, left: lang.position().left });
    fillLanguageOptions(select);
}

function searchInputFocus() {
    const search = $('.navi-search-input');
    search.focus();
    search[0] && typeof search[0].select === 'function' && search[0].select();
}

function searchInputBlur() {
    const search = $('.navi-search-input');
    const input = search[0];

    if (!input || !document.activeElement || document.activeElement !== input) {
        return false;
    }

    input.blur();
    return true;
}

top.global.navi.document = document;
top.global.navi.searchInputFocus = searchInputFocus;
top.global.navi.searchInputBlur = searchInputBlur;
</script><!----- FILE js/navi.js END ----->
