        this.outerHeight = this.$outer.height();

        this.$outer.on('wheel', e => this.outerWheel(e));
        this.$outer.on('mouseover', e => this.outerMouseOver(e));
        this.$outer.on('mouseout', e => this.outerMouseOut(e));

        this.$scrollBar = $('<div class="scroll-bar"></div>');
        this.$scrollBar.on('mousedown', e => this.barMouseDown(e));
        $(window).on('mousemove', e => this.barMouseMove(e));
        $(window).on('mouseup', e => this.barMouseUp(e));
        this.$outer.after(this.$scrollBar);

        this.$scrollBarBg = $('<div class="scroll-bar-bg"></div>');
        this.$scrollBarBg.on('click', e => this.barBgClick(e));
        this.$scrollBarBg.on('mouseover', e => this.outerMouseOver(e));
        this.$scrollBarBg.on('mouseout', e => this.outerMouseOut(e));
        this.$outer.after(this.$scrollBarBg);

        new MutationObserver(t => this.mutation(t)).observe(this.outer, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: ['style', 'class'],
        });

        new IntersectionObserver(() => this.resize()).observe(this.outer);
        new ResizeObserver(() => this.resize()).observe(this.outer);

        this.customEvents = [];
        this.setBarWidth(params.barWidth || 10);
        return this.render();
    }

    render() {
        this.innerHeight = this.$outer[0].scrollHeight;
        this.outerHeight = this.$outer.height();

        if (this.innerHeight <= this.outerHeight || !this.mouseOver) {
            return this.renderScrollBar({ visible: false, active: false });
        }

        const multiple = this.outerHeight / this.innerHeight;
        const newBarHeight = Math.max(this.outerHeight * multiple, 20);
        const newBarTop = (this.$outer[0].scrollTop / this.innerHeight) * this.outerHeight;

        this.renderScrollBar({
            top: newBarTop,
            height: newBarHeight,
            visible: true,
            active: false,
        });

        return this;
    }

    renderScrollBar(params) {
        typeof params.active !== 'undefined' && (this.scrollBarActive = params.active);
        typeof params.visible !== 'undefined' && (this.scrollBarVisible = params.visible);
        this.scrollBarActive ? this.$scrollBar.addClass('active') : this.$scrollBar.removeClass('active');
        this.scrollBarVisible ? this.$scrollBar.addClass('visible') : this.$scrollBar.removeClass('visible');

        if (typeof params.top === 'undefined' && typeof params.height === 'undefined') {
            return this;
        }

        if (params.top !== this.scrollBarTop || params.height !== this.scrollBarHeight) {
            this.$scrollBar.addClass('moving');
        } else {
            this.$scrollBar.removeClass('moving');
        }

        typeof params.height !== 'undefined' && (this.scrollBarHeight = params.height);
        typeof params.top !== 'undefined' && (this.scrollBarTop = params.top);

        const bottomLimit = this.$outer.height() - this.scrollBarHeight;
        this.scrollBarTop < 0 && (this.scrollBarTop = 0);
        this.scrollBarTop > bottomLimit && (this.scrollBarTop = bottomLimit);
        this.$scrollBar.css({ 'margin-top': this.scrollBarTop + 'px', height: this.scrollBarHeight + 'px', });
        return this;
    }

    outerWheel(e) {
        if (this.dragStartY >= 0) {
            return;
        }

        this.fromWheel1 = true;
        this.fromWheel2 = true;
        this.outer.scrollTop += e.deltaY;
        this.render();
        return this;
    }

    outerMouseOver(e) {
        if (this.fromWheel1 || this.dragStartY >= 0) {
            this.fromWheel1 = false;
            return;
        }

        this.mouseOver = true;
        this.render();
        return this;
    }

    outerMouseOut(e) {
        if (this.fromWheel2 || this.dragStartY >= 0) {
            this.fromWheel2 = false;
            return;
        }

        this.mouseOver = false;
        this.render();
        return this;
    }

    mutation(mutations) {
        if (this.dragStartY >= 0) {
            return;
        }

        for (let i = 0; i < mutations.length; ++i) {
            const mutation = mutations[i];

            if (mutation.type === 'childList') {
                return this.render();
            }

            if (mutation.type === 'attributes') {
                if (mutation.attributeName === 'style' || mutation.attributeName === 'class') {
                    return this.render();
                }
            }
        }

        return this;
    }

    resize() {
        if (this.dragStartY >= 0) {
            return;
        }

        this.$scrollBar.addClass('moving').css({
            top: this.$outer.offset().top,
            left: this.$outer.offset().left + this.$outer.width() - this.barWidth,
        });

        this.$scrollBarBg.css({
            top: this.$outer.offset().top,
            left: this.$outer.offset().left + this.$outer.width() - this.barWidth,
            height: this.$outer.height() + 'px',
        });

        this.outerHeight = this.$outer.height();
        requestAnimationFrame(() => this.$scrollBar.removeClass('moving'));
    }

    barMouseDown(e) {
        e.preventDefault();
        this.dragStartY = e.clientY;
        this.dragStartBarTop = this.scrollBarTop;
    }

    barMouseMove(e) {
        e.preventDefault();

        if (this.dragStartY === -1) {
            return;
        }

        const deltaY = e.clientY - this.dragStartY;

        this.renderScrollBar({
            top: this.dragStartBarTop + deltaY,
            active: true,
        });

        this.outer.scrollTop = this.scrollBarTop * (this.innerHeight - this.outerHeight) / (this.outerHeight - this.scrollBarHeight);
        const events = this.customEvents.filter(c => c.event === 'drag');

        for (let i = 0; i < events.length; ++i) {
            events[i].handler.bind(this)();
        }

        return this;
    }

    barMouseUp(e) {
        e.preventDefault();

        if (this.dragStartY === -1) {
            return;
        }

        this.dragStartY = -1;
    }

    barBgClick(e) {
        e.preventDefault();
        this.renderScrollBar({ top: e.clientY - this.$scrollBarBg.offset().top - (this.scrollBarHeight / 2) });
        this.outer.scrollTop = this.scrollBarTop * (this.innerHeight - this.outerHeight) / (this.outerHeight - this.scrollBarHeight);
        const events = this.customEvents.filter(c => c.event === 'bgclick');

        for (let i = 0; i < events.length; ++i) {
            events[i].handler.bind(this)();
        }

        return this;
    }

    on(event, handler) {
        if (typeof event !== 'string' || typeof handler !== 'function') {
            return this;
        }

        this.customEvents.push({ event: event, handler: handler });
        return this;
    }

    setBarWidth(width) {
        if (typeof width !== 'number' || width <= 0) {
            return this;
        }

        this.barWidth = width;

        this.$scrollBar.css({
            width: this.barWidth + 'px',
            left: this.$outer.offset().left + this.$outer.width() - this.barWidth,
        });

        this.$scrollBarBg.css({
            width: this.barWidth + 'px',
            left: this.$outer.offset().left + this.$outer.width() - this.barWidth,
        });

        return this;
    }

    scrollToElement(element) {
        if (!element) {
            return this;
        }

        const elTop = $(element).position().top;
        const elHeight = $(element).height();
        const viewTop = this.$outer.scrollTop();
        const viewHeight = this.$outer.height();

        if (elTop < viewTop) {
            this.$outer.scrollTop(elTop);
        } else if (elTop + elHeight > viewTop + viewHeight) {
            this.$outer.scrollTop(elTop + elHeight - viewHeight);
        }

        return this.render();
    }
}
</script><!----- FILE js/scrollbar.js END ----->
<!----- FILE js/tab.js START -----><script>
let tabIdAutoIncrement = 0;
let tabs = [];
addTab({ type: 'home', url: '?f=html/folder.html', name: '', path: '', unlock: false, current: true }, 'first');
showTab(1);
renderTabs();
renderLang();

$(document).on('wheel', function (e) {
    document.documentElement.scrollLeft += e.deltaY;
});

let clickTime = 0;

$(document).on('click', '.tabs .tab', function (e) {
    if ($(e.target).hasClass('tab-file-close')) {
        return true;
    }

    if (new Date().getTime() - clickTime < 300) {
        changeTab(+$(this).data('id'), { unlock: false });
        renderTabs();
        clickTime = 0;
        return;
    }

    clickTime = new Date().getTime();
    const id = +$(this).data('id');
    const index = tabs.findIndex(t => t.id === id);

    for (let i = 0; i < tabs.length; ++i) {
        tabs[i].current = (i === index);
    }

    showTab(id);
    renderTabs();
});

async function closeTabWithPrompt(id) {
    const tab = tabs.find(t => t.id === id);

    if (!tab || tab.type === 'home') {
        return false;
    }

    if (!tab.unsave) {
        removeTab(id);
        renderTabs();
        return true;
    }

    return await new Promise(resolve => {
        if (tab.type === 'userinfo' || tab.type === 'config') {
            top.global.frame.openDialog({
                text_1: 'tab.dialog.unsaved_close_text',
                type: 'warning',
                buttons: [{
                    label: 'tab.dialog.yes',
                    onClick: function () {
                        removeTab(id);
                        renderTabs();
                        top.global.frame.closeDialog();
                        resolve(true);
                    },
                }, {
                    label: 'tab.dialog.no',
                    onClick: function () {
                        top.global.frame.closeDialog();
                        resolve(false);
                    },
                }],
            });
            return;
        }

        top.global.frame.openDialog({
            text_1: 'tab.dialog.unsaved_text_1',
            text_1_args: [tab.path.split('/').pop()],
            text_2: 'tab.dialog.unsaved_text_2',
            type: 'warning',
            buttons: [{
                label: 'tab.dialog.save',
                onClick: async function () {
                    const { code } = await top.global.content['content-' + id].saveContent();

                    if (code) {
                        error(code);
                        return;
                    }

                    removeTab(id);
                    renderTabs();
                    top.global.frame.closeDialog();
                    resolve(true);
                },
            }, {
                label: 'tab.dialog.discard',
                onClick: function () {
                    removeTab(id);
                    renderTabs();
                    top.global.frame.closeDialog();
                    resolve(true);
                },
            }, {
                label: 'tab.dialog.cancel',
                onClick: function () {
                    top.global.frame.closeDialog();
                    resolve(false);
                },
            }],
        });
    });
}

$(document).on('click', '.tabs .tab .tab-file-close', function () {
    const id = +$(this).parents('.tab').data('id');
    closeTabWithPrompt(id);
});

function getCurrentTab() {
    return tabs.find(t => t.current) || tabs[1] || null;
}

function getTabIndexById(id) {
    return tabs.findIndex(t => t.id === id);
}

function isMainTab(tab) {
    return !tab || tab.type === 'home' || tab.id === tabs[0].id;
}

function getNormalTabIds() {
    return tabs.slice(1).map(tab => tab.id);
}

function closeSavedTabs() {
    const ids = tabs.slice(1).filter(tab => !tab.unsave).map(tab => tab.id);

    for (let i = ids.length - 1; i >= 0; --i) {
        removeTab(ids[i]);
    }

    renderTabs();
    return true;
}

async function closeAllTabs() {
    const ids = getNormalTabIds();

    for (let i = 0; i < ids.length; ++i) {
        const tab = tabs.find(item => item.id === ids[i]);

        if (!tab) {
            continue;
        }

        if (!tab.unsave) {
            removeTab(tab.id);
            continue;
        }

        const result = await closeTabWithPrompt(tab.id);
        if (!result) {
            break;
        }
    }

    renderTabs();
    return true;
}

async function closeOtherTabs(id) {
    const targetIndex = getTabIndexById(id);

    if (targetIndex < 1) {
        return false;
    }

    const ids = tabs
        .filter(tab => tab.id !== id && tab.type !== 'home')
        .map(tab => tab.id);

    for (let i = 0; i < ids.length; ++i) {
        const tab = tabs.find(item => item.id === ids[i]);

        if (!tab) {
            continue;
        }

        if (!tab.unsave) {
            removeTab(tab.id);
            continue;
        }

        const result = await closeTabWithPrompt(tab.id);

        if (!result) {
            break;
        }
    }

    renderTabs();
    return true;
}

async function closeTabsOnSide(id, side) {
    const targetIndex = getTabIndexById(id);

    if (targetIndex < 1) {
        return false;
    }

    const ids = [];

    for (let i = 1; i < tabs.length; ++i) {
        if (side === 'left' && i < targetIndex) {
            ids.push(tabs[i].id);
        } else if (side === 'right' && i > targetIndex) {
            ids.push(tabs[i].id);
        }
    }

    for (let i = 0; i < ids.length; ++i) {
        const tab = tabs.find(item => item.id === ids[i]);

        if (!tab) {
            continue;
        }

        if (!tab.unsave) {
            removeTab(tab.id);
            continue;
        }

        const result = await closeTabWithPrompt(tab.id);
        if (!result) {
            break;
        }
    }

    renderTabs();
    return true;
}

function openTabContextMenu(e, tab, blankArea) {
    e.preventDefault();

    const menu = $(top.document).find('.tree-menu-main').empty();
    const items = [];
    const currentTab = tab || getCurrentTab();
    const targetId = currentTab ? currentTab.id : null;
    const isBlankMenu = !!blankArea;

    if (isBlankMenu) {
        items.push({ name: 'close_saved', action: 'close-saved', disabled: !tabs.slice(1).some(item => !item.unsave) });
        items.push({ name: 'close_all', action: 'close-all', disabled: tabs.length <= 1 });
    } else if (!currentTab || isMainTab(currentTab)) {
        items.push({ name: 'close_saved', action: 'close-saved', disabled: !tabs.slice(1).some(item => !item.unsave) });
        items.push({ name: 'close_all', action: 'close-all', disabled: tabs.length <= 1 });
    } else {
        const currentIndex = getTabIndexById(currentTab.id);
        items.push({ name: 'close', action: 'close', hotkey: 'Ctrl+F4', disabled: isMainTab(currentTab) });
        items.push({ name: 'close_others', action: 'close-others', disabled: tabs.filter(item => item.type !== 'home').length <= 1 });
        items.push({ name: 'close_left', action: 'close-left', disabled: currentIndex <= 1 });
        items.push({ name: 'close_right', action: 'close-right', disabled: currentIndex >= tabs.length - 1 });
        items.push({ name: 'close_saved', action: 'close-saved', disabled: !tabs.slice(1).some(item => !item.unsave) });
        items.push({ name: 'close_all', action: 'close-all', disabled: tabs.length <= 1 });
    }

    for (let i = 0; i < items.length; ++i) {
        const item = items[i];
        const $item = $(`<li class="tree-menu-item tree-menu-tab-${item.action}${item.disabled ? ' tree-menu-item-disabled' : ''}" data-tab-action="${item.action}" data-tab-id="${targetId || ''}"></li>`);
        $item.append(`<span data-lang="tab.menu.${item.name}"></span>`);

        if (item.hotkey) {
            $item.append(`<span class="tree-menu-hotkey">${item.hotkey}</span>`);
        }

        menu.append($item);
    }

    const $menu = $(top.document).find('.tree-menu-main');
    const position = getFrameMenuPosition(e);
    const menuLeft = position.left;
    const menuTop = e.clientY + 41;
    $menu.css({ top: menuTop + 'px', left: menuLeft + 'px', opacity: 0 }).show();
    renderLang();
    top.global.frame.renderLang();

    requestAnimationFrame(() => {
        const rect = $menu[0].getBoundingClientRect();
        const viewportWidth = top.window.innerWidth;
        const viewportHeight = top.window.innerHeight;
        const left = menuLeft + rect.width > viewportWidth ? Math.max(0, menuLeft - rect.width) : menuLeft;
        const topPosition = menuTop + rect.height > viewportHeight ? Math.max(0, menuTop - rect.height) : menuTop;
        $menu.css({ left: left + 'px', top: topPosition + 'px', opacity: 1 });
    });
}

$(document).on('contextmenu', function (e) {
    const target = e.target || e.srcElement;
    if (target && ($(target).is('input, textarea, select') || $(target).closest('input, textarea, select').length)) {
        return true;
    }

    if ($(e.target).closest('.tree-menu-main, .tree-menu').length) {
        return true;
    }

    if ($(e.target).closest('.tab').length) {
        const id = +$(e.target).closest('.tab').data('id');
        const tab = tabs.find(item => item.id === id);
        openTabContextMenu(e, tab || null);
        return false;
    }

    if ($(e.target).closest('.tab-page').length) {
        openTabContextMenu(e, null, true);
        return false;
    }

    $(top.document).find('.tree-menu').css({ opacity: 0 }).hide();
    return false;
});

$(document).on('click', function (e) {
    if ($(e.target).closest('.tab, .tabs, .tree-menu-main, .tree-menu').length) {
        return;
    }

    $(top.document).find('.tree-menu').css({ opacity: 0 }).hide();
});

$(top.document).on('click', '.tree-menu-item[data-tab-action]', function () {
    const action = $(this).data('tab-action');
    const targetId = +$(this).data('tab-id');
    const target = Number.isFinite(targetId) && targetId > 0 ? tabs.find(item => item.id === targetId) : getCurrentTab();

    if (action === 'close-saved') {
        closeSavedTabs();
    } else if (action === 'close-all') {
        closeAllTabs();
    } else if (action === 'close' && target) {
        closeTabWithPrompt(target.id);
    } else if (action === 'close-others' && target) {
        closeOtherTabs(target.id);
    } else if (action === 'close-left' && target) {
        closeTabsOnSide(target.id, 'left');
    } else if (action === 'close-right' && target) {
        closeTabsOnSide(target.id, 'right');
    }

    $(top.document).find('.tree-menu').css({ opacity: 0 }).hide();
});

let dragTarget = -1;
let moveTarget = -1;

$(document).on('dragstart', '.tabs .tab', function (e) {
    e.dataTransfer.effectAllowed = 'move';
    const id = +$(this).data('id');
    moveTarget = tabs.findIndex(t => t.id === id);
});

$(document).on('dragover', function (e) {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    const tabs = $('.tabs .tab');
    let overIndex = -1;
    let middleX = 0;

    for (let i = 0; i < tabs.length; ++i) {
        const D = $(tabs[i]);
        const L = D.position().left;
        const R = L + D.width();

        if (e.pageX >= L && e.pageX <= R) {
            overIndex = i;
            middleX = (L + R) / 2;
            break;
        }
    }

    overIndex < 0 && (overIndex = tabs.length - 1);
    dragTarget = e.pageX < middleX ? overIndex : overIndex + 1;
    dragTarget < 1 && (dragTarget = 1);
    $('.tabs .tab').removeClass('drag-target').eq(dragTarget - 1).addClass('drag-target');
});

$(document).on('dragend', function () {
    if (moveTarget === dragTarget || moveTarget === dragTarget - 1) {
        dragTarget = -1;
        moveTarget = -1;

        for (let i = 0; i < tabs.length; ++i) {
            tabs[i].drag_target = false;
        }

        return;
    }

    const movedTab = tabs.splice(moveTarget, 1)[0];

    if (moveTarget < dragTarget) {
        tabs.splice(dragTarget - 1, 0, movedTab);
    } else {
        tabs.splice(dragTarget, 0, movedTab);
    }

    for (let i = 0; i < tabs.length; ++i) {
        tabs[i].drag_target = false;
        tabs[i].unlock = false;
    }

    renderTabs();
    dragTarget = -1;
    moveTarget = -1;
});

$(document).on('keydown', async function (e) {
    const key = e.key.toLowerCase();

    if (e.ctrlKey && key === 's') {
        e.preventDefault();
        const { code } = await top.global.frame.saveContent();
        code && error(code);
    } else if (e.ctrlKey && key === 'r') {
        e.preventDefault();
        top.global.frame.resetTreeWidth();
    }
});

function renderTabs() {
    const tabsContainer = $('.tabs').empty();
    const tabHomeClass = ['tab', 'tab-home'];
    tabs[0].current && tabHomeClass.push('current');
    tabsContainer.append(`<li class="${tabHomeClass.join(' ')}" data-id="1" data-lang-title="tab.home"></li>`);

    for (let i = 1; i < tabs.length; ++i) {
        const tabClass = ['tab'];
        tabs[i].current && tabClass.push('current');
        tabs[i].drag_target && tabClass.push('drag-target');
        tabs[i].unsave && tabClass.push('unsave');
        tabs[i].unlock && tabClass.push('unlock');

        if (tabs[i].type === 'userinfo') {
            tabsContainer.append(`
                <li class="${tabClass.join(' ')}" draggable="true" data-id="${tabs[i].id}" data-lang-title="userinfo.group_userinfo">
                    <div class="tab-filetype tab-filetype-userinfo"></div>
                    <div class="tab-file-name" data-lang="userinfo.group_userinfo"></div>
                    <div class="tab-file-close" data-lang-title="tab.close"></div>
                    <div class="tab-file-unsave"></div>
                </li>
            `);
        } else if (tabs[i].type === 'config') {
            tabsContainer.append(`
                <li class="${tabClass.join(' ')}" draggable="true" data-id="${tabs[i].id}" data-lang-title="config.group_config">
                    <div class="tab-filetype tab-filetype-config"></div>
                    <div class="tab-file-name" data-lang="config.group_config"></div>
                    <div class="tab-file-close" data-lang-title="tab.close"></div>
                    <div class="tab-file-unsave"></div>
                </li>
            `);
        } else if (tabs[i].type === 'help') {
            tabsContainer.append(`
                <li class="${tabClass.join(' ')}" draggable="true" data-id="${tabs[i].id}" data-lang-title="navi.help">
                    <div class="tab-filetype tab-filetype-help"></div>
                    <div class="tab-file-name" data-lang="navi.help"></div>
                    <div class="tab-file-close" data-lang-title="tab.close"></div>
                    <div class="tab-file-unsave"></div>
                </li>
            `);
        } else if (tabs[i].type === 'search') {
            tabsContainer.append(`
                <li class="${tabClass.join(' ')}" draggable="true" data-id="${tabs[i].id}" data-lang-title="navi.search_results">
                    <div class="tab-filetype tab-filetype-search"></div>
                    <div class="tab-file-name" data-lang="navi.search_results"></div>
                    <div class="tab-file-close" data-lang-title="tab.close"></div>
                    <div class="tab-file-unsave"></div>
                </li>
            `);
        } else if (tabs[i].type === 'folder' && normalizePath(tabs[i].path) === '') {
            const windowsComputerRoot = top.global.config.platform === 'windows' && top.global.data.userinfo.base_root === true;
            const rootLang = windowsComputerRoot ? 'common.my_computer' : 'common.root';

            tabsContainer.append(`
                <li class="${tabClass.join(' ')}" draggable="true" data-id="${tabs[i].id}" data-lang-title="${rootLang}_title">
                    <div class="tab-filetype filetype-${windowsComputerRoot ? 'computer' : 'folder'}"></div>
                    <div class="tab-file-name" data-lang="${rootLang}"></div>
                    <div class="tab-file-close" data-lang-title="tab.close"></div>
                    <div class="tab-file-unsave"></div>
                </li>
            `);
        } else {
            const type = tabs[i].type === 'folder' ? 'folder' : tabs[i].path.split('.').pop().toLowerCase();
            const filename = tabs[i].path.split('/').pop();
            const filePath = top.global.config.platform === 'windows' && /^([A-Z]):/.test(tabs[i].path) ? tabs[i].path.replace(/\//g, '\\') : '/' + tabs[i].path;

            tabsContainer.append(`
                <li class="${tabClass.join(' ')}" draggable="true" data-id="${tabs[i].id}" title="${filePath}">
                    <div class="tab-filetype filetype-${fileType(type)}"></div>
                    <div class="tab-file-name">${filename}</div>
                    <div class="tab-file-close" data-lang-title="tab.close"></div>
                    <div class="tab-file-unsave"></div>
                </li>
            `);
        }
    }

    renderLang();
}

function addTab(tab, position) {
    position = position || 'last';

    const newTab = Object.assign({}, {
        id: ++tabIdAutoIncrement,
        current: false,
        drag_target: false,
        unsave: false,
        unlock: true,
        type: 'file',
    }, tab);

    if (position === 'first') {
        tabs.splice(1, 0, newTab);
    } else if (position === 'before_current') {
        const currentIndex = tabs.findIndex(t => t.current);
        tabs.splice(currentIndex, 0, newTab);
    } else if (position === 'after_current') {
        const currentIndex = tabs.findIndex(t => t.current);
        tabs.splice(currentIndex + 1, 0, newTab);
    } else {
        tabs.push(newTab);
    }

    tabs = tabs.filter(t => !t.unlock || t.id === newTab.id);
    top.global.frame.addContent(newTab);
    return newTab;
}

function findTab(params) {
    for (let i = 0; i < tabs.length; ++i) {
        const tab = tabs[i];
        let match = true;

        for (const key in params) {
            if (tab[key] !== params[key]) {
                match = false;
                break;
            }
        }

        if (match) {
            return tab;
        }
    }

    return false;
}

function showTab(id) {
    for (let i = 0; i < tabs.length; ++i) {
        tabs[i].current = (tabs[i].id === id);
    }

    top.global.frame.showContent(id);

    requestAnimationFrame(() => {
        const tab = $(`.tabs .tab[data-id="${id}"]`)[0];

        if (!tab) {
            return false;
        }

        tab.scrollIntoView();
    });

    return true;
}

function changeTab(id, params) {
    const index = tabs.findIndex(t => t.id === id);

    if (index < 0) {
        return false;
    }

    tabs[index] = Object.assign(tabs[index], params);
    return true;
}

function removeTab(id) {
    if (id < 1) {
        return false;
    }

    const index = tabs.findIndex(t => t.id === id);

    if (index < 1) {
        return false;
    }

    const removedTab = tabs.splice(index, 1);

    if (removedTab.length && removedTab[0].current) {
        tabs[index - 1].current = true;
        showTab(tabs[index - 1].id);
    }

    top.global.frame.removeContent(id);
    return true;
}

top.global.tab.document = document;
top.global.tab.addTab = addTab;
top.global.tab.findTab = findTab;
top.global.tab.showTab = showTab;
top.global.tab.changeTab = changeTab;
top.global.tab.removeTab = removeTab;
top.global.tab.renderTabs = renderTabs;
top.global.tab.renderLang = renderLang;
