<!----- FILE js/tree.js START -----><script>
class Node {
    constructor(params) {
        this.$ = null;
        this.$bg = null;
        this.change = [];

        const properties = {
            new: false,
            dir: '',
            name: '',
            type: 'folder',
            path: '',
            open: false,
            disk: false,
            mine: true,
            link: false,
            readonly: false,
            mode: '',
            hover: false,
            rename: false,
            parent: null,
            active: false,
            current: false,
            selected: false,
            nameError: false,
            iconBlobUrl: null,
            children: [],
            clickTime: Date.now(),
        };

        const setMethods = {
            name: value => {
                const parentPath = this.parent ? this.parent.path : '';
                const separator = parentPath.includes('\\') ? '\\' : '/';
                properties.path = parentPath ? parentPath + separator + value : value;
            },
            active: value => {
                value && setNodeStatusAll({ active: false });
            },
            rename: value => {
                value && (this.active = false);
            },
            parent: value => {
                const separator = value.path.includes('\\') ? '\\' : '/';
                properties.path = value.path ? value.path + separator + this.name : this.name;
            },
        };

        let renderPending = false;

        for (const k in properties) {
            Object.defineProperty(this, k, {
                get: () => properties[k],
                set: value => {
                    if (value === properties[k]) {
                        return;
                    }

                    setMethods[k] && setMethods[k](value);
                    properties[k] = value;
                    this.change.includes(k) || this.change.push(k);

                    if (k === 'children') {
                        requestAnimationFrame(() => this.renderFolder());
                        return;
                    }

                    if (this === root || renderPending) {
                        return;
                    }

                    renderPending = true;
                    requestAnimationFrame(() => {
                        this.render();
                        renderPending = false;
                    });
                }
            });
        }

        Object.assign(this, params);
        return this;
    }

    fileType() {
        return this.type === 'folder' ? 'folder' : fileType(this.name.split('.').pop().toLowerCase());
    }

    isImage() {
        return ['png', 'svg'].includes(this.fileType());
    }

    isVideo() {
        return ['mp4'].includes(this.fileType());
    }

    isAudio() {
        return ['mp3'].includes(this.fileType());
    }

    isChessText() {
        return ['pfc', 'pgn'].includes(this.fileType());
    }

    isExecutable() {
        return ['exe'].includes(this.fileType());
    }

    setCustomIcon($icon) {
        if (!$icon || !$icon.length) {
            return this;
        }

        const url = this.iconBlobUrl ? `url(${this.iconBlobUrl})` : '';
        $icon[0].style.setProperty('background-image', url, 'important');
        $icon[0].style.setProperty('background-size', 'contain', 'important');
        $icon[0].style.setProperty('background-repeat', 'no-repeat', 'important');
        $icon[0].style.setProperty('background-position', 'center center', 'important');
        return this;
    }

    clearCustomIcon($icon) {
        if (!$icon || !$icon.length) {
            return this;
        }

        $icon[0].style.removeProperty('background-image');
        $icon[0].style.removeProperty('background-size');
        $icon[0].style.removeProperty('background-repeat');
        $icon[0].style.removeProperty('background-position');
        return this;
    }

    async loadIcon() {
        if (!this.isExecutable()) {
            return this;
        }

        if (this.iconBlobUrl) {
            return this;
        }

        const xhr = new XMLHttpRequest();
        xhr.responseType = 'arraybuffer';
        xhr.open('POST', '?a=icon', true);

        xhr.onload = () => {
            if (xhr.status !== 200 || !xhr.response) {
                return;
            }

            const contentType = xhr.getResponseHeader('Content-Type') || 'image/vnd.microsoft.icon';

            if (!contentType.startsWith('image/')) {
                return;
            }

            if (this.iconBlobUrl) {
                URL.revokeObjectURL(this.iconBlobUrl);
            }

            this.iconBlobUrl = URL.createObjectURL(new Blob([xhr.response], { type: contentType }));

            if (this.$) {
                const $icon = this.$.find('.tree-item-icon').first();
                this.setCustomIcon($icon);
            }
        };

        xhr.onerror = () => { };
        xhr.send(JSON.stringify({ path: this.path }));
        return this;
    }

    renderBg() {
        this.$bg && this.$bg.remove();
        const classes = ['file-bg'];
        this.hover && classes.push('file-bg-hover');

        if (!this.new) {
            this.active && classes.push('file-bg-active');
            this.current && classes.push('file-bg-current');
            this.selected && classes.push('file-bg-selected');
        }

        if (classes.length > 1) {
            const offsetTop = this.$.offset().top + treeRoot.scrollTop - 40;
            this.$bg = $(`<div class="${classes.join(' ')}" style="top: ${offsetTop}px;"></div>`);
            $treeRoot.append(this.$bg);
        }

        return this;
    }

    render() {
        const renderBg = ['new', 'rename', 'hover', 'active', 'current', 'selected'];

        if (this.change.find(c => renderBg.includes(c))) {
            this.renderBg();
        }

        const simple = ['hover', 'active', 'current', 'selected', 'nameError', 'clickTime'];
        const notSimple = this.change.find(c => !simple.includes(c));

        if (this.$ && !notSimple) {
            this.change.length = 0;
            renderLang();
            return this;
        }

        const isFolder = this.type === 'folder';
        const itemType = isFolder ? 'folder' : 'file';
        const $new = $('<li class="tree-item"></li>');

        const $line = $(`<div class="tree-item-line tree-item-${itemType}" title="${this.name}"></div>`);
        this.open && $line.addClass('tree-item-folder-open');
        this.disk && $line.addClass('tree-item-disk');
        !this.mine && $line.addClass('tree-item-not-mine');
        this.link && $line.addClass('tree-item-link');
        $new.append($line);

        $line.append('<span class="tree-item-switch"></span>');
        const ext = isFolder ? 'folder' : this.name.includes('.') ? this.name.split('.').pop().toLowerCase() : 'null';
        const $icon = $(`<span class="tree-item-icon filetype-${fileType(ext)}"></span>`);

        if (!isFolder && ['exe', 'com'].includes(ext)) {
            this.iconBlobUrl ? this.setCustomIcon($icon) : this.clearCustomIcon($icon);
            this.loadIcon();
        } else {
            this.clearCustomIcon($icon);
        }

        $line.append($icon);

        if (this.new || this.rename) {
            const $name = $(`<input class="tree-item-name-input" type="text" value="${this.name}" spellcheck="false" />`);
            $name.on('mousedown click dblclick', function (e) {
                if ($(e.target).is('input, textarea, select')) {
                    return true;
                }
                e.stopPropagation();
                return false;
            });
            $name.on('keydown', e => this.keyDownNameInput(e));
            $name.on('input', e => this.inputNameInput(e));
            $name.on('blur', e => this.blurNameInput(e));
            $line.append($name);
        } else {
            $line.append(`<span class="tree-item-name">${this.disk ? `<span data-lang="tree.local_disk"></span>(${this.name})` : this.name}</span>`);
        }

        isFolder && $line.on('click', e => this.clickFolder(e));
        isFolder || $line.on('click', e => this.clickFile(e));
        isFolder || $line.on('dblclick', e => this.dblclickFile(e));
        $line.on('contextmenu', e => this.contextmenu(e));
        $line.on('mouseover', e => this.mouseover(e));
        $line.on('mouseout', e => this.mouseout(e));

        if (this.$) {
            $new.append(this.$.children('.tree-list'));
            this.$.replaceWith($new);
        } else {
            isFolder && $new.append('<ul class="tree-list"></ul>');
            const index = this.parent.children.indexOf(this);
            const $parent = this.parent.$.children('.tree-list');
            const siblings = $parent.children();
            index >= siblings.length ? $parent.append($new) : siblings.eq(index).before($new);
        }

        if (this.new || this.rename) {
            const dotIndex = this.name.lastIndexOf('.');
            const end = dotIndex > 0 ? dotIndex : this.name.length;
            $new.find('.tree-item-name-input').focus()[0].setSelectionRange(0, end);
        }

        this.$ = $new;
        this.change.length = 0;
        renderLang();
        return this;
    }

    changeName() {
        this.rename = true;
        return this;
    }

    remove() {
        this.$bg && this.$bg.remove();
        this.$bg = null;
        this.$.remove();
        this.parent.children.remove(this);
        openFolders.remove(this.path);
        return this;
    }

    renderFolder() {
        this.$.children('.tree-list').empty();
        this.$.find('.file-bg').remove();
        return this;
    }

    async loadFolder() {
        isRecursiveCall() || (fetchFoldersCache = {});
        this.open = true;
        const response = await fetchFolders(this) || await ajax({ url: '?a=dir', data: JSON.stringify({ path: this.path || '' }) });
        const folderData = response && response.data !== undefined ? response.data : [];
        const folder = Array.isArray(folderData) ? folderData : Array.isArray(folderData.items) ? folderData.items : [];
        const code = response && response.code;

        if (code) {
            error(code);
            return;
        }

        clearTreeBranchState(this);
        this.children = [];

        for (let i = 0; i < folder.length; ++i) {
            const item = folder[i];
            const props = parseProperty(item.property);
            const child = new Node({
                name: item.name,
                type: item.type,
                disk: props.disk,
                mine: props.mine,
                link: props.link,
                readonly: props.readonly,
                mode: item.mode,
                parent: this,
            });

            this.children.push(child);
            openFolders.includes(child.path) && await child.loadFolder();
        }

        return this;
    }

    openFile() {
        if (this.isImage()) {
            this.openFileWith('image');
            return this;
        }

        if (this.isVideo()) {
            this.openFileWith('video');
            return this;
        }

        if (this.isAudio()) {
            this.openFileWith('audio');
            return this;
        }

        if (CodeMirror.findModeByFileName(this.name) || this.isChessText()) {
            this.openFileWith('editor');
            return this;
        }

        this.downloadFile();
        return this;
    }

    openFileWith(type) {
        if (!['editor', 'image', 'video', 'audio'].includes(type)) {
            return this;
        }

        const openTab = tab.findTab({ path: this.path, url: `?f=html/${type}.html` });

        if (openTab) {
            tab.showTab(openTab.id);
        } else {
            const newTab = tab.addTab({ type: 'file', path: this.path, url: `?f=html/${type}.html` }, 'after_current');
            tab.showTab(newTab.id);
        }

        tab.renderTabs();
        return this;
    }

    async downloadFile() {
        const { code, data } = await ajax({ url: '?a=download', data: JSON.stringify({ path: this.path, timeout: 60 }) });
        code ? error(code) : (window.location.href = `?d=${data.token}`);
    }

    async fetchDownloadUrl() {
        const { code, data } = await ajax({ url: '?a=download', data: JSON.stringify({ path: this.path, timeout: 300 }) });

        if (code) {
            error(code);
            return this;
        }

        const downloadUrl = `${window.location.origin}${window.location.pathname}?d=${data.token}`;

        top.global.frame.openDialog({
            type: 'success',
            text_1: 'tree.dialog.fetch_download_url_success',
            text_2: downloadUrl,
            buttons: [{
                label: 'tree.dialog.copy',
                onClick: function () {
                    top.global.frame.copy(downloadUrl);
                    top.global.frame.closeDialog();

                    top.global.frame.openDialog({
                        type: 'success',
                        text_1: 'tree.dialog.copy_success',
                        buttons: [{
                            label: 'common.ok',
                            onClick: function () {
                                top.global.frame.closeDialog();
                            },
                        }],
                    });
                },
            }, {
                label: 'common.ok',
                onClick: function () {
                    top.global.frame.closeDialog();
                },
            }],
        });
    }

    openFolder(withNewTab) {
        if (withNewTab) {
            const newTab = tab.addTab({ type: 'folder', path: this.path, url: '?f=html/folder.html' }, 'after_current');
            tab.showTab(newTab.id);
            tab.renderTabs();
            return this;
        }

        const openTab = tab.findTab({ path: this.path });

        if (openTab) {
            tab.showTab(openTab.id);
        } else {
            tab.changeTab(1, { path: this.path });
            tab.showTab(1);
        }

        tab.renderTabs();
        return this;
    }

    fixDblClick() {
        const flag = Date.now() - this.clickTime < 300;
        this.clickTime = Date.now();
        return flag;
    }

    async clickFolder(e) {
        const target = e.target || e.srcElement;
        if (target && $(target).is('input, textarea, select')) {
            return true;
        }

        e.cancelBubble = true;
        e.stopPropagation();
        e.preventDefault();

        if (this.fixDblClick() || this.new || this.rename) {
            return;
        }

        if (!e.ctrlKey) {
            this.open = !this.open;

            if (this.open) {
                await this.loadFolder();
                openFolders.includes(this.path) || openFolders.push(this.path);
            } else {
                clearTreeBranchState(this);
                this.children = [];
                openFolders.remove(this.path);
            }
        }

        if (e.ctrlKey) {
            setNodeStatusAll({ current: false });
            this.current = true;
            this.selected = !this.selected;
        } else if (!$(e.target).hasClass('tree-item-switch')) {
            setNodeStatusAll({ current: false, selected: false });
            this.current = true;
            this.selected = true;
            this.openFolder();
            tab.renderTabs();
        }

        this.active = true;
        closeMenu();
        return false;
    }

    clickFile(e) {
        const target = e.target || e.srcElement;
        if (target && $(target).is('input, textarea, select')) {
            return true;
        }

        e.cancelBubble = true;
        e.stopPropagation();
        e.preventDefault();

        if (this.fixDblClick()) {
            return;
        }

        setNodeStatusAll({ current: false });
        e.ctrlKey || this.openFile();
        e.ctrlKey || setNodeStatusAll({ selected: false });
        this.current = true;
        this.selected = !this.selected;
        this.active = true;
        closeMenu();
        return false;
    }

    dblclickFile() {
        const mode = CodeMirror.findModeByFileName(this.name);

        if (!mode) {
