        return false;
    }

    contextmenu(e) {
        const target = e.target || e.srcElement;
        if (target && $(target).is('input, textarea, select')) {
            return true;
        }

        e.cancelBubble = true;
        e.stopPropagation();
        e.preventDefault();
        const selected = getNodeByStatusAll({ selected: true });
        selected.length > 1 || selected.includes(this) || setNodeStatusAll({ selected: false });
        this.active = true;
        openContextMenu(e, this.type);
        return false;
    }

    mouseover() {
        if (menuVisible) {
            return;
        }

        setNodeStatusAll({ hover: false });
        this.hover = true;
        return true;
    }

    mouseout() {
        if (menuVisible) {
            return;
        }

        this.hover = false;
        return true;
    }

    keyDownNameInput(e) {
        if (e.key === 'Enter' || e.key === 'Escape') {
            this.$.find('.tree-item-name-input').trigger('blur');
        }

        return true;
    }

    inputNameInput() {
        if (!this.new && !this.rename) {
            return;
        }

        const $input = this.$.find('.tree-item-name-input');
        const newName = $input.removeClass("error warning").val().trim();
        this.nameError = false;
        $('.tree-item-name-input-error').remove();

        const siblingNames = this.parent.children.filter(t => t !== this).map(t => t.name);
        const error = checkValidFilename(newName, siblingNames);

        if (error.level === 'success') {
            return;
        }

        $input.addClass(error.level);
        this.nameError = error.level;

        const errorTips = $(`<div class="tree-item-name-input-error ${error.level}" data-lang="tree.error.${error.type}"></div>`);
        errorTips.data('lang-args', JSON.stringify([`<span class="filename">${newName}</span>`]));
        const offset = $input.offset();
        errorTips.css({ top: (offset.top + 23) + 'px', left: offset.left + 'px', right: '0px' });
        $('body').append(errorTips);

        renderLang();
        return true;
    }

    async blurNameInput() {
        if (!this || !this.new && !this.rename) {
            return;
        }

        $('.tree-item-name-input-error').remove();
        const newName = this.$.find('.tree-item-name-input').removeClass("error warning").val().trim();

        if (!newName || this.nameError || newName === this.name) {
            if (this.new) {
                this.remove();
            } else {
                this.rename = false;
            }

            return;
        }

        const newPath = this.parent.path ? this.parent.path + (this.parent.path.includes('\\') ? '\\' : '/') + newName : newName;

        if (this.new) {
            if (this.type === 'folder') {
                const { code } = await ajax({ url: '?a=mkdir', data: JSON.stringify({ path: newPath }) });
                code && error(code);
            } else {
                const formData = new FormData();
                formData.append('content', new Blob(['']));
                formData.append('path', newPath);
                const { code } = await ajax({ url: '?a=upload', data: formData, processData: false, contentType: false, dataType: 'json' });
                code && error(code);
            }
        } else {
            const { code } = await ajax({ url: '?a=move', data: JSON.stringify({ src: this.path, dst: newPath }) });

            if (code) {
                error(code);
            } else {
                const openTab = tab.findTab({ path: this.path });

                if (openTab) {
                    tab.changeTab(openTab.id, { path: newPath });
                    tab.renderTabs();
                    content.trigger(openTab.id, 'treeRename');
                }
            }
        }

        await this.parent.loadFolder();
        await syncDirectoryFromTree(this.parent.path);
        return true;
    }
}

const root = new Node({ type: 'folder', $: $('.tree-root') });
const tab = top.global.tab;
const content = top.global.frame;
const openFolders = [];
const $treeRoot = $('.tree-root');
const treeRoot = $treeRoot[0];

let menuVisible = false;
let openWithMenuVisible = false;
let fetchFoldersCache = {};

renderLang();
root.loadFolder();
const scrollbar = new ScrollBar(treeRoot);

$('.tree-title').on('click', function () {
    root.openFolder();
});

$(document).on('click', function (e) {
    const target = e.target || e.srcElement;
    if (target && $(target).is('input, textarea, select')) {
        return true;
    }

    blur();
    return true;
});

$(document).on('contextmenu', function (e) {
    const target = e.target || e.srcElement;
    if (target && $(target).is('input, textarea, select')) {
        return true;
    }

    e.preventDefault();
    setNodeStatusAll({ active: false });
    openContextMenu(e, 'root');
    return false;
});

$(document).on('keydown', async function (e) {
    const key = e.key.toLowerCase();
    const node = getNodeByStatus({ active: true });
    const readonly = isGlobalReadonly();

    if (e.ctrlKey && key === 's') {
        e.preventDefault();
        const { code } = await top.global.frame.saveContent();
        code && error(code);
    } else if (!readonly && e.ctrlKey && key === 'x' && node) {
        e.preventDefault();
        setClipboard('cut');
    } else if (!readonly && e.ctrlKey && key === 'c' && node) {
        e.preventDefault();
        setClipboard('copy');
    } else if (!readonly && e.ctrlKey && key === 'v') {
        e.preventDefault();
        await paste();
    } else if (e.ctrlKey && key === 'r') {
        e.preventDefault();
        top.global.frame.resetTreeWidth();
    } else if (e.shiftKey && e.altKey && key === 'c') {
        e.preventDefault();
        copyPath();
    } else if (!readonly && key === 'f2') {
        e.preventDefault();
        rename();
    } else if (key === 'f5') {
        e.preventDefault();
        refresh();
    } else if (!readonly && key === 'delete') {
        e.preventDefault();
        remove();
    }

    return false;
});

$(top.document).on('click', '.tree-menu-open-file', () => nodeTrigger('openFile'));
$(top.document).on('click', '.tree-menu-open-with-editor', () => nodeTrigger('openFileWith', 'editor'));
$(top.document).on('click', '.tree-menu-open-with-image', () => nodeTrigger('openFileWith', 'image'));
$(top.document).on('click', '.tree-menu-open-with-video', () => nodeTrigger('openFileWith', 'video'));
$(top.document).on('click', '.tree-menu-open-with-audio', () => nodeTrigger('openFileWith', 'audio'));
$(top.document).on('click', '.tree-menu-view-folder', () => nodeTrigger('openFolder'));
$(top.document).on('click', '.tree-menu-view-folder-new-tab', () => nodeTrigger('openFolder', true));
$(top.document).on('click', '.tree-menu-download', () => nodeTrigger('downloadFile'));
$(top.document).on('click', '.tree-menu-fetch-download-url', () => nodeTrigger('fetchDownloadUrl'));
$(top.document).on('click', '.tree-menu-cut', () => setClipboard('cut'));
$(top.document).on('click', '.tree-menu-copy', () => setClipboard('copy'));
$(top.document).on('click', '.tree-menu-paste', () => paste());
$(top.document).on('click', '.tree-menu-zip-archive', () => zipSelection());
$(top.document).on('click', '.tree-menu-tgz-archive', () => tgzSelection());
$(top.document).on('click', '.tree-menu-unzip-current', () => unzipSelection('current'));
$(top.document).on('click', '.tree-menu-unzip-folder', () => unzipSelection('folder'));
$(top.document).on('click', '.tree-menu-zip_archive', () => zipSelection());
$(top.document).on('click', '.tree-menu-tgz_archive', () => tgzSelection());
$(top.document).on('click', '.tree-menu-unzip_current', () => unzipSelection('current'));
$(top.document).on('click', '.tree-menu-unzip_folder', () => unzipSelection('folder'));
$(top.document).on('click', '.tree-menu-copy-path', () => copyPath());
$(top.document).on('click', '.tree-menu-rename', () => nodeTrigger('changeName'));
$(top.document).on('click', '.tree-menu-remove', () => remove());
$(top.document).on('click', '.tree-menu-refresh', () => refresh());
$(top.document).on('click', '.tree-menu-new-file', () => create('file'));
$(top.document).on('click', '.tree-menu-new-folder', () => create('folder'));

function getNodeByStatus(status, node) {
    node = node || root;
    let match = true;

    for (const key in status) {
        if (node[key] !== status[key]) {
            match = false;
            break;
        }
    }

    if (match) {
        return node;
    }

    for (let i = 0; i < node.children.length; ++i) {
        const found = getNodeByStatus(status, node.children[i]);

        if (found) {
            return found;
        }
    }

    return null;
}

function getNodeByStatusAll(status, node, files) {
    node = node || root;
    files = files || [];
    let match = true;

    for (const key in status) {
        if (node[key] !== status[key]) {
            match = false;
            break;
        }
    }

    match && files.push(node);

    for (let i = 0; i < node.children.length; ++i) {
        getNodeByStatusAll(status, node.children[i], files);
    }

    return files;
}

function setNodeStatusAll(status, node) {
    node = node || root;

    for (const key in status) {
        node[key] = status[key];
    }

    for (let i = 0; i < node.children.length; ++i) {
        setNodeStatusAll(status, node.children[i]);
    }
}

function clearTreeBranchState(node) {
    for (let i = 0; i < node.children.length; ++i) {
        const child = node.children[i];
        child.hover = false;
        child.active = false;
        child.current = false;
        child.selected = false;
        child.$bg && child.$bg.remove();
        child.$bg = null;
        clearTreeBranchState(child);
    }
}

function isWindowsComputerRoot(type) {
    const config = top.global.config || {};
    const userinfo = top.global.data.userinfo || {};
    if (config.platform !== 'windows' || userinfo.base_root !== true) {
        return false;
    }

    if (type === 'root') {
        return true;
    }

    const currentNode = getNodeByStatus({ current: true }) || getNodeByStatus({ active: true });
    return !!currentNode && normalizePath(currentNode.path) === '';
}

function getZipMenuItem(node) {
    const supported = isZipMenuSupported();
    const zipNode = isZipFileNode(node);
    const zipName = getZipArchiveBaseName(node && (node.path || node.name) ? (node.path || node.name) : '');
    const readonly = isGlobalReadonly();

    return {
        name: 'zip_unzip',
        hidden: !supported || readonly,
        submenu: [
            { name: 'zip-archive', action: () => zipSelection(), hidden: !isZipSupported() || readonly },
            { name: 'tgz-archive', action: () => tgzSelection(), hidden: !isTgzSupported() || readonly },
            { name: 'unzip-current', action: () => unzipSelection('current'), hidden: !zipNode || readonly },
            { name: 'unzip-folder', action: () => unzipSelection('folder'), hidden: !zipNode || readonly, langArgs: [zipName] },
        ],
    };
}

function getContextMenuActionNodes() {
    const node = getNodeByStatus({ active: true });

    if (!node || node === root) {
        return [];
    }

    const selected = node.selected ? getNodeByStatusAll({ selected: true }).filter(item => item !== root) : [];
    return selected.length ? selected : [node];
}

async function zipSelection() {
    if (isGlobalReadonly()) {
        closeMenu();
        return false;
    }
    const nodes = getContextMenuActionNodes();
    closeMenu();

    if (!nodes.length) {
        return false;
    }

    const src = nodes.map(item => item.path);
    const { code, data } = await requestZip(src.length === 1 ? src[0] : src);

    if (code) {
        error(code);
        return false;
    }

    const zipParentPath = getZipPathFromTarget({
        type: nodes[0] && nodes[0].type === 'folder' ? 'folder' : 'file',
        path: data && data.zip ? data.zip : nodes[0].path,
    });
    const parentNode = getNodeByStatus({ path: zipParentPath }) || root;

    await parentNode.loadFolder();
    await syncDirectoryFromTree(zipParentPath);
    return true;
}

async function tgzSelection() {
    if (isGlobalReadonly()) {
        closeMenu();
        return false;
    }
    const nodes = getContextMenuActionNodes();
    closeMenu();

    if (!nodes.length) {
        return false;
    }

    const src = nodes.map(item => item.path);
    const { code, data } = await requestTgz(src.length === 1 ? src[0] : src);

    if (code) {
        error(code);
        return false;
    }

    const tgzParentPath = getZipPathFromTarget({
        type: nodes[0] && nodes[0].type === 'folder' ? 'folder' : 'file',
        path: data && data.tgz ? data.tgz : nodes[0].path,
    });
    const parentNode = getNodeByStatus({ path: tgzParentPath }) || root;

    await parentNode.loadFolder();
    await syncDirectoryFromTree(tgzParentPath);
    return true;
}

async function unzipSelection(mode) {
    if (isGlobalReadonly()) {
        closeMenu();
        return false;
    }

    const node = getNodeByStatus({ active: true });
    closeMenu();

    if (!node || !isZipFileNode(node)) {
        return false;
    }

    const dst = mode === 'folder' ? getZipUnzipTargetPath(node, 'folder') : (mode === 'current' ? getZipUnzipTargetPath(node, 'current') : undefined);
    const action = isZipFilePath(node.path) && /\.(tgz|tar\.gz)$/i.test(node.path) ? requestUntgz : requestUnzip;
    const { code } = await action(node.path, dst);

    if (code) {
        error(code);
        return false;
    }

    const parentPath = node.parent ? node.parent.path : getParentPath(node.path);
    const parentNode = node.parent || getNodeByStatus({ path: parentPath }) || root;

    await parentNode.loadFolder();
    await syncDirectoryFromTree(parentPath);
    return true;
}

async function openContextMenu(e, type) {
    const pasteDisabled = !getClipboard();
    const menuMap = {
        folder: [
            { name: 'view-folder' },
            { name: 'view-folder-new-tab' },
            { name: 'new-file' },
            { name: 'new-folder' },
            { type: 'separator' },
            { name: 'refresh', hotkey: 'F5' },
            { type: 'separator' },
            { name: 'cut', hotkey: 'Ctrl+X' },
            { name: 'copy', hotkey: 'Ctrl+C' },
            { name: 'paste', hotkey: 'Ctrl+V', disabled: pasteDisabled },
            { type: 'separator' },
            getZipMenuItem(getNodeByStatus({ active: true }) || root),
            { type: 'separator' },
            { name: 'copy-path', hotkey: 'Shift+Alt+C' },
            { type: 'separator' },
            { name: 'rename', hotkey: 'F2' },
            { name: 'remove', hotkey: 'Delete' },
        ],
        root: [
            { name: 'new-file' },
            { name: 'new-folder' },
            { type: 'separator' },
            { name: 'refresh', hotkey: 'F5' },
            { type: 'separator' },
            { name: 'paste', hotkey: 'Ctrl+V', disabled: pasteDisabled },
        ],
        file: [
            { name: 'open-file' },
            {
                name: 'open-with',
                submenu: [
                    { name: 'open-with-editor' },
                    { name: 'open-with-image' },
                    { name: 'open-with-video' },
                    { name: 'open-with-audio' },
                ]
            },
            { name: 'download' },
            { name: 'fetch-download-url' },
            { type: 'separator' },
            getZipMenuItem(getNodeByStatus({ active: true }) || root),
            { type: 'separator' },
            { name: 'refresh', hotkey: 'F5' },
            { type: 'separator' },
            { name: 'cut', hotkey: 'Ctrl+X' },
            { name: 'copy', hotkey: 'Ctrl+C' },
            { name: 'paste', hotkey: 'Ctrl+V', disabled: pasteDisabled },
            { type: 'separator' },
            { name: 'copy-path', hotkey: 'Shift+Alt+C' },
            { type: 'separator' },
            { name: 'rename', hotkey: 'F2' },
            { name: 'remove', hotkey: 'Delete' },
        ],
    };

    const $menu = $(top.document).find('.tree-menu-main').empty();
    let menus = menuMap[type] || menuMap.file;

    if (isWindowsComputerRoot(type)) {
        menus = compactContextMenuSeparators(menus.filter(item => {
            if (item.hidden) {
                return false;
            }

            if (item.type === 'separator') {
                return true;
            }

            return !shouldHideContextActionOnWindowsComputerRoot(item.name);
        }));
    }

    if (isGlobalReadonly()) {
        menus = compactContextMenuSeparators(menus.filter(item => {
            if (item.hidden) {
                return false;
            }

            if (item.type === 'separator') {
                return true;
            }

            return !shouldHideContextActionOnReadonly(item.name);
        }));
    } else {
        menus = compactContextMenuSeparators(menus.filter(item => !item.hidden));
    }

    for (let i = 0; i < menus.length; ++i) {
        const params = menus[i];

        if (params.type === 'separator') {
            $menu.append(`<li class="tree-menu-separator"></li>`);
            continue;
        }

        const langArgs = params.langArgs ? ` data-lang-args='${JSON.stringify(params.langArgs).replace(/'/g, '&apos;')}'` : '';
        const name = `<span data-lang="tree.menu.${params.name.replace(/-/g, '_')}"${langArgs}></span>`;
        const hotkey = params.hotkey ? `<span class="tree-menu-hotkey">${params.hotkey}</span>` : '';
        const $menuItem = $(`<li class="tree-menu-item tree-menu-${params.name}">${name}${hotkey}</li>`);
        params.disabled && $menuItem.addClass('tree-menu-item-disabled');
        $menu.append($menuItem);

        if (!params.submenu || params.submenu.length <= 0) {
            continue;
        }

        $menuItem.append('<span class="tree-menu-submenu"></span>');
        const $subMenu = $(`<div class="tree-menu tree-menu-submenu-${params.name}"></div>`);
        $menuItem.append($subMenu);

        for (let j = 0; j < params.submenu.length; ++j) {
            const subParams = params.submenu[j];
            if (subParams.hidden) {
                continue;
            }

            const subLangArgs = subParams.langArgs ? ` data-lang-args='${JSON.stringify(subParams.langArgs).replace(/'/g, '&apos;')}'` : '';
            const subName = `<span data-lang="tree.menu.${subParams.name.replace(/-/g, '_')}"${subLangArgs}></span>`;
            const subHotkey = subParams.hotkey ? `<span class="tree-menu-hotkey">${subParams.hotkey}</span>` : '';
            $subMenu.append(`<li class="tree-menu-item tree-menu-${subParams.name}">${subName}${subHotkey}</li>`);
        }

        syncContextMenuSubmenuPosition($menuItem);
    }

    const menuElement = $menu[0];
    const layoutToken = {};
    const position = getFrameMenuPosition(e);
    const menuLeft = position.left;
    const menuTop = e.clientY + 41;
    menuElement.vsfileLayoutToken = layoutToken;
    $menu.css({ top: menuTop + 'px', left: menuLeft + 'px', opacity: 0 }).show();
    renderLang();
    setNodeStatusAll({ hover: false });
    await top.global.frame.renderLang();
    await new Promise(resolve => top.requestAnimationFrame(resolve));

    if (menuElement.vsfileLayoutToken !== layoutToken) {
        return;
    }

    const rect = menuElement.getBoundingClientRect();
    const viewportWidth = top.window.innerWidth;
    const viewportHeight = top.window.innerHeight;
    const left = menuLeft + rect.width > viewportWidth ? Math.max(0, menuLeft - rect.width) : menuLeft;
    const topPosition = menuTop + rect.height > viewportHeight ? Math.max(0, menuTop - rect.height) : menuTop;

    $menu.css({ left: left + 'px', top: topPosition + 'px', opacity: 1 });
    menuVisible = true;
}

function closeMenu() {
    menuVisible = false;
    const menu = $(top.document).find('.tree-menu-main')[0];
    menu && (menu.vsfileLayoutToken = null);
    $(top.document).find('.tree-menu').css({ opacity: 0 }).hide();
}

function blur() {
    setNodeStatusAll({ hover: false, current: false, selected: false, active: false });
    closeMenu();
}

function getClipboard() {
    try {
        const clipboard = getLocalConfig().clipboard;
        const validAction = clipboard && ['copy', 'cut'].includes(clipboard.action);
        const validFiles = clipboard && Array.isArray(clipboard.files) && clipboard.files.length > 0
            && clipboard.files.every(path => typeof path === 'string' && path !== '');
        return validAction && validFiles ? clipboard : null;
    } catch (error) {
        return null;
    }
}

function setClipboard(action) {
    if (isGlobalReadonly()) {
        return null;
    }

    const node = getNodeByStatus({ active: true });

    if (!node || node === root) {
        return null;
    }

    const selected = node.selected ? getNodeByStatusAll({ selected: true }).filter(item => item !== root) : [];
    const files = (selected.length ? selected : [node]).map(item => item.path);
    let config = {};

    try {
        config = getLocalConfig();
    } catch (error) {
        config = {};
    }

    if (!config || typeof config !== 'object' || Array.isArray(config)) {
        config = {};
    }

    config.clipboard = { action: action, files: files };
    setLocalConfig(config);
    closeMenu();
    return config.clipboard;
}

function updateCutClipboard(files) {
    let config = {};

    try {
        config = getLocalConfig();
    } catch (error) {
        config = {};
    }

    if (!config || typeof config !== 'object' || Array.isArray(config)) {
        config = {};
    }

    if (files.length) {
        config.clipboard = { action: 'cut', files: files };
    } else {
        delete config.clipboard;
    }

    setLocalConfig(config);
}

function clearClipboard() {
    let config = {};

    try {
        config = getLocalConfig();
    } catch (error) {
        config = {};
    }

    if (!config || typeof config !== 'object' || Array.isArray(config)) {
        config = {};
    }

    delete config.clipboard;
    setLocalConfig(config);
}

async function syncDirectoryFromTree(path) {
    if (top.global.frame && typeof top.global.frame.syncDirectory === 'function') {
        await top.global.frame.syncDirectory(path, { reloadTree: false });
    }
}

async function paste() {
    if (isGlobalReadonly()) {
        closeMenu();
        return false;
    }

    const clipboard = getClipboard();

    if (!clipboard) {
        closeMenu();
        return false;
    }

    const target = getNodeByStatus({ active: true }) || root;
    const directory = target.type === 'folder' ? target : target.parent || root;
    const files = clipboard.files.slice();
    const strategy = await resolvePasteStrategy(clipboard, directory.path);
    const changedDirsMap = {};
    const remaining = [];
    let completed = 0;
    closeMenu();

    changedDirsMap[directory.path] = true;

    if (!strategy) {
        return false;
    }

    for (; completed < files.length; ++completed) {
        const source = files[completed];
        const { code, data } = await ajax({
            url: '?a=paste',
            data: JSON.stringify({ src: source, target: directory.path, action: clipboard.action, strategy: strategy }),
        });

        if (code) {
            remaining.push(...files.slice(completed));
            error(code);
            break;
        }

        clipboard.action === 'cut' && data.source_exists && remaining.push(source);

        if (clipboard.action === 'cut' && !data.source_exists) {
            changedDirsMap[getParentPath(source)] = true;
        }
    }

    clearClipboard();
    await directory.loadFolder();

    const changedDirs = Object.keys(changedDirsMap);

    for (let i = 0; i < changedDirs.length; ++i) {
        await syncDirectoryFromTree(changedDirs[i]);
    }

    return completed === files.length && remaining.length === 0;
}

async function fetchFolders(node) {
    if (fetchFoldersCache[node.path]) {
        return fetchFoldersCache[node.path];
    }

    const fetchPromises = [];
    const fetchs = [...openFolders];
    fetchs.includes(node.path) || fetchs.unshift(node.path);

    for (let i = 0; i < fetchs.length; ++i) {
        const path = fetchs[i];

        if (!path.startsWith(node.path)) {
            continue;
        }

        fetchPromises.push(new Promise(async resolve => {
            fetchFoldersCache[path] = await ajax({ url: '?a=dir', data: JSON.stringify({ path: path || '' }) });
            resolve();
        }));
    }

    await Promise.all(fetchPromises);
    return fetchFoldersCache[node.path];
}

function nodeTrigger(funcName, arg1) {
    const node = getNodeByStatus({ active: true });
    node && typeof node[funcName] === 'function' && node[funcName](arg1);
    closeMenu();
}

async function copyPath() {
    const node = getNodeByStatus({ active: true }) || getNodeByStatus({ current: true });
    closeMenu();

    if (!node) {
        return false;
    }

    const isWindowsDrive = top.global.config.platform === 'windows' && /^([A-Z]):/i.test(node.path);
    const path = isWindowsDrive ? node.path.replace(/\//g, '\\') : '/' + node.path.replace(/^\/+/, '');

    try {
        await top.global.frame.copy(path);

        top.global.frame.openDialog({
            type: 'success',
            text_1: 'tree.dialog.copy_success',
            buttons: [{
                label: 'common.ok',
                onClick: function () {
                    top.global.frame.closeDialog();
                },
            }],
        });

        return true;
    } catch (error) {
        return false;
    }
}

async function create(type) {
    if (isGlobalReadonly()) {
        closeMenu();
        return false;
    }

    const target = getNodeByStatus({ active: true }) || root;
    const parent = target.type === 'folder' ? target : target.parent;
    closeMenu();

    parent.open || await parent.loadFolder();

    const node = new Node({
        name: '',
        type: type,
        new: true,
        parent: parent,
    });

    const firstFileIndex = parent.children.findIndex(t => t.type === type);
    const insertIndex = firstFileIndex === -1 ? parent.children.length : firstFileIndex;
    parent.children.splice(insertIndex, 0, node);
}

function rename() {
    if (isGlobalReadonly()) {
        closeMenu();
        return false;
    }

    const selected = getNodeByStatusAll({ selected: true }).filter(item => item !== root);
    const node = selected[0] || getNodeByStatus({ active: true });
    node && !node.new && !node.rename && (node.rename = true);
    closeMenu();
}

async function refresh() {
    const target = getNodeByStatus({ active: true }) || root;
    const node = target.type === 'folder' ? target : target.parent;
    closeMenu();
    await node.loadFolder();
    await syncDirectoryFromTree(node.path);
}

function remove() {
    if (isGlobalReadonly()) {
        closeMenu();
        return false;
    }

    const removeNode = getNodeByStatus({ active: true });
    closeMenu();

    if (!removeNode || removeNode === root) {
        return;
    }

    const selectedFiles = getNodeByStatusAll({ selected: true });
    const multi = selectedFiles.length > 1;

    top.global.frame.openDialog({
        type: 'warning',
        text_1: 'tree.dialog.remove_confirm_title' + (multi ? '_multiple' : ''),
        text_1_args: [multi ? '' : removeNode.name],
        text_2: 'tree.dialog.remove_confirm_text',
        buttons: [{
            label: 'common.ok',
            onClick: async function () {
                top.global.frame.closeDialog();
                const removeList = selectedFiles.length > 1 ? selectedFiles : [removeNode];
                const changedDirsMap = {};

                await Promise.all(removeList.map(async node => {
                    const { code } = await ajax({ url: '?a=remove', data: JSON.stringify({ path: node.path }) });

                    if (code) {
                        error(code);
                        return;
                    }

                    node.remove();
                    changedDirsMap[node.parent ? node.parent.path : ''] = true;
                    const removeTab = tab.findTab({ path: node.path });

                    if (removeTab) {
                        tab.removeTab(removeTab.id);
                        tab.renderTabs();
                    }
                }));

                const changedDirs = Object.keys(changedDirsMap);

                for (let i = 0; i < changedDirs.length; ++i) {
                    await syncDirectoryFromTree(changedDirs[i]);
                }
            },
        }, {
            label: 'common.cancel',
            onClick: function () {
                top.global.frame.closeDialog();
            },
        }],
    });
}

async function gotoPath(path) {
    if (!path) {
        return null;
    }

    const folders = path.replace(/\\/g, '/').split('/');
    openFolders.length = 0;

    for (let i = 0; i < folders.length; ++i) {
        const folderPath = folders.slice(0, i + 1).join('/');
        openFolders.push(folderPath);
    }

    await root.loadFolder();
    const targetNode = getNodeByStatus({ path: path });

    targetNode && requestAnimationFrame(() => {
        targetNode.active = true;
        scrollbar.scrollToElement(targetNode.$);
    });

    return targetNode;
}

async function reloadPath(path) {
    const targetNode = path ? getNodeByStatus({ path: path }) : root;
    targetNode && targetNode.type === 'folder' && await targetNode.loadFolder();
    return targetNode;
}

top.global.tree.document = document;
top.global.tree.blur = blur;
top.global.tree.gotoPath = gotoPath;
top.global.tree.reloadPath = reloadPath;
top.global.tree.renderLang = renderLang;
