<!----- FILE js/userinfo.js START -----><script>
ignoreAutoFillPassword();
const id = $(frameElement).data('id');
const tab = top.global.tab;

const changed = {
    password: false,
    totp: false,
};

let pendingTotpSecret = '';
let totpSetupActive = false;

function setChangedStatus() {
    let changedStatus = false;

    for (const key in changed) {
        if (changed[key]) {
            changedStatus = true;
            break;
        }
    }

    tab.changeTab(id, { unsave: changedStatus, unlock: false });
    tab.renderTabs();
}

function setTotpChangedStatus(value) {
    changed.totp = value === true;
    setChangedStatus();
}

function getCurrentContentId() {
    const frame = window.frameElement;

    if (!frame) {
        return null;
    }

    const id = $(frame).data('id');
    return id ? String(id) : null;
}

function registerContentRenderLang() {
    const contentId = getCurrentContentId();

    if (!contentId) {
        return;
    }

    const content = top.global.content['content-' + contentId];

    if (!content) {
        return;
    }

    content.renderLang = async function () {
        await renderLang();
        await loadUserInfo();
        await renderLang();

        if (totpSetupActive && pendingTotpSecret) {
            renderTotpSetup(pendingTotpSecret);
        }
    };
}

async function init() {
    registerContentRenderLang();
    new ScrollBar($('.userinfo-content')[0], { barWidth: 14 });
    await renderLang();
    await loadUserInfo();
    await renderLang();
    bindGroupSwitch();
    bindInputChangeStatus();
    bindPasswordTips();
    setChangedStatus();
}

init();

function bindGroupSwitch() {
    $(document).on('click', '.userinfo-nav-item', function () {
        const group = $(this).data('group');
        const target = $('.userinfo-group[data-group="' + group + '"]');

        $('.userinfo-nav-item').removeClass('active');
        $(this).addClass('active');

        if (target.length) {
            const content = $('.userinfo-content');
            const offsetTop = target.offset().top - content.offset().top + content.scrollTop();
            content.scrollTop(offsetTop);
        }
    });
}

function bindInputChangeStatus() {
    $(document).on('input change', '.userinfo-input', function () {
        changed.password = true;
        setChangedStatus();
    });
}

function clearPasswordTip(tip) {
    tip.removeAttr('data-lang');
    tip.removeClass('userinfo-tip-error userinfo-tip-warning userinfo-tip-success');
    tip.text('');
}

function setPasswordTip(tip, langKey, className) {
    clearPasswordTip(tip);

    if (!langKey) {
        return;
    }

    tip.attr('data-lang', langKey);
    tip.addClass(className || 'userinfo-tip-error');
    tip.text('');
    renderLang();
}

function getPasswordStrength(password) {
    if (!password) {
        return 'weak';
    }

    const hasLower = /[a-z]/.test(password);
    const hasUpper = /[A-Z]/.test(password);
    const hasNumber = /\d/.test(password);
    const hasSpecial = /[^A-Za-z0-9]/.test(password);
    const typeCount = Number(hasLower) + Number(hasUpper) + Number(hasNumber) + Number(hasSpecial);

    if (password.length >= 12 && typeCount >= 3) {
        return 'strong';
    }

    if (password.length >= 8 && typeCount >= 2) {
        return 'medium';
    }

    return 'weak';
}

function syncPasswordTips() {
    const currentPassword = $('#userinfo-current-password').val();
    const newPassword = $('#userinfo-new-password').val();
    const confirmPassword = $('#userinfo-confirm-password').val();
    const currentTip = $('#userinfo-tips-current-password');
    const newTip = $('#userinfo-tips-new-password');
    const confirmTip = $('#userinfo-tips-confirm-password');

    if (!currentPassword && (newPassword || confirmPassword)) {
        setPasswordTip(currentTip, 'common.error.no_current_password', 'userinfo-tip-error');
    } else {
        clearPasswordTip(currentTip);
    }

    if (!newPassword) {
        clearPasswordTip(newTip);

        if (confirmPassword) {
            setPasswordTip(confirmTip, 'userinfo.password_mismatch', 'userinfo-tip-error');
        } else {
            clearPasswordTip(confirmTip);
        }
        return;
    }

    if (confirmPassword && newPassword !== confirmPassword) {
        clearPasswordTip(newTip);
        setPasswordTip(confirmTip, 'userinfo.password_mismatch', 'userinfo-tip-error');
        return;
    }

    clearPasswordTip(confirmTip);

    const strength = getPasswordStrength(newPassword);

    if (strength === 'weak') {
        setPasswordTip(newTip, 'userinfo.password_strength_weak', 'userinfo-tip-error');
        return;
    }

    if (strength === 'medium') {
        setPasswordTip(newTip, 'userinfo.password_strength_medium', 'userinfo-tip-warning');
        return;
    }

    setPasswordTip(newTip, 'userinfo.password_strength_strong', 'userinfo-tip-success');
}

function bindPasswordTips() {
    $(document).on('input change', '#userinfo-new-password, #userinfo-confirm-password', function () {
        syncPasswordTips();
    });

    $(document).on('input change', '#userinfo-current-password', function () {
        syncPasswordTips();
    });
}

function normalizeExts(value) {
    if (!value) {
        return [];
    }

    if (Array.isArray(value)) {
        return value.filter(item => item !== undefined && item !== null && item !== '').map(item => String(item));
    }

    if (typeof value === 'string') {
        return value.split(',').map(item => item.trim()).filter(Boolean);
    }

    return [String(value)];
}

function formatWriteExtDisplayValue(value) {
    const text = String(value == null ? '' : value).trim();

    if (text === '?') {
        return getLangTextByPath('config.exts_none') || '<无扩展名文件>';
    }

    return text;
}

function parseWriteSizeLimit(value) {
    if (value === false || value === '' || value === null || value === undefined) {
        return false;
    }

    if (typeof value === 'number' && isFinite(value)) {
        return Math.max(0, Math.floor(value));
    }

    if (typeof value !== 'string') {
        return false;
    }

    const trimmed = value.trim();

    if (!trimmed) {
        return false;
    }

    const match = trimmed.match(/^([0-9]+(?:\.[0-9]+)?)([a-z]*)$/i);

    if (!match) {
        return false;
    }

    const number = parseFloat(match[1]);

    if (!isFinite(number) || number < 0) {
        return false;
    }

    const unit = (match[2] || 'b').toUpperCase();
    const unitMap = {
        '': 0,
        B: 0,
        K: 1,
        KB: 1,
        M: 2,
        MB: 2,
        G: 3,
        GB: 3,
        T: 4,
        TB: 4,
        P: 5,
        PB: 5,
        E: 6,
        EB: 6,
        Z: 7,
        ZB: 7,
        Y: 8,
        YB: 8,
    };

    if (!Object.prototype.hasOwnProperty.call(unitMap, unit)) {
        return false;
    }

    return Math.max(0, Math.floor(number * Math.pow(1024, unitMap[unit])));
}

function formatBytesLimit(value) {
    const parsed = parseWriteSizeLimit(value);

    if (parsed === false) {
        return getLangTextByPath('userinfo.unlimited') || '无限制';
    }

    const units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'];
    let number = parsed;
    let unitIndex = 0;

    while (number >= 1024 && unitIndex < units.length - 1) {
        number /= 1024;
        unitIndex += 1;
    }

    return number.toFixed(number >= 10 || number % 1 === 0 ? 0 : 2) + ' ' + units[unitIndex];
}

function getTotpOtpauthUri(username, secret) {
    const safeUsername = String(username || '').trim() || 'user';
    const issuer = getTotpIssuer();
    const label = encodeURIComponent(safeUsername);
    const query = 'secret=' + encodeURIComponent(secret) + '&issuer=' + encodeURIComponent(issuer);
    return 'otpauth://totp/' + label + '?' + query;
}

function getTotpIssuer() {
    const issuer = String(getLangTextByPath('login.title') || '').trim();
    return issuer || 'VS File Manager';
}

function setTotpGroupBodyView(view) {
    const groupBody = $('#userinfo-totp-group-body');

    groupBody.removeClass('totp-view-default totp-view-setup totp-view-unbind');

    if (view === 'default' || view === 'setup' || view === 'unbind') {
        groupBody.addClass('totp-view-' + view);
    }
}

function resetTotpSetupView() {
    setTotpGroupBodyView('default');
    $('#userinfo-totp-secret').text('');
    $('#userinfo-totp-code').val('');
    $('#userinfo-totp-unbind-code').val('');
    $('#userinfo-totp-qrcode').empty();
}

function renderTotpSetup(secret) {
    const username = $('#userinfo-username-value').text();
    const qrcodeContainer = $('#userinfo-totp-qrcode');
    const uri = getTotpOtpauthUri(username, secret);

    qrcodeContainer.empty();

    new QRCode(qrcodeContainer.get(0), {
        text: uri,
        width: 160,
        height: 160,
        colorDark: '#111111',
        colorLight: '#ffffff',
        correctLevel: QRCode.CorrectLevel.M,
    });

    $('#userinfo-totp-secret').text(secret);
    setTotpGroupBodyView('setup');
}

async function loadUserInfo() {
    const response = await ajax({ url: '?a=userinfo', type: 'GET' });

    if (response.code) {
        error(response.code);
        return;
    }

    const data = response.data || {};
    const allowExts = normalizeExts(data.write_exts_allow);
    const denyExts = normalizeExts(data.write_exts_deny);

    $('#userinfo-username-value').text(data.username || '');
    $('#userinfo-write-size-limit-value').text(formatBytesLimit(data.write_size_limit));

    const totpConfigured = data.totp === true;

    if (top.global && top.global.data && top.global.data.userinfo) {
        top.global.data.userinfo.totp = totpConfigured;
    }

    const totpStatus = $('#userinfo-totp-status');
    const totpDisableButton = $('#userinfo-totp-disable');
    const totpEnableButton = $('#userinfo-totp-enable');

    resetTotpSetupView();
    totpStatus.attr('data-lang', totpConfigured ? 'userinfo.totp_configured' : 'userinfo.totp_unconfigured');
    totpStatus.text('');
    totpStatus.show();
    totpDisableButton.hide();
    totpEnableButton.hide();

    if (totpConfigured) {
        pendingTotpSecret = '';
        totpSetupActive = false;
        totpDisableButton.show();
    } else {
        totpEnableButton.show();
    }

    renderLang();

    const readonlyItems = $('#userinfo-readonly-value .userinfo-readonly-item');
    readonlyItems.removeClass('active');
    readonlyItems.filter('[data-state="' + (data.readonly ? 'yes' : 'no') + '"]').addClass('active');

    const writeExtsRow = $('.userinfo-info-row[data-kind="write-exts"]');

    if (data.readonly) {
        writeExtsRow.hide();
    } else {
        const writeItems = $('#userinfo-write-exts-value .userinfo-write-exts-item');
        writeItems.removeClass('active');

        if (allowExts.length > 0) {
            writeItems.filter('[data-mode="allow"]').addClass('active').find('[data-kind="allow-content"]').text(allowExts.map(formatWriteExtDisplayValue).join(' '));
        } else if (denyExts.length > 0) {
            writeItems.filter('[data-mode="deny"]').addClass('active').find('[data-kind="deny-content"]').text(denyExts.map(formatWriteExtDisplayValue).join(' '));
        } else {
            writeItems.filter('[data-mode="none"]').addClass('active');
        }

        writeExtsRow.show();
    }
}

$(document).on('click', '#userinfo-totp-enable', async function () {
    resetTotpSetupView();
    setTotpGroupBodyView(null);
    pendingTotpSecret = '';
    totpSetupActive = false;
    setTotpChangedStatus(true);

    const response = await ajax({
        url: '?a=otp',
        data: JSON.stringify({ action: 'generate' }),
    });

    if (response.code) {
        setTotpGroupBodyView('default');
        setTotpChangedStatus(false);
        error(response.code);
        return;
    }

    const secret = response.data && response.data.secret ? String(response.data.secret).trim() : '';

    if (!secret) {
        setTotpGroupBodyView('default');
        setTotpChangedStatus(false);
        error('common.error.internal_server_error');
        return;
    }

    pendingTotpSecret = secret;
    totpSetupActive = true;
    renderTotpSetup(secret);
});

$(document).on('click', '#userinfo-totp-disable', function () {
    pendingTotpSecret = '';
    totpSetupActive = false;
    $('#userinfo-totp-unbind-code').val('');
    setTotpGroupBodyView('unbind');
    setTotpChangedStatus(true);
});

$(document).on('click', '#userinfo-totp-cancel, #userinfo-totp-unbind-cancel', function () {
    pendingTotpSecret = '';
    totpSetupActive = false;
    resetTotpSetupView();
    setTotpChangedStatus(false);
});

$(document).on('click', '#userinfo-totp-verify-button', async function () {
    const code = String($('#userinfo-totp-code').val() || '').trim();

    if (!/^\d{6}$/.test(code)) {
        error('common.error.totp_invalid');
        return;
    }

    const response = await ajax({
        url: '?a=otp',
        data: JSON.stringify({
            action: 'bind',
            code: code,
        }),
    });

    if (response.code) {
        error(response.code);
        return;
    }

    pendingTotpSecret = '';
    totpSetupActive = false;
    setTotpChangedStatus(false);
    await loadUserInfo();
    await renderLang();
});

$(document).on('click', '#userinfo-totp-unbind-button', async function () {
    const code = String($('#userinfo-totp-unbind-code').val() || '').trim();

    if (!/^\d{6}$/.test(code)) {
        error('common.error.totp_invalid');
        return;
    }

    const response = await ajax({
        url: '?a=otp',
        data: JSON.stringify({
            action: 'unbind',
            code: code,
        }),
    });

    if (response.code) {
        error(response.code);
        return;
    }

    pendingTotpSecret = '';
    totpSetupActive = false;
    setTotpChangedStatus(false);
    await loadUserInfo();
    await renderLang();
});

$(document).on('click', '.userinfo-reset', function () {
    $('#userinfo-current-password').val('');
    $('#userinfo-new-password').val('');
    $('#userinfo-confirm-password').val('');
    clearPasswordTip($('#userinfo-tips-current-password'));
    clearPasswordTip($('#userinfo-tips-new-password'));
    clearPasswordTip($('#userinfo-tips-confirm-password'));
    changed.password = false;
    setChangedStatus();
});

$(document).on('click', '.userinfo-submit', async function () {
    const currentPassword = $('#userinfo-current-password').val();
    const newPassword = $('#userinfo-new-password').val();
    const confirmPassword = $('#userinfo-confirm-password').val();

    if (!currentPassword) {
        syncPasswordTips();
        error('common.error.no_current_password');
        return;
    }

    if (!newPassword) {
        error('common.error.no_new_password');
        return;
    }

    if (!confirmPassword) {
        error('common.error.no_confirm_password');
        return;
    }

    if (newPassword !== confirmPassword) {
        syncPasswordTips();
        error('common.error.password_mismatch');
        return;
    }

    if (getPasswordStrength(newPassword) === 'weak') {
        setPasswordTip($('#userinfo-tips-new-password'), 'userinfo.password_weak_forbidden', 'userinfo-tip-error');
        return;
    }

    const response = await ajax({
        url: '?a=userinfo',
        data: JSON.stringify({
            current_password: currentPassword,
            new_password: newPassword,
            confirm_password: confirmPassword,
        })
    });

    if (response.code) {
        error(response.code);
        return;
    }

    $('#userinfo-current-password').val('');
    $('#userinfo-new-password').val('');
    $('#userinfo-confirm-password').val('');
    clearPasswordTip($('#userinfo-tips-current-password'));
    clearPasswordTip($('#userinfo-tips-new-password'));
    clearPasswordTip($('#userinfo-tips-confirm-password'));
    changed.password = false;
    setChangedStatus();

    top.global.frame.openDialog({
        type: 'info',
        text_1: 'common.error.success',
        buttons: [{
            label: 'common.ok',
            onClick: function () {
                top.location.href = '?a=logout';
            },
        }],
    });
});
</script><!----- FILE js/userinfo.js END ----->
<!----- FILE js/video.js START -----><script>
const id = $(frameElement).data('id');
const content = top.global.content['content-' + id];
const video = document.getElementById('video');
const status = document.getElementById('video-status');
let pendingRestore = null;
let retryingToken = false;
let tokenRetryCount = 0;
let shouldBePlaying = false;
let statusLangPath = '';

document.title = content.path.split('/').pop();
renderPath(content.path);

video.addEventListener('loadedmetadata', function () {
    statusLangPath = setStatusLangText(status);
    tokenRetryCount = 0;

    if (!pendingRestore) {
        return;
    }

    const restore = pendingRestore;
    pendingRestore = null;
    video.currentTime = Math.min(restore.time, video.duration || restore.time);
    restore.play && video.play();
});

video.addEventListener('play', function () {
    shouldBePlaying = true;
});

video.addEventListener('pause', function () {
    video.error || (shouldBePlaying = false);
});

video.addEventListener('error', async function () {
    if (retryingToken || tokenRetryCount >= 1) {
        statusLangPath = setStatusLangText(status, 'video.play_failed');
        return;
    }

    retryingToken = true;
    const streamUrl = video.currentSrc || video.src;
    const tokenInvalid = await isDownloadTokenInvalid(streamUrl);

    if (!tokenInvalid) {
        retryingToken = false;
        statusLangPath = setStatusLangText(status, 'video.play_failed');
        return;
    }

    ++tokenRetryCount;
    const restore = { time: video.currentTime || 0, play: shouldBePlaying };
    await loadVideo(restore);
    retryingToken = false;
});

content.hide = function () {
    video.pause();
};

content.renderLang = async function () {
    await renderLang();
    renderPath(content.path);
    statusLangPath && (status.textContent = getLangTextByPath(statusLangPath));
};

loadVideo();
renderLang();

async function loadVideo(restore) {
    statusLangPath = setStatusLangText(status, 'video.loading');

    const response = await ajax({
        url: '?a=download',
        data: JSON.stringify({ path: content.path, timeout: 3600 }),
    });

    if (response.code) {
        statusLangPath = response.message
            ? setStatusLangText(status, '', response.message)
            : setStatusLangText(status, 'video.load_failed');
        return false;
    }

    pendingRestore = restore || null;
    video.src = '?d=' + encodeURIComponent(response.data.token) + '&inline=1';
    return true;
}

async function isDownloadTokenInvalid(url) {
    if (!url) {
        return false;
    }

    try {
        const response = await fetch(url, {
            cache: 'no-store',
            headers: { Range: 'bytes=0-0' },
        });
        const contentType = response.headers.get('Content-Type') || '';

        if (!contentType.includes('application/json')) {
            return false;
        }

        const result = await response.json();
        return result.code === 1022;
    } catch (error) {
        return false;
    }
}

$(document).on('click contextmenu', function () {
    top.global.tree.blur();
});

$(window).on('unload', function () {
    video.pause();
    video.removeAttribute('src');
    video.load();
});
</script><!----- FILE js/video.js END ----->
